# 轻量 PitchFrame 结构（本地兼容封装）
# 说明：外部可能存在不同签名的 PitchFrame，这里统一使用本地兼容类，
# 接受 f0_raw/f0_smooth 等关键字并提供 to_dict()，避免关键字不匹配导致运行时异常。
from dataclasses import dataclass, field
from enum import Enum


class RetakePhase(str, Enum):
    IDLE = "idle"
    COUNTDOWN = "countdown"
    RECORDING = "recording"
    REVIEW = "review"


@dataclass
class PitchFrame:
    # 基本时间戳
    timestamp: float
    # 原始/平滑音高（Hz）
    f0_raw: float = 0.0
    f0_smooth: float = 0.0
    # 置信度与附加信息
    confidence: float = 0.0
    note_info: Optional[Dict[str, Any]] = None
    has_pitch: bool = False
    audio_rms: float = 0.0
    vibrato_info: Optional[Dict[str, Any]] = None
    # 兼容历史字段：部分路径可能直接传入/读取 frequency
    frequency: Optional[float] = None
    display_frequency: Optional[float] = None

    def to_dict(self) -> dict:
        """统一导出为 UI/绘制使用的字典结构。
        frequency 使用 f0_smooth（无则回退 frequency），并额外提供 raw_frequency 字段。
        """
        try:
            freq = self.f0_smooth if (self.f0_smooth and self.f0_smooth > 0) else (self.frequency or 0.0)
        except Exception:
            freq = float(self.frequency or 0.0)
        try:
            raw = float(self.f0_raw or 0.0)
        except Exception:
            raw = 0.0
        d = {
            'timestamp': float(self.timestamp),
            'frequency': float(freq),            # 平滑后频率（用于绘制）
            'detected_frequency': float(freq),   # 检测层输出（尽量保真）
            'display_frequency': float(self.display_frequency if (self.display_frequency and self.display_frequency > 0) else freq),
            'raw_frequency': float(raw),         # 原始频率（可选调试/对比）
            'confidence': float(self.confidence or 0.0),
            'note_info': self.note_info,
            'has_pitch': bool(self.has_pitch and float(freq) > 0.0),
            'audio_rms': float(self.audio_rms or 0.0),
            'vibrato_info': self.vibrato_info or {'has_vibrato': False},
            # 兼容保留字段
            'f0_smooth': float(self.f0_smooth or 0.0),
            'f0_raw': float(raw),
        }
        return d


# Plan 2 overlay buffer container (keeps retake data in memory until commit)
@dataclass
class RetakeOverlayState:
    """In-memory overlay buffers for non-destructive retakes (Plan 2)."""

    start: float = 0.0
    end: float = 0.0
    active: bool = False
    recording: bool = False
    requires_commit: bool = False
    epoch: int = 0
    start_sample_index: int = 0
    end_sample_index: int = 0
    created_wall_time: float = 0.0
    last_timestamp: float = 0.0
    paused_at: Optional[float] = None
    original_duration: float = 0.0
    original_audio_length: int = 0
    original_pitch_count: int = 0
    original_time_offset: float = 0.0
    audio_samples: List[float] = field(default_factory=list)
    pitch_packets: List[Dict[str, Any]] = field(default_factory=list)
    preview_attached: bool = False
    phase: RetakePhase = RetakePhase.IDLE

    def clear(self) -> None:
        self.audio_samples.clear()
        self.pitch_packets.clear()
        self.active = False
        self.recording = False
        self.requires_commit = False
        self.start = 0.0
        self.end = 0.0
        self.start_sample_index = 0
        self.end_sample_index = 0
        self.created_wall_time = 0.0
        self.last_timestamp = 0.0
        self.paused_at = None
        self.original_duration = 0.0
        self.original_audio_length = 0
        self.original_pitch_count = 0
        self.original_time_offset = 0.0
        self.preview_attached = False
        self.phase = RetakePhase.IDLE

    def duration(self) -> float:
        return max(0.0, float(self.end) - float(self.start))

    def has_data(self) -> bool:
        return bool(self.audio_samples or self.pitch_packets)


@dataclass
class RetakeSessionContext:
    """Tracks the lifecycle of a single retake session for orchestration/telemetry."""

    active: bool = False
    start: float = 0.0
    end: float = 0.0
    created_at: float = 0.0
    resume_time: float = 0.0
    baseline_duration: float = 0.0
    overlay_ready: bool = False
    overlay_preview_points: int = 0
    preview_audio_samples: int = 0
    mask_applied: bool = False
    tail_snapshot_present: bool = False
    auto_stop_armed: bool = False
    auto_stop_reason: Optional[str] = None
    last_update: float = 0.0
    status: str = "idle"
    committed: bool = False
    discarded: bool = False
    recording_started_at: Optional[float] = None
    phase: RetakePhase = RetakePhase.IDLE

    def reset(self, status: str = "idle") -> None:
        self.active = False
        self.start = 0.0
        self.end = 0.0
        self.created_at = 0.0
        self.resume_time = 0.0
        self.baseline_duration = 0.0
        self.overlay_ready = False
        self.overlay_preview_points = 0
        self.preview_audio_samples = 0
        self.mask_applied = False
        self.tail_snapshot_present = False
        self.auto_stop_armed = False
        self.auto_stop_reason = None
        self.last_update = time.time()
        self.status = status
        self.committed = False
        self.discarded = False
        self.recording_started_at = None
        self.phase = RetakePhase.IDLE


