        # ===== 统一日志 RateLimiter =====
        class _RateLimiter:
            def __init__(self):
                self.state = {}

            def allow(self, key: str, interval: float, burst: int = 1):
                now = time.time()
                st = self.state.get(key, {'next': 0.0, 'remain': burst})
                if now >= st['next']:
                    st['next'] = now + interval
                    st['remain'] = burst - 1
                    self.state[key] = st
                    return True
                if st['remain'] > 0:
                    st['remain'] -= 1
                    self.state[key] = st
                    return True
                return False

        self._rate_limiter = _RateLimiter()

        def _log_rate_limit(key: str, msg: str, interval: float = 0.6, burst: int = 1):
            if self._rate_limiter.allow(key, interval, burst):
                try:
                    print(msg)
                except Exception:
                    pass
                # 细粒度 push：若距离上次重帧已超过阈值的一定比例，主动触发一次 draw_idle
                try:
                    now_t = time.time()
                    if hasattr(self, '_last_heavy_redraw_time'):
                        gap = now_t - float(getattr(self, '_last_heavy_redraw_time', 0.0))
                        base = float(getattr(self, '_heavy_redraw_base', 0.030))
                        push_factor = float(getattr(self, '_push_heavy_factor', 0.90))
                        if gap > base * push_factor and hasattr(self, 'canvas'):
                            self.canvas.draw_idle()
                except Exception:
                    pass

        self._log_rate_limit = _log_rate_limit

        # 监听日志开关：默认安静模式，仅输出关键结果。
        # 可通过环境变量 MINDECHO_VERBOSE_MONITOR=1 开启详细探测日志。
        try:
            self.monitor_log_verbose = str(os.environ.get('MINDECHO_VERBOSE_MONITOR', '0')).strip().lower() in ('1', 'true', 'yes', 'on')
        except Exception:
            self.monitor_log_verbose = False

        def _monitor_log(key: str, msg: str, interval: float = 0.8, burst: int = 1, verbose: bool = False):
            try:
                if verbose and (not bool(getattr(self, 'monitor_log_verbose', False))):
                    return
                self._log_rate_limit(f"monitor_{key}", msg, interval=interval, burst=burst)
            except Exception:
                try:
                    print(msg)
                except Exception:
                    pass

        self._monitor_log = _monitor_log

