    def _professional_get_freq_range(self) -> Tuple[float, float]:
        try:
            if getattr(self, 'audio_processor', None) is not None:
                ap = self.audio_processor
                min_f = float(getattr(ap, 'min_frequency', 80.0))
                max_f = float(getattr(ap, 'max_frequency', 1047.0))
            else:
                min_f = float(getattr(self, 'min_frequency', 80.0))
                max_f = float(getattr(self, 'max_frequency', 1047.0))
        except Exception:
            min_f, max_f = 80.0, 1047.0
        # 专业模式建议略放宽上限以容纳谐波
        max_f = max(max_f, min_f * 8.0, 5200.0)
        return max(20.0, min_f), max_f

    def _note_label_from_freq(self, freq: float) -> str:
        try:
            if freq <= 0:
                return ""
            semitones = int(round(12.0 * math.log2(float(freq) / 440.0)))
            midi = 69 + semitones
            note_names = ['C', 'C#', 'D', 'D#', 'E', 'F', 'F#', 'G', 'G#', 'A', 'A#', 'B']
            note = note_names[midi % 12]
            octave = int(midi // 12) - 1
            return f"{note}{octave}"
        except Exception:
            return ""

    def _professional_enqueue(self, t: float, f: float, c: float, src: str = "true") -> None:
        try:
            if f <= 0:
                return
            c = max(0.0, min(1.0, float(c)))
            item_t = float(t)
            item_src = str(src)
            try:
                recording = bool(getattr(self, 'is_recording_active', False))
            except Exception:
                recording = False
            try:
                pending_len = len(self._professional_pending)
            except Exception:
                pending_len = 0
            try:
                drop_backlog = int(getattr(self, '_professional_harmonic_drop_when_backlog', 1500))
            except Exception:
                drop_backlog = 1500
            try:
                defer_harm = bool(getattr(self, '_professional_defer_harmonics_until_stop', True))
            except Exception:
                defer_harm = True
            if recording and defer_harm and item_src == "harm":
                return
            if recording and item_src == "harm" and pending_len > drop_backlog:
                return
            item = (item_t, float(f), float(c), item_src)
            if item_src != "harm":
                try:
                    prev_base_t = float(getattr(self, '_professional_last_base_t', 0.0) or 0.0)
                except Exception:
                    prev_base_t = 0.0
                try:
                    self._professional_last_base_t = max(prev_base_t, item_t)
                except Exception:
                    self._professional_last_base_t = item_t
            if isinstance(self._professional_pending, list):
                self._professional_pending.append(item)
                try:
                    hard_cap = int(getattr(self, '_professional_pending_hard_cap', 9000))
                except Exception:
                    hard_cap = 9000
                if hard_cap > 0 and len(self._professional_pending) > hard_cap:
                    self._professional_pending = self._professional_pending[-hard_cap:]
            else:
                self._professional_pending.append(item)
                try:
                    hard_cap = int(getattr(self, '_professional_pending_hard_cap', 9000))
                except Exception:
                    hard_cap = 9000
                if hard_cap > 0:
                    while len(self._professional_pending) > hard_cap:
                        self._professional_pending.popleft()
        except Exception:
            pass

    def _capture_harmonic_candidates(self, pitch_data: dict) -> None:
        """采集多频段候选（用于专业模式）"""
        try:
            ts = float(pitch_data.get('_professional_time', pitch_data.get('global_time', pitch_data.get('timestamp', time.time()))))
        except Exception:
            ts = time.time()
        # 若为绝对时间戳且存在 start_time，则转为相对时间轴
        try:
            st = float(getattr(self, 'start_time', 0.0) or 0.0)
            if ts > 1e8 and st > 1e8:
                ts = ts - st
        except Exception:
            pass
        try:
            recording = bool(getattr(self, 'is_recording_active', False))
        except Exception:
            recording = False
        try:
            pending_len = len(self._professional_pending)
        except Exception:
            pending_len = 0
        try:
            drop_backlog = int(getattr(self, '_professional_harmonic_drop_when_backlog', 1500))
        except Exception:
            drop_backlog = 1500
        try:
            harmonic_enabled = bool(getattr(self, '_professional_harmonic_realtime_enabled', True))
        except Exception:
            harmonic_enabled = True
        try:
            emit_min_dt = float(getattr(self, '_professional_harmonic_emit_min_dt', 0.018))
        except Exception:
            emit_min_dt = 0.018
        if recording:
            try:
                trim_iv = float(getattr(self, '_professional_realtime_trim_interval', 0.60))
            except Exception:
                trim_iv = 0.60
            try:
                last_trim = float(getattr(self, '_professional_last_realtime_trim_t', 0.0) or 0.0)
            except Exception:
                last_trim = 0.0
            if trim_iv <= 0 or (ts - last_trim) >= trim_iv:
                try:
                    keep_hh = float(getattr(self, '_professional_harmonic_history_realtime_keep_sec', 48.0))
                except Exception:
                    keep_hh = 48.0
                try:
                    keep_mr = float(getattr(self, '_professional_main_recent_realtime_keep_sec', 36.0))
                except Exception:
                    keep_mr = 36.0
                try:
                    keep_pd = float(getattr(self, '_professional_pending_realtime_keep_sec', 10.0))
                except Exception:
                    keep_pd = 10.0
                # 录制中保护可回看历史：谐波历史至少保留 max_history_time + guard_sec
                try:
                    guard_sec = float(getattr(self, '_professional_full_history_guard_sec', 12.0))
                except Exception:
                    guard_sec = 12.0
                try:
                    keep_hh = max(keep_hh, float(getattr(self, 'max_history_time', 300.0) or 300.0) + max(0.0, guard_sec))
                except Exception:
                    pass
                cutoff_hh = float(ts) - max(8.0, keep_hh)
                cutoff_mr = float(ts) - max(6.0, keep_mr)
                cutoff_pd = float(ts) - max(4.0, keep_pd)
                try:
                    if isinstance(self.harmonic_history, list):
                        hard_cap_hh = int(getattr(self, '_professional_harmonic_history_hard_cap', 320000) or 320000)
                        if hard_cap_hh > 0 and len(self.harmonic_history) > hard_cap_hh:
                            self.harmonic_history = self.harmonic_history[-hard_cap_hh:]
                    else:
                        hard_cap_hh = int(getattr(self, '_professional_harmonic_history_hard_cap', 320000) or 320000)
                        if hard_cap_hh > 0:
                            while len(self.harmonic_history) > hard_cap_hh:
                                self.harmonic_history.popleft()
                except Exception:
                    pass
                try:
                    mr = getattr(self, '_professional_main_recent', None)
                    if mr is not None:
                        if isinstance(mr, list):
                            if len(mr) > 800:
                                self._professional_main_recent = [it for it in mr if float(it[0]) >= cutoff_mr]
                        else:
                            while mr and float(mr[0][0]) < cutoff_mr:
                                mr.popleft()
                except Exception:
                    pass
                try:
                    pd = getattr(self, '_professional_pending', None)
                    if pd is not None:
                        if isinstance(pd, list):
                            if len(pd) > 500:
                                self._professional_pending = [it for it in pd if float(it[0]) >= cutoff_pd]
                        else:
                            while pd and float(pd[0][0]) < cutoff_pd:
                                pd.popleft()
                except Exception:
                    pass
                try:
                    self._professional_last_realtime_trim_t = float(ts)
                except Exception:
                    pass
        skip_harmonics = False
        if recording:
            if (not harmonic_enabled) or pending_len > int(drop_backlog * 1.9):
                skip_harmonics = True
            else:
                try:
                    last_emit = float(getattr(self, '_professional_harmonic_last_emit_t', 0.0) or 0.0)
                except Exception:
                    last_emit = 0.0
                if emit_min_dt > 0 and (ts - last_emit) < emit_min_dt:
                    skip_harmonics = True
        def _append_main_recent(t_val: float, f_val: float, c_val: float) -> None:
            try:
                if not hasattr(self, '_professional_main_recent') or self._professional_main_recent is None:
                    return
                item = (float(t_val), float(f_val), float(c_val))
                if isinstance(self._professional_main_recent, list):
                    self._professional_main_recent.append(item)
                else:
                    self._professional_main_recent.append(item)
            except Exception:
                pass
        try:
            candidates = pitch_data.get('harmonic_candidates') or pitch_data.get('harmonics')
        except Exception:
            candidates = None
        if candidates:
            try:
                true_list = []
                for cand in candidates:
                    try:
                        freq = float(cand.get('frequency', cand.get('freq', 0.0)) or 0.0)
                        conf = float(cand.get('confidence', cand.get('energy', 0.6)) or 0.0)
                        src = str(cand.get('source', 'true'))
                    except Exception:
                        continue
                    if freq > 0:
                        if src != 'harm':
                            true_list.append((freq, conf))
                            src = 'true'
                        if isinstance(self.harmonic_history, list):
                            self.harmonic_history.append((ts, freq, conf, src))
                        else:
                            self.harmonic_history.append((ts, freq, conf, src))
                        self._professional_enqueue(ts, freq, conf, src)
                        if src == 'true':
                            _append_main_recent(ts, freq, conf)
                # 若存在 raw_frequency，则用于增强快速转音的主线跟随
                try:
                    raw_f = float(pitch_data.get('raw_frequency', 0.0) or 0.0)
                except Exception:
                    raw_f = 0.0
                if raw_f > 0:
                    try:
                        sep_semi = float(getattr(self, '_true_peak_min_sep_semi', 0.8))
                    except Exception:
                        sep_semi = 0.8
                    sep_ratio = 2 ** (sep_semi / 12.0)
                    def _close_to_any(ff):
                        for tf, _ in true_list:
                            if max(ff, 1e-6) / max(tf, 1e-6) < sep_ratio and max(tf, 1e-6) / max(ff, 1e-6) < sep_ratio:
                                return True
                        return False
                    if not _close_to_any(raw_f):
                        true_list.append((raw_f, 0.85))
                        if isinstance(self.harmonic_history, list):
                            self.harmonic_history.append((ts, raw_f, 0.85, "true"))
                        else:
                            self.harmonic_history.append((ts, raw_f, 0.85, "true"))
                        self._professional_enqueue(ts, raw_f, 0.85, "true")
                        _append_main_recent(ts, raw_f, 0.85)
                # 基于真实主线生成谐波（多主线时避开重叠）
                if true_list and (not skip_harmonics):
                    try:
                        min_f, max_f = self._professional_get_freq_range()
                        try:
                            harm_min = float(getattr(self, '_professional_harmonic_min_conf', 0.05))
                            harm_weight = float(getattr(self, '_professional_harmonic_weight', 0.58))
                            harm_count = int(getattr(self, '_professional_harmonic_count', 12))
                        except Exception:
                            harm_min, harm_weight, harm_count = 0.05, 0.58, 12
                        fast_change = bool(pitch_data.get('_fast_change'))
                        if recording:
                            try:
                                harm_min = max(harm_min, float(getattr(self, '_professional_harmonic_recording_min_conf', 0.08)))
                            except Exception:
                                harm_min = max(harm_min, 0.08)
                            try:
                                cap = int(getattr(self, '_professional_harmonic_recording_count_cap', 4))
                            except Exception:
                                cap = 4
                            if pending_len > drop_backlog or fast_change:
                                try:
                                    cap = min(cap, int(getattr(self, '_professional_harmonic_fast_count_cap', 2)))
                                except Exception:
                                    cap = min(cap, 2)
                                harm_weight = harm_weight * 0.78
                            harm_count = max(1, min(harm_count, cap))
                        # 重叠判定（半音内视为同一条）
                        try:
                            sep_semi = float(getattr(self, '_true_peak_min_sep_semi', 0.8))
                        except Exception:
                            sep_semi = 0.8
                        sep_ratio = 2 ** (sep_semi / 12.0)
                        def _close_to_true(ff):
                            for tf, _ in true_list:
                                if max(ff, 1e-6) / max(tf, 1e-6) < sep_ratio and max(tf, 1e-6) / max(ff, 1e-6) < sep_ratio:
                                    return True
                            return False
                        for base, base_conf in true_list:
                            if base_conf < harm_min:
                                continue
                            strength = (base_conf - harm_min) / max(1e-6, (1.0 - harm_min))
                            strength = max(0.0, min(1.0, strength))
                            weight_scale = 0.35 + 0.65 * strength
                            dyn_count = max(2, int(round(harm_count * (0.6 + 0.6 * strength))))
                            if fast_change:
                                dyn_count = max(2, min(4, int(round(dyn_count * 0.6))))
                            # 上方谐波
                            for k in range(2, dyn_count + 1):
                                hf = base * k
                                if hf > max_f * 1.02:
                                    break
                                if _close_to_true(hf):
                                    continue
                                hconf = base_conf * (0.72 ** (k - 1)) * harm_weight * weight_scale
                                if fast_change:
                                    hconf = hconf * 0.45
                                if isinstance(self.harmonic_history, list):
                                    self.harmonic_history.append((ts, hf, hconf, "harm"))
                                else:
                                    self.harmonic_history.append((ts, hf, hconf, "harm"))
                                self._professional_enqueue(ts, hf, hconf, "harm")
                            # 下方一条次谐波（仅在范围内且不靠近真实主线）
                            sub = base * 0.5
                            if sub >= min_f * 0.98 and (not _close_to_true(sub)):
                                hconf = base_conf * 0.25 * weight_scale
                                if fast_change:
                                    hconf = hconf * 0.45
                                if isinstance(self.harmonic_history, list):
                                    self.harmonic_history.append((ts, sub, hconf, "harm"))
                                else:
                                    self.harmonic_history.append((ts, sub, hconf, "harm"))
                                self._professional_enqueue(ts, sub, hconf, "harm")
                        try:
                            self._professional_harmonic_last_emit_t = float(ts)
                        except Exception:
                            pass
                    except Exception:
                        pass
                return
            except Exception:
                pass
        # 兜底：没有多候选时，用单频作为一条候选
        try:
            freq = float(pitch_data.get('raw_frequency', 0.0) or 0.0)
            if freq <= 0:
                freq = float(pitch_data.get('frequency', 0.0) or 0.0)
            conf = float(pitch_data.get('confidence', 0.6) or 0.0)
            if freq > 0:
                if isinstance(self.harmonic_history, list):
                    self.harmonic_history.append((ts, freq, conf, "true"))
                else:
                    self.harmonic_history.append((ts, freq, conf, "true"))
                self._professional_enqueue(ts, freq, conf, "true")
                _append_main_recent(ts, freq, conf)
                # 轻量生成谐波候选，增强多频段可视化
                try:
                    if skip_harmonics:
                        return
                    min_f, max_f = self._professional_get_freq_range()
                    base = float(freq)
                    base_conf = max(0.05, min(1.0, conf))
                    try:
                        harm_min = float(getattr(self, '_professional_harmonic_min_conf', 0.035))
                        harm_weight = float(getattr(self, '_professional_harmonic_weight', 0.58))
                        harm_count = int(getattr(self, '_professional_harmonic_count', 12))
                    except Exception:
                        harm_min = 0.035
                        harm_weight = 0.58
                        harm_count = 12
                    if recording:
                        try:
                            harm_min = max(harm_min, float(getattr(self, '_professional_harmonic_recording_min_conf', 0.08)))
                        except Exception:
                            harm_min = max(harm_min, 0.08)
                        try:
                            cap = int(getattr(self, '_professional_harmonic_recording_count_cap', 4))
                        except Exception:
                            cap = 4
                        if pending_len > drop_backlog:
                            try:
                                cap = min(cap, int(getattr(self, '_professional_harmonic_fast_count_cap', 2)))
                            except Exception:
                                cap = min(cap, 2)
                            harm_weight = harm_weight * 0.78
                        harm_count = max(1, min(harm_count, cap))
                    if base_conf < harm_min:
                        return
                    try:
                        strength = (base_conf - harm_min) / max(1e-6, (1.0 - harm_min))
                        strength = max(0.0, min(1.0, strength))
                    except Exception:
                        strength = 0.0
                    weight_scale = 0.35 + 0.65 * strength
                    for k in range(2, max(3, harm_count + 1)):
                        hf = base * k
                        if hf > max_f * 1.02:
                            break
                        hconf = base_conf * (0.72 ** (k - 1)) * harm_weight * weight_scale
                        if isinstance(self.harmonic_history, list):
                            self.harmonic_history.append((ts, hf, hconf, "harm"))
                        else:
                            self.harmonic_history.append((ts, hf, hconf, "harm"))
                        self._professional_enqueue(ts, hf, hconf, "harm")
                    try:
                        self._professional_harmonic_last_emit_t = float(ts)
                    except Exception:
                        pass
                except Exception:
                    pass
        except Exception:
            pass

    def _build_professional_main_tracks(self, x0: float, x1: float) -> List[Dict[str, Any]]:
        """构建专业模式主能量多轨（多频段）段列表，含换气断开处理。"""
        try:
            margin = float(getattr(self, '_professional_main_margin', 0.22))
        except Exception:
            margin = 0.22
        try:
            max_tracks = int(getattr(self, '_professional_main_tracks_max', 3))
        except Exception:
            max_tracks = 3
        try:
            gap_thr = float(getattr(self, '_professional_main_gap_s', 0.18))
        except Exception:
            gap_thr = 0.18
        try:
            match_semi = float(getattr(self, '_professional_main_match_semi', 4.0))
        except Exception:
            match_semi = 4.0
        try:
            same_t_eps = float(getattr(self, '_professional_same_time_eps', 0.008))
        except Exception:
            same_t_eps = 0.008
        try:
            link_max_semi = float(getattr(self, '_professional_track_link_max_semi', 1.8))
        except Exception:
            link_max_semi = 1.8
        try:
            min_f, max_f = self._professional_get_freq_range()
        except Exception:
            min_f, max_f = 80.0, 5200.0

        points: List[Tuple[float, float, float, int]] = []
        def _band_index(freq_hz: float) -> int:
            try:
                ff = float(freq_hz)
            except Exception:
                ff = 0.0
            try:
                edges = tuple(float(v) for v in getattr(self, '_professional_band_edges_hz', (320.0, 900.0)))
            except Exception:
                edges = (320.0, 900.0)
            if ff <= 0:
                return 0
            idx = 0
            for edge in edges:
                if ff < edge:
                    return idx
                idx += 1
            return idx
        recent = getattr(self, '_professional_main_recent', None)
        try:
            if recent is not None and len(recent) > 0:
                try:
                    win = float(getattr(self, '_professional_main_recent_window', 30.0))
                except Exception:
                    win = 30.0
                prune_before = x0 - max(1.0, win)
                if not isinstance(recent, list):
                    try:
                        while recent and float(recent[0][0]) < prune_before:
                            recent.popleft()
                    except Exception:
                        pass
                for item in list(recent):
                    try:
                        t, f, c = item[0], item[1], item[2]
                        t = float(t)
                        f = float(f)
                        c = float(c) if c is not None else 0.6
                    except Exception:
                        continue
                    if f <= 0:
                        continue
                    if t < x0 - margin or t > x1 + margin:
                        continue
                    if f < min_f * 0.9 or f > max_f * 1.05:
                        continue
                    points.append((t, f, c, _band_index(f)))
        except Exception:
            points = []

        if not points:
            try:
                for item in list(getattr(self, 'harmonic_history', [])):
                    if not isinstance(item, (list, tuple)):
                        continue
                    if len(item) >= 4:
                        t, f, c, src = item[0], item[1], item[2], item[3]
                        if str(src) == "harm":
                            continue
                    elif len(item) == 3:
                        t, f, c = item
                    else:
                        continue
                    try:
                        t = float(t)
                        f = float(f)
                        c = float(c) if c is not None else 0.6
                    except Exception:
                        continue
                    if f <= 0:
                        continue
                    if t < x0 - margin or t > x1 + margin:
                        continue
                    if f < min_f * 0.9 or f > max_f * 1.05:
                        continue
                    points.append((t, f, c, _band_index(f)))
            except Exception:
                points = []

        if not points:
            try:
                raw_hist = list(getattr(self, '_professional_raw_history', []))
            except Exception:
                raw_hist = []
            if raw_hist:
                for t, f in raw_hist:
                    try:
                        t = float(t)
                        f = float(f)
                    except Exception:
                        continue
                    if f <= 0:
                        continue
                    if t < x0 - margin or t > x1 + margin:
                        continue
                    points.append((t, f, 0.8, _band_index(f)))
            else:
                try:
                    tbuf = list(getattr(self, 'time_data', []))
                    pbuf = list(getattr(self, 'pitch_data', []))
                except Exception:
                    tbuf, pbuf = [], []
                if tbuf and pbuf and len(tbuf) == len(pbuf):
                    for t, f in zip(tbuf, pbuf):
                        try:
                            t = float(t)
                            f = float(f)
                        except Exception:
                            continue
                        if f <= 0:
                            continue
                        if t < x0 - margin or t > x1 + margin:
                            continue
                        points.append((t, f, 0.7, _band_index(f)))

        if not points:
            return []

        points.sort(key=lambda v: v[0])

        tracks: List[Dict[str, Any]] = []
        for t, f, c, band in points:
            best_idx = None
            best_semi = None
            for i, tr in enumerate(tracks):
                if int(tr.get('band', -1)) != int(band):
                    continue
                last_t = tr['last_t']
                last_f = tr['last_f']
                dt = t - last_t
                if dt < -1e-6:
                    continue
                try:
                    semi = abs(12.0 * math.log2(max(1e-9, f / max(last_f, 1e-9))))
                except Exception:
                    semi = 999.0
                if semi <= match_semi:
                    if best_idx is None or semi < best_semi:
                        best_idx = i
                        best_semi = semi
            if best_idx is None:
                if len(tracks) >= max_tracks:
                    continue
                tracks.append({
                    'segments': [],
                    'current': [(t, f)],
                    'last_t': t,
                    'last_f': f,
                    'band': int(band),
                    'score': max(0.0, c),
                })
                continue
            tr = tracks[best_idx]
            dt = t - tr['last_t']
            force_break = False
            if best_semi is not None:
                # 同一时间片出现不同频段时，强制断段，防止跨频段串线
                if dt <= same_t_eps and best_semi > 0.65:
                    force_break = True
                # 频段跨度过大时，强制断段，仅连接同频段轨迹
                if best_semi > link_max_semi:
                    force_break = True
            if (dt > gap_thr or force_break) and tr['current']:
                tr['segments'].append(tr['current'])
                tr['current'] = []
            tr['current'].append((t, f))
            tr['last_t'] = t
            tr['last_f'] = f
            tr['score'] += max(0.0, c)

        for tr in tracks:
            if tr['current']:
                tr['segments'].append(tr['current'])
                tr['current'] = []

        tracks = [tr for tr in tracks if any(len(seg) >= 2 for seg in tr.get('segments', []))]
        tracks.sort(key=lambda tr: tr.get('score', 0.0), reverse=True)
        if max_tracks > 0:
            tracks = tracks[:max_tracks]
        return tracks

    def _build_professional_base_series(self, x0: float, x1: float) -> Tuple[List[float], List[float]]:
        """构建专业模式基音主线：沿用普通模式时间/音高序列，断开换气空隙。"""
        try:
            recording = bool(getattr(self, 'is_recording_active', False))
        except Exception:
            recording = False
        try:
            gap_thr = float(getattr(self, '_professional_main_gap_s', 0.18))
        except Exception:
            gap_thr = 0.18
        try:
            margin = float(getattr(self, '_professional_main_margin', 0.22))
        except Exception:
            margin = 0.22
        try:
            same_t_eps = float(getattr(self, '_professional_base_same_time_eps', 0.006))
        except Exception:
            same_t_eps = 0.006
        try:
            breath_gap = float(getattr(self, '_breath_gap_threshold', 0.14))
        except Exception:
            breath_gap = 0.14
        breath_gap = max(0.0, breath_gap)
        try:
            bridge_scale = float(getattr(self, '_bridge_time_scale', 1.15))
        except Exception:
            bridge_scale = 1.15
        try:
            bridge_semi_thr = float(getattr(self, '_bridge_semi_thr', 3.2))
        except Exception:
            bridge_semi_thr = 3.2
        try:
            jump_semi_thr = float(getattr(self, '_professional_base_jump_break_semi', 8.75))
        except Exception:
            jump_semi_thr = 8.75
        try:
            jump_dt = float(getattr(self, '_professional_base_jump_break_dt', 0.12))
        except Exception:
            jump_dt = 0.12
        jump_semi_thr = max(0.0, jump_semi_thr)
        jump_dt = max(0.0, jump_dt)
        try:
            max_step_semi = float(getattr(self, '_professional_base_max_step_semitones', 7.0))
        except Exception:
            max_step_semi = 7.0
        max_step_semi = max(0.5, max_step_semi)
        try:
            smooth_beta = float(getattr(self, '_professional_base_recording_smooth_beta', 0.36 if recording else 0.42))
        except Exception:
            smooth_beta = 0.36 if recording else 0.42
        if not recording:
            try:
                smooth_beta = float(getattr(self, '_professional_base_smooth_beta', smooth_beta))
            except Exception:
                pass
        smooth_beta = max(0.10, min(0.90, smooth_beta))

        def _postprocess_base_series(xs: List[float], ys: List[float]) -> Tuple[List[float], List[float]]:
            if (not xs) or (not ys):
                return xs, ys
            out_t: List[float] = []
            out_f: List[float] = []
            last_t = None
            last_f_raw = None
            last_f_smooth = None
            for t_raw, f_raw in zip(xs, ys):
                try:
                    t = float(t_raw)
                    f = float(f_raw)
                except Exception:
                    continue
                if not math.isfinite(t) or not math.isfinite(f) or f <= 0.0:
                    if out_t and out_t[-1] == out_t[-1]:
                        out_t.append(float('nan'))
                        out_f.append(float('nan'))
                    last_t = None
                    last_f_raw = None
                    last_f_smooth = None
                    continue
                if last_t is None or last_f_raw is None:
                    out_t.append(t)
                    out_f.append(f)
                    last_t = t
                    last_f_raw = f
                    last_f_smooth = f
                    continue
                dt = max(0.0, t - last_t)
                try:
                    semi_jump_raw = abs(12.0 * math.log2(max(1e-9, f / max(last_f_raw, 1e-9))))
                except Exception:
                    semi_jump_raw = 0.0
                # 借鉴普通模式：换气/空白时长断开，短时超大跳变断开
                force_break = False
                if dt > breath_gap:
                    if not (dt <= breath_gap * bridge_scale and semi_jump_raw <= bridge_semi_thr):
                        force_break = True
                elif jump_semi_thr > 0.0 and dt <= jump_dt and semi_jump_raw >= jump_semi_thr:
                    force_break = True
                if force_break and out_t and out_t[-1] == out_t[-1]:
                    out_t.append(float('nan'))
                    out_f.append(float('nan'))
                    last_t = None
                    last_f_raw = None
                    last_f_smooth = None
                    out_t.append(t)
                    out_f.append(f)
                    last_t = t
                    last_f_raw = f
                    last_f_smooth = f
                    continue
                # 借鉴普通模式：录制时限制单帧跨幅，避免邻近两点突然跨度过大
                f_adj = f
                if dt <= max(0.02, jump_dt) and max_step_semi > 0.0 and last_f_smooth is not None:
                    try:
                        semi_from_smooth = 12.0 * math.log2(max(1e-9, f / max(last_f_smooth, 1e-9)))
                    except Exception:
                        semi_from_smooth = 0.0
                    if abs(semi_from_smooth) > max_step_semi:
                        semi_from_smooth = math.copysign(max_step_semi, semi_from_smooth)
                        f_adj = last_f_smooth * (2.0 ** (semi_from_smooth / 12.0))
                if last_f_smooth is None:
                    f_smooth = f_adj
                else:
                    f_smooth = last_f_smooth + smooth_beta * (f_adj - last_f_smooth)
                out_t.append(t)
                out_f.append(f_smooth)
                last_t = t
                last_f_raw = f
                last_f_smooth = f_smooth
            return out_t, out_f
        try:
            fast_mode_live = bool(getattr(self, '_professional_fast_mode', False))
        except Exception:
            fast_mode_live = False
        try:
            pending_len_live = len(getattr(self, '_professional_pending', []))
        except Exception:
            pending_len_live = 0
        heavy_live = bool(recording and (fast_mode_live or pending_len_live > 1200))

        # 普通模式风格主基频：优先使用单一基频历史（仅取当前窗口尾部，避免全历史扫描）
        base_hist = []
        try:
            base_src = getattr(self, '_professional_base_history', [])
        except Exception:
            base_src = []
        if base_src:
            try:
                cap = int(getattr(self, '_professional_base_series_cap', 8000))
            except Exception:
                cap = 8000
            if recording:
                cap = min(cap, 4800)
            if heavy_live:
                cap = min(cap, 2400)
            cap = max(800, cap)
            lower_t = x0 - margin
            tmp_rev: List[Tuple[float, float]] = []
            try:
                for it in reversed(base_src):
                    try:
                        t = float(it[0]); p = float(it[1])
                    except Exception:
                        continue
                    if t > x1 + margin:
                        continue
                    if t < lower_t:
                        break
                    if p <= 0:
                        continue
                    tmp_rev.append((t, p))
                    if len(tmp_rev) >= cap:
                        break
                if tmp_rev:
                    base_hist = list(reversed(tmp_rev))
            except Exception:
                try:
                    base_hist = list(base_src)
                except Exception:
                    base_hist = []
        if base_hist:
            xs: List[float] = []
            ys: List[float] = []
            last_t = None
            for it in base_hist:
                try:
                    t = float(it[0])
                    p = float(it[1])
                except Exception:
                    continue
                if p <= 0:
                    continue
                if t < x0 - margin or t > x1 + margin:
                    continue
                if xs and last_t is not None and abs(t - last_t) <= same_t_eps:
                    xs[-1] = t
                    ys[-1] = p
                    last_t = t
                    continue
                if last_t is not None and (t - last_t) > gap_thr:
                    xs.append(float('nan'))
                    ys.append(float('nan'))
                xs.append(t)
                ys.append(p)
                last_t = t
            if xs and ys:
                return _postprocess_base_series(xs, ys)

        # 专业模式优先：使用真实Hz数据源，避免误用普通模式的y映射值(0~8)导致白点不可见
        prof_points: List[Tuple[float, float]] = []
        try:
            recent = getattr(self, '_professional_main_recent', None)
            if recent is not None and len(recent) > 0:
                try:
                    recent_cap = int(getattr(self, '_professional_base_recent_scan_cap', 5200))
                except Exception:
                    recent_cap = 5200
                try:
                    recent_cap_heavy = int(getattr(self, '_professional_base_recent_scan_cap_heavy', 2200))
                except Exception:
                    recent_cap_heavy = 2200
                if heavy_live:
                    recent_cap = min(recent_cap, recent_cap_heavy)
                recent_cap = max(600, recent_cap)
                lower_t = x0 - margin
                tmp_rev: List[Tuple[float, float]] = []
                for item in reversed(recent):
                    try:
                        t = float(item[0])
                        f = float(item[1])
                    except Exception:
                        continue
                    if f <= 0:
                        continue
                    if t > (x1 + margin):
                        continue
                    if t < lower_t:
                        break
                    tmp_rev.append((t, f))
                    if len(tmp_rev) >= recent_cap:
                        break
                if tmp_rev:
                    prof_points = list(reversed(tmp_rev))
        except Exception:
            prof_points = []

        if not prof_points:
            try:
                hh = list(getattr(self, 'harmonic_history', []))
            except Exception:
                hh = []
            if hh:
                lower_t = x0 - margin
                tmp_rev: List[Tuple[float, float]] = []
                back_cap = 3000 if heavy_live else 7000
                for it in reversed(hh):
                    try:
                        t = float(it[0])
                        f = float(it[1])
                        src = str(it[3]) if len(it) >= 4 else 'true'
                    except Exception:
                        continue
                    if f <= 0:
                        continue
                    if src == 'harm':
                        continue
                    if t > (x1 + margin):
                        continue
                    if t < lower_t:
                        break
                    tmp_rev.append((t, f))
                    if len(tmp_rev) >= back_cap:
                        break
                if tmp_rev:
                    prof_points = list(reversed(tmp_rev))

        if prof_points:
            xs: List[float] = []
            ys: List[float] = []
            last_t = None
            for t, p in prof_points:
                if last_t is not None and (t - last_t) > gap_thr:
                    xs.append(float('nan'))
                    ys.append(float('nan'))
                xs.append(float(t))
                ys.append(float(p))
                last_t = t
            return _postprocess_base_series(xs, ys)

        use_flat = False
        flat = []
        # 与普通模式一致：优先使用 time_data/pitch_data，_flat_points 作为兜底
        try:
            tbuf = list(getattr(self, 'time_data', []))
            pbuf = list(getattr(self, 'pitch_data', []))
        except Exception:
            tbuf, pbuf = [], []
        if not tbuf or not pbuf or len(tbuf) != len(pbuf):
            try:
                flat = list(getattr(self, '_flat_points', []))
                if flat:
                    use_flat = True
            except Exception:
                use_flat = False
            if not use_flat:
                return [], []
        xs: List[float] = []
        ys: List[float] = []
        last_t = None
        if use_flat:
            if recording and len(flat) > 16000:
                flat = flat[-16000:]
            for t, p in flat:
                try:
                    t = float(t)
                    p = float(p)
                except Exception:
                    continue
                if p <= 0:
                    continue
                if t < x0 - 0.25 or t > x1 + 0.25:
                    continue
                if last_t is not None and (t - last_t) > gap_thr:
                    xs.append(float('nan'))
                    ys.append(float('nan'))
                xs.append(t)
                ys.append(p)
                last_t = t
        else:
            if recording and len(tbuf) > 16000:
                tbuf = tbuf[-16000:]
                pbuf = pbuf[-16000:]
            for t, p in zip(tbuf, pbuf):
                try:
                    t = float(t)
                    p = float(p)
                except Exception:
                    continue
                if p <= 0:
                    continue
                if t < x0 - 0.25 or t > x1 + 0.25:
                    continue
                if last_t is not None and (t - last_t) > gap_thr:
                    xs.append(float('nan'))
                    ys.append(float('nan'))
                xs.append(t)
                ys.append(p)
                last_t = t
        return _postprocess_base_series(xs, ys)

    def _build_professional_base_predict_points(
        self,
        base_times: List[float],
        base_pitches: List[float],
        x0: float,
        x1: float,
        cursor_t: float,
    ) -> List[Tuple[float, float]]:
        """基于最近真实基频进行短时外推，用于专业模式前沿雪花预绘制。"""
        try:
            if not bool(getattr(self, '_professional_base_predict_enabled', True)):
                return []
        except Exception:
            return []
        try:
            horizon = float(getattr(self, '_professional_base_predict_horizon_s', 1.0))
        except Exception:
            horizon = 1.0
        horizon = max(0.08, min(1.2, horizon))
        try:
            gap_start = float(getattr(self, '_professional_base_predict_gap_start_s', 0.06))
        except Exception:
            gap_start = 0.06
        gap_start = max(0.01, min(0.30, gap_start))
        try:
            tail_sec = float(getattr(self, '_professional_base_predict_tail_sec', 0.35))
        except Exception:
            tail_sec = 0.35
        tail_sec = max(0.08, min(1.20, tail_sec))
        try:
            lead_sec = float(getattr(self, '_professional_base_predict_lead_sec', 0.08))
        except Exception:
            lead_sec = 0.08
        lead_sec = max(0.0, min(0.25, lead_sec))
        try:
            step_min = float(getattr(self, '_professional_base_predict_step_min_s', 0.018))
        except Exception:
            step_min = 0.018
        try:
            step_max = float(getattr(self, '_professional_base_predict_step_max_s', 0.05))
        except Exception:
            step_max = 0.05
        step_min = max(0.008, min(0.06, step_min))
        step_max = max(step_min, min(0.12, step_max))
        try:
            semi_slope_cap = float(getattr(self, '_professional_base_predict_semi_slope_cap', 18.0))
        except Exception:
            semi_slope_cap = 18.0
        semi_slope_cap = max(3.0, min(60.0, semi_slope_cap))

        valid: List[Tuple[float, float]] = []
        for t, p in zip(base_times, base_pitches):
            try:
                t_f = float(t)
                p_f = float(p)
            except Exception:
                continue
            if not math.isfinite(t_f) or not math.isfinite(p_f):
                continue
            if p_f <= 0.0:
                continue
            valid.append((t_f, p_f))
        if len(valid) < 2:
            return []

        last_t, last_f = valid[-1]
        gap = float(cursor_t) - float(last_t)
        if gap < gap_start:
            return []
        target_t = min(float(last_t) + horizon, float(cursor_t) + lead_sec)
        if target_t <= last_t + step_min:
            return []

        tail: List[Tuple[float, float]] = []
        cut_t = float(last_t) - tail_sec
        for t, p in reversed(valid):
            if t < cut_t:
                break
            tail.append((t, p))
        if len(tail) < 2:
            return []
        tail.reverse()

        dt_list: List[float] = []
        semi_slopes: List[float] = []
        try:
            prev_t, prev_f = tail[0]
            prev_semi = 12.0 * math.log2(max(1.0, prev_f) / 440.0)
            for t, p in tail[1:]:
                dt = float(t) - float(prev_t)
                if dt <= 1e-4 or dt > 0.25:
                    prev_t, prev_f = t, p
                    prev_semi = 12.0 * math.log2(max(1.0, prev_f) / 440.0)
                    continue
                semi = 12.0 * math.log2(max(1.0, p) / 440.0)
                s = (semi - prev_semi) / dt
                dt_list.append(dt)
                semi_slopes.append(max(-semi_slope_cap, min(semi_slope_cap, s)))
                prev_t, prev_f = t, p
                prev_semi = semi
        except Exception:
            return []

        if not dt_list:
            return []
        try:
            import numpy as _np
            dt_med = float(_np.median(_np.asarray(dt_list, dtype=_np.float32)))
            slope = float(_np.median(_np.asarray(semi_slopes, dtype=_np.float32))) if semi_slopes else 0.0
        except Exception:
            dt_med = dt_list[-1]
            slope = semi_slopes[-1] if semi_slopes else 0.0

        step = max(step_min, min(step_max, dt_med if dt_med > 1e-5 else 0.03))
        if step <= 1e-4:
            return []

        try:
            min_f, max_f = self._professional_get_freq_range()
        except Exception:
            min_f, max_f = 20.0, 5200.0
        last_semi = 12.0 * math.log2(max(1.0, last_f) / 440.0)

        out: List[Tuple[float, float]] = []
        t = float(last_t) + step
        while t <= target_t + 1e-6:
            dt = t - float(last_t)
            semi = last_semi + slope * dt
            f = 440.0 * (2.0 ** (semi / 12.0))
            f = max(float(min_f), min(float(max_f), float(f)))
            if (x0 - 0.15) <= t <= (x1 + 0.15):
                out.append((float(t), float(f)))
            t += step
        return out

    def _update_professional_base_predict_trail(self, pred_arr, diameter: float, heavy_mode: bool = False) -> None:
        """维护预测雪花的逐帧衰减尾巴，增强流动感。"""
        try:
            import numpy as _np
            now_t = time.time()
            trail_sec = float(getattr(self, '_professional_base_predict_trail_sec', 0.42))
            trail_sec = max(0.08, min(1.2, trail_sec))
            max_points = int(getattr(self, '_professional_base_predict_trail_max_points', 420))
            max_points = max(80, min(3000, max_points))
            fade_pow = float(getattr(self, '_professional_base_predict_trail_fade_power', 1.6))
            fade_pow = max(0.5, min(4.0, fade_pow))
            min_scale = float(getattr(self, '_professional_base_predict_trail_min_scale', 0.58))
            min_scale = max(0.25, min(0.95, min_scale))
            pred_scale = float(getattr(self, '_professional_base_predict_snowflake_scale', 1.95))
            pred_scale = max(1.1, min(3.0, pred_scale))
            pred_alpha = float(getattr(self, '_professional_base_predict_alpha', 0.34))
            pred_alpha = max(0.05, min(0.85, pred_alpha))
            try:
                ingest_stride = int(getattr(self, '_professional_base_predict_ingest_stride', 1))
            except Exception:
                ingest_stride = 1
            try:
                ingest_stride_heavy = int(getattr(self, '_professional_base_predict_ingest_stride_heavy', 2))
            except Exception:
                ingest_stride_heavy = 2
            if heavy_mode:
                ingest_stride = max(ingest_stride, ingest_stride_heavy)
            ingest_stride = max(1, min(8, ingest_stride))
            try:
                min_dt = float(getattr(self, '_professional_base_predict_trail_min_dt', 0.010))
            except Exception:
                min_dt = 0.010
            try:
                min_dsemi = float(getattr(self, '_professional_base_predict_trail_min_dsemi', 0.03))
            except Exception:
                min_dsemi = 0.03
            min_dt = max(0.0, min(0.08, min_dt))
            min_dsemi = max(0.0, min(0.40, min_dsemi))

            trail = getattr(self, '_professional_base_predict_trail', None)
            if not isinstance(trail, list):
                trail = []

            alive = []
            for item in trail:
                try:
                    px, py, ts = float(item[0]), float(item[1]), float(item[2])
                except Exception:
                    continue
                age = now_t - ts
                if 0.0 <= age <= trail_sec:
                    alive.append((px, py, ts))

            try:
                if pred_arr is not None and getattr(pred_arr, 'size', 0) > 0:
                    src = pred_arr[::ingest_stride] if ingest_stride > 1 else pred_arr
                    last_t_alive = float(alive[-1][0]) if alive else -1e9
                    last_y_alive = float(alive[-1][1]) if alive else 0.0
                    for p in src:
                        try:
                            px = float(p[0]); py = float(p[1])
                        except Exception:
                            continue
                        dt_ok = (px - last_t_alive) >= min_dt
                        try:
                            dsemi_ok = abs(float(py) - float(last_y_alive)) >= min_dsemi
                        except Exception:
                            dsemi_ok = True
                        if dt_ok or dsemi_ok:
                            alive.append((px, py, now_t))
                            last_t_alive = px
                            last_y_alive = py
            except Exception:
                pass

            if len(alive) > max_points:
                alive = alive[-max_points:]
            self._professional_base_predict_trail = alive

            if self._professional_base_predict_points is None:
                return
            if not alive:
                self._professional_base_predict_points.set_offsets(_np.empty((0, 2), dtype=_np.float32))
                self._professional_base_predict_points.set_alpha(0.0)
                self._professional_base_predict_points.set_visible(False)
                return

            arr = _np.asarray([(it[0], it[1]) for it in alive], dtype=_np.float32)
            ages = _np.asarray([max(0.0, now_t - float(it[2])) for it in alive], dtype=_np.float32)
            life = _np.clip(1.0 - (ages / max(1e-6, trail_sec)), 0.0, 1.0)
            alpha_vec = pred_alpha * _np.power(life, fade_pow)
            scale_vec = min_scale + (1.0 - min_scale) * life
            size_vec = ((float(diameter) * pred_scale * scale_vec) ** 2).astype(_np.float32, copy=False)

            base_rgb = tuple(getattr(self, '_professional_base_point_color', (0.68, 0.90, 1.00)))
            try:
                r, g, b = float(base_rgb[0]), float(base_rgb[1]), float(base_rgb[2])
            except Exception:
                r, g, b = 0.68, 0.90, 1.00
            colors = _np.empty((arr.shape[0], 4), dtype=_np.float32)
            colors[:, 0] = r
            colors[:, 1] = g
            colors[:, 2] = b
            colors[:, 3] = alpha_vec.astype(_np.float32, copy=False)

            self._professional_base_predict_points.set_offsets(arr)
            self._professional_base_predict_points.set_sizes(size_vec)
            self._professional_base_predict_points.set_color(colors)
            # 让每个点的RGBA透明度生效，避免被Collection全局alpha=0覆盖
            self._professional_base_predict_points.set_alpha(1.0)
            self._professional_base_predict_points.set_visible(True)
        except Exception:
            try:
                import numpy as _np
                if self._professional_base_predict_points is not None:
                    self._professional_base_predict_points.set_offsets(_np.empty((0, 2), dtype=_np.float32))
                    self._professional_base_predict_points.set_alpha(0.0)
                    self._professional_base_predict_points.set_visible(False)
            except Exception:
                pass

    def update_professional_display(self):
        """刷新专业模式显示（多频段点云）"""
        if getattr(self, 'professional_ax', None) is None or getattr(self, 'professional_canvas', None) is None:
            return
        rt_t0 = time.perf_counter()
        rt_queue_lag_s = 0.0
        # 录音态兜底：若时间轴定时器未驱动，尝试以墙钟同步 current_global_time
        try:
            recording = bool(getattr(self, 'is_recording_active', False))
        except Exception:
            recording = False
        if recording:
            try:
                if getattr(self, '_external_paused', False) or getattr(self, 'is_recording_paused', False):
                    raise RuntimeError("skip_time_sync_paused")
                if bool(getattr(self, '_retake_countdown_active', False)) and bool(getattr(self, '_retake_countdown_block_add', False)):
                    raise RuntimeError("skip_time_sync_countdown")
                st = getattr(self, 'start_time', None)
                if st is not None:
                    acc_pause = float(getattr(self, '_accumulated_pause_dur', 0.0))
                    shift = float(getattr(self, '_time_offset_shift', 0.0))
                    inferred = max(0.0, time.time() - float(st) - acc_pause + shift)
                    # 防止时间线领先于已到达数据太多，造成“新点追不上线”
                    try:
                        max_lead = float(getattr(self, '_professional_realtime_cursor_max_lead', 0.09))
                    except Exception:
                        max_lead = 0.09
                    latest_data_t = 0.0
                    try:
                        bh = getattr(self, '_professional_base_history', None)
                        if bh:
                            latest_data_t = max(latest_data_t, float(bh[-1][0]))
                    except Exception:
                        pass
                    try:
                        rh = getattr(self, '_professional_raw_history', None)
                        if rh:
                            latest_data_t = max(latest_data_t, float(rh[-1][0]))
                    except Exception:
                        pass
                    try:
                        latest_data_t = max(latest_data_t, float(getattr(self, 'last_pitch_time', 0.0) or 0.0))
                    except Exception:
                        pass
                    try:
                        latest_data_t = max(latest_data_t, float(getattr(self, '_professional_last_base_t', 0.0) or 0.0))
                    except Exception:
                        pass
                    try:
                        cur = float(getattr(self, 'current_global_time', 0.0) or 0.0)
                    except Exception:
                        cur = 0.0
                    try:
                        last_data_wall_t = float(getattr(self, '_professional_last_data_wall_t', 0.0) or 0.0)
                    except Exception:
                        last_data_wall_t = 0.0
                    try:
                        idle_gap = float(getattr(self, '_professional_data_idle_fallback_sec', 0.28))
                    except Exception:
                        idle_gap = 0.28
                    data_recent = (last_data_wall_t > 0.0) and ((time.time() - last_data_wall_t) <= max(0.08, idle_gap))
                    stale_gap = max(0.0, float(inferred) - float(latest_data_t))
                    try:
                        self._professional_realtime_stale_gap = float(stale_gap)
                    except Exception:
                        pass
                    if latest_data_t > 0.0 and max_lead >= 0.0:
                        try:
                            lead_cap = float(getattr(self, '_professional_realtime_max_lead_cap', 1.80))
                        except Exception:
                            lead_cap = 1.80
                        if recording and stale_gap > 0.35:
                            dyn_lead = min(max(max_lead, stale_gap * 0.55), max(0.0, lead_cap))
                        else:
                            dyn_lead = max_lead
                        inferred = min(inferred, latest_data_t + dyn_lead)
                    # 数据时钟优先：有新数据时不让墙钟强推时间线，避免“录音31s但时间线40s”
                    if data_recent and latest_data_t > 0.0:
                        if stale_gap <= 0.35:
                            inferred = min(inferred, latest_data_t + max(0.0, max_lead))
                    cur = float(getattr(self, 'current_global_time', 0.0) or 0.0)
                    # 基频实时优先：只要有新基频数据就单调追到数据时间，避免“线先走/后找点”
                    if latest_data_t > cur + 0.006:
                        try:
                            self.current_global_time = max(cur, latest_data_t)
                            cur = float(self.current_global_time)
                        except Exception:
                            pass
                    # 仅在无新数据一段时间后才启用墙钟兜底推进
                    allow_wall_fallback = (not data_recent) or (latest_data_t <= 1e-6)
                    if allow_wall_fallback and inferred > cur + 0.05:
                        self.current_global_time = inferred
                    else:
                        try:
                            hard_sync_gap = float(getattr(self, '_professional_realtime_hard_sync_gap', 2.20))
                        except Exception:
                            hard_sync_gap = 2.20
                        # 数据明显滞后（常见于队列堆积）时，强制时间线追到录音实时位置
                        if stale_gap > max(0.6, hard_sync_gap) and inferred > cur + 0.08:
                            self.current_global_time = inferred
            except Exception:
                pass
        try:
            force_redraw = bool(getattr(self, '_professional_force_redraw', False))
        except Exception:
            force_redraw = False
        try:
            force_rebuild = bool(getattr(self, '_professional_force_rebuild', False))
        except Exception:
            force_rebuild = False
        try:
            prev_recording = bool(getattr(self, '_professional_prev_recording_state', recording))
        except Exception:
            prev_recording = recording
        if prev_recording and (not recording):
            force_rebuild = True
            try:
                self._professional_force_rebuild = True
            except Exception:
                pass
        try:
            self._professional_prev_recording_state = bool(recording)
        except Exception:
            pass
        # 节流刷新，降低卡顿（强制重绘/重建时跳过节流）
        try:
            now_t = time.time()
            min_iv = float(getattr(self, '_professional_min_update_interval', 0.03))
            try:
                target_fps = float(getattr(self, '_professional_target_fps', 55.0))
                if target_fps > 1.0:
                    min_iv = min(min_iv, 1.0 / target_fps)
            except Exception:
                pass
            try:
                if isinstance(self._professional_pending, list):
                    _pl = len(self._professional_pending)
                else:
                    _pl = len(self._professional_pending)
            except Exception:
                _pl = 0
            try:
                fast_age = now_t - float(getattr(self, '_professional_fast_change_t', 0.0) or 0.0)
                fast_active = recording and fast_age < 0.28
            except Exception:
                fast_active = False
            try:
                self._professional_fast_active = bool(fast_active)
            except Exception:
                pass
            fast_mode = bool(recording and (fast_active or (_pl > 1400)))
            try:
                self._professional_fast_mode = bool(fast_mode)
            except Exception:
                pass
            if recording:
                try:
                    rec_min_iv = float(getattr(self, '_professional_recording_min_update_interval', 0.016))
                except Exception:
                    rec_min_iv = 0.016
                min_iv = min(min_iv, max(0.010, rec_min_iv))
            if _pl < 800 and recording:
                min_iv = min(min_iv, 0.022)
            elif _pl > 2400:
                try:
                    heavy_iv = float(getattr(self, '_professional_pending_heavy_min_update_interval', 0.028))
                except Exception:
                    heavy_iv = 0.028
                min_iv = max(min_iv, max(0.016, heavy_iv))
            if fast_active:
                min_iv = min(min_iv, 0.012)
            if fast_mode:
                min_iv = min(min_iv, 0.012)
            if (now_t - float(getattr(self, '_professional_last_update_t', 0.0))) < min_iv:
                if not (force_redraw or force_rebuild):
                    return
            self._professional_last_update_t = now_t
        except Exception:
            pass
        # 热力图更新节流（快速变化时降低重负担，保证主线实时性）
        try:
            heat_interval = float(getattr(self, '_professional_heat_min_interval', 0.065))
            if recording:
                heat_interval = max(heat_interval, float(getattr(self, '_professional_heat_lowfreq_interval', 0.12)))
                if bool(getattr(self, '_professional_rt_degrade_heat', False)):
                    heat_interval = max(heat_interval, 0.22)
            if recording and (fast_active or _pl > 1400):
                heat_interval = max(heat_interval, 0.20)
            try:
                cur_gt0 = float(getattr(self, 'current_global_time', 0.0) or 0.0)
                last_pitch0 = float(getattr(self, 'last_pitch_time', 0.0) or 0.0)
                silent_thr0 = float(getattr(self, '_professional_silence_threshold', 0.16))
                silent_mode = bool(recording and ((cur_gt0 - last_pitch0) > silent_thr0))
            except Exception:
                silent_mode = False
            if silent_mode:
                heat_interval = min(heat_interval, 0.06)
            heat_update_due = (time.time() - float(getattr(self, '_professional_heat_last_t', 0.0))) >= heat_interval
        except Exception:
            heat_update_due = True
            silent_mode = False
        try:
            # 时间窗口
            x0 = float(getattr(self, 'time_offset', 0.0))
            x1 = x0 + float(getattr(self, 'time_window', 16.0))
        except Exception:
            x0, x1 = 0.0, 16.0
        # 录音中才自动跟随到最新时间，避免停止后无法回到 0s
        try:
            recording = bool(getattr(self, 'is_recording_active', False))
        except Exception:
            recording = False
        try:
            keep_history = bool(getattr(self, '_professional_keep_history', True))
        except Exception:
            keep_history = True
        try:
            fixed_window = bool(getattr(self, '_professional_fixed_window', True))
        except Exception:
            fixed_window = True
        try:
            auto_follow = bool(getattr(self, 'auto_follow', True) and getattr(self, 'auto_scroll_enabled', True))
        except Exception:
            auto_follow = True
        try:
            if recording and bool(getattr(self, '_professional_force_follow', True)):
                auto_follow = True
        except Exception:
            pass
        try:
            if isinstance(self._professional_pending, list):
                pending_len = len(self._professional_pending)
            else:
                pending_len = len(self._professional_pending)
        except Exception:
            pending_len = 0
        try:
            self._professional_rt_last_pending = int(pending_len)
        except Exception:
            pass
        try:
            cur_gt = float(getattr(self, 'current_global_time', 0.0) or 0.0)
            last_pitch = float(getattr(self, 'last_pitch_time', 0.0) or 0.0)
            silent_thr = float(getattr(self, '_professional_silence_threshold', 0.16))
            silent_mode = bool(recording and ((cur_gt - last_pitch) > silent_thr))
        except Exception:
            silent_mode = False
            cur_gt = float(getattr(self, 'current_global_time', 0.0) or 0.0)
        try:
            center_t_rt = float(getattr(self, 'center_display_time', 8.0) or 8.0)
        except Exception:
            center_t_rt = 8.0
        scroll_phase = bool(recording and auto_follow and (cur_gt > center_t_rt))
        try:
            self._professional_rt_scroll_phase = scroll_phase
        except Exception:
            pass
        try:
            latest_true_t = 0.0
            bh = getattr(self, '_professional_base_history', None)
            if bh:
                latest_true_t = max(latest_true_t, float(bh[-1][0]))
        except Exception:
            latest_true_t = 0.0
        try:
            mr = getattr(self, '_professional_main_recent', None)
            if mr:
                latest_true_t = max(latest_true_t, float(mr[-1][0]))
        except Exception:
            pass
        try:
            latest_true_t = max(latest_true_t, float(getattr(self, '_professional_last_base_t', 0.0) or 0.0))
        except Exception:
            pass
        if recording and latest_true_t > 0.0:
            rt_queue_lag_s = max(0.0, float(cur_gt) - float(latest_true_t))
        try:
            self._professional_rt_last_queue_lag_s = float(rt_queue_lag_s)
        except Exception:
            pass
        try:
            lag_harm = float(getattr(self, '_professional_rt_degrade_harm_lag_s', 0.14))
        except Exception:
            lag_harm = 0.14
        try:
            lag_heat = float(getattr(self, '_professional_rt_degrade_heat_lag_s', 0.20))
        except Exception:
            lag_heat = 0.20
        try:
            self._professional_rt_degrade_harm = bool(recording and ((rt_queue_lag_s > lag_harm) or (pending_len > 1800)))
            self._professional_rt_degrade_heat = bool(recording and ((rt_queue_lag_s > lag_heat) or (pending_len > 2400)))
        except Exception:
            pass
        try:
            if scroll_phase and recording:
                if rt_queue_lag_s > 0.08 or pending_len > 1400:
                    self._professional_rt_degrade_harm = True
                if rt_queue_lag_s > 0.12 or pending_len > 1900:
                    self._professional_rt_degrade_heat = True
        except Exception:
            pass
        # 录音态防跳变：抑制跨路径写入导致的 current_global_time 突然跳前/跳后
        try:
            if recording and bool(getattr(self, '_professional_jump_guard_enabled', True)):
                now_guard = time.time()
                try:
                    cur_guard = float(getattr(self, 'current_global_time', 0.0) or 0.0)
                except Exception:
                    cur_guard = 0.0
                try:
                    last_guard = float(getattr(self, '_professional_last_gt', cur_guard) or cur_guard)
                except Exception:
                    last_guard = cur_guard
                try:
                    last_guard_wall = float(getattr(self, '_professional_last_gt_wall', 0.0) or 0.0)
                except Exception:
                    last_guard_wall = 0.0
                try:
                    back_tol = float(getattr(self, '_professional_jump_backward_tol', 0.08))
                except Exception:
                    back_tol = 0.08
                try:
                    fwd_tol = float(getattr(self, '_professional_jump_forward_tol', 0.90))
                except Exception:
                    fwd_tol = 0.90
                back_tol = max(0.01, back_tol)
                fwd_tol = max(0.20, fwd_tol)
                if last_guard_wall > 0.0:
                    dt_guard = max(0.0, min(0.50, now_guard - last_guard_wall))
                    min_allowed = max(0.0, last_guard - back_tol)
                    max_allowed = last_guard + max(0.18, dt_guard * 2.4 + fwd_tol)
                    if cur_guard < min_allowed:
                        cur_guard = min_allowed
                    elif cur_guard > max_allowed:
                        cur_guard = max_allowed
                try:
                    st_guard = float(getattr(self, 'start_time', 0.0) or 0.0)
                except Exception:
                    st_guard = 0.0
                if st_guard > 0.0:
                    try:
                        acc_guard = float(getattr(self, '_accumulated_pause_dur', 0.0) or 0.0)
                    except Exception:
                        acc_guard = 0.0
                    try:
                        shift_guard = float(getattr(self, '_time_offset_shift', 0.0) or 0.0)
                    except Exception:
                        shift_guard = 0.0
                    elapsed_guard = max(0.0, now_guard - st_guard - acc_guard + shift_guard)
                    if cur_guard > elapsed_guard + max(0.25, fwd_tol):
                        cur_guard = elapsed_guard + max(0.12, min(0.45, fwd_tol * 0.5))
                self.current_global_time = max(0.0, float(cur_guard))
                self._professional_last_gt = float(self.current_global_time)
                self._professional_last_gt_wall = now_guard
            else:
                self._professional_last_gt_wall = 0.0
        except Exception:
            pass
        try:
            backlog_limit = int(getattr(self, '_professional_pending_limit', 6000))
            if backlog_limit <= 0:
                backlog_limit = 6000
        except Exception:
            backlog_limit = 6000
        # 录音起始零点硬锁：短时间内强制窗口从 0s 起跑，防止继承历史 offset/时钟
        startup_lock_visual = False
        try:
            if recording:
                now_wall = time.time()
                start_wall = float(getattr(self, '_professional_recording_start_wall', 0.0) or 0.0)
                if start_wall <= 0.0:
                    start_wall = now_wall
                    self._professional_recording_start_wall = start_wall
                lock_sec = float(getattr(self, '_professional_start_zero_lock_sec', 0.65))
                lock_until = float(getattr(self, '_professional_force_zero_window_until', 0.0) or 0.0)
                if lock_until <= 0.0:
                    lock_until = start_wall + max(0.0, lock_sec)
                    self._professional_force_zero_window_until = lock_until
                try:
                    guard_max = float(getattr(self, '_professional_start_guard_max_sec', 1.6))
                except Exception:
                    guard_max = 1.6
                guard_max = max(0.7, min(3.0, guard_max))
                guard_until = max(lock_until, start_wall + guard_max)
                retake_like = bool(
                    getattr(self, '_retake_countdown_active', False)
                    or getattr(self, '_retake_countdown_block_add', False)
                    or getattr(self, '_retake_overlay_enabled', False)
                    or getattr(self, '_retake_preserve_timeline', False)
                )
                if (not retake_like) and now_wall <= guard_until:
                    self._professional_start_zero_lock_active = True
                    startup_lock_visual = True
                    elapsed = max(0.0, now_wall - start_wall)
                    try:
                        cur_gt_lock = float(getattr(self, 'current_global_time', 0.0) or 0.0)
                    except Exception:
                        cur_gt_lock = 0.0
                    clamp_margin = float(getattr(self, '_professional_start_zero_clamp_margin', 0.12))
                    clamp_margin = max(0.05, clamp_margin)
                    if cur_gt_lock > elapsed + clamp_margin:
                        self.current_global_time = elapsed
                    if float(getattr(self, 'time_offset', 0.0) or 0.0) != 0.0:
                        self.time_offset = 0.0
                    try:
                        tw_lock = float(getattr(self, 'time_window', 16.0))
                    except Exception:
                        tw_lock = 16.0
                    x0, x1 = 0.0, tw_lock
                    self._professional_smoothed_xlim = (x0, x1)
                    self._professional_smooth_last_t = now_wall
                else:
                    self._professional_start_zero_lock_active = False
            else:
                self._professional_start_zero_lock_active = False
        except Exception:
            pass
        if startup_lock_visual:
            auto_follow = False
        if recording and auto_follow and pending_len > backlog_limit * 4:
            auto_follow = False
        if recording and auto_follow:
            # 录音态解耦：避免共享 time_offset 被其它路径改写后把专业模式窗口拖到异常时间段
            try:
                sm = getattr(self, '_professional_smoothed_xlim', None)
                if isinstance(sm, (tuple, list)) and len(sm) == 2:
                    x0 = float(sm[0]); x1 = float(sm[1])
                else:
                    cur_gt_follow = float(getattr(self, 'current_global_time', 0.0) or 0.0)
                    center_follow = float(getattr(self, 'center_display_time', 8.0))
                    tw_follow = float(getattr(self, 'time_window', 16.0))
                    x0 = 0.0 if cur_gt_follow <= center_follow else max(0.0, cur_gt_follow - center_follow)
                    x1 = x0 + tw_follow
            except Exception:
                pass
        # 保留历史：若固定窗口则不改动 x0/x1（与普通模式一致，仅滚动查看）
        if keep_history and (not fixed_window):
            try:
                last_item = None
                try:
                    last_item = self.harmonic_history[-1]
                except Exception:
                    last_item = None
                if last_item is not None:
                    last_t = float(last_item[0])
                else:
                    last_t = float(getattr(self, 'current_global_time', 0.0))
                if last_t > x1:
                    x1 = last_t
                if x0 != 0.0:
                    x0 = 0.0
            except Exception:
                pass

        # 专业模式时间轴平滑：在录音+自动跟随时对 x0/x1 做轻量平滑，避免跳跃式移动
        try:
            if recording and auto_follow:
                try:
                    center_t = float(getattr(self, 'center_display_time', 8.0))
                except Exception:
                    center_t = 8.0
                try:
                    cur_gt = float(getattr(self, 'current_global_time', 0.0) or 0.0)
                except Exception:
                    cur_gt = 0.0
                if cur_gt <= center_t:
                    target_x0 = 0.0
                else:
                    target_x0 = max(0.0, cur_gt - center_t)
                try:
                    tw = float(getattr(self, 'time_window', 16.0))
                except Exception:
                    tw = float(x1 - x0) if (x1 - x0) > 1e-6 else 16.0
                target_x1 = target_x0 + tw
                import time as _t
                now_t = _t.time()
                last_t = getattr(self, '_professional_smooth_last_t', None)
                dt = 0.0 if last_t is None else max(0.004, min(0.080, now_t - last_t))
                ideal_dt = 0.02
                try:
                    ideal_dt = max(0.008, float(getattr(self, 'fast_update_interval_ms', 20)) / 1000.0)
                except Exception:
                    pass
                if self._professional_smoothed_xlim is None:
                    self._professional_smoothed_xlim = (target_x0, target_x1)
                s_cur, e_cur = self._professional_smoothed_xlim
                width = float(target_x1 - target_x0)
                if width <= 1e-6:
                    width = float(getattr(self, 'time_window', 16.0))
                c_tar = (float(target_x0) + float(target_x1)) * 0.5
                c_cur = (float(s_cur) + float(e_cur)) * 0.5
                backlog = abs(c_tar - c_cur)
                try:
                    stale_gap_live = float(getattr(self, '_professional_realtime_stale_gap', 0.0) or 0.0)
                except Exception:
                    stale_gap_live = 0.0
                try:
                    snap_backlog = float(getattr(self, '_professional_timeline_snap_backlog', 0.14))
                except Exception:
                    snap_backlog = 0.14
                # 大跳变直接对齐，避免拖影
                if backlog > width * 0.75:
                    c_new = c_tar
                elif recording and stale_gap_live > 1.0:
                    # 严重滞后时直接跟随目标窗口，尽快恢复实时
                    c_new = c_tar
                elif recording and backlog > max(0.06, snap_backlog):
                    # 录音态优先实时：积压达到阈值时快速贴合目标中心
                    c_new = c_cur + (c_tar - c_cur) * 0.92
                else:
                    try:
                        frac = (dt / ideal_dt) if ideal_dt > 1e-6 else 1.0
                        frac = max(0.0, min(4.0, frac))
                        strength = 0.92
                        eff = 1.0 - pow(max(0.0, 1.0 - float(strength)), frac)
                    except Exception:
                        eff = 0.92
                    delta = (c_tar - c_cur) * eff
                    max_step = 0.36 * (dt / ideal_dt if ideal_dt > 0 else 1.0)
                    # 追赶积压时放宽步长
                    if backlog > 0.25:
                        max_step = max(max_step, 0.52)
                    if delta > max_step:
                        delta = max_step
                    elif delta < -max_step:
                        delta = -max_step
                    c_new = c_cur + delta
                s_new = c_new - width * 0.5
                e_new = c_new + width * 0.5
                x0, x1 = float(s_new), float(e_new)
                self._professional_smoothed_xlim = (x0, x1)
                self._professional_smooth_last_t = now_t
            else:
                self._professional_smoothed_xlim = (x0, x1)
                self._professional_smooth_last_t = None
        except Exception:
            pass
        else:
            # 非录音态：若无新点且窗口未变，跳过重绘以减少卡顿
            try:
                if not force_redraw:
                    if not (isinstance(self._professional_pending, list) and self._professional_pending) and (
                        not isinstance(self._professional_pending, list) and len(self._professional_pending) == 0
                    ):
                        last_x0 = getattr(self, '_professional_last_x0', None)
                        if last_x0 is not None and abs(float(last_x0) - float(x0)) < 1e-6:
                            return
            except Exception:
                pass

        # 频率范围与log轴
        min_f, max_f = self._professional_get_freq_range()
        y0 = math.log2(min_f)
        y1 = math.log2(max_f)

        # 时间分箱
        try:
            bin_w = float(getattr(self, '_professional_time_bin', 0.05))
        except Exception:
            bin_w = 0.05
        bin_w = max(0.02, min(0.10, bin_w))
        # 参考普通模式的灵敏度：录音时提高时间分辨率
        try:
            if recording:
                if pending_len < 1200:
                    bin_w = max(0.02, min(bin_w * 0.85, 0.040))
                else:
                    bin_w = max(bin_w, 0.04)
                try:
                    if fast_active:
                        bin_w = max(0.02, min(bin_w * 0.70, 0.028))
                except Exception:
                    pass
        except Exception:
            pass
        span = max(1.0, (x1 - x0))
        # 历史模式下自适应分箱（非固定窗口时启用）
        try:
            max_bins = int(getattr(self, '_professional_max_bins', 512))
        except Exception:
            max_bins = 512
        if keep_history and (not fixed_window) and span > float(getattr(self, 'time_window', 16.0)):
            bin_w = max(bin_w, span / float(max_bins))
        time_bins = max(64, min(max_bins, int(span / bin_w)))
        freq_bins = int(getattr(self, '_professional_freq_bins', 96) or 96)
        try:
            if recording and pending_len < 1200:
                freq_bins = min(176, max(freq_bins, 128))
        except Exception:
            pass
        freq_bins = max(48, min(160, freq_bins))

        # 初始化热力图缓存
        try:
            import numpy as _np
            need_rebuild = False
            if self._professional_heat_buffer is None or self._professional_heat_buffer.shape != (time_bins, freq_bins):
                self._professional_heat_buffer = _np.zeros((time_bins, freq_bins), dtype=_np.float32)
                self._professional_last_x0 = float(x0)
                need_rebuild = True
        except Exception:
            self._professional_heat_buffer = np.zeros((time_bins, freq_bins), dtype=np.float32)
            self._professional_last_x0 = float(x0)
            need_rebuild = True
        if force_rebuild:
            need_rebuild = True

        # 非录音且固定窗口：按窗口重建历史（支持滚动查看）
        rebuild_from_history = False
        if keep_history and fixed_window and (not recording):
            try:
                last_x0 = float(self._professional_last_x0) if self._professional_last_x0 is not None else None
                if force_rebuild or (last_x0 is None) or abs(float(x0) - float(last_x0)) > max(1e-4, bin_w * 0.2):
                    rebuild_from_history = True
            except Exception:
                rebuild_from_history = True

        if keep_history and (need_rebuild or rebuild_from_history):
            try:
                import numpy as _np
                self._professional_heat_buffer[:] = 0.0
                try:
                    defer_harmonics = bool(getattr(self, '_professional_defer_harmonics_until_stop', True))
                except Exception:
                    defer_harmonics = True
                if bool(getattr(self, '_professional_rt_degrade_harm', False)):
                    defer_harmonics = True
                for item in list(getattr(self, 'harmonic_history', [])):
                    try:
                        if isinstance(item, (list, tuple)):
                            if len(item) >= 4:
                                t, f, c, src = item[0], item[1], item[2], item[3]
                            elif len(item) == 3:
                                t, f, c = item
                                src = "true"
                            else:
                                continue
                        else:
                            continue
                        if recording and defer_harmonics and str(src) == "harm":
                            continue
                        if t < x0 - bin_w or t > x1 + bin_w:
                            continue
                        xi = int((float(t) - x0) / bin_w)
                        if xi < 0 or xi >= time_bins:
                            continue
                        ylog = math.log2(max(1.0, float(f)))
                        if ylog < y0 or ylog > y1:
                            continue
                        yi = int((ylog - y0) / (y1 - y0) * (freq_bins - 1))
                        c = max(0.0, min(1.0, float(c)))
                        try:
                            warm_sec = float(getattr(self, '_professional_warmup_sec', 1.0))
                        except Exception:
                            warm_sec = 1.0
                        warm = 1.0
                        try:
                            if warm_sec > 0 and float(t) < warm_sec:
                                warm = max(0.0, float(t) / warm_sec)
                        except Exception:
                            warm = 1.0
                        if str(src) == "harm":
                            cmin = float(getattr(self, '_professional_harmonic_min_conf', 0.05))
                            if c < cmin:
                                continue
                            c = (c * warm) ** 1.2
                        else:
                            cmin = float(getattr(self, '_professional_true_min_conf', 0.03))
                            if c < cmin:
                                continue
                            c = (c * warm) ** 0.6
                        self._professional_heat_buffer[xi, yi] += c
                    except Exception:
                        continue
            except Exception:
                pass
            try:
                self._professional_force_rebuild = False
            except Exception:
                pass
            try:
                self._professional_last_x0 = float(x0)
            except Exception:
                pass

        # 窗口滑动：按 bin 移动缓存（历史重建时跳过）
        if not rebuild_from_history:
            try:
                import numpy as _np
                last_x0 = float(self._professional_last_x0) if self._professional_last_x0 is not None else float(x0)
                shift_bins = int(round((x0 - last_x0) / bin_w))
                if abs(shift_bins) >= time_bins:
                    self._professional_heat_buffer[:] = 0.0
                elif shift_bins != 0:
                    if shift_bins > 0:
                        self._professional_heat_buffer[:-shift_bins, :] = self._professional_heat_buffer[shift_bins:, :]
                        self._professional_heat_buffer[-shift_bins:, :] = 0.0
                    else:
                        sb = abs(shift_bins)
                        self._professional_heat_buffer[sb:, :] = self._professional_heat_buffer[:-sb, :]
                        self._professional_heat_buffer[:sb, :] = 0.0
                    self._professional_last_x0 = last_x0 + shift_bins * bin_w
                else:
                    self._professional_last_x0 = last_x0
            except Exception:
                pass

        # 轻量衰减（可选，保留历史时不衰减）
        if recording and not keep_history:
            try:
                import numpy as _np
                decay = float(getattr(self, '_professional_trail_decay', 0.985))
                self._professional_heat_buffer *= decay
            except Exception:
                pass

        # 增量写入新点（历史重建时跳过）
        try:
            import numpy as _np
            heat_data_dirty = False
            if not rebuild_from_history:
                pending = []
                if isinstance(self._professional_pending, list):
                    pending = self._professional_pending
                    self._professional_pending = []
                else:
                    while self._professional_pending:
                        pending.append(self._professional_pending.popleft())
                if pending:
                    pending_len = len(pending)
                    max_items = int(getattr(self, '_professional_pending_limit', 6000))
                    if max_items <= 0:
                        max_items = 6000
                    try:
                        commit_delay_singing = float(getattr(self, '_professional_commit_delay_singing', 0.10))
                    except Exception:
                        commit_delay_singing = 0.10
                    # 录音态更贴近普通模式实时感：缩短提交延迟
                    if recording:
                        commit_delay_singing = min(commit_delay_singing, 0.015)
                    try:
                        commit_delay_silence = float(getattr(self, '_professional_commit_delay_silence', 0.24))
                    except Exception:
                        commit_delay_silence = 0.24
                    try:
                        cur_gt2 = float(getattr(self, 'current_global_time', 0.0) or 0.0)
                    except Exception:
                        cur_gt2 = 0.0
                    if silent_mode:
                        commit_cutoff = cur_gt2 - max(0.0, commit_delay_silence)
                    else:
                        commit_cutoff = cur_gt2 - max(0.0, commit_delay_singing)
                    try:
                        budget = int(getattr(self, '_professional_pending_budget', 4000))
                        if budget > 0:
                            max_items = min(max_items, budget)
                    except Exception:
                        pass
                    try:
                        if recording and (fast_active or pending_len > 1400):
                            max_items = max(1200, min(max_items, 2200))
                    except Exception:
                        pass
                    if pending_len > max_items:
                        max_items = min(max_items + pending_len // 3, 20000)

                    harm_stride = 1
                    try:
                        defer_harmonics = bool(getattr(self, '_professional_defer_harmonics_until_stop', True))
                    except Exception:
                        defer_harmonics = True
                    if bool(getattr(self, '_professional_rt_degrade_harm', False)):
                        defer_harmonics = True
                    try:
                        if recording and pending_len > 2200:
                            harm_stride = max(harm_stride, int(getattr(self, '_professional_harmonic_draw_stride_heavy', 2)))
                        if recording and pending_len > 4200:
                            harm_stride = max(harm_stride, int(getattr(self, '_professional_harmonic_draw_stride_extreme', 3)))
                    except Exception:
                        harm_stride = max(1, harm_stride)
                    harm_seen = 0
                    try:
                        h_drop = int(getattr(self, '_professional_harmonic_drop_when_backlog', 1500))
                    except Exception:
                        h_drop = 1500
                    try:
                        warm_sec_cfg = float(getattr(self, '_professional_warmup_sec', 1.0))
                    except Exception:
                        warm_sec_cfg = 1.0
                    try:
                        harm_cmin = float(getattr(self, '_professional_harmonic_min_conf', 0.05))
                    except Exception:
                        harm_cmin = 0.05
                    try:
                        true_cmin = float(getattr(self, '_professional_true_min_conf', 0.03))
                    except Exception:
                        true_cmin = 0.03
                    try:
                        pending_append = self._professional_pending.append
                    except Exception:
                        pending_append = None
                    heavy_realtime = bool(recording and (fast_active or pending_len > 1800))

                    # 录音实时优先：积压时保留最新点，避免“越录越落后”
                    if recording and pending_len > 0:
                        try:
                            realtime_tail_sec = float(getattr(self, '_professional_realtime_draw_tail_sec', 2.6))
                        except Exception:
                            realtime_tail_sec = 2.6
                        try:
                            pending_draw_cap = int(getattr(self, '_professional_pending_draw_cap_recording', 1400))
                        except Exception:
                            pending_draw_cap = 1400
                        realtime_tail_sec = max(0.8, min(8.0, realtime_tail_sec))
                        pending_draw_cap = max(300, min(6000, pending_draw_cap))
                        try:
                            keep_recent = int(getattr(self, '_professional_pending_recent_keep', 3200))
                        except Exception:
                            keep_recent = 3200
                        keep_recent = max(max_items, keep_recent)
                        if pending_len > keep_recent:
                            pending = pending[-keep_recent:]
                            pending_len = len(pending)
                        try:
                            drop_lag_s = float(getattr(self, '_professional_realtime_drop_lag_s', 0.35))
                        except Exception:
                            drop_lag_s = 0.35
                        if drop_lag_s > 0.0:
                            lag_floor = cur_gt2 - drop_lag_s
                            _new_pending = []
                            for it in pending:
                                try:
                                    tt = float(it[0]) if isinstance(it, (list, tuple)) and len(it) >= 2 else None
                                except Exception:
                                    tt = None
                                if tt is None or tt >= lag_floor:
                                    _new_pending.append(it)
                            if _new_pending:
                                pending = _new_pending
                                pending_len = len(pending)
                        # 仅绘制录制态最新时间尾部，避免旧包拖慢实时渲染
                        try:
                            newest_t_live = float(pending[-1][0]) if pending else cur_gt2
                        except Exception:
                            newest_t_live = cur_gt2
                        tail_floor = max(cur_gt2 - realtime_tail_sec, newest_t_live - realtime_tail_sec)
                        if pending:
                            _tail_pending = []
                            for it in pending:
                                try:
                                    tt = float(it[0]) if isinstance(it, (list, tuple)) and len(it) >= 2 else None
                                except Exception:
                                    tt = None
                                if tt is None or tt >= tail_floor:
                                    _tail_pending.append(it)
                            if _tail_pending:
                                pending = _tail_pending
                                pending_len = len(pending)
                        if pending_len > pending_draw_cap:
                            pending = pending[-pending_draw_cap:]
                            pending_len = len(pending)
                        # 借鉴普通模式“头部优先”思路：录制态按预算仅处理最新真实点/谐波点
                        try:
                            true_budget = int(getattr(self, '_professional_realtime_true_budget', 760))
                        except Exception:
                            true_budget = 760
                        try:
                            harm_budget = int(getattr(self, '_professional_realtime_harm_budget', 260))
                        except Exception:
                            harm_budget = 260
                        true_budget = max(120, min(2600, true_budget))
                        harm_budget = max(0, min(1800, harm_budget))
                        if bool(getattr(self, '_professional_defer_harmonics_until_stop', True)):
                            harm_budget = 0
                        if fast_active or pending_len > int(max(300, pending_draw_cap * 0.65)):
                            sel_rev = []
                            keep_true = 0
                            keep_harm = 0
                            for it in reversed(pending):
                                src_tag = None
                                try:
                                    if isinstance(it, (list, tuple)) and len(it) >= 4:
                                        src_tag = str(it[3])
                                except Exception:
                                    src_tag = None
                                is_harm_it = (src_tag == 'harm')
                                if is_harm_it:
                                    if keep_harm >= harm_budget:
                                        continue
                                    keep_harm += 1
                                    sel_rev.append(it)
                                else:
                                    if keep_true >= true_budget:
                                        continue
                                    keep_true += 1
                                    sel_rev.append(it)
                                if keep_true >= true_budget and keep_harm >= harm_budget:
                                    break
                            if sel_rev:
                                pending = list(reversed(sel_rev))
                                pending_len = len(pending)
                        try:
                            newest_t = float(pending[-1][0]) if pending else cur_gt2
                            queue_lag = max(0.0, cur_gt2 - newest_t)
                        except Exception:
                            queue_lag = 0.0
                        if queue_lag > 0.12 or pending_len > int(max_items * 0.85):
                            # 积压时取消提交延迟，优先把最新点画出来
                            commit_cutoff = cur_gt2 + 1.0

                    for item in pending:
                        if isinstance(item, (list, tuple)):
                            if len(item) >= 4:
                                t, f, c, src = item[0], item[1], item[2], item[3]
                            elif len(item) == 3:
                                t, f, c = item
                                src = "true"
                            else:
                                continue
                        else:
                            continue
                        src_tag = src if isinstance(src, str) else str(src)
                        is_harm = (src_tag == "harm")
                        if recording and defer_harmonics and is_harm:
                            continue
                        if recording and is_harm:
                            harm_seen += 1
                            if harm_stride > 1 and (harm_seen % harm_stride) != 0:
                                continue
                            if pending_len > h_drop:
                                continue
                        try:
                            t = float(t)
                            if recording and (t > commit_cutoff):
                                if is_harm and pending_len > int(max_items * 0.8):
                                    continue
                                if pending_append is not None:
                                    pending_append((t, f, c, src_tag))
                                continue
                            if t < x0 - bin_w:
                                continue
                            if t > x1 + bin_w:
                                # 未来点暂存，等待窗口追上
                                if is_harm and recording:
                                    continue
                                if pending_append is not None:
                                    pending_append((t, f, c, src_tag))
                                continue
                            # 计算 bin
                            xi = int((t - x0) / bin_w)
                            if xi < 0 or xi >= time_bins:
                                continue
                            ylog = math.log2(max(1.0, float(f)))
                            if ylog < y0 or ylog > y1:
                                continue
                            yi = int((ylog - y0) / (y1 - y0) * (freq_bins - 1))
                            c = max(0.0, min(1.0, float(c)))
                            warm = 1.0
                            try:
                                if warm_sec_cfg > 0 and t < warm_sec_cfg:
                                    warm = max(0.0, t / warm_sec_cfg)
                            except Exception:
                                warm = 1.0
                            if is_harm:
                                if c < harm_cmin:
                                    continue
                                c = (c * warm) ** (1.15 if heavy_realtime else 1.2)
                            else:
                                if c < true_cmin:
                                    continue
                                c = (c * warm) ** 0.6
                            self._professional_heat_buffer[xi, yi] += c
                            heat_data_dirty = True
                        except Exception:
                            continue
        except Exception:
            heat_data_dirty = False
            pass

        heat = self._professional_heat_buffer

        # 初始化色表
        if self._professional_cmap is None:
            try:
                from matplotlib.colors import LinearSegmentedColormap
                colors = [
                    (0.02, 0.03, 0.05),
                    (0.03, 0.10, 0.20),
                    (0.06, 0.25, 0.45),
                    (0.00, 0.55, 0.70),
                    (0.20, 0.78, 0.60),
                    (0.75, 0.88, 0.40),
                    (0.98, 0.78, 0.35),
                    (0.99, 0.92, 0.80),
                ]
                self._professional_cmap = LinearSegmentedColormap.from_list("pro_heat", colors, N=256)
            except Exception:
                self._professional_cmap = None

        # 绘制热力图
        try:
            lock_recording_heat = bool(getattr(self, '_professional_heat_lock_recording_style', True))
        except Exception:
            lock_recording_heat = True
        try:
            recording_dot_mode = bool(getattr(self, '_professional_heat_recording_dot_mode', True))
        except Exception:
            recording_dot_mode = True
        recording_heat_raw = bool(recording and lock_recording_heat and recording_dot_mode)
        if heat is None:
            heat = np.zeros((time_bins, freq_bins), dtype=np.float32)
        else:
            # 轻量模糊（优先快速路径，避免卡顿）
            try:
                import numpy as _np
                if recording_heat_raw:
                    raise RuntimeError('recording_heat_raw_mode')
                blur_mode = str(getattr(self, '_professional_blur_mode', 'fast')).lower()
                blur_strength = float(getattr(self, '_professional_blur_strength', 1.0))
                blur_strength = max(0.0, min(1.0, blur_strength))
                skip_blur = False
                try:
                    if recording and pending_len > 2000:
                        skip_blur = True
                except Exception:
                    skip_blur = False
                try:
                    if recording:
                        fast_age = time.time() - float(getattr(self, '_professional_fast_change_t', 0.0) or 0.0)
                        if fast_age < 0.28:
                            skip_blur = True
                except Exception:
                    pass
                try:
                    if recording and (fast_active or pending_len > 1400):
                        skip_blur = True
                        blur_strength = 0.0
                except Exception:
                    pass
                try:
                    if recording and bool(getattr(self, '_professional_rt_degrade_heat', False)):
                        skip_blur = True
                        blur_strength = 0.0
                except Exception:
                    pass
                if recording and (not skip_blur) and heat_update_due:
                    if pending_len < 800:
                        blur_strength = min(0.85, blur_strength * 0.90)
                    else:
                        blur_strength = min(0.70, blur_strength * 0.80)
                if heat_update_due and (not skip_blur) and blur_mode == 'fast' and blur_strength > 0.0:
                    base = heat
                    hx1 = _np.roll(base, 1, axis=0)
                    hx2 = _np.roll(base, -1, axis=0)
                    hy1 = _np.roll(base, 1, axis=1)
                    hy2 = _np.roll(base, -1, axis=1)
                    blurred = (base * 4.0 + hx1 + hx2 + hy1 + hy2) / 8.0
                    # 修正边界，避免环绕伪影
                    blurred[0, :] = base[0, :]
                    blurred[-1, :] = base[-1, :]
                    blurred[:, 0] = base[:, 0]
                    blurred[:, -1] = base[:, -1]
                    heat = base * (1.0 - blur_strength) + blurred * blur_strength
                elif heat_update_due and (not skip_blur) and blur_mode == 'gaussian' and blur_strength > 0.0:
                    kernel = _np.array([1.0, 2.0, 1.0], dtype=_np.float32)
                    kernel = kernel / kernel.sum()
                    heat = _np.apply_along_axis(lambda m: _np.convolve(m, kernel, mode='same'), 0, heat)
                    heat = _np.apply_along_axis(lambda m: _np.convolve(m, kernel, mode='same'), 1, heat)
            except Exception:
                pass
        # 动态范围压缩（提升弱谐波）
        try:
            use_gpu = bool(getattr(self, '_professional_use_gpu', False))
        except Exception:
            use_gpu = False
        gpu_done = False
        if (not recording_heat_raw) and use_gpu and heat_update_due:
            try:
                import importlib
                _cp = importlib.import_module("cu" + "py")
                min_size = int(getattr(self, '_professional_gpu_min_size', 80000))
                if heat is not None and heat.size >= min_size:
                    h_gpu = _cp.asarray(heat)
                    h_gpu = _cp.log1p(h_gpu * 6.0)
                    try:
                        if recording:
                            pwr = 1.0 if pending_len < 1200 else 0.92
                        else:
                            pwr = 0.85
                    except Exception:
                        pwr = 0.85
                    h_gpu = _cp.power(h_gpu, pwr)
                    floor_p = 25.0 if keep_history else 40.0
                    floor = float(_cp.percentile(h_gpu, floor_p)) if h_gpu.size else 0.0
                    h_gpu = _cp.maximum(h_gpu - floor, 0.0)
                    heat = _cp.asnumpy(h_gpu)
                    gpu_done = True
            except Exception:
                gpu_done = False
        if (not recording_heat_raw) and (not gpu_done) and heat_update_due and (not bool(getattr(self, '_professional_rt_degrade_heat', False))):
            try:
                import numpy as _np
                heat = _np.log1p(heat * 6.0)
                try:
                    if recording:
                        pwr = 1.0 if pending_len < 1200 else 0.92
                    else:
                        pwr = 0.85
                except Exception:
                    pwr = 0.85
                heat = _np.power(heat, pwr)
                floor_p = 25.0 if keep_history else 40.0
                floor = float(_np.percentile(heat, floor_p)) if heat.size else 0.0
                heat = _np.maximum(heat - floor, 0.0)
            except Exception:
                pass
        if self._professional_im is None:
            self.professional_ax.cla()
            try:
                self.professional_ax.set_facecolor("#0b0f14")
            except Exception:
                pass
            try:
                rec_heat_alpha = float(getattr(self, '_professional_heat_alpha_recording', 0.28))
            except Exception:
                rec_heat_alpha = 0.28
            try:
                idle_heat_alpha = float(getattr(self, '_professional_heat_alpha_idle', 0.85))
            except Exception:
                idle_heat_alpha = 0.85
            heat_alpha = rec_heat_alpha if recording else idle_heat_alpha
            self._professional_im = self.professional_ax.imshow(
                heat.T,
                origin='lower',
                aspect='auto',
                extent=[x0, x1, y0, y1],
                cmap=self._professional_cmap,
                interpolation=('nearest' if recording_heat_raw else 'bilinear'),
                alpha=heat_alpha
            )
            try:
                self._professional_heat_last_t = time.time()
            except Exception:
                pass
            try:
                if self._professional_colorbar is None:
                    self._professional_colorbar = self.professional_figure.colorbar(
                        self._professional_im, ax=self.professional_ax, fraction=0.03, pad=0.02
                    )
                    self._professional_colorbar.set_label('能量/置信度', fontsize=10, color="#d7dbe2")
                    try:
                        self._professional_colorbar.ax.yaxis.set_tick_params(color="#c9d1d9")
                        for lab in self._professional_colorbar.ax.get_yticklabels():
                            lab.set_color("#c9d1d9")
                    except Exception:
                        pass
            except Exception:
                pass
        else:
            try:
                try:
                    rec_heat_alpha = float(getattr(self, '_professional_heat_alpha_recording', 0.28))
                except Exception:
                    rec_heat_alpha = 0.28
                try:
                    idle_heat_alpha = float(getattr(self, '_professional_heat_alpha_idle', 0.85))
                except Exception:
                    idle_heat_alpha = 0.85
                try:
                    lock_recording_heat = bool(getattr(self, '_professional_heat_lock_recording_style', True))
                except Exception:
                    lock_recording_heat = True
                force_heat_push = bool(recording and heat_data_dirty)
                if heat_update_due or force_heat_push:
                    self._professional_im.set_data(heat.T)
                    try:
                        self._professional_heat_last_t = time.time()
                    except Exception:
                        pass
                else:
                    # 非更新帧做短过渡淡化，避免“小点↔热力”来回闪烁
                    try:
                        fade_a = float(getattr(self, '_professional_heat_fade_alpha', 0.15))
                    except Exception:
                        fade_a = 0.15
                    if recording and (not lock_recording_heat):
                        self._professional_im.set_alpha(max(0.20, 0.45 - fade_a))
                self._professional_im.set_extent([x0, x1, y0, y1])
                try:
                    self._professional_im.set_interpolation('nearest' if recording_heat_raw else 'bilinear')
                    if recording and lock_recording_heat:
                        self._professional_im.set_alpha(rec_heat_alpha)
                    elif heat_update_due:
                        self._professional_im.set_alpha(rec_heat_alpha if recording else idle_heat_alpha)
                except Exception:
                    pass
            except Exception:
                pass
            try:
                if self._professional_colorbar is not None:
                    try:
                        if recording and bool(getattr(self, '_professional_skip_colorbar_update_while_recording', True)):
                            raise RuntimeError('skip_colorbar_during_recording')
                        now_cb = time.time()
                        if (now_cb - float(getattr(self, '_professional_colorbar_last_update', 0.0))) > 0.5:
                            self._professional_colorbar.update_normal(self._professional_im)
                            self._professional_colorbar_last_update = now_cb
                    except Exception:
                        try:
                            if not (recording and bool(getattr(self, '_professional_skip_colorbar_update_while_recording', True))):
                                self._professional_colorbar.update_normal(self._professional_im)
                        except Exception:
                            pass
            except Exception:
                pass
        # 动态对比度（避免满屏同色）
        try:
            import numpy as _np
            now_cb = time.time()
            allow_update = True
            try:
                lock_recording_heat = bool(getattr(self, '_professional_heat_lock_recording_style', True))
            except Exception:
                lock_recording_heat = True
            try:
                if recording and (fast_active or pending_len > 1400):
                    allow_update = (now_cb - float(getattr(self, '_professional_clim_last_t', 0.0))) > 0.25
            except Exception:
                pass
            if recording and lock_recording_heat:
                try:
                    rec_clim_iv = float(getattr(self, '_professional_recording_clim_interval', 0.45))
                except Exception:
                    rec_clim_iv = 0.45
                allow_update = heat_update_due and ((now_cb - float(getattr(self, '_professional_clim_last_t', 0.0))) >= max(0.15, rec_clim_iv))
            if allow_update and heat_update_due:
                target_vmax = float(_np.percentile(heat, 99.0)) if heat.size else 1.0
                try:
                    vmax_floor = float(getattr(self, '_professional_vmax_floor', 0.35))
                except Exception:
                    vmax_floor = 0.35
                target_vmax = max(target_vmax, vmax_floor, 1e-4)
                if recording_heat_raw:
                    try:
                        target_vmax = max(target_vmax, float(_np.max(heat)) if heat.size else target_vmax)
                    except Exception:
                        pass
                if recording and lock_recording_heat:
                    try:
                        clim_smooth = float(getattr(self, '_professional_recording_clim_smooth', 0.18))
                    except Exception:
                        clim_smooth = 0.18
                    clim_smooth = max(0.02, min(0.95, clim_smooth))
                    prev_vmax = float(getattr(self, '_professional_vmax_cache', target_vmax) or target_vmax)
                    vmax = (1.0 - clim_smooth) * prev_vmax + clim_smooth * target_vmax
                    try:
                        if bool(getattr(self, '_professional_recording_clim_only_rise', True)):
                            vmax = max(prev_vmax, vmax)
                    except Exception:
                        pass
                else:
                    vmax = target_vmax
                self._professional_vmax_cache = vmax
                self._professional_clim_last_t = now_cb
            else:
                vmax = float(getattr(self, '_professional_vmax_cache', 1.0) or 1.0)
            self._professional_im.set_clim(0.0, vmax)
        except Exception:
            pass

        # 轴与标签
        axis_style_due = True
        try:
            self.professional_ax.set_xlim(x0, x1)
            self.professional_ax.set_ylim(y0, y1)
            if recording:
                now_axis = time.time()
                try:
                    axis_iv = float(getattr(self, '_professional_axis_style_interval_recording', 0.35))
                except Exception:
                    axis_iv = 0.35
                last_axis = float(getattr(self, '_professional_axis_last_style_t', 0.0) or 0.0)
                axis_style_due = (now_axis - last_axis) >= max(0.10, axis_iv)
                if axis_style_due:
                    self._professional_axis_last_style_t = now_axis
            if axis_style_due:
                self.professional_ax.set_xlabel('时间 (秒)', fontsize=11, color="#d7dbe2")
                self.professional_ax.set_ylabel('频率 (Hz)', fontsize=11, color="#d7dbe2")
                self.professional_ax.set_title('专业模式 · 多频段发声可视化', fontsize=14, fontweight='bold', color="#f0f3f7")
                self.professional_ax.tick_params(colors="#c9d1d9")
        except Exception:
            pass

        # 音名刻度（按八度显示）
        if axis_style_due:
            try:
                ticks = []
                labels = []
                base_freq = 32.703  # C1
                while base_freq < min_f:
                    base_freq *= 2.0
                f = base_freq
                while f <= max_f * 1.01:
                    ticks.append(math.log2(f))
                    labels.append(self._note_label_from_freq(f))
                    f *= 2.0
                self.professional_ax.set_yticks(ticks)
                self.professional_ax.set_yticklabels(labels, color="#c9d1d9")
            except Exception:
                pass

        # 辅助网格线（按半音/音阶）
        try:
            grid_key = (round(min_f, 3), round(max_f, 3))
            if self._professional_grid_range != grid_key:
                # 清理旧网格线
                for ln in list(getattr(self, '_professional_grid_artists', []) or []):
                    try:
                        if ln is not None and ln in getattr(self.professional_ax, 'lines', []):
                            ln.remove()
                    except Exception:
                        pass
                self._professional_grid_artists = []
                self._professional_grid_range = grid_key

                # 半音网格
                try:
                    n0 = int(math.floor(12.0 * math.log2(min_f / 440.0)))
                    n1 = int(math.ceil(12.0 * math.log2(max_f / 440.0)))
                    for n in range(n0, n1 + 1):
                        f = 440.0 * (2.0 ** (n / 12.0))
                        if f < min_f or f > max_f:
                            continue
                        y = math.log2(f)
                        is_oct = (n % 12 == 0)
                        alpha = 0.22 if is_oct else 0.08
                        lw = 0.9 if is_oct else 0.45
                        ln = self.professional_ax.axhline(y=y, color=(1, 1, 1), alpha=alpha, linewidth=lw, zorder=2)
                        self._professional_grid_artists.append(ln)
                except Exception:
                    pass
        except Exception:
            pass

        # 纵向时间辅助线（专业模式专属风格）
        try:
            step = 1.0 if (x1 - x0) <= 18.0 else 2.0
            grid_anchor = int(math.floor(x0 / step))
            vgrid_key = (grid_anchor, step)
            allow_vgrid_rebuild = True
            try:
                if recording:
                    now_vg = time.time()
                    last_vg = float(getattr(self, '_professional_vgrid_last_t', 0.0) or 0.0)
                    iv_vg = float(getattr(self, '_professional_vgrid_interval_recording', 0.80) or 0.80)
                    if (now_vg - last_vg) < max(0.25, iv_vg):
                        allow_vgrid_rebuild = False
            except Exception:
                allow_vgrid_rebuild = True
            if allow_vgrid_rebuild and self._professional_vgrid_range != vgrid_key:
                for ln in list(getattr(self, '_professional_vgrid_artists', []) or []):
                    try:
                        if ln is not None and ln in getattr(self.professional_ax, 'lines', []):
                            ln.remove()
                    except Exception:
                        pass
                self._professional_vgrid_artists = []
                self._professional_vgrid_range = vgrid_key
                # 主刻度线
                start = grid_anchor * step
                t = start
                while t <= x1 + 1e-6:
                    ln = self.professional_ax.axvline(x=t, color=(0.6, 0.8, 1.0), alpha=0.18, linewidth=0.9, linestyle='--', zorder=3)
                    self._professional_vgrid_artists.append(ln)
                    t += step
                # 次刻度线（半步）
                half = step * 0.5
                t = start + half
                while t <= x1 + 1e-6:
                    ln = self.professional_ax.axvline(x=t, color=(0.6, 0.8, 1.0), alpha=0.10, linewidth=0.6, linestyle=':', zorder=3)
                    self._professional_vgrid_artists.append(ln)
                    t += step
                try:
                    self._professional_vgrid_last_t = time.time()
                except Exception:
                    pass
        except Exception:
            pass

        # 当前时间指示线：参考普通模式（<= center_display_time 跟随当前时间，之后锁定居中）
        try:
            center_t = float(getattr(self, 'center_display_time', 8.0))
            try:
                recording = bool(getattr(self, 'is_recording_active', False))
            except Exception:
                recording = False
            try:
                auto_follow = bool(getattr(self, 'auto_follow', True) and getattr(self, 'auto_scroll_enabled', True))
            except Exception:
                auto_follow = True
            if not recording:
                cur_gt = float(getattr(self, '_professional_stop_time', None) or getattr(self, 'current_global_time', 0.0) or 0.0)
            else:
                cur_gt = float(getattr(self, 'current_global_time', 0.0) or 0.0)
            if auto_follow and cur_gt > center_t:
                cur_t = x0 + max(0.0, min(center_t, x1 - x0))
            else:
                cur_t = min(max(x0, cur_gt), x1)
            if not hasattr(self, '_professional_time_cursor') or self._professional_time_cursor is None:
                self._professional_time_cursor = self.professional_ax.axvline(
                    x=cur_t, color=(0.9, 0.95, 1.0), alpha=0.55, linewidth=1.2, linestyle='-', zorder=5
                )
            else:
                try:
                    self._professional_time_cursor.set_xdata([cur_t, cur_t])
                except Exception:
                    pass
        except Exception:
            pass

        # 录制期间强制隐藏泛音小散点，避免覆盖基频白点
        try:
            if recording and getattr(self, '_professional_main_points', None) is not None:
                self._professional_main_points.set_offsets([])
                self._professional_main_points.set_alpha(0.0)
                self._professional_main_points.set_visible(False)
        except Exception:
            pass

        # 基音主线：沿用普通模式细节点/断续逻辑
        base_times = []
        base_pitches = []
        base_median = None
        try:
            base_times, base_pitches = self._build_professional_base_series(x0, x1)
            if base_pitches:
                try:
                    import numpy as _np
                    clean_bp = [p for p in base_pitches if p == p]
                    if clean_bp:
                        base_median = float(_np.median(_np.asarray(clean_bp, dtype=_np.float32)))
                except Exception:
                    base_median = None
        except Exception:
            base_times, base_pitches = [], []
        try:
            if self._professional_base_line is None:
                line_color = str(getattr(self, '_professional_base_line_color', '#FFB6D5'))
                line_w = float(getattr(self, 'current_linewidth', 0.6) or 0.6)
                self._professional_base_line, = self.professional_ax.plot([], [], color=line_color, linewidth=line_w, alpha=0.98, zorder=19)
            elif self._professional_base_line not in getattr(self.professional_ax, 'lines', []):
                try:
                    self.professional_ax.add_line(self._professional_base_line)
                except Exception:
                    pass
            try:
                self._professional_base_line.set_color(str(getattr(self, '_professional_base_line_color', '#FFB6D5')))
                self._professional_base_line.set_linewidth(float(getattr(self, 'current_linewidth', 0.6) or 0.6))
            except Exception:
                pass
            if base_times and base_pitches:
                try:
                    import numpy as _np
                    _bx = _np.asarray(base_times, dtype=_np.float32)
                    _by = _np.asarray(base_pitches, dtype=_np.float32)
                    _ok = _np.isfinite(_bx) & _np.isfinite(_by)
                    _lx = _np.where(_ok, _bx, _np.nan)
                    _ly = _np.where(_ok, _np.log2(_np.maximum(1.0, _by)), _np.nan)
                    self._professional_base_line.set_data(_lx, _ly)
                except Exception:
                    line_x = []
                    line_y = []
                    for t, p in zip(base_times, base_pitches):
                        if t == t and p == p:
                            line_x.append(float(t))
                            line_y.append(math.log2(max(1.0, float(p))))
                        else:
                            line_x.append(float('nan'))
                            line_y.append(float('nan'))
                    self._professional_base_line.set_data(line_x, line_y)
                self._professional_base_line.set_alpha(0.98)
                self._professional_base_line.set_zorder(19)
                self._professional_base_line.set_visible(True)
            else:
                self._professional_base_line.set_data([], [])
                self._professional_base_line.set_alpha(0.0)
                self._professional_base_line.set_visible(False)
        except Exception:
            pass
        try:
            if self._professional_base_points is None:
                base_point_rgb = tuple(getattr(self, '_professional_base_point_color', (0.68, 0.90, 1.00)))
                self._professional_base_points = self.professional_ax.scatter(
                    [], [], s=16, color=base_point_rgb, alpha=0.96,
                    linewidths=0, edgecolors='none', zorder=24
                )
            elif self._professional_base_points not in getattr(self.professional_ax, 'collections', []):
                try:
                    self.professional_ax.add_collection(self._professional_base_points)
                except Exception:
                    pass
            if getattr(self, '_professional_base_head_points', None) is None:
                base_point_rgb = tuple(getattr(self, '_professional_base_point_color', (0.68, 0.90, 1.00)))
                self._professional_base_head_points = self.professional_ax.scatter(
                    [], [], s=24, color=base_point_rgb, alpha=0.0,
                    linewidths=0, edgecolors='none', zorder=23
                )
            elif self._professional_base_head_points not in getattr(self.professional_ax, 'collections', []):
                try:
                    self.professional_ax.add_collection(self._professional_base_head_points)
                except Exception:
                    pass
            if getattr(self, '_professional_base_predict_points', None) is None:
                base_point_rgb = tuple(getattr(self, '_professional_base_point_color', (0.68, 0.90, 1.00)))
                self._professional_base_predict_points = self.professional_ax.scatter(
                    [], [], s=18, marker='o', color=base_point_rgb, alpha=0.0,
                    linewidths=0, edgecolors='none', zorder=25
                )
            elif self._professional_base_predict_points not in getattr(self.professional_ax, 'collections', []):
                try:
                    self.professional_ax.add_collection(self._professional_base_predict_points)
                except Exception:
                    pass
            try:
                lock_base_recording = bool(getattr(self, '_professional_base_points_lock_recording_style', True))
            except Exception:
                lock_base_recording = True
            try:
                base_recording_alpha = float(getattr(self, '_professional_base_points_recording_alpha', 0.92))
            except Exception:
                base_recording_alpha = 0.92
            try:
                base_hold_sec = float(getattr(self, '_professional_base_points_hold_sec', 0.20))
            except Exception:
                base_hold_sec = 0.20
            try:
                base_keepalive_sec = float(getattr(self, '_professional_base_points_keepalive_recording_sec', 6.0))
            except Exception:
                base_keepalive_sec = 6.0
            now_base_draw = time.time()
            if base_times and base_pitches:
                import numpy as _np
                try:
                    edge_pad = float(getattr(self, '_professional_base_point_edge_pad', 0.25))
                except Exception:
                    edge_pad = 0.25
                bt = _np.asarray(base_times, dtype=_np.float32)
                bp = _np.asarray(base_pitches, dtype=_np.float32)
                mask = _np.isfinite(bt) & _np.isfinite(bp)
                if edge_pad > 0.0:
                    mask &= (bt >= float(x0 - edge_pad)) & (bt <= float(x1 + edge_pad))
                if _np.any(mask):
                    arr = _np.column_stack((bt[mask], _np.log2(_np.maximum(1.0, bp[mask])))).astype(_np.float32, copy=False)
                    try:
                        cap = int(getattr(self, '_professional_base_point_cap', 4000))
                    except Exception:
                        cap = 4000
                    # 自适应：快速变化时加密点密度，平稳时适度抽样
                    try:
                        fast_mode = bool(getattr(self, '_professional_fast_mode', False))
                    except Exception:
                        fast_mode = False
                    dt_avg = 0.0
                    try:
                        if arr.shape[0] >= 6:
                            tail_t = arr[-120:, 0] if arr.shape[0] > 120 else arr[:, 0]
                            diffs = _np.diff(tail_t)
                            dt_avg = float(_np.mean(diffs)) if diffs.size else 0.0
                    except Exception:
                        dt_avg = 0.0
                    try:
                        stale_gap_live = float(getattr(self, '_professional_realtime_stale_gap', 0.0) or 0.0)
                    except Exception:
                        stale_gap_live = 0.0
                    if recording:
                        try:
                            cap = int(getattr(self, '_professional_base_point_cap_recording', 6500))
                        except Exception:
                            cap = 6500
                    if fast_mode or (0.0 < dt_avg < 0.035):
                        try:
                            cap = int(getattr(self, '_professional_base_point_cap_fast', 2600))
                        except Exception:
                            cap = 2600
                    if recording and (pending_len > 1200 or stale_gap_live > 0.35):
                        try:
                            heavy_cap = int(getattr(self, '_professional_base_point_cap_heavy', 5000))
                        except Exception:
                            heavy_cap = 5000
                        cap = min(cap, heavy_cap)
                    try:
                        hard_cap = int(getattr(self, '_professional_base_point_cap_hard_max', 9000))
                    except Exception:
                        hard_cap = 9000
                    cap = max(600, min(cap, hard_cap))
                    try:
                        cur_gt3 = float(getattr(self, 'current_global_time', 0.0) or 0.0)
                    except Exception:
                        cur_gt3 = 0.0
                    # 录音态实时优先：仅渲染最近时间窗口，避免历史点堆积导致“越画越不实时”
                    if recording and arr.shape[0] > 0 and cur_gt3 > 0.0:
                        try:
                            rt_win = float(getattr(self, '_professional_base_realtime_render_sec', 3.8))
                        except Exception:
                            rt_win = 3.8
                        try:
                            rt_win_heavy = float(getattr(self, '_professional_base_realtime_render_sec_heavy', 2.2))
                        except Exception:
                            rt_win_heavy = 2.2
                        try:
                            rt_future = float(getattr(self, '_professional_base_realtime_future_margin_s', 0.14))
                        except Exception:
                            rt_future = 0.14
                        # 保证录制态真实基频小点至少覆盖当前可视窗的大部分，避免只剩预测大点可见
                        try:
                            keep_visible_ratio = float(getattr(self, '_professional_base_realtime_keep_visible_ratio', 0.92))
                        except Exception:
                            keep_visible_ratio = 0.92
                        try:
                            if bool(getattr(self, '_professional_rt_scroll_phase', False)):
                                keep_visible_ratio = float(getattr(self, '_professional_base_realtime_keep_visible_ratio_scroll', 0.55))
                        except Exception:
                            pass
                        keep_visible_ratio = max(0.45, min(1.20, keep_visible_ratio))
                        try:
                            view_span = max(0.0, float(x1) - float(x0))
                        except Exception:
                            view_span = 0.0
                        rt_floor = max(1.2, min(24.0, view_span * keep_visible_ratio + 0.35))
                        rt_win = max(1.0, min(8.0, rt_win))
                        rt_win_heavy = max(0.8, min(rt_win, rt_win_heavy))
                        if fast_mode or pending_len > 1200 or stale_gap_live > 0.35:
                            rt_win = max(rt_win_heavy, rt_floor)
                        else:
                            rt_win = max(rt_win, rt_floor)
                        rt_mask = (arr[:, 0] >= float(cur_gt3 - rt_win)) & (arr[:, 0] <= float(cur_gt3 + max(0.02, rt_future)))
                        if _np.any(rt_mask):
                            arr = arr[rt_mask]
                    if cap > 0 and arr.shape[0] > cap:
                        # 优先保留最新尾部，旧点再下采样：保证前沿细节点始终“追得上”
                        keep_tail = int(min(max(180, cap // 3), cap - 1)) if cap > 1 else 0
                        if keep_tail > 0 and arr.shape[0] > keep_tail:
                            head = arr[:-keep_tail]
                            tail = arr[-keep_tail:]
                            head_need = max(0, cap - keep_tail)
                            if head_need > 0 and head.shape[0] > head_need:
                                idx = _np.linspace(0, head.shape[0] - 1, num=head_need, dtype=_np.int32)
                                head = head[idx]
                            arr = _np.vstack((head, tail)) if head.size else tail
                        else:
                            step = int(_np.ceil(arr.shape[0] / cap))
                            arr = arr[::step]
                    # 基频点：对齐普通模式雪花尺寸（最近点轻微放大）
                    base_w = float(getattr(self, 'current_linewidth', 0.6))
                    zoom = float(getattr(self, 'zoom_level', 1.0))
                    min_d = float(getattr(self, '_professional_base_point_min_d', 2.0))
                    max_d = float(getattr(self, '_professional_base_point_max_d', 5.0))
                    diameter = max(min_d, min(base_w * 3.6 / (0.6 if zoom < 1 else min(zoom, 3.0)), max_d))
                    try:
                        self._professional_base_points.set_color(tuple(getattr(self, '_professional_base_point_color', (0.68, 0.90, 1.00))))
                    except Exception:
                        pass
                    self._professional_base_points.set_offsets(arr)
                    if recording:
                        try:
                            self._professional_base_points_last_offsets = arr.copy()
                            self._professional_base_points_last_update_t = now_base_draw
                        except Exception:
                            pass
                    try:
                        cur_gt3 = float(getattr(self, 'current_global_time', 0.0) or 0.0)
                    except Exception:
                        cur_gt3 = 0.0
                    pred_arr = _np.empty((0, 2), dtype=_np.float32)
                    if recording and arr.shape[0] > 0 and cur_gt3 > 0.0:
                        try:
                            pred_pts = self._build_professional_base_predict_points(base_times, base_pitches, x0, x1, cur_gt3)
                            if pred_pts:
                                pred_t = _np.asarray([float(it[0]) for it in pred_pts], dtype=_np.float32)
                                pred_f = _np.asarray([float(it[1]) for it in pred_pts], dtype=_np.float32)
                                pred_arr = _np.column_stack((pred_t, _np.log2(_np.maximum(1.0, pred_f)))).astype(_np.float32, copy=False)
                        except Exception:
                            pred_arr = _np.empty((0, 2), dtype=_np.float32)
                    try:
                        head_window = float(getattr(self, '_professional_base_snowflake_window_s', 1.0))
                    except Exception:
                        head_window = 1.0
                    try:
                        head_scale = float(getattr(self, '_professional_base_snowflake_scale', 1.35))
                    except Exception:
                        head_scale = 1.35
                    try:
                        snow_alpha = float(getattr(self, '_professional_base_snowflake_alpha', 0.60))
                    except Exception:
                        snow_alpha = 0.60
                    try:
                        glow_alpha = float(getattr(self, '_professional_base_snowflake_glow_alpha', 0.34))
                    except Exception:
                        glow_alpha = 0.34
                    try:
                        heavy_points_mode = bool(recording and (fast_mode or pending_len > 1200 or stale_gap_live > 0.35))
                    except Exception:
                        heavy_points_mode = False
                    if recording and lock_base_recording:
                        try:
                            rec_point_scale = float(getattr(self, '_professional_base_point_recording_scale', 0.82))
                        except Exception:
                            rec_point_scale = 0.82
                        rec_point_scale = max(0.45, min(1.0, rec_point_scale))
                        self._professional_base_points.set_sizes([(diameter * rec_point_scale) ** 2])
                        self._professional_base_points.set_alpha(base_recording_alpha)
                        if self._professional_base_head_points is not None:
                            self._professional_base_head_points.set_offsets(_np.empty((0, 2), dtype=_np.float32))
                            self._professional_base_head_points.set_alpha(0.0)
                            self._professional_base_head_points.set_visible(False)
                    elif arr.shape[0] > 0 and cur_gt3 > 0 and (not heavy_points_mode):
                        dt = cur_gt3 - arr[:, 0]
                        size_hi = (diameter * head_scale) ** 2
                        size_lo = (diameter) ** 2
                        sizes = _np.where(dt <= head_window, size_hi, size_lo)
                        self._professional_base_points.set_sizes(sizes)
                        self._professional_base_points.set_alpha(0.98)
                        if self._professional_base_head_points is not None:
                            try:
                                head_mask = _np.logical_and(dt >= 0.0, dt <= head_window)
                                if _np.any(head_mask):
                                    head_arr = arr[head_mask]
                                    glow_scale = float(getattr(self, '_professional_base_snowflake_glow_scale', 1.85))
                                    glow_size = (diameter * glow_scale) ** 2
                                    self._professional_base_head_points.set_color(tuple(getattr(self, '_professional_base_point_color', (0.68, 0.90, 1.00))))
                                    self._professional_base_head_points.set_offsets(head_arr)
                                    self._professional_base_head_points.set_sizes([glow_size] * head_arr.shape[0])
                                    self._professional_base_head_points.set_alpha(glow_alpha)
                                    self._professional_base_head_points.set_visible(True)
                                else:
                                    self._professional_base_head_points.set_offsets(_np.empty((0, 2), dtype=_np.float32))
                                    self._professional_base_head_points.set_alpha(0.0)
                                    self._professional_base_head_points.set_visible(False)
                            except Exception:
                                pass
                    else:
                        self._professional_base_points.set_sizes([diameter ** 2])
                        self._professional_base_points.set_alpha(snow_alpha)
                        if self._professional_base_head_points is not None:
                            self._professional_base_head_points.set_offsets(_np.empty((0, 2), dtype=_np.float32))
                            self._professional_base_head_points.set_alpha(0.0)
                            self._professional_base_head_points.set_visible(False)
                    if (not recording or (not lock_base_recording)) and arr.shape[0] > 0 and cur_gt3 > 0:
                        self._professional_base_points.set_alpha(snow_alpha)
                    self._professional_base_points.set_zorder(24)
                    self._professional_base_points.set_visible(True)
                    if self._professional_base_predict_points is not None:
                        try:
                            self._update_professional_base_predict_trail(pred_arr, diameter, heavy_points_mode)
                        except Exception:
                            pass
                else:
                    reused_cache = False
                    if recording and lock_base_recording:
                        try:
                            last_offsets = getattr(self, '_professional_base_points_last_offsets', None)
                            last_t = float(getattr(self, '_professional_base_points_last_update_t', 0.0) or 0.0)
                            cache_age = max(0.0, now_base_draw - last_t)
                            hold_window = max(0.05, base_hold_sec)
                            keepalive_window = max(hold_window, base_keepalive_sec)
                            if last_offsets is not None and cache_age <= keepalive_window:
                                self._professional_base_points.set_offsets(last_offsets)
                                if cache_age <= hold_window:
                                    cache_alpha = base_recording_alpha
                                else:
                                    # 长缺帧时轻微衰减透明度，保持连续可见但不过分抢眼
                                    fade_ratio = min(1.0, max(0.0, (cache_age - hold_window) / max(0.05, keepalive_window - hold_window)))
                                    cache_alpha = max(0.56, base_recording_alpha * (1.0 - 0.35 * fade_ratio))
                                self._professional_base_points.set_alpha(cache_alpha)
                                try:
                                    self._professional_base_points.set_sizes([float(getattr(self, '_professional_base_point_min_d', 2.0)) ** 2])
                                except Exception:
                                    pass
                                self._professional_base_points.set_zorder(24)
                                self._professional_base_points.set_visible(True)
                                reused_cache = True
                        except Exception:
                            reused_cache = False
                    if not reused_cache:
                        self._professional_base_points.set_offsets(_np.empty((0, 2), dtype=_np.float32))
                        self._professional_base_points.set_alpha(0.0)
                        self._professional_base_points.set_visible(False)
                    if self._professional_base_head_points is not None:
                        self._professional_base_head_points.set_offsets(_np.empty((0, 2), dtype=_np.float32))
                        self._professional_base_head_points.set_alpha(0.0)
                        self._professional_base_head_points.set_visible(False)
                    if self._professional_base_predict_points is not None:
                        if recording:
                            try:
                                d0 = max(2.0, float(getattr(self, '_professional_base_point_min_d', 2.0)))
                                self._update_professional_base_predict_trail(_np.empty((0, 2), dtype=_np.float32), d0)
                            except Exception:
                                self._professional_base_predict_points.set_offsets(_np.empty((0, 2), dtype=_np.float32))
                                self._professional_base_predict_points.set_alpha(0.0)
                                self._professional_base_predict_points.set_visible(False)
                        else:
                            self._professional_base_predict_points.set_offsets(_np.empty((0, 2), dtype=_np.float32))
                            self._professional_base_predict_points.set_alpha(0.0)
                            self._professional_base_predict_points.set_visible(False)
                            self._professional_base_predict_trail = []
            else:
                import numpy as _np
                reused_cache = False
                if recording and lock_base_recording:
                    try:
                        last_offsets = getattr(self, '_professional_base_points_last_offsets', None)
                        last_t = float(getattr(self, '_professional_base_points_last_update_t', 0.0) or 0.0)
                        cache_age = max(0.0, now_base_draw - last_t)
                        hold_window = max(0.05, base_hold_sec)
                        keepalive_window = max(hold_window, base_keepalive_sec)
                        if last_offsets is not None and cache_age <= keepalive_window:
                            self._professional_base_points.set_offsets(last_offsets)
                            if cache_age <= hold_window:
                                cache_alpha = base_recording_alpha
                            else:
                                fade_ratio = min(1.0, max(0.0, (cache_age - hold_window) / max(0.05, keepalive_window - hold_window)))
                                cache_alpha = max(0.56, base_recording_alpha * (1.0 - 0.35 * fade_ratio))
                            self._professional_base_points.set_alpha(cache_alpha)
                            try:
                                self._professional_base_points.set_sizes([float(getattr(self, '_professional_base_point_min_d', 2.0)) ** 2])
                            except Exception:
                                pass
                            self._professional_base_points.set_zorder(24)
                            self._professional_base_points.set_visible(True)
                            reused_cache = True
                    except Exception:
                        reused_cache = False
                if not reused_cache:
                    self._professional_base_points.set_offsets(_np.empty((0, 2), dtype=_np.float32))
                    self._professional_base_points.set_alpha(0.0)
                    self._professional_base_points.set_visible(False)
                if self._professional_base_head_points is not None:
                    self._professional_base_head_points.set_offsets(_np.empty((0, 2), dtype=_np.float32))
                    self._professional_base_head_points.set_alpha(0.0)
                    self._professional_base_head_points.set_visible(False)
                if self._professional_base_predict_points is not None:
                    if recording:
                        try:
                            d0 = max(2.0, float(getattr(self, '_professional_base_point_min_d', 2.0)))
                            self._update_professional_base_predict_trail(_np.empty((0, 2), dtype=_np.float32), d0)
                        except Exception:
                            self._professional_base_predict_points.set_offsets(_np.empty((0, 2), dtype=_np.float32))
                            self._professional_base_predict_points.set_alpha(0.0)
                            self._professional_base_predict_points.set_visible(False)
                    else:
                        self._professional_base_predict_points.set_offsets(_np.empty((0, 2), dtype=_np.float32))
                        self._professional_base_predict_points.set_alpha(0.0)
                        self._professional_base_predict_points.set_visible(False)
                        self._professional_base_predict_trail = []
        except Exception:
            pass

        tracks_for_predict = []
        try:
            base_only_recording = bool(getattr(self, '_professional_base_only_recording', True))
        except Exception:
            base_only_recording = True
        # 叠加主音轨迹（与现有音调体系结合）
        try:
            now_ml = time.time()
            try:
                fast_active = bool(getattr(self, '_professional_fast_active', False))
            except Exception:
                fast_active = False
            try:
                fast_mode = bool(getattr(self, '_professional_fast_mode', False) or fast_active)
            except Exception:
                fast_mode = fast_active
            if recording and base_only_recording:
                try:
                    for coll in list(getattr(self, '_professional_main_collections', []) or []):
                        try:
                            if coll in getattr(self.professional_ax, 'collections', []):
                                coll.remove()
                        except Exception:
                            pass
                    self._professional_main_collections = []
                except Exception:
                    pass
                try:
                    pts = getattr(self, '_professional_main_points', None)
                    if pts is not None:
                        pts.set_offsets([])
                        pts.set_alpha(0.0)
                        pts.set_visible(False)
                except Exception:
                    pass
                self._professional_mainline_last_update = now_ml
                raise RuntimeError("base_only_recording")
            if fast_mode:
                try:
                    for coll in list(getattr(self, '_professional_main_collections', []) or []):
                        try:
                            if coll in getattr(self.professional_ax, 'collections', []):
                                coll.remove()
                        except Exception:
                            pass
                    self._professional_main_collections = []
                except Exception:
                    pass
                try:
                    pts = getattr(self, '_professional_main_points', None)
                    if pts is not None:
                        pts.set_offsets([])
                        pts.set_alpha(0.0)
                        pts.set_visible(False)
                except Exception:
                    pass
                self._professional_mainline_last_update = now_ml
                raise RuntimeError("skip mainline in fast mode")
            try:
                mainline_iv = float(getattr(self, '_professional_mainline_interval_recording', 0.085))
            except Exception:
                mainline_iv = 0.085
            try:
                if fast_active or pending_len > 1000:
                    mainline_iv = max(mainline_iv, float(getattr(self, '_professional_mainline_interval_fast', 0.12)))
            except Exception:
                pass
            if (not fast_active) and (now_ml - float(getattr(self, '_professional_mainline_last_update', 0.0))) < mainline_iv and recording:
                raise RuntimeError("skip mainline update")
            tracks = self._build_professional_main_tracks(x0, x1)
            if tracks and base_median is not None:
                try:
                    sep = float(getattr(self, '_professional_base_sep_semi', 2.6))
                except Exception:
                    sep = 2.6
                filtered = []
                for tr in tracks:
                    segs = tr.get('segments', []) if isinstance(tr, dict) else []
                    vals = []
                    for seg in segs:
                        for _, pf in seg:
                            try:
                                vals.append(float(pf))
                            except Exception:
                                pass
                    if not vals:
                        continue
                    try:
                        import numpy as _np
                        med = float(_np.median(_np.asarray(vals, dtype=_np.float32)))
                    except Exception:
                        med = vals[len(vals) // 2]
                    try:
                        semi = abs(12.0 * math.log2(max(1e-9, med / max(base_median, 1e-9))))
                    except Exception:
                        semi = 999.0
                    if semi > sep:
                        filtered.append(tr)
                tracks = filtered
            tracks_for_predict = list(tracks) if tracks else []
            if not tracks:
                try:
                    hold_until = float(getattr(self, '_professional_main_hold_until', 0.0))
                except Exception:
                    hold_until = 0.0
                if now_ml <= hold_until:
                    raise RuntimeError("hold mainline")
                try:
                    for coll in list(getattr(self, '_professional_main_collections', []) or []):
                        try:
                            if coll in getattr(self.professional_ax, 'collections', []):
                                coll.remove()
                        except Exception:
                            pass
                    self._professional_main_collections = []
                except Exception:
                    pass
                try:
                    pts = getattr(self, '_professional_main_points', None)
                    if pts is not None:
                        pts.set_offsets([])
                        pts.set_alpha(0.0)
                        pts.set_visible(False)
                except Exception:
                    pass
                self._professional_mainline_last_update = now_ml
            else:
                try:
                    import numpy as _np
                    from matplotlib.collections import LineCollection
                    palette = list(getattr(self, '_professional_band_palette', [
                        (0.72, 0.90, 1.00),
                        (0.98, 0.91, 0.72),
                        (0.89, 0.82, 0.98),
                    ]))
                    if not palette:
                        palette = [
                            (0.72, 0.90, 1.00),
                            (0.98, 0.91, 0.72),
                            (0.89, 0.82, 0.98),
                        ]
                    for coll in list(getattr(self, '_professional_main_collections', []) or []):
                        try:
                            if coll in getattr(self.professional_ax, 'collections', []):
                                coll.remove()
                        except Exception:
                            pass
                    self._professional_main_collections = []
                    all_points = []
                    all_colors = []
                    for idx, tr in enumerate(tracks):
                        band_idx = int(tr.get('band', idx)) if isinstance(tr, dict) else idx
                        track_color = palette[band_idx % len(palette)]
                        segs = []
                        for seg in tr.get('segments', []):
                            if len(seg) < 2:
                                continue
                            xs = [float(p[0]) for p in seg]
                            ys = [math.log2(max(1.0, float(p[1]))) for p in seg]
                            pts = _np.column_stack([xs, ys]).reshape(-1, 1, 2)
                            segs.extend(_np.concatenate([pts[:-1], pts[1:]], axis=1))
                            for x, y in zip(xs, ys):
                                if x0 <= x <= x1:
                                    all_points.append((x, y))
                                    all_colors.append(track_color)
                        if segs:
                            lc = LineCollection(segs, colors=[track_color] * len(segs), linewidths=0.72, alpha=0.30, zorder=11)
                            self.professional_ax.add_collection(lc)
                            self._professional_main_collections.append(lc)
                    try:
                        point_cap = int(getattr(self, '_professional_main_point_cap', 2200))
                    except Exception:
                        point_cap = 2200
                    if point_cap > 0 and len(all_points) > point_cap:
                        step = int(_np.ceil(len(all_points) / point_cap))
                        all_points = all_points[::step]
                        all_colors = all_colors[::step]
                    if all_points and (not recording):
                        if getattr(self, '_professional_main_points', None) is None:
                            self._professional_main_points = self.professional_ax.scatter([], [], s=7, alpha=0.22, linewidths=0, edgecolors='none', zorder=12)
                        pts = _np.asarray(all_points, dtype=_np.float32)
                        self._professional_main_points.set_offsets(pts)
                        try:
                            self._professional_main_points.set_color(all_colors)
                        except Exception:
                            pass
                        self._professional_main_points.set_alpha(0.22)
                        self._professional_main_points.set_visible(True)
                    else:
                        if getattr(self, '_professional_main_points', None) is not None:
                            self._professional_main_points.set_offsets([])
                            self._professional_main_points.set_alpha(0.0)
                            self._professional_main_points.set_visible(False)
                    self._professional_mainline_last_update = now_ml
                    try:
                        hold_sec = float(getattr(self, '_professional_main_hold_sec', 0.35))
                    except Exception:
                        hold_sec = 0.35
                    self._professional_main_hold_until = now_ml + max(0.0, hold_sec)
                except Exception:
                    pass
        except Exception:
            pass

        # 辅助预测频段：淡色散点，仅用于美感
        try:
            if recording:
                if getattr(self, '_professional_predict_scatter', None) is not None:
                    try:
                        self._professional_predict_scatter.set_offsets([])
                        self._professional_predict_scatter.set_alpha(0.0)
                        self._professional_predict_scatter.set_visible(False)
                    except Exception:
                        pass
                raise RuntimeError("skip predict while recording")
            if not bool(getattr(self, '_professional_predict_enabled', False)):
                if getattr(self, '_professional_predict_scatter', None) is not None:
                    try:
                        self._professional_predict_scatter.set_offsets([])
                        self._professional_predict_scatter.set_alpha(0.0)
                        self._professional_predict_scatter.set_visible(False)
                    except Exception:
                        pass
                raise RuntimeError("predict_disabled")
            now_pred = time.time()
            if (not recording) and (now_pred - float(getattr(self, '_professional_predict_last_t', 0.0))) < 0.15:
                raise RuntimeError("skip predict idle")
            pred_points = []
            pred_colors = []
            if tracks_for_predict:
                # 频段配色（淡色，不抢主线）
                band_colors = [
                    (0.78, 0.86, 0.95),  # 低频
                    (0.72, 0.90, 0.88),  # 中低
                    (0.80, 0.90, 0.74),  # 中高
                    (0.92, 0.80, 0.86),  # 明亮
                    (0.92, 0.90, 0.96),  # 空气感
                ]
                try:
                    step_t = max(0.035, float(getattr(self, '_professional_time_bin', 0.05)) * 0.85)
                except Exception:
                    step_t = 0.04
                horizon = min(0.5, float(getattr(self, 'time_window', 16.0)) * 0.03)
                for tr in tracks_for_predict:
                    segs = tr.get('segments', []) if isinstance(tr, dict) else []
                    if not segs:
                        continue
                    last_seg = segs[-1]
                    if len(last_seg) < 2:
                        continue
                    (t1, f1) = last_seg[-2]
                    (t2, f2) = last_seg[-1]
                    try:
                        t1 = float(t1); t2 = float(t2)
                        f1 = float(f1); f2 = float(f2)
                    except Exception:
                        continue
                    dt = max(1e-6, t2 - t1)
                    df = f2 - f1
                    steps = max(1, int(horizon / step_t))
                    for i in range(1, steps + 1):
                        tt = t2 + step_t * i
                        if tt > x1 + 0.2:
                            break
                        ff = max(1.0, f2 + df * (step_t * i / dt))
                        yv = math.log2(ff)
                        if yv < y0 or yv > y1:
                            continue
                        # 频段划分用于淡色点
                        if ff < 200:
                            color = band_colors[0]
                        elif ff < 800:
                            color = band_colors[1]
                        elif ff < 3000:
                            color = band_colors[2]
                        elif ff < 6000:
                            color = band_colors[3]
                        else:
                            color = band_colors[4]
                        pred_points.append((tt, yv))
                        pred_colors.append(color)
            if self._professional_predict_scatter is None:
                self._professional_predict_scatter = self.professional_ax.scatter([], [], s=12, alpha=0.22, linewidths=0, edgecolors='none', zorder=9)
            if pred_points:
                import numpy as _np
                arr = _np.asarray(pred_points, dtype=_np.float32)
                self._professional_predict_scatter.set_offsets(arr)
                try:
                    self._professional_predict_scatter.set_color(pred_colors)
                except Exception:
                    pass
                self._professional_predict_scatter.set_alpha(0.22)
                self._professional_predict_scatter.set_visible(True)
            else:
                try:
                    self._professional_predict_scatter.set_offsets([])
                    self._professional_predict_scatter.set_alpha(0.0)
                    self._professional_predict_scatter.set_visible(False)
                except Exception:
                    pass
            self._professional_predict_last_t = now_pred
        except Exception:
            pass

        try:
            now_draw = time.time()
            draw_min_iv = float(getattr(self, '_professional_min_draw_interval', 0.012))
            try:
                if recording and pending_len > 1800:
                    draw_min_iv = max(draw_min_iv, 0.020)
            except Exception:
                pass
            last_draw = float(getattr(self, '_professional_last_draw_t', 0.0) or 0.0)
            if force_redraw or force_rebuild or (now_draw - last_draw) >= draw_min_iv:
                self.professional_canvas.draw_idle()
                self._professional_last_draw_t = now_draw
        except Exception:
            pass
        try:
            rt_frame_ms = (time.perf_counter() - rt_t0) * 1000.0
            self._professional_rt_last_frame_ms = float(rt_frame_ms)
            budget_ms = float(getattr(self, '_professional_rt_frame_budget_ms', 14.0) or 14.0)
            if recording and rt_frame_ms > budget_ms:
                self._professional_rt_degrade_harm = True
                if rt_frame_ms > (budget_ms * 1.4):
                    self._professional_rt_degrade_heat = True
            report_iv = float(getattr(self, '_professional_rt_monitor_interval_s', 0.5) or 0.5)
            now_report = time.time()
            last_report = float(getattr(self, '_professional_rt_last_report_t', 0.0) or 0.0)
            if recording and (now_report - last_report) >= max(0.2, report_iv):
                self._professional_rt_last_report_t = now_report
                if bool(getattr(self, 'debug_flags', {}).get('display_diag', False)):
                    print(
                        f"[PRO-RT] frame={rt_frame_ms:.2f}ms budget={budget_ms:.2f}ms "
                        f"lag={float(getattr(self, '_professional_rt_last_queue_lag_s', 0.0)):.3f}s "
                        f"pending={int(getattr(self, '_professional_rt_last_pending', 0))} "
                        f"degrade(harm={int(bool(getattr(self, '_professional_rt_degrade_harm', False)))},"
                        f"heat={int(bool(getattr(self, '_professional_rt_degrade_heat', False)))})"
                    )
        except Exception:
            pass
        try:
            if force_redraw:
                self._professional_force_redraw = False
        except Exception:
            pass
        # 初始化细节点悬停提示（优雅浮窗 + 三角指示）
        try:
            if getattr(self, '_hover_annot', None) is None:
                self._ensure_hover_annot()
            if not bool(getattr(self, '_professional_hover_bound', False)):
                self.professional_canvas.mpl_connect('figure_leave_event', self._on_mouse_leave)
                self._professional_hover_bound = True
        except Exception:
            self._hover_annot = None
    
    def safe_clear_axis(self):
        """安全地清除轴内容，仅保留分段主线与白色细节点，避免恢复冲突元素。
        去除：彩色渐变(LineCollection)、批量细节点(batched_points)、临时叠加线(provisional)。"""
        # 保存现有的坐标轴范围
        saved_xlim = self.ax.get_xlim()
        saved_ylim = self.ax.get_ylim()

        # 仅保留必要的分段元素与高亮点
        saved_highlight_point = None
        saved_segment_lines = []
        saved_segment_points = []
        saved_head_points_scatter = None
        saved_overlay_preview_line = None
        saved_overlay_preview_scatter = None

        try:
            if hasattr(self, '_segment_lines') and self._segment_lines:
                for ln in self._segment_lines:
                    if ln in self.ax.lines:
                        saved_segment_lines.append(ln)
            if hasattr(self, '_segment_points') and self._segment_points:
                for pts in self._segment_points:
                    # segment points 是 PathCollection, 位于 collections
                    if pts in self.ax.collections:
                        saved_segment_points.append(pts)
            # 严格隐藏批量点（避免滚动时出现浅灰点）
            if hasattr(self, '_batched_points') and self._batched_points is not None:
                try:
                    if self._batched_points in self.ax.collections:
                        self._batched_points.remove()
                except Exception:
                    pass
                try:
                    self._batched_points.set_alpha(0.0)
                    self._batched_points.set_visible(False)
                except Exception:
                    pass
            # 头部即时散点
            if hasattr(self, '_head_points_scatter') and self._head_points_scatter is not None:
                if self._head_points_scatter in self.ax.collections:
                    saved_head_points_scatter = self._head_points_scatter
            # 回录覆盖预览：保留线条与细节点，避免清轴后“闪现/消失”
            try:
                line = getattr(self, '_retake_overlay_preview_line', None)
                if line is not None and line in self.ax.lines:
                    saved_overlay_preview_line = line
            except Exception:
                pass
            try:
                sc = getattr(self, '_retake_overlay_preview_scatter', None)
                if sc is not None and sc in self.ax.collections:
                    saved_overlay_preview_scatter = sc
            except Exception:
                pass
            # 临时叠加线：直接移除并清空，杜绝同窗双线与跨窗连线
            if hasattr(self, '_provisional_line') and self._provisional_line is not None:
                try:
                    if self._provisional_line in self.ax.lines:
                        self._provisional_line.remove()
                except Exception:
                    pass
                self._provisional_line = None
            if hasattr(self, '_provisional_polyline'):
                self._provisional_polyline = None
        except Exception:
            pass

        # 移除并清空渐变元素，避免普通模式下“多出一条线”
        if hasattr(self, 'gradient_lines') and self.gradient_lines:
            for line in list(self.gradient_lines):
                try:
                    if line in self.ax.collections:
                        line.remove()
                except Exception:
                    pass
            self.gradient_lines = []

        if hasattr(self, 'highlight_point') and self.highlight_point is not None:
            # 保存高亮点
            saved_highlight_point = self.highlight_point

        # 清除轴
        self.ax.clear()
        # 重要：清空后旧的辅助线对象会失去可见挂载关系，直接置空以便后续重建
        try:
            self.v_guide_line = None
            self.h_guide_line = None
            self.v_guide_glow_line = None
            self.h_guide_glow_line = None
            self._onepass_time_cursor = None
            self._stable_segment_points_cache = {}
        except Exception:
            pass

        # 恢复坐标轴范围
        self.ax.set_xlim(saved_xlim)
        self.ax.set_ylim(saved_ylim)

        if saved_highlight_point is not None:
            try:
                self.ax.add_collection(saved_highlight_point)
            except Exception:
                pass
            self.highlight_point = saved_highlight_point

        # 恢复分段曲线（保持对象身份，避免重复创建）
        if (saved_segment_lines or saved_segment_points) and not bool(getattr(self, '_clear_all_artists_on_next_grid', False)):
            try:
                for ln in saved_segment_lines:
                    # 已附着到其他 axes 的 line 不要重复 add_line
                    if getattr(ln, 'axes', None) is None:
                        self.ax.add_line(ln)
                for pts in saved_segment_points:
                    if pts not in self.ax.collections:
                        self.ax.add_collection(pts)
                # 重新赋回引用，防止被外部认为已失效
                self._segment_lines = saved_segment_lines
                self._segment_points = saved_segment_points
            except Exception as _rec_e:
                try:
                    print(f"⚠️ 重新挂载分段曲线失败: {_rec_e}")
                except Exception:
                    pass

        # 恢复头部即时散点，避免清轴后一小段时间内细节点消失
        if saved_head_points_scatter is not None:
            try:
                if saved_head_points_scatter not in self.ax.collections:
                    self.ax.add_collection(saved_head_points_scatter)
                self._head_points_scatter = saved_head_points_scatter
                try:
                    # 提升层级，避免被线条覆盖
                    self._head_points_scatter.set_zorder(14)
                    # 保守可见性
                    if hasattr(self._head_points_scatter, 'set_alpha'):
                        cur_a = None
                        try:
                            cur_a = self._head_points_scatter.get_alpha()
                        except Exception:
                            cur_a = None
                        self._head_points_scatter.set_alpha(0.9 if cur_a is None else max(0.6, cur_a))
                except Exception:
                    pass
            except Exception:
                pass

        # 恢复回录覆盖预览线与散点，避免选区内线条闪烁/丢失
        if saved_overlay_preview_line is not None:
            try:
                if getattr(saved_overlay_preview_line, 'axes', None) is None:
                    self.ax.add_line(saved_overlay_preview_line)
                self._retake_overlay_preview_line = saved_overlay_preview_line
                try:
                    saved_overlay_preview_line.set_visible(True)
                    saved_overlay_preview_line.set_zorder(160)
                except Exception:
                    pass
            except Exception:
                pass
        if saved_overlay_preview_scatter is not None:
            try:
                if saved_overlay_preview_scatter not in self.ax.collections:
                    self.ax.add_collection(saved_overlay_preview_scatter)
                self._retake_overlay_preview_scatter = saved_overlay_preview_scatter
                try:
                    saved_overlay_preview_scatter.set_visible(True)
                    saved_overlay_preview_scatter.set_zorder(162)
                except Exception:
                    pass
            except Exception:
                pass
        # 覆盖预览激活时：确保清轴后重新挂载/更新 overlay 预览图元
        try:
            if getattr(self, '_retake_overlay_preview_active', False):
                try:
                    self._ensure_overlay_preview_artists()
                except Exception:
                    pass
                try:
                    self._update_overlay_preview_artists()
                except Exception:
                    pass
        except Exception:
            pass

    def setup_ecg_grid(self, create_pitch_line: bool = True):
        """设置心电图式网格（智能标注）
        create_pitch_line: 是否创建/恢复数据线对象（清除后可跳过以保持空白初始状态）"""
        # 保存现有的pitch_line数据
        existing_line_data = None
        if hasattr(self, 'pitch_line') and self.pitch_line in self.ax.lines:
            existing_line_data = self.pitch_line.get_data()
        
        # 使用安全清除方法保护彩色渐变
        self.safe_clear_axis()
        
        # 重新设置基本属性
        self.ax.set_facecolor(self.bg_color)
        
        # 隐藏Y轴的数字刻度，只保留音名标注
        self.ax.set_yticklabels([])
        self.ax.tick_params(axis='y', which='both', left=False, right=False)
        # 根据缩放级别选择可见半范围（zoom 越大显示越多音调）
        half_range = self.compute_half_range()
        # 拖动后保持中心可见
        self.clamp_y_center(half_range)
        y_start = self.y_view_center - half_range
        y_end = self.y_view_center + half_range
        # 对整体允许的物理范围做硬裁剪（假设支持 0-8 八度）
        if y_start < 0:
            shift = -y_start
            y_start += shift
            y_end += shift
        if y_end > 8:
            shift = y_end - 8
            y_start -= shift
            y_end -= shift

        # 计算显示范围（八度数）
        display_range = y_end - y_start

        # 智能标注密度控制
        if self.auto_scale:
            if display_range > 6:
                self.setup_sparse_grid(y_start, y_end)
            elif display_range > 3:
                self.setup_medium_grid(y_start, y_end)
            else:
                self.setup_dense_grid(y_start, y_end)
        else:
            self.setup_dense_grid(y_start, y_end)

        # 时间网格线
        time_start = self.time_offset
        time_end = self.time_offset + self.time_window
        for second in range(int(time_start), int(time_end) + 2):
            if time_start <= second <= time_end:
                self.ax.axvline(x=second, color=self.grid_color,
                                linestyle='--', linewidth=0.5, alpha=0.5)

        if create_pitch_line:
            # 确保pitch_line存在并恢复数据
            try:
                self._ensure_pitch_line(alpha=1.0)
            except Exception:
                # 失败则直接创建一次
                self.pitch_line, = self.ax.plot([], [], color=self.line_color,
                                                linewidth=self.current_linewidth, alpha=1.0, zorder=10)
            # 若处于 seek 清除态：仍可“安全恢复<=cap的历史线”，避免左侧历史在网格重建后突然消失
            try:
                if bool(getattr(self, '_clear_all_artists_on_next_grid', False)):
                    # 仅当启用了cap时，恢复到 <=cap 的数据，严禁右侧旧点回潮
                    if existing_line_data is not None and len(existing_line_data[0]) > 0 and getattr(self, '_cap_visible_time_enabled', False):
                        try:
                            xs, ys = list(existing_line_data[0] or []), list(existing_line_data[1] or [])
                        except Exception:
                            xs, ys = [], []
                        if xs and ys and len(xs) == len(ys):
                            try:
                                # 使用统一cap过滤逻辑，保证严格锁下不越界
                                ft, fp = self._cap_filter_times_pitches(xs, ys)
                            except Exception:
                                # 兜底：手动按cap过滤
                                ft, fp = [], []
                                try:
                                    cap = float(getattr(self, '_max_visible_time', 0.0))
                                except Exception:
                                    cap = float('inf')
                                for tx, py in zip(xs, ys):
                                    try:
                                        if float(tx) <= cap + 1e-9:
                                            ft.append(tx); fp.append(py)
                                    except Exception:
                                        pass
                            # 应用过滤后的数据；若为空则保持空线（避免恢复右侧旧段）
                            try:
                                self.pitch_line.set_data(ft, fp)
                                if ft:
                                    self.pitch_line.set_alpha(1.0)
                                else:
                                    # 无可恢复历史则保持不可见
                                    self.pitch_line.set_alpha(0.0)
                            except Exception:
                                pass
                    # 若未启用cap：继续沿用“完全不恢复”的策略（保持空线），避免误把右侧旧段带回
                else:
                    # 非清除态：正常恢复之前保存的主线数据
                    if existing_line_data is not None and len(existing_line_data[0]) > 0:
                        self.pitch_line.set_data(existing_line_data[0], existing_line_data[1])
            except Exception:
                # 任意异常不影响主流程
                pass
        else:
            # 仍然确保存在不可见占位线，避免后续 NoneType
            try:
                self._ensure_pitch_line(alpha=0.0)
                try:
                    self.pitch_line.set_alpha(0.0)
                except Exception:
                    pass
            except Exception:
                # 最差情况下也创建一条不可见线
                self.pitch_line, = self.ax.plot([], [], color=self.line_color,
                                                linewidth=self.current_linewidth, alpha=0.0, zorder=10)

        # X轴范围保持 16 秒窗口
        x_min = self.time_offset
        x_max = self.time_offset + self.time_window
        self.ax.set_xlim(x_min, x_max)

        # Y轴范围（音高）
        self.ax.set_ylim(y_start, y_end)

        # 纵轴漂移监控（锁定模式下）
        if getattr(self, 'freeze_y_center', False):
            drift = abs(self.y_view_center - getattr(self, '_initial_y_center', self.y_view_center))
            if drift > 0.05 and abs(drift - getattr(self, '_last_warn_y_shift', 0.0)) > 0.02:
                dbg = bool(getattr(self, 'debug_flags', {}).get('ydrift_log', False))
                now_t = time.time()
                if dbg and (now_t - float(getattr(self, '_last_warn_y_shift_ts', 0.0) or 0.0) >= float(getattr(self, '_warn_y_shift_interval_s', 1.5) or 1.5)):
                    print(f"⚠️ [YDRIFT-DETECT] setup_ecg_grid drift={drift:.3f} center={self.y_view_center:.3f}")
                    self._last_warn_y_shift_ts = now_t
                self._last_warn_y_shift = drift

        # 重建网格后，确保辅助线存在并位置正确
        try:
            self.update_guides()
        except Exception:
            pass
        # 一次性清除标志
        try:
            if getattr(self, '_clear_all_artists_on_next_grid', False):
                self._clear_all_artists_on_next_grid = False
        except Exception:
            pass
    
    def _ensure_pitch_line(self, *, alpha: float = 0.0):
        """确保 self.pitch_line 存在且附着到当前 axes；若不存在则创建为不可见占位线。
        alpha 参数用于新建时的初始透明度，不会强行修改已存在线条的透明度。"""
        try:
            pl = getattr(self, 'pitch_line', None)
            if pl is not None:
                # 若线对象存在但未附着到当前 axes，尝试重新挂载；失败则重建
                if getattr(pl, 'axes', None) is self.ax and pl in getattr(self.ax, 'lines', []):
                    return
                try:
                    # 已有对象但未附着，尝试挂载
                    if getattr(pl, 'axes', None) is None:
                        self.ax.add_line(pl)
                        return
                except Exception:
                    pass
            # 走到这里表示需要新建
            color = getattr(self, 'line_color', '#FF6600')
            lw = float(getattr(self, 'current_linewidth', 1.0))
            self.pitch_line, = self.ax.plot([], [], color=color, linewidth=lw, alpha=float(alpha), zorder=10)
        except Exception:
            # 发生异常时，尽量保证成员存在以避免后续 NoneType 访问
            try:
                color = getattr(self, 'line_color', '#FF6600')
                lw = float(getattr(self, 'current_linewidth', 1.0))
                self.pitch_line, = self.ax.plot([], [], color=color, linewidth=lw, alpha=float(alpha), zorder=10)
            except Exception:
                pass

    # should_show_note_label 逻辑已被各 zoom 模式的严格规则替换
    
    def draw_interactive_note_labels(self, y_start, y_end):
        """绘制交互式音调标签（更快更顺）
        - 高倍缩放仍做视图节流，但当节流命中时，对现有文本执行“快速样式更新”，避免整批重建造成卡顿；
        - 高亮采用基于距离的平滑权重（alpha/粗细），不做花哨的多色切换，仅适度加粗靠近中心的音；
        - 当前音高中心使用已存在的平滑值（_smoothed_hy，若有），减少跳动。
        """
        # 高倍缩放下按视图变化节流重建，避免卡顿
        try:
            profile = getattr(self, '_current_zoom_profile', None) or self._get_zoom_profile()
            self._current_zoom_profile = profile
            mode = profile.get('mode')
            zoom = float(getattr(self, 'zoom_level', 1.0))
            now = time.time()
            # 依据缩放确定重建的最小间隔；有当前音高时更频繁一些
            if zoom >= 4.5:
                min_interval = 0.08 if getattr(self, 'current_pitch_active', False) else 0.12
            elif zoom >= 2.0:
                min_interval = 0.06 if getattr(self, 'current_pitch_active', False) else 0.09
            else:
                min_interval = 0.0
            last = getattr(self, '_last_note_labels_meta', None)
            if last is not None:
                last_y0, last_y1, last_mode, last_t = last
                # 视窗轻微移动时允许跳过重建；但先做一次“快速样式更新”以保持高亮流畅
                if (abs(y_start - last_y0) < 0.12 and abs(y_end - last_y1) < 0.12 and mode == last_mode):
                    if (now - last_t) < min_interval:
                        try:
                            labels = getattr(self, '_note_label_texts', [])
                            positions = getattr(self, '_note_label_pos', [])
                            if labels and positions and len(labels) == len(positions):
                                # 使用“平滑中心 + 最近半音”融合作为高亮中心，提高匹配度
                                center_base = getattr(self, '_smoothed_hy', None)
                                if center_base is None:
                                    center_base = getattr(self, 'current_pitch_y', getattr(self, 'y_view_center', (y_start + y_end) * 0.5))
                                # 最近半音对齐
                                try:
                                    q_center = round(center_base * 12.0) / 12.0
                                except Exception:
                                    q_center = center_base
                                d_semi = abs(center_base - q_center) * 12.0
                                conf = float(getattr(self, '_last_stable_conf', 0.6))
                                if conf < 0.0: conf = 0.0
                                if conf > 1.0: conf = 1.0
                                # 置信度与偏差越小越靠近最近半音；C3-C4 区域稍微增加吸附
                                mid_bias = 1.10 if 3.0 <= center_base <= 4.0 else 1.0
                                snap_dist_w = max(0.0, 1.0 - (d_semi / 0.45))  # 约45 cents内产生吸附
                                w_snap = max(0.0, min(1.0, conf * 1.05 * snap_dist_w * mid_bias))
                                snap_strength = 0.65  # 最大吸附强度
                                center = (1.0 - snap_strength * w_snap) * center_base + (snap_strength * w_snap) * q_center
                                # 距离权重：r1 强区，r2 渐隐区（更紧凑，提高匹配感）
                                r1, r2 = 0.22, 0.65
                                for i, txt in enumerate(labels):
                                    try:
                                        y_pos = positions[i]
                                        d = abs(y_pos - center)
                                        if d <= r1:
                                            w = 1.0
                                        elif d >= r2:
                                            w = 0.0
                                        else:
                                            t = (d - r1) / (r2 - r1)
                                            w = 1.0 - t * t  # 二次缓出，更平顺
                                        new_alpha = 0.30 + 0.70 * w
                                        if new_alpha < 0.05: new_alpha = 0.05
                                        if new_alpha > 1.00: new_alpha = 1.00
                                        txt.set_alpha(new_alpha)
                                        txt.set_fontweight('bold' if d <= 0.16 else 'normal')
                                    except Exception:
                                        pass
                        except Exception:
                            pass
                        return
            self._last_note_labels_meta = (y_start, y_end, mode, now)
        except Exception:
            pass

        # 清理旧元素（确保缩进一致，避免语法分析错误）
        if hasattr(self, '_note_label_texts'):
            for t in self._note_label_texts:
                try:
                    t.remove()
                except Exception:
                    pass
        self._note_label_texts = []
        self._note_label_pos = []

        if hasattr(self, '_active_note_highlight_lines'):
            for ln in self._active_note_highlight_lines:
                try:
                    if ln in self.ax.lines:
                        ln.remove()
                except Exception:
                    pass
            self._active_note_highlight_lines.clear()
        else:
            self._active_note_highlight_lines = []
        # 保障字段
        if not hasattr(self, 'current_pitch_y'): self.current_pitch_y = 4.0
        if not hasattr(self, 'current_pitch_active'): self.current_pitch_active = False
        # 变换
        import matplotlib.transforms as mtransforms
        if not hasattr(self, '_axis_blended_transform'):
            self._axis_blended_transform = mtransforms.blended_transform_factory(self.ax.transAxes, self.ax.transData)
        label_x = self.label_x_frac
        # 优先使用已平滑的当前音高中心，并对齐最近半音以提升匹配度
        if self.current_pitch_active:
            center_base = getattr(self, '_smoothed_hy', getattr(self, 'current_pitch_y', self.y_view_center))
        else:
            center_base = self.y_view_center
        try:
            q_center = round(center_base * 12.0) / 12.0
        except Exception:
            q_center = center_base
        conf = float(getattr(self, '_last_stable_conf', 0.6))
        if conf < 0.0: conf = 0.0
        if conf > 1.0: conf = 1.0
        d_semi = abs(center_base - q_center) * 12.0
        mid_bias = 1.10 if 3.0 <= center_base <= 4.0 else 1.0
        snap_dist_w = max(0.0, 1.0 - (d_semi / 0.45))
        w_snap = max(0.0, min(1.0, conf * 1.05 * snap_dist_w * mid_bias))
        snap_strength = 0.65
        hl_center = (1.0 - snap_strength * w_snap) * center_base + (snap_strength * w_snap) * q_center
        # 显示缓冲
        display_start = max(0.0, y_start - 1.0)
        display_end = min(8.0, y_end + 1.0)
        profile = getattr(self, '_current_zoom_profile', None) or self._get_zoom_profile()
        self._current_zoom_profile = profile
        mode = profile.get('mode')
        filt = profile['note_filter']
        fixed_mode = mode in ('zoom_0_5','zoom_0_8')
        # 预计算一次坐标变换，避免每条标签重复求解
        try:
            base_px_x = self.ax.transAxes.transform((label_x, 0))[0]
            inv_axes = self.ax.transAxes.inverted()
        except Exception:
            base_px_x = None
            inv_axes = None
        zoom = float(getattr(self, 'zoom_level', 1.0))
        # 限制高倍缩放下的水平虚线数量（联动性能模式）
        try:
            from src.audio_processing.performance_manager import get_performance_manager, PerformanceMode
            _pm = get_performance_manager(); _mode = _pm.get_current_mode() if _pm else None
            is_hp = (_mode == PerformanceMode.HIGH_PERFORMANCE)
            is_bal = (_mode == PerformanceMode.BALANCED)
        except Exception:
            _mode = None
            is_hp = False
            is_bal = True  # 退化为均衡
        if zoom >= 4.5:
            if is_hp:
                max_hlines = 1
            elif is_bal:
                max_hlines = 1
            else:
                max_hlines = 0
        elif zoom >= 2.0:
            if is_hp:
                max_hlines = 3
            elif is_bal:
                max_hlines = 2
            else:
                max_hlines = 1
        else:
            max_hlines = 4
        added_hlines = 0
        # 遍历十二平均律位置
        for octave in range(int(display_start), int(display_end) + 1):
            for semitone in range(12):
                # 模式过滤
                if mode == 'zoom_0_5':
                    if not (semitone == 0 and 3 <= octave <= 5):
                        continue
                elif mode == 'zoom_0_8':
                    if semitone != 0: continue
                elif mode == 'zoom_1_5':
                    if semitone not in (0,5,7): continue
                elif mode == 'zoom_2_5':
                    if 3 <= octave <= 5:
                        if semitone not in (0,2,4,5,7,9,11): continue
                    else:
                        if semitone not in (0,5,7): continue
                elif mode == 'zoom_5_0':
                    pass
                else:
                    if not filt(octave, semitone): continue
                # 统一再次通过 filter 保障
                if not filt(octave, semitone):
                    continue
                y_pos = octave + semitone / 12.0
                if not (display_start <= y_pos <= display_end):
                    continue
                note_full = f"{self.note_names[semitone]}{octave}"
                distance = abs(y_pos - hl_center)
                # 5.0x 下远离中心的弱级别半音直接省略
                if mode == 'zoom_5_0' and semitone not in (0,2,4,5,7,9,11) and distance > 0.35:
                    continue
                # 样式层级（更克制）：基础样式随模式，强调通过“距离-透明度”实现
                if mode == 'zoom_5_0':
                    if semitone == 0:
                        font_size = 11; alpha = 0.95; color = '#FFFF88'; font_weight = 'bold'
                    elif semitone in (2,4,5,7,9,11):
                        font_size = 10; alpha = 0.75; color = self.text_color; font_weight = 'normal'
                    else:
                        font_size = 9; alpha = 0.50; color = self.text_color; font_weight = 'normal'
                elif mode == 'zoom_0_5':
                    font_size = 12; alpha = 0.95; color = '#FFFF88'; font_weight = 'bold'
                elif mode == 'zoom_2_5' and not (3 <= octave <= 5):
                    if semitone == 0:
                        font_size = 11; alpha = 0.88; color = '#FFFFAA'; font_weight = 'bold'
                    else:
                        font_size = 9; alpha = 0.52; color = self.text_color; font_weight = 'normal'
                elif semitone == 0:
                    font_size = 11; alpha = 0.95; color = '#FFFF88'; font_weight = 'bold'
                elif semitone in (2,4,5,7,9,11):
                    font_size = 10; alpha = 0.75; color = self.text_color; font_weight = 'normal'
                else:
                    font_size = 9; alpha = 0.50; color = self.text_color; font_weight = 'normal'
                # 平滑距离权重（不过度花哨，只调透明度与粗细）
                if getattr(self, 'current_pitch_active', False):
                    center = hl_center
                    d = abs(y_pos - center)
                    r1, r2 = 0.22, 0.65
                    if d <= r1:
                        w = 1.0
                    elif d >= r2:
                        w = 0.0
                    else:
                        t = (d - r1) / (r2 - r1)
                        w = 1.0 - t * t
                    alpha = max(alpha, 0.30 + 0.70 * w)
                    font_weight = 'bold' if d <= 0.16 else font_weight
                # 边缘淡出（固定模式主音 & 全局边界C0/C8 不淡出）
                apply_fade = True
                if (fixed_mode and semitone == 0) or (semitone == 0 and octave in (0,8)):
                    apply_fade = False
                if apply_fade:
                    vd = min(abs(y_pos - y_start), abs(y_pos - y_end))
                    if vd < 0.5:
                        alpha *= (vd / 0.5)
                if alpha < 0.2:
                    continue
                txt = self.ax.text(label_x, y_pos, note_full,
                                   fontsize=font_size, ha='right', va='center',
                                   color=color, alpha=alpha, fontweight=font_weight,
                                   transform=self._axis_blended_transform,
                                   clip_on=False, zorder=50,
                                   bbox=dict(facecolor=self.bg_color, edgecolor='none', pad=0.2, alpha=0.55))
                try:
                    if base_px_x is not None and inv_axes is not None:
                        extra_px = -4 if (mode == 'zoom_5_0' and (semitone % 2 == 1)) else 0
                        new_axes_x = inv_axes.transform((base_px_x + self.label_left_pixel_offset + extra_px, 0))[0]
                        txt.set_x(new_axes_x)
                except Exception:
                    pass
                self._note_label_texts.append(txt)
                self._note_label_pos.append(y_pos)
                if (max_hlines > 0 and added_hlines < max_hlines and
                    self.current_pitch_active and distance <= 1.0):
                    ln_alpha = alpha * 0.3
                    try:
                        ln = self.ax.axhline(y=y_pos, color=color, linestyle=':', linewidth=0.8, alpha=ln_alpha, zorder=5)
                        self._active_note_highlight_lines.append(ln)
                        added_hlines += 1
                    except Exception:
                        pass
        # 边界标签保障（滚动模式）
        if mode in ('zoom_1_5','zoom_2_5','zoom_5_0'):
            for boundary_oct in (0,8):
                if not (y_start - 0.001 <= boundary_oct <= y_end + 0.001):
                    continue
                wanted = f"C{boundary_oct}"
                if any(t.get_text() == wanted for t in self._note_label_texts):
                    continue
                txt = self.ax.text(label_x, boundary_oct, wanted,
                                   fontsize=12, ha='right', va='center',
                                   color='#FFFFAA', alpha=0.95, fontweight='bold',
                                   transform=self._axis_blended_transform,
                                   clip_on=False, zorder=60,
                                   bbox=dict(facecolor=self.bg_color, edgecolor='none', pad=0.25, alpha=0.65))
                try:
                    if base_px_x is not None and inv_axes is not None:
                        new_axes_x = inv_axes.transform((base_px_x + self.label_left_pixel_offset, 0))[0]
                        txt.set_x(new_axes_x)
                except Exception:
                    pass
                self._note_label_texts.append(txt)
    
    def setup_sparse_grid(self, y_start, y_end):
        """稀疏网格模式（只显示八度线）"""
        for octave in range(max(0, int(y_start)), min(9, int(y_end) + 2)):
            y_pos = octave
            if y_start <= y_pos <= y_end:
                # 八度线
                self.ax.axhline(y=y_pos, color=self.grid_color, linestyle='-', 
                               linewidth=2.0, alpha=0.9)
        
        # 使用智能交互式标签
        self.draw_interactive_note_labels(y_start, y_end)
    
    def setup_medium_grid(self, y_start, y_end):
        """中等密度网格（显示主要音符）"""
        profile = getattr(self, '_current_zoom_profile', None)
        if not profile:
            profile = self._get_zoom_profile(); self._current_zoom_profile = profile
        filt = profile['note_filter']
        for octave in range(max(0, int(y_start)), min(9, int(y_end) + 2)):
            y_oct = octave
            if y_start <= y_oct <= y_end:
                self.ax.axhline(y=y_oct, color=self.grid_color, linestyle='-', linewidth=1.2, alpha=0.75)
            for semitone in (0,2,4,5,7,9,11):
                if semitone == 0 or not filt(octave, semitone):
                    continue
                y_pos = octave + semitone / 12
                if y_start <= y_pos <= y_end:
                    self.ax.axhline(y=y_pos, color=self.grid_color, linestyle=':', linewidth=0.7, alpha=0.5)
        
        # 使用智能交互式标签
        self.draw_interactive_note_labels(y_start, y_end)
    
    def setup_dense_grid(self, y_start, y_end):
        """密集网格模式（显示所有音符）"""
        profile = getattr(self, '_current_zoom_profile', None)
        if not profile:
            profile = self._get_zoom_profile(); self._current_zoom_profile = profile
        filt = profile['note_filter']
        mode = profile.get('mode')
        for octave in range(max(0, int(y_start)), min(9, int(y_end) + 2)):
            y_oct = octave
            if y_start <= y_oct <= y_end:
                self.ax.axhline(y=y_oct, color=self.grid_color, linestyle='-', linewidth=1.0, alpha=0.65)
            for semitone in range(12):
                if semitone == 0 or not filt(octave, semitone):
                    continue
                y_pos = octave + semitone / 12
                if y_start <= y_pos <= y_end:
                    if mode == 'zoom_5_0':
                        # 5.0 模式：黑键最淡，白键次之
                        if semitone in [1,3,6,8,10]:
                            alpha = 0.18; lw = 0.4
                        elif semitone in [2,4,7,9,11]:
                            alpha = 0.36; lw = 0.5
                        else:
                            alpha = 0.5; lw = 0.55
                    elif mode == 'zoom_2_5':
                        if 3 <= octave <= 5:
                            if semitone in [2,4,7,9,11]:
                                alpha = 0.50; lw = 0.55
                            else:
                                alpha = 0.35; lw = 0.45
                        else:
                            alpha = 0.28; lw = 0.45
                    else:
                        alpha = 0.55 if semitone in [2,4,7,9,11] else 0.32
                        lw = 0.55
                    self.ax.axhline(y=y_pos, color=self.grid_color, linestyle=':', linewidth=lw, alpha=alpha)
        
        # 使用智能交互式标签
        self.draw_interactive_note_labels(y_start, y_end)
    
    def update_axis_ranges(self):
        """更新坐标轴范围（支持缩放）"""
        # 如果启用纵轴锁定（freeze_y_center），保持最初锁定的Y范围不随数据滚动变化
        if getattr(self, 'freeze_y_center', False):
            # 确定当前X轴范围（仍需随时间滚动）
            if hasattr(self, '_last_render_window'):
                x_min, x_max = self._last_render_window
            else:
                x_min = self.time_offset
                x_max = self.time_offset + self.time_window
            self.ax.set_xlim(x_min, x_max)

            # 首次锁定：记录当时的Y范围（避免之后因 zoom_level 或 center 计算被改写）
            if not hasattr(self, '_locked_y_limits') or self._locked_y_limits is None:
                self._locked_y_limits = self.ax.get_ylim()
            else:
                # 强制使用锁定范围
                self.ax.set_ylim(*self._locked_y_limits)
                try:
                    if getattr(self, 'debug_flags', {}).get('axis_log', False):
                        print(f"[AXIS LOCKED] ylim={self._locked_y_limits}")
                except Exception:
                    pass

            # 冻结模式下也刷新标签使其始终出现在当前左边界
            try:
                y_min, y_max = self.ax.get_ylim()
                self.draw_interactive_note_labels(y_min, y_max)
            except Exception:
                pass

            # 在锁定模式下无须每帧重建网格，避免闪烁；仅在显式缩放/解锁时再调用 setup_ecg_grid
            self.canvas.draw_idle()
            return

        # 正常（未锁定）模式：根据当前中心与缩放计算Y范围
        half_range = self.compute_half_range()
        profile = getattr(self, '_current_zoom_profile', None) or self._get_zoom_profile()
        # 更新当前可视半范围供拖拽换算使用
        self.y_view_range = half_range
        if profile.get('disable_v_scroll'):
            # 固定模式直接根据规范设置范围
            if profile['mode'] == 'zoom_0_8':
                y_min, y_max = 0.0, 8.0
                self.y_view_center = 4.0
            else:  # zoom_0_5
                # 保证完整覆盖 C3,C4,C5 三个标签 (含上下边界微扩展避免边界裁剪)
                y_min, y_max = 2.95, 5.05
                self.y_view_center = 4.0
        else:
            # 可滚动模式：限制中心避免超出 0-8
            self.clamp_y_center(half_range)
            y_min = self.y_view_center - half_range
            y_max = self.y_view_center + half_range
            if y_min < 0:
                shift = -y_min; y_min += shift; y_max += shift; self.y_view_center += shift
            if y_max > 8:
                shift = y_max - 8; y_min -= shift; y_max -= shift; self.y_view_center -= shift
        self.ax.set_ylim(y_min, y_max)
        try:
            if getattr(self, 'debug_flags', {}).get('axis_log', False):
                print(f"[AXIS] mode={profile.get('mode')} center={self.y_view_center:.2f} ylim=({y_min:.2f},{y_max:.2f})")
        except Exception:
            pass
        # 记录当前内部 profile 半范围与可滚动状态，便于诊断“看起来没动”问题
        try:
            if getattr(self, 'debug_flags', {}).get('axis_log', False):
                now = time.time()
                if not hasattr(self, '_last_axis_diag_log'):
                    self._last_axis_diag_log = 0.0
                if now - self._last_axis_diag_log > 1.0:  # 1s节流
                    print(f"[AXIS DIAG] half_range={half_range:.2f} disable_scroll={profile.get('disable_v_scroll')} center={self.y_view_center:.2f}")
                    self._last_axis_diag_log = now
        except Exception:
            pass

        # 更新X轴范围（时间）
        # 停止态：严格尊重 time_offset/time_window，禁止使用历史渲染窗口和平滑，以防被“拉回末尾”
        if not getattr(self, 'is_recording_active', False):
            x_min = self.time_offset
            x_max = self.time_offset + self.time_window
            try:
                self.ax.set_xlim(x_min, x_max)
            except Exception:
                pass
        else:
            # 录音态：始终依据当前目标窗口推进，避免“锁在上次渲染窗口”导致累积滞后
            x_min = self.time_offset
            x_max = self.time_offset + self.time_window
            # 平滑滚动：超过中心时间后且自动跟随时使用平滑过渡
            try:
                smooth_active = (
                    getattr(self, 'is_recording_active', False)
                    and getattr(self, 'auto_follow', True)
                    and getattr(self, 'auto_scroll_enabled', True)
                    and not getattr(self, 'freeze_y_center', False)
                    and getattr(self, 'current_global_time', 0.0) > self.center_display_time
                )
            except Exception:
                smooth_active = False
            if smooth_active and hasattr(self, '_smooth_set_xlim'):
                # 使用“自适应跟随”参数，减少顿挫
                try:
                    s, m = self._get_follow_smoothing()
                    self._smooth_set_xlim(x_min, x_max, strength=float(s), max_step=float(m))
                except Exception:
                    self.ax.set_xlim(x_min, x_max)
            else:
                self.ax.set_xlim(x_min, x_max)

        # 仅在模式或Y范围变化时重建网格，避免频繁 clear 带来的闪烁
        try:
            profile_mode = (getattr(self, '_current_zoom_profile', None) or self._get_zoom_profile()).get('mode')
        except Exception:
            profile_mode = None
        need_grid = False
        try:
            last_state = getattr(self, '_last_grid_state', None)
            cur_state = (profile_mode, float(y_min), float(y_max))
            if last_state is None:
                need_grid = True
            else:
                # 模式改变或Y范围发生变化（阈值极小，保证切换时重绘）
                ly_mode, ly0, ly1 = last_state
                if ly_mode != cur_state[0] or abs(ly0 - cur_state[1]) > 1e-6 or abs(ly1 - cur_state[2]) > 1e-6:
                    need_grid = True
        except Exception:
            need_grid = True
        if need_grid:
            self.setup_ecg_grid()
            try:
                self._last_grid_state = (profile_mode, float(y_min), float(y_max))
            except Exception:
                self._last_grid_state = (profile_mode, y_min, y_max)
        else:
            # 网格无需重建时，仍确保辅助线与标签同步
            try:
                self.update_guides()
            except Exception:
                pass

        # 强制刷新画布以确保时间轴标签正确显示
        self.canvas.draw_idle()
        try:
            has_technique_events = bool(getattr(self, '_technique_events', None))
        except Exception:
            has_technique_events = False
        try:
            self._refresh_technique_artists(force=has_technique_events)
        except Exception:
            pass
        # 回听图元随坐标变化同步更新
        try:
            if hasattr(self, 'update_listenback_artists'):
                self.update_listenback_artists()
        except Exception:
            pass

    # ================= Y轴锁定控制 =================
    def lock_y_axis(self):
        """显式锁定当前Y轴范围，防止后续被自动缩放或跟随修改"""
        self.freeze_y_center = True
        self._locked_y_limits = self.ax.get_ylim()
        self._initial_y_center = (self._locked_y_limits[0] + self._locked_y_limits[1]) / 2.0
        print(f"🔒 锁定Y轴: {self._locked_y_limits}")

    def unlock_y_axis(self):
        """解除Y轴锁定，允许根据中心/缩放重新计算"""
        prev_limits = getattr(self, '_locked_y_limits', None)
        self.freeze_y_center = False
        self._locked_y_limits = None
        print(f"🔓 解锁Y轴 (之前={prev_limits})，即将重新计算网格")
        # 解除锁定后立刻重建网格以反映当前中心和 zoom
        self.update_axis_ranges()
    
    def on_mouse_press(self, event):
        """鼠标按下事件"""
        if event.inaxes != self.ax:
            return
        selection_mode = self._interaction_selection_mode()
        # 回听/重录：播放状态命中检测 + 选区拖拽/播放切换
        try:
            if selection_mode in ('listenback', 'retake'):
                if selection_mode == 'listenback':
                    ap = getattr(self, 'audio_processor', None)
                    is_playing = bool(ap and getattr(ap, '_lb_state', '') == 'playing')
                    # 播放中：优先检测暂停/结束按钮命中
                    if is_playing and event.xdata is not None and event.ydata is not None:
                        x, y = float(event.xdata), float(event.ydata)
                        # 命中暂停左右条
                        try:
                            if self._pause_hit_boxes:
                                for (x0,x1,y0,y1) in self._pause_hit_boxes:
                                    if x0 <= x <= x1 and y0 <= y <= y1:
                                        self._handle_pause_click()
                                        return
                        except Exception:
                            pass
                        # 命中结束按钮
                        try:
                            if self._stop_hit_box:
                                x0,x1,y0,y1 = self._stop_hit_box
                                if x0 <= x <= x1 and y0 <= y <= y1:
                                    self._handle_stop_click()
                                    return
                        except Exception:
                            pass
                # 未播放时允许拖拽/触发播放
                if getattr(self, 'selection_active', False):
                    # 计算阈值：约6px对应的秒数
                    try:
                        px_w = float(self.ax.bbox.width)
                        x0, x1 = self.ax.get_xlim()
                        sec_per_px = max(1e-9, (x1 - x0) / max(1.0, px_w))
                        thr = sec_per_px * 6.0
                    except Exception:
                        thr = 0.05
                    x = event.xdata
                    start = end = None
                    if x is not None:
                        try:
                            start = float(self.sel_start)
                            end = float(self.sel_end)
                        except Exception:
                            start = end = None
                    # 先检测左右边线把手，再检测播放头，避免播放头抢占左线
                    if x is not None and start is not None and end is not None:
                        if start > end:
                            start, end = end, start
                        dL = abs(x - start)
                        dR = abs(x - end)
                        if dL <= dR and dL <= thr:
                            self._sel_dragging_side = 'left'
                            self._sel_dragging_last_x = None
                            try:
                                self._set_selection_hover_state('left')
                            except Exception:
                                pass
                            return
                        if dR < dL and dR <= thr:
                            self._sel_dragging_side = 'right'
                            self._sel_dragging_last_x = None
                            try:
                                self._set_selection_hover_state('right')
                            except Exception:
                                pass
                            return
                    # 播放头命中检测（仅 listenback 需要）
                    if selection_mode == 'listenback':
                        try:
                            if x is not None and hasattr(self, '_lb_playhead') and self._lb_playhead is not None:
                                phx_data = self._lb_playhead.get_xdata()
                                phx = float(phx_data[0]) if phx_data is not None and len(phx_data) > 0 else float(self.sel_start)
                                if abs(x - phx) <= thr:
                                    self._dragging_playhead = True
                                    self._lb_user_moved_playhead = True
                                    return
                        except Exception:
                            pass
                        # 仅点击绿色播放按钮所在正方形命中区域才触发
                        try:
                            if x is not None and self._play_hit_box is not None and event.ydata is not None:
                                x0,x1,y0,y1 = self._play_hit_box
                                if x0 <= x <= x1 and y0 <= event.ydata <= y1:
                                    self._toggle_listenback_play_pause()
                                    return
                        except Exception:
                            pass
                    # 区间整体拖动：点击选区中间（非播放按钮区域）即可左右平移
                    if x is not None and start is not None and end is not None and start <= x <= end:
                        if selection_mode in ('retake', 'listenback'):
                            self._sel_dragging_side = 'block'
                            self._sel_dragging_last_x = x
                            return
        except Exception:
            pass

        # 否则进入原有平移拖拽
        self.dragging = True
        self.drag_start_pos = (event.x, event.y)
        self.drag_start_y_center = self.y_view_center
        self.drag_start_time_offset = self.time_offset
    
    def on_mouse_release(self, event):
        """鼠标释放事件"""
        # 回听选区拖拽结束
        if getattr(self, '_sel_dragging_side', None) is not None:
            self._sel_dragging_side = None
            self._sel_dragging_last_x = None
            try:
                self._set_selection_hover_state(None)
            except Exception:
                pass
            try:
                self.update_listenback_artists()
            except Exception:
                pass
            if hasattr(self, 'canvas'):
                self.canvas.draw_idle()
            return
        # 回听播放头拖拽结束
        if getattr(self, '_dragging_playhead', False):
            self._dragging_playhead = False
            # 保持已移动标记，不在此处清除
            try:
                self.update_listenback_artists()
            except Exception:
                pass
            if hasattr(self, 'canvas'):
                self.canvas.draw_idle()
            return
        self.dragging = False
        self.drag_start_pos = None
    
    def on_mouse_move(self, event):
        """鼠标移动事件"""
        # 更新光标（暂停/浏览态 -> 蓝色羽毛）
        try:
            self._update_hover_cursor(event)
        except Exception:
            pass
        try:
            self._update_selection_hover_hint(event)
        except Exception:
            pass
        # 回听：拖拽选区
        if getattr(self, '_sel_dragging_side', None) is not None:
            try:
                x = self._event_time_from_axes_pixels(event)
                if x is None:
                    return
                mode = self._interaction_selection_mode()
                if self._sel_dragging_side == 'block':
                    last = getattr(self, '_sel_dragging_last_x', None)
                    if last is None:
                        self._sel_dragging_last_x = x
                        return
                    delta = x - last
                    if abs(delta) <= 1e-9:
                        return
                    span = float(self.sel_end) - float(self.sel_start)
                    new_start = float(self.sel_start) + delta
                    new_end = new_start + span
                    # 保证不越界
                    if mode == 'listenback':
                        max_time = self._get_listenback_right_limit()
                    else:
                        max_time = getattr(self, 'max_history_time', None)
                        try:
                            max_time = float(max_time) if max_time is not None else None
                        except Exception:
                            max_time = None
                    if new_start < 0.0:
                        shift = -new_start
                        new_start += shift
                        new_end += shift
                    if max_time is not None and new_end > max_time:
                        shift = new_end - max_time
                        new_start -= shift
                        new_end -= shift
                        if new_start < 0.0:
                            new_start = 0.0
                    if mode == 'retake':
                        self.set_retake_range(new_start, new_end, refresh=False, sync_playhead=False, anchor_side='block')
                    else:
                        self.sel_start = new_start
                        self.sel_end = new_end
                        # 选区调整后，清除恢复点并标记为“用户移动”，确保可多次回听
                        try:
                            self._lb_resume_abs_start = None
                            self._lb_user_moved_playhead = True
                        except Exception:
                            pass
                        # 播放头随选区平移（非拖动状态）
                        try:
                            ap_state = getattr(getattr(self, 'audio_processor', None), '_lb_state', '')
                            if ap_state != 'playing' and not getattr(self, '_dragging_playhead', False):
                                self._ensure_playhead()
                                if hasattr(self, '_lb_playhead') and self._lb_playhead is not None:
                                    phx_data = self._lb_playhead.get_xdata()
                                    phx = float(phx_data[0]) if phx_data is not None and len(phx_data) > 0 else float(self.sel_start)
                                    phx = min(max(phx + delta, self.sel_start), self.sel_end)
                                    self._lb_playhead.set_xdata([phx, phx])
                                    self._lb_playhead.set_ydata([0.0, 1.0])
                                    self._lb_playhead.set_visible(True)
                                    self._lb_playhead.set_zorder(148)
                        except Exception:
                            pass
                    self._sel_dragging_last_x = x
                    self.update_listenback_artists()
                    if hasattr(self, 'canvas'):
                        self.canvas.draw_idle()
                    return
                if self._sel_dragging_side == 'left':
                    new_start = min(x, self.sel_end)
                    if mode == 'retake':
                        self.set_retake_range(new_start, self.sel_end, refresh=False, sync_playhead=True, anchor_side='left')
                    else:
                        self.sel_start = min(x, self.sel_end)
                        # 清除恢复点，避免复用旧播放位置
                        try:
                            self._lb_resume_abs_start = None
                            self._lb_user_moved_playhead = True
                        except Exception:
                            pass
                        # 联动播放头：未播放时播放头起点跟随左边线
                        try:
                            ap_state = getattr(getattr(self, 'audio_processor', None), '_lb_state', '')
                            if ap_state == 'stopped':
                                self._ensure_playhead()
                                if hasattr(self, '_lb_playhead') and self._lb_playhead is not None:
                                    self._lb_playhead.set_xdata([self.sel_start, self.sel_start])
                                    self._lb_playhead.set_ydata([0.0, 1.0])
                                    self._lb_playhead.set_visible(True)
                                    self._lb_playhead.set_zorder(148)
                        except Exception:
                            pass
                elif self._sel_dragging_side == 'right':
                    new_end = max(x, self.sel_start)
                    if mode == 'retake':
                        self.set_retake_range(self.sel_start, new_end, refresh=False, sync_playhead=False, anchor_side='right')
                    else:
                        # listenback 右边界限制
                        max_time = self._get_listenback_right_limit()
                        if max_time is not None:
                            new_end = min(new_end, max_time)
                        self.sel_end = max(new_end, self.sel_start)
                        try:
                            self._lb_resume_abs_start = None
                            self._lb_user_moved_playhead = True
                        except Exception:
                            pass
                self.update_listenback_artists()
                if hasattr(self, 'canvas'):
                    self.canvas.draw_idle()
            except Exception:
                pass
            return
        # 回听：拖拽播放头
        if getattr(self, '_dragging_playhead', False) and event.inaxes == self.ax:
            try:
                x = event.xdata
                if x is None:
                    return
                # 限制在选区范围内
                xL = float(self.sel_start)
                xR = float(self.sel_end)
                lo, hi = (xL, xR) if xL <= xR else (xR, xL)
                x = min(max(x, lo), hi)
                self._ensure_playhead()
                if hasattr(self, '_lb_playhead') and self._lb_playhead is not None:
                    self._lb_playhead.set_xdata([x, x])
                    self._lb_playhead.set_ydata([0.0, 1.0])
                    self._lb_playhead.set_visible(True)
                    self._lb_playhead.set_zorder(148)
                # 标记用户已手动移动播放头
                self._lb_user_moved_playhead = True
                if hasattr(self, 'canvas'):
                    self.canvas.draw_idle()
            except Exception:
                pass
            return
        if (not self.dragging) or (event.inaxes != self.ax):
            # 非拖拽时尝试悬停提示（提炼为助手函数，避免此处嵌套影响缩进解析）
            try:
                self._handle_non_drag_hover(event)
            except Exception:
                pass
            return
        
        if self.drag_start_pos is None:
            return
        
        # 计算移动距离
        dx = event.x - self.drag_start_pos[0]
        dy = event.y - self.drag_start_pos[1]
        
        # 转换为数据坐标
        fig_height = self.figure.get_figheight() * self.figure.dpi
        fig_width = self.figure.get_figwidth() * self.figure.dpi
        
        # 垂直拖拽调整音高范围（若允许）
        prof = getattr(self, '_current_zoom_profile', None) or self._get_zoom_profile()
        if not prof.get('disable_v_scroll'):
            if not hasattr(self, 'y_view_range'):
                self.y_view_range = self.compute_half_range()
            dy_data = -dy / fig_height * (self.y_view_range * 2)
            new_y_center = self.drag_start_y_center + dy_data
            self.y_view_center = max(1.0, min(7.0, new_y_center))
        
        # 水平拖拽调整时间偏移
        dx_data = -dx / fig_width * self.time_window * 1.5  # 负号实现反向拖拽
        new_time_offset = self.drag_start_time_offset + dx_data
        self.time_offset = max(0, min(self.max_history_time - self.time_window, new_time_offset))
        # 标记手动操作时间，供平滑器在短期内提升响应或避免与手动冲突
        try:
            import time as _t
            self._last_manual_scroll_time = _t.time()
        except Exception:
            pass
        
        # 更新显示（轻量：仅设置 xlim，避免重建网格导致粘滞感）
        try:
            x_min = self.time_offset
            x_max = self.time_offset + self.time_window
            # 手动拖拽：直接设置，避免“跟随平滑器”带来的滞后
            self.ax.set_xlim(x_min, x_max)
        except Exception:
            pass
        # 同步回听图元
        try:
            self.update_listenback_artists()
        except Exception:
            pass
        # 录音中：轻量刷新批量细节点；停止后：空白区域快速路径，返回数据区再完整重绘
        if getattr(self, 'is_recording_active', False):
            self._refresh_batched_points_for_current_xlim()
            # 水平滚动后避免临时折线与分段线同窗叠加，强制隐藏临时折线
            try:
                if hasattr(self, '_provisional_line') and self._provisional_line is not None:
                    self._provisional_line.set_visible(False)
            except Exception:
                pass
            # 统一细节点层级
            try:
                if hasattr(self, '_batched_points') and self._batched_points is not None:
                    self._batched_points.set_zorder(14)
            except Exception:
                pass
        else:
            try:
                # 快速判断：若当前视口完全在最后数据点之后，则走轻路径避免重帧
                last_t = None
                try:
                    last_t = self.time_data[-1] if self.time_data else None
                except Exception:
                    last_t = None
                x_min = self.time_offset
                x_max = self.time_offset + self.time_window
                in_blank_future = (last_t is not None) and (x_min > last_t + 1e-3)
                # 完全空工程（无数据）也视为空白区域
                if (last_t is None) or in_blank_future:
                    # 轻路径：仅更新辅助线/滚动条/画布
                    try:
                        self.update_guides()
                    except Exception:
                        pass
                else:
                    # 回到数据区：强制一次完整重绘，保证逐段散点与线条同步
                    self._force_redraw_on_next_update = True
                    self.update_display()
            except Exception:
                pass
        if hasattr(self, 'canvas'):
            self.canvas.draw_idle()
        
        # 同步更新滚动条
        self.update_scrollbars()

        # 非拖拽状态下，尝试悬停提示（此处通常为拖拽路径，不执行）
        try:
            if not self.dragging:
                self._handle_hover_tooltip(event)
        except Exception:
            pass

    # ================= 回听：播放/暂停 与 播放头 =================
    def _toggle_listenback_play_pause(self):
        try:
            ap = getattr(self, 'audio_processor', None)
            if ap is None:
                return
            now = time.time()
            # 选区对应的绝对时间：基于可视化器 start_time
            if not hasattr(self, 'start_time') or self.start_time is None:
                return
            abs_start = float(self.start_time) + float(self.sel_start)
            abs_end = float(self.start_time) + float(self.sel_end)
            state = getattr(ap, '_lb_state', 'stopped')
            if state == 'playing':
                # 使用统一的暂停处理，保证_resume点与_user_paused等状态正确
                self._handle_pause_click()
                return
            if state == 'paused' or getattr(self, '_lb_user_paused', False):
                try:
                    ap_sr = float(getattr(ap, 'sample_rate', getattr(self, 'sample_rate', 48000)))
                except Exception:
                    ap_sr = float(getattr(self, 'sample_rate', 48000))
                upper_bound = abs_end if abs_end > abs_start else abs_start
                buffer_abs_start = float(getattr(ap, '_lb_data_abs_start', abs_start))
                played_sec = float(getattr(ap, '_lb_pos', 0)) / max(ap_sr, 1.0)
                buffer_resume_abs = buffer_abs_start + played_sec
                buffer_resume_abs = max(abs_start, min(upper_bound, buffer_resume_abs))
                try:
                    resume_abs_start = float(getattr(self, '_lb_resume_abs_start', None) or 0.0)
                    if resume_abs_start <= 0.0:
                        phx = None
                        if hasattr(self, '_lb_playhead') and self._lb_playhead is not None:
                            xd = self._lb_playhead.get_xdata()
                            if xd is not None and len(xd) > 0:
                                phx = float(xd[0])
                        if phx is None:
                            resume_abs_start = buffer_resume_abs
                        else:
                            resume_abs_start = float(self.start_time) + float(phx)
                except Exception:
                    resume_abs_start = buffer_resume_abs
                resume_abs_start = max(abs_start, min(upper_bound, resume_abs_start))
                tol = max(1.0 / max(ap_sr, 1.0), 5e-4)
                user_moved = bool(getattr(self, '_lb_user_moved_playhead', False))
                can_resume = (
                    state == 'paused'
                    and not user_moved
                    and getattr(ap, '_lb_data', None) is not None
                    and abs(buffer_resume_abs - resume_abs_start) <= tol
                )
                actual_abs_start = buffer_resume_abs if can_resume else resume_abs_start
                try:
                    self._lb_user_paused = False
                except Exception:
                    pass
                try:
                    self._lb_resume_abs_start = None
                except Exception:
                    pass
                ok = False
                if can_resume:
                    ok = bool(ap.resume_listenback_playback())
                if not ok:
                    ok = ap.start_listenback_playback(resume_abs_start, abs_end)
                    actual_abs_start = resume_abs_start
                if not ok:
                    return
                self.selection_active = False
                self._ensure_playhead()
                try:
                    self._start_playhead_timer(actual_abs_start, abs_end)
                except Exception:
                    self._start_playhead_timer(abs_start, abs_end)
                try:
                    self._lb_user_moved_playhead = False
                except Exception:
                    pass
                try:
                    if self._sel_play_icon is not None:
                        self._sel_play_icon.set_visible(False)
                    for art in (self._sel_pause_icon_left, self._sel_pause_icon_right, self._sel_stop_icon):
                        if art is not None:
                            art.set_visible(True)
                    self.update_listenback_artists()
                except Exception:
                    pass
                self.canvas.draw_idle()
                return
            # 开始播放：若播放头在选区内，则从播放头位置开始
            try:
                phx = None
                if hasattr(self, '_lb_playhead') and self._lb_playhead is not None:
                    xd = self._lb_playhead.get_xdata()
                    if xd is not None and len(xd) > 0:
                        phx = float(xd[0])
                if phx is not None:
                    ph_abs = float(self.start_time) + float(phx)
                    # 夹紧到 [abs_start, abs_end]
                    abs_s = max(abs_start, min(ph_abs, abs_end - 1e-6))
                else:
                    abs_s = abs_start
            except Exception:
                abs_s = abs_start
            # 开始播放：清除“用户暂停”标记
            try:
                self._lb_user_paused = False
            except Exception:
                pass
            ok = ap.start_listenback_playback(abs_s, abs_end)
            if not ok:
                # 一次性自愈：若没有数据，尝试自动将选区对齐到最近5秒数据并重试
                try:
                    last_end_abs = self._get_listenback_chunk_end()
                    if last_end_abs is not None and hasattr(self, 'start_time') and self.start_time is not None:
                        span = max(1.0, min(10.0, float(self.sel_end - self.sel_start) or 5.0))
                        new_abs_end = last_end_abs
                        new_abs_start = new_abs_end - span
                        # 更新本地选区（相对轴）
                        self.sel_start = float(new_abs_start - float(self.start_time))
                        self.sel_end = float(new_abs_end - float(self.start_time))
                        self.update_listenback_artists()
                        self.canvas.draw_idle()
                        # 重试一次
                        ok = ap.start_listenback_playback(new_abs_start, new_abs_end)
                except Exception:
                    pass
            if not ok:
                return
            # 播放中隐藏选区，显示移动播放头
            self.selection_active = False
            self._ensure_playhead()
            self._start_playhead_timer(abs_s, abs_end)
            try:
                if self._sel_play_icon is not None:
                    self._sel_play_icon.set_visible(False)
                for art in (self._sel_pause_icon_left, self._sel_pause_icon_right, self._sel_stop_icon):
                    if art is not None:
                        art.set_visible(True)
            except Exception:
                pass
            # 立即刷新一次UI，让选区线/把手隐藏、暂停与结束按钮出现
            try:
                self.update_listenback_artists()
            except Exception:
                pass
            self.canvas.draw_idle()
        except Exception as e:
            try:
                print(f"⚠️ 回听切换失败: {e}")
            except Exception:
                pass

    def _ensure_playhead(self):
        try:
            if not hasattr(self, 'ax') or self.ax is None:
                return
            if not hasattr(self, '_lb_playhead') or self._lb_playhead is None:
                # 雾霾蓝播放头（可拖动）
                haze_blue = (0.49, 0.60, 0.67, 0.95)  # 近似雾霾蓝，稍不透明
                self._lb_playhead = self.ax.axvline(x=self.sel_start, color=haze_blue, linewidth=1.6, zorder=148)
                # 使用轴坐标 0..1 覆盖高度
                try:
                    self._lb_playhead.set_ydata([0.0, 1.0])
                except Exception:
                    pass
            else:
                try:
                    # 确保样式一致
                    haze_blue = (0.49, 0.60, 0.67, 0.95)
                    self._lb_playhead.set_color(haze_blue)
                    self._lb_playhead.set_linewidth(1.6)
                    self._lb_playhead.set_ydata([0.0, 1.0])
                except Exception:
                    pass
        except Exception:
            pass

    def _ensure_onepass_time_cursor(self):
        try:
            if not hasattr(self, 'ax') or self.ax is None:
                return
            line_color = str(getattr(self, 'guide_v_color', '#C0C0C0') or '#C0C0C0')
            line_alpha = float(getattr(self, 'guide_alpha_main', 0.90) or 0.90)
            line_width = float(getattr(self, 'guide_linewidth_main', 0.8) or 0.8)
            dash_pattern = tuple(getattr(self, 'guide_dash_pattern', (6, 4)) or (6, 4))
            cursor = getattr(self, '_onepass_time_cursor', None)
            if cursor is None or getattr(cursor, 'axes', None) is None or cursor not in getattr(self.ax, 'lines', []):
                self._onepass_time_cursor = self.ax.axvline(
                    x=float(getattr(self, 'current_global_time', 0.0) or 0.0),
                    color=line_color,
                    linewidth=line_width,
                    alpha=line_alpha,
                    linestyle='--',
                    zorder=148,
                )
                cursor = self._onepass_time_cursor
            if cursor is not None:
                try:
                    cursor.set_color(line_color)
                    cursor.set_alpha(line_alpha)
                    cursor.set_linewidth(line_width)
                    cursor.set_linestyle((0, dash_pattern))
                    cursor.set_ydata([0.0, 1.0])
                    cursor.set_zorder(148)
                except Exception:
                    try:
                        cursor.set_linestyle('--')
                    except Exception:
                        pass
        except Exception:
            pass

    def _set_onepass_time_cursor(self, sec: float, *, visible: bool = True):
        try:
            self._ensure_onepass_time_cursor()
            cursor = getattr(self, '_onepass_time_cursor', None)
            if cursor is None:
                return
            x_val = float(max(0.0, sec))
            cursor.set_xdata([x_val, x_val])
            cursor.set_ydata([0.0, 1.0])
            cursor.set_visible(bool(visible))
            cursor.set_zorder(148)
        except Exception:
            pass

    # ================= 悬停提示实现 =================
    def _hover_gating_allowed(self) -> bool:
        try:
            # 0) 选区/回听/重录交互阶段：允许悬停放大镜（避免被录音态误判而关闭）
            try:
                if bool(getattr(self, 'selection_active', False)) or bool(getattr(self, 'retake_selection_active', False)) or bool(getattr(self, 'listenback_enabled', False)):
                    return True
            except Exception:
                pass
            # 0.5) 外部/伴奏/录音暂停标记：允许悬停浏览
            try:
                if bool(getattr(self, '_external_paused', False)) or bool(getattr(self, 'is_backing_paused', False)) or bool(getattr(self, 'is_recording_paused', False)):
                    return True
            except Exception:
                pass
            # 1) 直接使用本组件自身的暂停/录音状态（优先级最高，最直观符合用户期望）
            try:
                if bool(getattr(self, 'is_paused', False)):
                    return True
            except Exception:
                pass
            try:
                # 非录音状态也允许浏览
                if hasattr(self, 'is_recording') and not bool(getattr(self, 'is_recording', False)):
                    return True
            except Exception:
                pass
            try:
                # 录音活跃状态关闭时（已停止）允许浏览
                if hasattr(self, 'is_recording_active') and not bool(getattr(self, 'is_recording_active', False)):
                    return True
            except Exception:
                pass

            # 2) 音频处理器状态（如存在）
            ap = getattr(self, 'audio_processor', None)
            if ap is not None:
                if getattr(ap, 'is_recording', False) and getattr(ap, 'is_paused', False):
                    return True
                if not getattr(ap, 'is_recording', False):
                    return True
            lb_state = getattr(self, '_lb_state', None)
            lb_user_paused = getattr(self, '_lb_user_paused', False)
            if lb_state == 'paused' or lb_user_paused:
                return True
        except Exception:
            return False
        return False

    def _collect_visible_point_collections(self):
        cols = []
        try:
            hp = getattr(self, '_head_points_scatter', None)
            if hp is not None and hp.get_visible():
                cols.append(hp)
        except Exception:
            pass
        try:
            bf = getattr(self, '_browse_points_fallback', None)
            if bf is not None and bf.get_visible():
                cols.append(bf)
        except Exception:
            pass
        try:
            bp = getattr(self, '_batched_points', None)
            if bp is not None and bp.get_visible():
                cols.append(bp)
        except Exception:
            pass
        try:
            segs = getattr(self, '_segment_points', None)
            if isinstance(segs, (list, tuple)):
                for s in segs:
                    try:
                        if s is not None and s.get_visible():
                            cols.append(s)
                    except Exception:
                        continue
        except Exception:
            pass
        return cols

    # ================= 自定义蓝色羽毛光标 =================
    def _ensure_blue_feather_cursor(self):
        """懒生成一枚蓝色羽毛样式的 QCursor，失败返回 None。"""
        try:
            if getattr(self, '_cursor_feather_blue', None) is not None:
                return self._cursor_feather_blue
            try:
                from PyQt6.QtGui import QCursor, QPixmap, QPainter, QPen, QBrush, QColor, QPainterPath, QLinearGradient
            except Exception:
                from PyQt5.QtGui import QCursor, QPixmap, QPainter, QPen, QBrush, QColor, QPainterPath, QLinearGradient  # type: ignore
            size = 36
            pm = QPixmap(size, size)
            pm.fill(QColor(0, 0, 0, 0))
            p = None
            try:
                p = QPainter(pm)
                try:
                    p.setRenderHint(QPainter.RenderHint.Antialiasing, True)
                except Exception:
                    p.setRenderHint(QPainter.Antialiasing, True)
                # 羽毛主体路径
                path = QPainterPath()
                path.moveTo(7, 8)
                path.cubicTo(12, 3, 22, 3, 29, 12)
                path.cubicTo(31, 16, 29, 24, 22, 29)
                path.cubicTo(16, 33, 10, 28, 10, 22)
                path.cubicTo(10, 18, 12, 14, 15, 12)
                # 竖梗
                stem = QPainterPath()
                stem.moveTo(13, 31)
                stem.lineTo(24, 9)
                # 轻微投影
                shadow = QPainterPath(path)
                shadow.translate(1.5, 1.5)
                p.setPen(QPen(QColor(0, 0, 0, 50), 1.0))
                p.setBrush(QBrush(QColor(0, 0, 0, 40)))
                p.drawPath(shadow)
                # 渐变填充
                blue = QColor(66, 170, 255)
                blue2 = QColor(30, 120, 210)
                dark = QColor(24, 96, 168)
                grad = QLinearGradient(7, 8, 29, 30)
                grad.setColorAt(0.0, blue)
                grad.setColorAt(1.0, blue2)
                p.setPen(QPen(dark, 1.2))
                p.setBrush(QBrush(grad))
                p.drawPath(path)
                p.setPen(QPen(dark, 1.5))
                p.drawPath(stem)
            finally:
                try:
                    if p is not None:
                        p.end()
                except Exception:
                    pass
            try:
                cur = QCursor(pm, 7, 8)
            except Exception:
                cur = QCursor(pm)
            self._cursor_feather_blue = cur
            return cur
        except Exception:
            return None

    def _update_hover_cursor(self, event):
        """根据门控与轴命中，切换画布光标为蓝色羽毛或默认箭头。"""
        try:
            canvas = getattr(self, 'canvas', None)
            if canvas is None:
                return
            try:
                from PyQt6.QtCore import Qt
                from PyQt6.QtGui import QCursor
                ARROW = QCursor(Qt.CursorShape.ArrowCursor)
            except Exception:
                from PyQt5.QtCore import Qt  # type: ignore
                from PyQt5.QtGui import QCursor  # type: ignore
                ARROW = QCursor(Qt.ArrowCursor)
            # 主轴或放大镜轴上均维持羽毛光标（镜片上也保持一致的视觉风格）
            magn_ax = getattr(self, '_magnifier_ax', None)
            on_main = bool(event and event.inaxes == self.ax)
            on_magn = bool(event and magn_ax is not None and event.inaxes == magn_ax)
            allowed = bool(self._hover_gating_allowed()) and (on_main or on_magn)
            if allowed:
                cur = self._ensure_blue_feather_cursor()
                if cur is not None and not getattr(self, '_cursor_is_feather', False):
                    try:
                        canvas.setCursor(cur)
                        self._cursor_is_feather = True
                    except Exception:
                        pass
            else:
                if getattr(self, '_cursor_is_feather', False):
                    try:
                        canvas.setCursor(ARROW)
                    except Exception:
                        pass
                    self._cursor_is_feather = False
        except Exception:
            pass

    # ================= 悬停注解确保（ax.clear 后可自愈） =================
    def _ensure_hover_annot(self):
        try:
            # 若已有注解但已从当前 ax 分离，或 ax 改变，统一重建
            need_new = False
            if getattr(self, '_hover_annot', None) is None:
                need_new = True
            else:
                try:
                    if getattr(self._hover_annot, 'axes', None) is not self.ax:
                        need_new = True
                except Exception:
                    need_new = True
            if not need_new:
                return self._hover_annot
            # 创建新的注解
            from matplotlib.patches import FancyBboxPatch  # noqa: F401
            box_fc = getattr(self, 'bg_color', '#111111')
            edge_c = getattr(self, 'grid_color', '#666666')
            txt_c = getattr(self, 'text_color', '#DDDDDD')
            ann = self.ax.annotate(
                "",
                xy=(0, 0),
                xytext=(10, 16),
                textcoords='offset points',
                ha='left', va='bottom',
                fontsize=10,
                color=txt_c,
                bbox=dict(boxstyle='round,pad=0.35,rounding_size=3', fc=box_fc, ec=edge_c, alpha=0.90, lw=1.0),
                arrowprops=dict(arrowstyle='-|>', connectionstyle='arc3,rad=0.15', color=edge_c, lw=1.0, shrinkA=0, shrinkB=8)
            )
            try:
                ann.set_clip_on(False)
            except Exception:
                pass
            ann.set_visible(False)
            ann.set_zorder(9999)
            self._hover_annot = ann
            return ann
        except Exception:
            self._hover_annot = None
            return None

    def _handle_non_drag_hover(self, event):
        """非拖拽态下的悬停处理：
        - 主轴上：执行悬停命中与放大镜更新
        - 离开主轴且不在放大镜轴上：隐藏悬停工件
        """
        try:
            magn_ax = getattr(self, '_magnifier_ax', None)
            in_main = (event.inaxes == self.ax)
            in_magn = (magn_ax is not None and event.inaxes == magn_ax)
            if in_main:
                try:
                    self._handle_hover_tooltip(event)
                except Exception:
                    pass
                return
            if (not in_magn) and hasattr(self, '_hover_annot') and (self._hover_annot is not None):
                if self._hover_annot.get_visible():
                    self._hover_annot.set_visible(False)
                try:
                    self._hide_hover_highlight()
                except Exception:
                    pass
                try:
                    self._hide_magnifier()
                except Exception:
                    pass
                if hasattr(self, 'canvas'):
                    self.canvas.draw_idle()
        except Exception:
            pass

    # ================= 悬停高亮（光晕 + 外环） =================
    def _ensure_hover_highlight_artists(self):
        try:
            if not hasattr(self, 'ax') or self.ax is None:
                return
            # 光晕：较大点，半透明亮蓝
            if self._hover_glow is None or getattr(self._hover_glow, 'axes', None) is not self.ax:
                try:
                    # 若对象存在但已脱离当前轴，先尝试移除再重建
                    if self._hover_glow is not None:
                        try:
                            self._hover_glow.remove()
                        except Exception:
                            pass
                    glow_color = (0.20, 0.60, 1.00, 0.28)  # 柔和蓝色光晕
                    self._hover_glow = self.ax.scatter([], [], s=190, color=glow_color,
                                                       linewidths=0, edgecolors='none', zorder=9980)
                    self._hover_glow.set_visible(False)
                except Exception:
                    self._hover_glow = None
            # 外环：细描边环形，透明填充
            if self._hover_ring is None or getattr(self._hover_ring, 'axes', None) is not self.ax:
                try:
                    if self._hover_ring is not None:
                        try:
                            self._hover_ring.remove()
                        except Exception:
                            pass
                    ring_edge = (0.75, 0.85, 1.00, 0.95)  # 淡亮边
                    self._hover_ring = self.ax.scatter([], [], s=46, facecolors=(0,0,0,0),
                                                       linewidths=1.4, edgecolors=[ring_edge], zorder=9985)
                    self._hover_ring.set_visible(False)
                except Exception:
                    self._hover_ring = None
        except Exception:
            pass

    def _update_hover_highlight(self, x: float, y: float):
        try:
            self._ensure_hover_highlight_artists()
            changed = False
            if self._hover_glow is not None:
                try:
                    self._hover_glow.set_offsets([(x, y)])
                    self._hover_glow.set_visible(True)
                    changed = True
                except Exception:
                    pass
            if self._hover_ring is not None:
                try:
                    self._hover_ring.set_offsets([(x, y)])
                    self._hover_ring.set_visible(True)
                    changed = True
                except Exception:
                    pass
            if changed:
                self._hover_highlight_last_xy = (x, y)
        except Exception:
            pass

    def _hide_hover_highlight(self):
        try:
            changed = False
            if self._hover_glow is not None and self._hover_glow.get_visible():
                try:
                    self._hover_glow.set_visible(False)
                    changed = True
                except Exception:
                    pass
            if self._hover_ring is not None and self._hover_ring.get_visible():
                try:
                    self._hover_ring.set_visible(False)
                    changed = True
                except Exception:
                    pass
            if changed and hasattr(self, 'canvas'):
                self.canvas.draw_idle()
        except Exception:
            pass

    def _set_onepass_playback_point_mode(self, enabled: bool):
        try:
            self._onepass_playback_fixed_points_enabled = bool(enabled)
        except Exception:
            pass

    def _get_stable_segment_points_mode(self):
        try:
            if bool(getattr(self, '_onepass_playback_fixed_points_enabled', False)):
                return 'onepass_playback'
            mode_text = self.display_mode.currentText() if hasattr(self, 'display_mode') else '普通模式'
        except Exception:
            mode_text = '普通模式'
        if mode_text != '普通模式':
            return ''
        try:
            import time as _t
            host = getattr(self, '_host_interface', None)
            lfm_ctrl = getattr(host, '_lfm_ctrl', None) if host is not None else None
            lfm_playing = bool(lfm_ctrl is not None and getattr(lfm_ctrl, 'playing', False))
            recording_live = bool(getattr(self, 'is_recording_active', False)) or lfm_playing
            if not recording_live:
                return ''
            if not bool(getattr(self, 'auto_follow', True)) or not bool(getattr(self, 'auto_scroll_enabled', True)):
                return ''
            if bool(getattr(self, '_retake_overlay_preview_active', False)) or bool(getattr(self, '_retake_countdown_active', False)):
                return ''
            if float(getattr(self, 'current_global_time', 0.0) or 0.0) <= float(getattr(self, 'center_display_time', 8.0) or 8.0):
                return ''
            if (not lfm_playing) and float(getattr(self, '_manual_time_offset_override_until', 0.0) or 0.0) > _t.time():
                return ''
            return 'realtime_follow_scroll_lfm' if lfm_playing else 'realtime_follow_scroll'
        except Exception:
            return ''

    def _get_stable_segment_offsets(self, seg_times, seg_pitches, mode_key: str):
        try:
            import numpy as _np
            import math as _math
            if not seg_times or not seg_pitches:
                return _np.empty((0, 2), dtype=_np.float32)
            count = min(len(seg_times), len(seg_pitches))
            if count <= 0:
                return _np.empty((0, 2), dtype=_np.float32)
            cache = getattr(self, '_stable_segment_points_cache', None)
            if not isinstance(cache, dict):
                cache = {}
                self._stable_segment_points_cache = cache
            sig = (str(mode_key or ''), float(seg_times[0]), float(seg_times[count - 1]), int(count))
            cached = cache.get(sig)
            if cached is not None:
                return cached
            if str(mode_key or '') == 'onepass_playback':
                target_cap = int(getattr(self, '_onepass_playback_segment_points_cap', 900) or 900)
                target_floor = int(getattr(self, '_onepass_playback_segment_points_floor', 260) or 260)
            else:
                target_cap = int(getattr(self, '_realtime_scroll_segment_points_cap', 720) or 720)
                target_floor = int(getattr(self, '_realtime_scroll_segment_points_floor', 220) or 220)
            target_cap = max(80, target_cap)
            target_floor = max(80, min(target_floor, target_cap))
            if count <= target_cap:
                offs = _np.column_stack((
                    _np.asarray(seg_times[:count], dtype=_np.float32),
                    _np.asarray(seg_pitches[:count], dtype=_np.float32),
                ))
            else:
                sample_count = min(count, max(target_floor, target_cap))
                idx = _np.linspace(0, count - 1, num=sample_count, dtype=_np.float64)
                idx = _np.unique(_np.clip(_np.round(idx).astype(_np.int32), 0, count - 1))
                if idx.size <= 1 and count > 1:
                    step = max(1, int(_math.ceil(float(count) / float(sample_count))))
                    idx = _np.arange(0, count, step, dtype=_np.int32)
                    if idx[-1] != count - 1:
                        idx = _np.append(idx, count - 1)
                t_arr = _np.asarray(seg_times[:count], dtype=_np.float32)[idx]
                y_arr = _np.asarray(seg_pitches[:count], dtype=_np.float32)[idx]
                offs = _np.column_stack((t_arr, y_arr)) if t_arr.size > 0 else _np.empty((0, 2), dtype=_np.float32)
            cache[sig] = offs
            return offs
        except Exception:
            try:
                import numpy as _np
                return _np.column_stack((seg_times, seg_pitches)) if seg_times and seg_pitches else _np.empty((0, 2), dtype=_np.float32)
            except Exception:
                return []

    def _get_onepass_fixed_segment_offsets(self, seg_times, seg_pitches):
        return self._get_stable_segment_offsets(seg_times, seg_pitches, 'onepass_playback')

    # ================= 放大镜（局部放大） =================
    def _ensure_magnifier(self):
        try:
            if getattr(self, '_magnifier_ax', None) is not None:
                try:
                    # 仅当仍属于当前 figure 时复用
                    if getattr(self._magnifier_ax, 'figure', None) is self.figure:
                        return
                except Exception:
                    pass
            if not hasattr(self, 'figure') or self.figure is None:
                return
            fig = self.figure
            # 初始放在右上角，等首次更新再定位
            w_frac = max(0.08, min(0.5, float(self._magn_size_px) / float(fig.bbox.width)))
            h_frac = max(0.08, min(0.5, float(self._magn_size_px) / float(fig.bbox.height)))
            left = 0.8
            bottom = 0.1
            import matplotlib.pyplot as _plt  # 确保后端可用
            ax = fig.add_axes([left, bottom, w_frac, h_frac], zorder=9970)
            try:
                # 避免额外纵横比约束导致再次插值
                ax.set_aspect('auto')
            except Exception:
                pass
            # 放大镜轴背景设为透明，避免出现矩形底色，保证圆形裁剪可见
            try:
                ax.set_facecolor((0, 0, 0, 0))
                ax.patch.set_alpha(0.0)
            except Exception:
                pass
            for spine in ax.spines.values():
                spine.set_visible(False)
            ax.set_xticks([])
            ax.set_yticks([])
            ax.set_xlim(0, 1)
            ax.set_ylim(0, 1)
            # 截图式镜片图像（默认用 2x2 占位，extent 归一坐标）
            try:
                import numpy as _np
                _placeholder = _np.zeros((2, 2, 4), dtype=_np.uint8)
                # 禁止插值，确保像素级显示（后续按轴像素尺寸做最近邻缩放）
                im = ax.imshow(_placeholder, extent=(0, 1, 0, 1), origin='upper', interpolation='none', zorder=9972)
                try:
                    im.set_resample(False)
                except Exception:
                    pass
                self._magn_image = im
            except Exception:
                self._magn_image = None
            # 旧版线/点在截图模式下禁用
            try:
                ln_color = getattr(getattr(self, 'pitch_line', None), 'get_color', lambda: '#88ccff')()
                self._magn_line, = ax.plot([], [], color=ln_color or '#88ccff', linewidth=1.6, zorder=9971)
                self._magn_line.set_visible(False)
            except Exception:
                self._magn_line = None
            try:
                self._magn_points = ax.scatter([], [], s=16, c='#FFFFFF', edgecolors='#88ccff', linewidths=0.4, zorder=9971)
                self._magn_points.set_visible(False)
            except Exception:
                self._magn_points = None
            # 圆形边框（分为两个：一个仅用于裁剪；另一个为可见的浅蓝色细边框）
            try:
                from matplotlib.patches import Circle
                # 使用轴坐标创建单位圆，随位置更新时重置变换
                # 注意：edgecolor 设为 'none' 且 linewidth=0，仅作为 clip path 使用
                circ = Circle((0.5, 0.5), 0.5, transform=ax.transAxes, fill=False,
                              edgecolor='none', linewidth=0.0, zorder=9976)
                ax.add_patch(circ)
                self._magnifier_border = circ
                # 截图图像裁剪为圆形镜片
                try:
                    if self._magn_image is not None:
                        self._magn_image.set_clip_path(circ)
                except Exception:
                    pass
                # 可见的浅蓝色细边框（满足“最外层浅蓝色很细边框”的视觉要求）
                try:
                    border = Circle((0.5, 0.5), 0.5, transform=ax.transAxes, fill=False,
                                     edgecolor=(0.50, 0.80, 1.0, 0.85), linewidth=1.1, zorder=9980)
                    ax.add_patch(border)
                    self._magnifier_visible_ring = border
                except Exception:
                    self._magnifier_visible_ring = None
            except Exception:
                self._magnifier_border = None
            # 顶部信息条（仅背景，不再绘制边线，避免白色横线伪线；同样裁剪为圆形）
            try:
                from matplotlib.patches import Rectangle
                header = Rectangle((0.0, 0.84), 1.0, 0.16, transform=ax.transAxes,
                                   facecolor=(0.06, 0.10, 0.16, 0.90), edgecolor='none',
                                   linewidth=0.0, zorder=9977)
                ax.add_patch(header)
                try:
                    if self._magnifier_border is not None:
                        header.set_clip_path(self._magnifier_border)
                except Exception:
                    pass
                self._magn_header_rect = header
            except Exception:
                self._magn_header_rect = None
            # 焦点淡色高亮带（默认隐藏，避免产生额外线条/带）
            try:
                from matplotlib.patches import Rectangle
                focus = Rectangle((0.25, 0.0), 0.50, 1.0, transform=ax.transAxes,
                                  facecolor=(0.5, 0.75, 1.0, 0.10), edgecolor='none', zorder=9971)
                ax.add_patch(focus)
                try:
                    focus.set_visible(False)
                except Exception:
                    pass
                self._magn_focus_band = focus
            except Exception:
                self._magn_focus_band = None
            # 垂直投影线（默认隐藏，避免在镜片中出现额外竖线）
            try:
                self._magn_vline = ax.axvline(0.5, color=(0.85, 0.92, 1.0, 0.6), linewidth=0.9, zorder=9975)
                try:
                    self._magn_vline.set_visible(False)
                except Exception:
                    pass
            except Exception:
                self._magn_vline = None
            # 放大区内悬停高亮环（默认隐藏，避免蓝白色圆圈伪线）
            try:
                ring_edge = (0.85, 0.92, 1.00, 0.98)
                self._magn_hi_ring = ax.scatter([], [], s=60, facecolors=(0,0,0,0),
                                               linewidths=1.5, edgecolors=[ring_edge], zorder=9978)
                # 使用轴坐标, 便于以 (fx, fy) 归一化坐标定位到截图图像上
                try:
                    self._magn_hi_ring.set_transform(ax.transAxes)
                except Exception:
                    pass
                try:
                    self._magn_hi_ring.set_visible(False)
                except Exception:
                    pass
            except Exception:
                self._magn_hi_ring = None
            # 放大区内文本（仅显示在顶部信息条内，不再在主图重复显示）
            try:
                txt_c = getattr(self, 'text_color', '#DDDDDD')
                self._magn_text = ax.text(0.03, 0.95, '', transform=ax.transAxes, va='top', ha='left',
                                          fontsize=9, color=txt_c, zorder=9979)
                try:
                    # 文本也裁剪到圆形范围，确保不改变镜片外观
                    if self._magnifier_border is not None:
                        self._magn_text.set_clip_path(self._magnifier_border)
                except Exception:
                    pass
            except Exception:
                self._magn_text = None
            self._magnifier_ax = ax
            self._magn_visible = True
        except Exception:
            pass

    def _update_magnifier(self, event, x: float, y: float, text: str = ''):
        try:
            self._ensure_magnifier()
            ax_main = self.ax
            ax = self._magnifier_ax
            if ax is None or ax_main is None or event is None:
                return
            fig = self.figure
            # 主动隐藏所有叠加通道，确保只显示 inset 放大镜
            try:
                if self._magn_ab is not None:
                    self._magn_ab.set_visible(False)
            except Exception:
                pass
            try:
                if self._magn_ab_frame is not None:
                    self._magn_ab_frame.set_visible(False)
            except Exception:
                pass
            try:
                if self._magn_overlay_label is not None:
                    self._magn_overlay_label.hide()
            except Exception:
                pass
            try:
                if self._magn_overlay_window is not None:
                    self._magn_overlay_window.hide()
            except Exception:
                pass
            # 计算像素尺寸占比
            w_frac = max(0.06, min(0.6, float(self._magn_size_px) / float(fig.bbox.width)))
            h_frac = max(0.06, min(0.6, float(self._magn_size_px) / float(fig.bbox.height)))
            # 在鼠标附近摆放（向右上偏移），并避免越界
            px = float(event.x)
            py = float(event.y)
            fig_w = float(fig.bbox.width)
            fig_h = float(fig.bbox.height)
            # 默认在鼠标右上方放置；若越界则自动镜像至其他象限，避免遮挡鼠标附近的线条
            left = (px + 18) / fig_w
            bottom = (py + 18) / fig_h
            # 若右侧放不下，则放到鼠标左侧
            if left + w_frac > 0.985:
                left = (px - 18 - w_frac * fig_w) / fig_w
            # 若上方放不下，则放到鼠标下方
            if bottom + h_frac > 0.985:
                bottom = (py - 18 - h_frac * fig_h) / fig_h
            if left + w_frac > 0.985:
                left = max(0.005, 0.985 - w_frac)
            if bottom + h_frac > 0.985:
                bottom = max(0.005, 0.985 - h_frac)
            ax.set_position([left, bottom, w_frac, h_frac])
            # 保持透明背景（避免矩形区域显现）
            try:
                ax.patch.set_alpha(0.0)
            except Exception:
                pass
            # 依据固定时间窗计算截图的数据窗口（并强制在显示像素维度上为正方形，便于圆形裁剪）
            try:
                x0, x1 = ax_main.get_xlim()
                y0, y1 = ax_main.get_ylim()
            except Exception:
                return
            main_w_px = float(ax_main.bbox.width)
            main_h_px = float(ax_main.bbox.height)
            if main_w_px <= 0 or main_h_px <= 0:
                return
            # 像素比例（数据单位/像素）
            dx_per_px = (x1 - x0) / max(1e-6, main_w_px)
            dy_per_px = (y1 - y0) / max(1e-6, main_h_px)
            # 先确定水平半宽（依据目标秒数或倍率），再按像素比例换算垂直半高，使显示区域为正方形
            try:
                target_sec = float(getattr(self, '_magn_target_window_sec', 2.0))
                half_w_data = 0.5 * target_sec
            except Exception:
                half_w_data = 0.5 * self._magn_size_px * dx_per_px / max(1e-6, float(self._magn_zoom))
            # 为保证像素上的正方形：dy = dx * (dy_per_px / dx_per_px)
            half_h_data = float(half_w_data) * float(dy_per_px) / max(1e-9, float(dx_per_px))
            xL, xR = (x - half_w_data, x + half_w_data)
            yB, yT = (y - half_h_data, y + half_h_data)
            # 截图：从 figure 的 RGBA 缓冲区裁剪出主轴内 [xL,xR]x[yB,yT] 的像素区域
            try:
                import numpy as _np
                # 临时隐藏放大镜轴，避免把自身边框/叠加件截进镜片（自我递归）
                _magn_prev_visible = True
                try:
                    _magn_prev_visible = bool(ax.get_visible())
                    ax.set_visible(False)
                except Exception:
                    pass
                # 同步渲染器，确保缓冲区与当前可见元素一致（此时放大镜已隐藏）
                try:
                    fig.canvas.draw()
                except Exception:
                    pass
                # 确保渲染器最新
                try:
                    # 避免频繁阻塞重绘——仅在没有 renderer 时强制一次
                    if getattr(fig.canvas, 'renderer', None) is None:
                        fig.canvas.draw()
                except Exception:
                    try:
                        fig.canvas.draw()
                    except Exception:
                        pass
                # 把数据窗口转换为显示像素
                p0 = ax_main.transData.transform([(xL, yB), (xR, yT)])
                (xL_px, yB_px), (xR_px, yT_px) = p0[0], p0[1]
                # 与主轴 bbox 求交，避免截出轴外的黑边
                ab = ax_main.get_window_extent()
                ax_x0, ax_y0, ax_x1, ax_y1 = float(ab.x0), float(ab.y0), float(ab.x1), float(ab.y1)
                ix0 = int(_np.floor(max(min(xL_px, xR_px), ax_x0)))
                ix1 = int(_np.ceil(min(max(xL_px, xR_px), ax_x1)))
                iy0 = int(_np.floor(max(min(yB_px, yT_px), ax_y0)))
                iy1 = int(_np.ceil(min(max(yB_px, yT_px), ax_y1)))
                # 读取整幅图像 RGBA
                fig_w_px = int(_np.round(fig.bbox.width))
                fig_h_px = int(_np.round(fig.bbox.height))
                buf = None
                try:
                    mem = fig.canvas.buffer_rgba()
                    buf = _np.frombuffer(mem, dtype=_np.uint8).reshape(fig_h_px, fig_w_px, 4)
                except Exception:
                    try:
                        _renderer = getattr(fig.canvas, 'renderer', None) or fig.canvas.get_renderer()
                        buf = _np.asarray(_renderer.buffer_rgba())
                    except Exception:
                        buf = None
                if buf is None:
                    raise RuntimeError('no-figure-buffer')
                # 转为数组索引（注意：图像数组原点在左上，显示坐标原点在左下）
                row0 = int(max(0, min(fig_h_px, _np.floor(fig_h_px - iy1))))
                row1 = int(max(0, min(fig_h_px, _np.ceil (fig_h_px - iy0))))
                col0 = int(max(0, min(fig_w_px, ix0)))
                col1 = int(max(0, min(fig_w_px, ix1)))
                if row1 <= row0 or col1 <= col0:
                    # 无有效区域：直接隐藏
                    if self._magn_image is not None:
                        self._magn_image.set_visible(False)
                    self._magn_visible = False
                    return
                crop = buf[row0:row1, col0:col1, :]
                # 等比缩放到放大镜轴像素大小内，并居中填充，避免被横向/纵向挤压
                try:
                    import numpy as _np
                    # 放大镜轴当前像素尺寸
                    ax_bb = ax.get_window_extent()
                    ax_w = max(1, int(_np.round(ax_bb.width)))
                    ax_h = max(1, int(_np.round(ax_bb.height)))
                    ch, cw = int(crop.shape[0]), int(crop.shape[1])
                    # 计算等比缩放目标大小
                    scale = min(ax_w / float(cw), ax_h / float(ch))
                    new_w = max(1, int(_np.round(cw * scale)))
                    new_h = max(1, int(_np.round(ch * scale)))
                    # 生成最近邻索引进行缩放
                    if new_w != cw or new_h != ch:
                        yy = (_np.arange(new_h) / (new_h / float(ch))).round().astype(int)
                        xx = (_np.arange(new_w) / (new_w / float(cw))).round().astype(int)
                        yy = _np.clip(yy, 0, ch - 1)
                        xx = _np.clip(xx, 0, cw - 1)
                        resized = crop[yy[:, None], xx[None, :], :]
                    else:
                        resized = crop
                    # 创建背景并居中贴图
                    canvas = _np.empty((ax_h, ax_w, 4), dtype=_np.uint8)
                    # 背景色：使用轴背景颜色（若解析失败则用全透明）
                    try:
                        _bg = getattr(self, 'bg_color', '#0c0c0c')
                        if isinstance(_bg, str) and _bg.startswith('#') and (len(_bg) in (7, 9)):
                            r = int(_bg[1:3], 16)
                            g = int(_bg[3:5], 16)
                            b = int(_bg[5:7], 16)
                            a = 255
                        else:
                            r, g, b, a = 0, 0, 0, 0
                    except Exception:
                        r, g, b, a = 0, 0, 0, 0
                    canvas[..., 0] = r
                    canvas[..., 1] = g
                    canvas[..., 2] = b
                    canvas[..., 3] = a
                    # 计算居中位置
                    y0 = (ax_h - new_h) // 2
                    x0 = (ax_w - new_w) // 2
                    canvas[y0:y0+new_h, x0:x0+new_w, :] = resized
                    crop = canvas
                    # 记录内容区域在轴坐标下的矩形，供高亮环/命中对齐
                    try:
                        x0f = x0 / float(ax_w)
                        y0f = y0 / float(ax_h)
                        wf = new_w / float(ax_w)
                        hf = new_h / float(ax_h)
                        self._magn__content_rect_axes = (x0f, y0f, wf, hf)
                    except Exception:
                        try:
                            self._magn__content_rect_axes = (0.0, 0.0, 1.0, 1.0)
                        except Exception:
                            pass
                except Exception:
                    pass
                # 计算与主轴交集对应的数据范围（用于镜内标记定位）
                try:
                    inv = ax_main.transData.inverted()
                    # 注意：索引行列转回显示坐标时，y 使用 ax 坐标的显示系；
                    # 这里直接用 display 坐标边界 (ix0,iy0)-(ix1,iy1)
                    (x_eff0, y_eff0) = inv.transform((float(ix0), float(iy0)))
                    (x_eff1, y_eff1) = inv.transform((float(ix1), float(iy1)))
                    xL_eff = min(x_eff0, x_eff1)
                    xR_eff = max(x_eff0, x_eff1)
                    yB_eff = min(y_eff0, y_eff1)
                    yT_eff = max(y_eff0, y_eff1)
                except Exception:
                    xL_eff, xR_eff, yB_eff, yT_eff = xL, xR, yB, yT
                _magn_eff_window = (xL_eff, xR_eff, yB_eff, yT_eff)
                self._magn__last_eff_window = _magn_eff_window
                # 更新镜片图像（截图模式）
                if self._magn_image is not None:
                    self._magn_image.set_data(crop)
                    try:
                        self._magn_image.set_visible(True)
                    except Exception:
                        pass
            except Exception:
                # 截屏失败则隐藏镜片图像
                try:
                    if self._magn_image is not None:
                        self._magn_image.set_visible(False)
                except Exception:
                    pass
            finally:
                # 恢复放大镜可见状态
                try:
                    if _magn_prev_visible:
                        ax.set_visible(True)
                except Exception:
                    pass
            # 焦点带宽度与位置（默认隐藏；若未来需要再启用，可在此处设为可见并更新位置）
            try:
                if getattr(self, '_magn_focus_band', None) is not None:
                    try:
                        self._magn_focus_band.set_visible(False)
                    except Exception:
                        pass
            except Exception:
                pass
            # 垂直投影线默认隐藏（避免伪线）。如需显示，可在此处更新位置并设为可见
            try:
                if getattr(self, '_magn_vline', None) is not None:
                    try:
                        self._magn_vline.set_visible(False)
                    except Exception:
                        pass
            except Exception:
                pass
            # 禁用镜内线与点（避免与截图冲突导致“错误连线/尺寸不一”）
            try:
                if self._magn_line is not None:
                    self._magn_line.set_visible(False)
                if self._magn_points is not None:
                    self._magn_points.set_visible(False)
            except Exception:
                pass
            # 文本（仅在镜片顶部信息条显示；主图注解已隐藏）
            try:
                if self._magn_text is not None:
                    self._magn_text.set_text(text or '')
                    try:
                        # 锁定在顶部条内部，避免漂移
                        self._magn_text.set_position((0.03, 0.95))
                    except Exception:
                        pass
                    try:
                        self._magn_text.set_visible(True)
                    except Exception:
                        pass
            except Exception:
                pass
            # 高亮环默认隐藏（避免蓝色圆圈伪线）
            try:
                if self._magn_hi_ring is not None:
                    try:
                        self._magn_hi_ring.set_visible(False)
                    except Exception:
                        pass
            except Exception:
                pass
            # 显示
            self._magn_visible = True
            try:
                ax.set_visible(True)
            except Exception:
                pass
            # 轻量刷新显示
            try:
                fig.canvas.draw_idle()
            except Exception:
                pass
        except Exception:
            pass

    def _hide_magnifier(self):
        try:
            ax = getattr(self, '_magnifier_ax', None)
            if ax is None:
                return
            try:
                ax.set_visible(False)
            except Exception:
                pass
            self._magn_visible = False
            try:
                if self._magn_ab is not None:
                    self._magn_ab.set_visible(False)
            except Exception:
                pass
            try:
                if self._magn_ab_frame is not None:
                    self._magn_ab_frame.set_visible(False)
            except Exception:
                pass
            try:
                if self._magn_overlay_label is not None:
                    self._magn_overlay_label.hide()
            except Exception:
                pass
            try:
                if self._magn_overlay_window is not None:
                    self._magn_overlay_window.hide()
            except Exception:
                pass
        except Exception:
            pass

    # ============ Qt 叠加放大镜（兜底显示） ============
    def _ensure_magn_overlay_label(self):
        try:
            if self._magn_overlay_label is not None:
                return self._magn_overlay_label
            try:
                from PyQt6.QtWidgets import QLabel
                from PyQt6.QtCore import Qt
            except Exception:
                from PyQt5.QtWidgets import QLabel  # type: ignore
                from PyQt5.QtCore import Qt  # type: ignore
            # 使用主窗口作为父控件，避免被画布遮挡
            lbl = QLabel(self)
            try:
                lbl.setAttribute(Qt.WidgetAttribute.WA_TransparentForMouseEvents, True)
                lbl.setAttribute(Qt.WidgetAttribute.WA_NoSystemBackground, True)
                lbl.setAttribute(Qt.WidgetAttribute.WA_TranslucentBackground, True)
            except Exception:
                try:
                    lbl.setAttribute(Qt.WA_TransparentForMouseEvents, True)
                    lbl.setAttribute(Qt.WA_NoSystemBackground, True)
                    lbl.setAttribute(Qt.WA_TranslucentBackground, True)
                except Exception:
                    pass
            lbl.setStyleSheet("background: transparent;")
            lbl.hide()
            self._magn_overlay_label = lbl
            return lbl
        except Exception as _e:
            try:
                if bool(getattr(self, 'debug_flags', {}).get('hover_magnifier_log', False)):
                    print(f"[HOVER_DIAG] overlay=0 reason=create_fail err={_e}")
            except Exception:
                pass
            self._magn_overlay_label = None
            return None

    def _ensure_magn_overlay_window(self):
        try:
            if self._magn_overlay_window is not None:
                return self._magn_overlay_window
            try:
                from PyQt6.QtWidgets import QLabel
                from PyQt6.QtCore import Qt
                from PyQt6.QtGui import QGuiApplication
            except Exception:
                from PyQt5.QtWidgets import QLabel  # type: ignore
                from PyQt5.QtCore import Qt  # type: ignore
                from PyQt5.QtGui import QGuiApplication  # type: ignore
            w = QLabel(None)
            try:
                w.setWindowFlags(Qt.WindowType.FramelessWindowHint | Qt.WindowType.ToolTip | Qt.WindowType.WindowStaysOnTopHint)
                w.setAttribute(Qt.WidgetAttribute.WA_TransparentForMouseEvents, True)
                w.setAttribute(Qt.WidgetAttribute.WA_TranslucentBackground, True)
                try:
                    w.setAttribute(Qt.WidgetAttribute.WA_ShowWithoutActivating, True)
                except Exception:
                    pass
            except Exception:
                try:
                    w.setWindowFlags(Qt.FramelessWindowHint | Qt.ToolTip | Qt.WindowStaysOnTopHint)
                    w.setAttribute(Qt.WA_TransparentForMouseEvents, True)
                    w.setAttribute(Qt.WA_TranslucentBackground, True)
                except Exception:
                    pass
            try:
                w.setScaledContents(True)
            except Exception:
                pass
            w.hide()
            self._magn_overlay_window = w
            return w
        except Exception:
            self._magn_overlay_window = None
            return None

    def _update_magn_overlay_window(self, event, pm=None):
        try:
            win = self._ensure_magn_overlay_window()
            if win is None:
                return
            canvas = getattr(self, 'canvas', None)
            if canvas is None or event is None:
                return
            try:
                from PyQt6.QtCore import QPoint
                from PyQt6.QtGui import QGuiApplication
            except Exception:
                from PyQt5.QtCore import QPoint  # type: ignore
                from PyQt5.QtGui import QGuiApplication  # type: ignore
            try:
                dpr = float(getattr(canvas, 'devicePixelRatio', lambda: 1.0)())
            except Exception:
                try:
                    dpr = float(getattr(canvas, 'devicePixelRatioF', lambda: 1.0)())
                except Exception:
                    dpr = 1.0
            if dpr <= 0:
                dpr = 1.0
            cx = float(event.x) / dpr
            cy = float(event.y) / dpr
            ch = float(canvas.height()) if canvas is not None else 0.0
            qt_y = (ch - cy) if ch > 0 else cy
            size_px = int(getattr(self, '_magn_size_px', 180))
            size_px = max(80, min(320, size_px))
            win.resize(size_px, size_px)
            # 圆形镜框样式
            win.setStyleSheet(
                "background: transparent;"
                f"border: 2px solid rgba(128,200,255,230);"
                f"border-radius: {size_px//2}px;"
            )
            if pm is not None:
                try:
                    win.setPixmap(pm)
                except Exception:
                    pass
            # 全局坐标
            try:
                global_pos = canvas.mapToGlobal(QPoint(int(cx), int(qt_y)))
            except Exception:
                return
            x = int(global_pos.x() + 24)
            y = int(global_pos.y() + 24)
            # 限制在屏幕可见区域
            try:
                screen = QGuiApplication.primaryScreen()
                if screen is not None:
                    geo = screen.availableGeometry()
                    max_x = int(geo.x() + geo.width() - size_px)
                    max_y = int(geo.y() + geo.height() - size_px)
                    x = max(int(geo.x()), min(x, max_x))
                    y = max(int(geo.y()), min(y, max_y))
                    # 调试：固定到右上角，排除坐标偏移
                    try:
                        if bool(getattr(self, 'debug_flags', {}).get('hover_magnifier_log', False)):
                            x = max_x
                            y = int(geo.y())
                    except Exception:
                        pass
            except Exception:
                pass
            try:
                win.move(x, y)
                win.show()
                win.raise_()
                try:
                    if bool(getattr(self, 'debug_flags', {}).get('hover_magnifier_log', False)):
                        print(f"[HOVER_DIAG] overlay_window_pos=({x},{y}) size={size_px}")
                except Exception:
                    pass
            except Exception:
                pass
        except Exception:
            pass

    def _update_magn_overlay_label(self, event, crop, x: float = None, y: float = None):
        try:
            lbl = self._ensure_magn_overlay_label()
            if lbl is None:
                try:
                    if bool(getattr(self, 'debug_flags', {}).get('hover_magnifier_log', False)):
                        print("[HOVER_DIAG] overlay=0 reason=no_label")
                except Exception:
                    pass
                return
            try:
                import numpy as _np
            except Exception:
                try:
                    if bool(getattr(self, 'debug_flags', {}).get('hover_magnifier_log', False)):
                        print("[HOVER_DIAG] overlay=0 reason=no_numpy")
                except Exception:
                    pass
                return
            # 若没有传入截图，则尝试从主轴截图
            if crop is None and (x is not None) and (y is not None):
                try:
                    crop = self._capture_magnifier_crop(float(x), float(y))
                except Exception:
                    crop = None
            has_crop = isinstance(crop, _np.ndarray) and crop.ndim == 3 and crop.shape[2] == 4
            if has_crop:
                h, w = int(crop.shape[0]), int(crop.shape[1])
                if h <= 2 or w <= 2:
                    has_crop = False
            try:
                from PyQt6.QtGui import QImage, QPixmap, QPainter, QPainterPath, QPen, QColor
                from PyQt6.QtCore import Qt
            except Exception:
                from PyQt5.QtGui import QImage, QPixmap, QPainter, QPainterPath, QPen, QColor  # type: ignore
                from PyQt5.QtCore import Qt  # type: ignore
            # QImage 格式兼容（PyQt6: QImage.Format.Format_RGBA8888; PyQt5: QImage.Format_RGBA8888）
            try:
                qimg_fmt = getattr(QImage, 'Format_RGBA8888', None)
                if qimg_fmt is None:
                    qimg_fmt = QImage.Format.Format_RGBA8888
            except Exception:
                qimg_fmt = None
            size_px = int(getattr(self, '_magn_size_px', 180))
            size_px = max(80, min(320, size_px))
            # 透明画布
            pm = QPixmap(size_px, size_px)
            pm.fill(Qt.GlobalColor.transparent)
            painter = None
            try:
                painter = QPainter(pm)
                painter.setRenderHint(QPainter.RenderHint.Antialiasing, True)
                # 裁剪圆形
                path = QPainterPath()
                try:
                    path.addEllipse(0, 0, int(size_px), int(size_px))
                except Exception:
                    pass
                painter.setClipPath(path)
                if has_crop:
                    # 构建 QImage
                    try:
                        if qimg_fmt is not None:
                            img = QImage(crop.data, w, h, w * 4, qimg_fmt)
                        else:
                            img = QImage(crop.data, w, h, w * 4, QImage.Format_ARGB32)
                    except Exception:
                        try:
                            img = QImage(crop.data, w, h, w * 4, QImage.Format_ARGB32)
                        except Exception:
                            img = None
                    if img is None:
                        return
                    # 缩放
                    try:
                        img_scaled = img.scaled(size_px, size_px, Qt.AspectRatioMode.KeepAspectRatio, Qt.TransformationMode.SmoothTransformation)
                    except Exception:
                        img_scaled = img.scaled(size_px, size_px, Qt.KeepAspectRatio, Qt.SmoothTransformation)
                    # 居中绘制
                    dx = (size_px - img_scaled.width()) // 2
                    dy = (size_px - img_scaled.height()) // 2
                    painter.drawImage(int(dx), int(dy), img_scaled)
                if not has_crop and (x is not None) and (y is not None):
                    # 无截图时：用数据点绘制简化放大内容
                    try:
                        ax = getattr(self, 'ax', None)
                        if ax is not None:
                            x0, x1 = ax.get_xlim()
                            y0, y1 = ax.get_ylim()
                        else:
                            x0, x1, y0, y1 = 0.0, 1.0, 0.0, 1.0
                    except Exception:
                        x0, x1, y0, y1 = 0.0, 1.0, 0.0, 1.0
                    try:
                        target_sec = float(getattr(self, '_magn_target_window_sec', 2.0))
                    except Exception:
                        target_sec = 2.0
                    half_w = 0.5 * target_sec
                    # 依据主视图纵横比估算 y 半高
                    try:
                        dy = (y1 - y0) / max(1e-6, (x1 - x0)) * (half_w * 2.0)
                        half_h = 0.5 * dy
                    except Exception:
                        half_h = 0.5
                    xL, xR = float(x) - half_w, float(x) + half_w
                    yB, yT = float(y) - half_h, float(y) + half_h
                    # 取附近点
                    pts = []
                    try:
                        segs = getattr(self, '_segment_points', []) or []
                        for sc in segs:
                            try:
                                offsets = sc.get_offsets()
                            except Exception:
                                offsets = None
                            if offsets is None:
                                continue
                            for ox, oy in offsets:
                                if ox >= xL and ox <= xR and oy >= yB and oy <= yT:
                                    pts.append((float(ox), float(oy)))
                    except Exception:
                        pts = []
                    # fallback to line
                    if not pts:
                        try:
                            ln = getattr(self, 'pitch_line', None)
                            if ln is not None:
                                xs = ln.get_xdata()
                                ys = ln.get_ydata()
                                if xs is not None and ys is not None:
                                    for ox, oy in zip(xs, ys):
                                        try:
                                            oxf = float(ox); oyf = float(oy)
                                        except Exception:
                                            continue
                                        if oxf >= xL and oxf <= xR and oyf >= yB and oyf <= yT:
                                            pts.append((oxf, oyf))
                        except Exception:
                            pts = []
                    # 画线与点
                    if pts:
                        try:
                            pts.sort(key=lambda v: v[0])
                        except Exception:
                            pass
                        def _map(px, py):
                            fx = (px - xL) / max(1e-6, (xR - xL))
                            fy = (py - yB) / max(1e-6, (yT - yB))
                            # y 反转到像素
                            return (int(fx * size_px), int((1.0 - fy) * size_px))
                        # 线
                        try:
                            path2 = QPainterPath()
                            mx0, my0 = _map(pts[0][0], pts[0][1])
                            path2.moveTo(mx0, my0)
                            for px, py in pts[1:]:
                                mx, my = _map(px, py)
                                path2.lineTo(mx, my)
                            pen_line = QPen(QColor(160, 220, 255, 200))
                            pen_line.setWidthF(1.2)
                            pen_line.setCosmetic(True)
                            painter.setPen(pen_line)
                            painter.drawPath(path2)
                        except Exception:
                            pass
                        # 点
                        try:
                            pen_pt = QPen(QColor(255, 255, 255, 230))
                            pen_pt.setWidthF(1.0)
                            pen_pt.setCosmetic(True)
                            painter.setPen(pen_pt)
                            for px, py in pts[:: max(1, int(len(pts)/80))]:
                                mx, my = _map(px, py)
                                painter.drawEllipse(mx-1, my-1, 2, 2)
                        except Exception:
                            pass
                # 画圆形外框（平滑）
                pen = QPen(QColor(128, 200, 255, 230))
                pen.setWidthF(1.6)
                try:
                    pen.setCosmetic(True)
                except Exception:
                    pass
                painter.setPen(pen)
                painter.setBrush(Qt.BrushStyle.NoBrush)
                painter.drawEllipse(1, 1, int(size_px - 2), int(size_px - 2))
                # 顶部文本信息
                try:
                    if (x is not None) and (y is not None):
                        txt = self._format_magnifier_text(float(y), float(x))
                    else:
                        txt = ""
                    if txt:
                        painter.setPen(QPen(QColor(220, 240, 255, 230)))
                        try:
                            painter.drawText(8, 18, txt)
                        except Exception:
                            pass
                except Exception:
                    pass
            finally:
                try:
                    if painter is not None:
                        painter.end()
                except Exception:
                    pass
            # 设置并显示
            if lbl is not None:
                try:
                    lbl.setPixmap(pm)
                    lbl.resize(size_px, size_px)
                except Exception:
                    pass
            try:
                if self._magn_overlay_window is not None:
                    self._magn_overlay_window.hide()
            except Exception:
                pass
            # 仅使用主窗口叠加层显示，避免顶层窗口被系统遮挡
            # 位置：以 event.x/y 为左下坐标 -> 转换为 Qt 左上
            try:
                canvas = getattr(self, 'canvas', None)
                try:
                    dpr = float(getattr(canvas, 'devicePixelRatio', lambda: 1.0)()) if canvas is not None else 1.0
                except Exception:
                    try:
                        dpr = float(getattr(canvas, 'devicePixelRatioF', lambda: 1.0)()) if canvas is not None else 1.0
                    except Exception:
                        dpr = 1.0
                if dpr <= 0:
                    dpr = 1.0
                cx = float(event.x) / dpr
                cy = float(event.y) / dpr
            except Exception:
                return
            try:
                ch = float(canvas.height()) if canvas is not None else 0.0
            except Exception:
                ch = 0.0
            # Matplotlib y 原点在底部，Qt 原点在顶部
            qt_y = (ch - cy) if ch > 0 else cy
            # 与细节点拉开距离
            x = int(cx + 40)
            y = int(qt_y + 40)
            # 越界修正
            try:
                cw = int(canvas.width()) if canvas is not None else 0
                ch = int(canvas.height()) if canvas is not None else 0
                if x + size_px > cw:
                    x = max(0, int(cx - 40 - size_px))
                if y + size_px > ch:
                    y = max(0, int(qt_y - 40 - size_px))
            except Exception:
                pass
            if lbl is not None:
                try:
                    if canvas is not None:
                        try:
                            from PyQt6.QtCore import QPoint
                        except Exception:
                            from PyQt5.QtCore import QPoint  # type: ignore
                        global_pos = canvas.mapToGlobal(QPoint(x, y))
                        local_pos = self.mapFromGlobal(global_pos)
                        lbl.move(int(local_pos.x()), int(local_pos.y()))
                    else:
                        lbl.move(x, y)
                    lbl.raise_()
                    lbl.show()
                except Exception:
                    pass
            try:
                if bool(getattr(self, 'debug_flags', {}).get('hover_magnifier_log', False)):
                    print(f"[HOVER_DIAG] overlay=1 has_crop={int(has_crop)} pos=({x},{y}) size={size_px} canvas=({cw},{ch})")
            except Exception:
                pass
        except Exception as _e:
            try:
                if bool(getattr(self, 'debug_flags', {}).get('hover_magnifier_log', False)):
                    print(f"[HOVER_DIAG] overlay=0 reason=exception err={_e}")
            except Exception:
                pass

    def _find_nearest_point(self, event, max_pixel_dist=12):
        try:
            if not event or not hasattr(self, 'ax') or self.ax is None:
                return None
            if not event.inaxes or event.inaxes != self.ax:
                return None
            cols = self._collect_visible_point_collections()
            if not cols:
                return None
            ex, ey = event.x, event.y
            best = None
            best_d = float('inf')
            import numpy as _np
            for col in cols:
                try:
                    offsets = col.get_offsets()
                    if offsets is None:
                        continue
                    arr = _np.asarray(offsets)
                    if arr.size == 0:
                        continue
                    pts = self.ax.transData.transform(arr)
                    dx = pts[:, 0] - ex
                    dy = pts[:, 1] - ey
                    dist2 = dx * dx + dy * dy
                    i = int(_np.argmin(dist2))
                    d = float(dist2[i] ** 0.5)
                    if d < best_d:
                        best_d = d
                        best = (col, i, float(arr[i, 0]), float(arr[i, 1]))
                except Exception:
                    continue
            if best is None or best_d > float(max_pixel_dist):
                return None
            return best
        except Exception:
            return None

    def _fallback_nearest_from_segments(self, event, max_pixel_dist=20):
        try:
            if not hasattr(self, '_segments') or not self._segments or not event or event.inaxes != self.ax:
                return None
            import numpy as _np
            try:
                x0, x1 = self.ax.get_xlim()
            except Exception:
                x0, x1 = None, None
            pts_list = []
            for (ts, ys) in self._segments:
                if not ts:
                    continue
                if x0 is not None and x1 is not None:
                    # 仅取视口内，降低运算开销
                    for t, y in zip(ts, ys):
                        if t >= x0 and t <= x1:
                            pts_list.append((t, y))
                else:
                    for t, y in zip(ts, ys):
                        pts_list.append((t, y))
            if not pts_list:
                return None
            arr = _np.asarray(pts_list, dtype=float)
            pix = self.ax.transData.transform(arr)
            dx = pix[:, 0] - event.x
            dy = pix[:, 1] - event.y
            dist2 = dx*dx + dy*dy
            i = int(_np.argmin(dist2))
            d = float(dist2[i] ** 0.5)
            if d > float(max_pixel_dist):
                return None
            return (None, i, float(arr[i,0]), float(arr[i,1]))
        except Exception:
            return None

    def _fallback_nearest_from_line(self, event, max_pixel_dist=18):
        """当没有可见散点/分段点时，从主线 Line2D 上选最近点。
        仅用于普通模式下已画线但未显式绘制细点的情况。
    返回 (col_or_None, idx, x, y)
        """
        try:
            if not event or event.inaxes != self.ax:
                return None
            ln = getattr(self, 'pitch_line', None)
            if ln is None:
                return None
            try:
                if hasattr(ln, 'get_visible') and not ln.get_visible():
                    return None
            except Exception:
                pass
            import numpy as _np
            # 避免使用 "obj or []" 触发 numpy 数组真值歧义 (DeprecationWarning)
            _xs_raw = ln.get_xdata()
            _ys_raw = ln.get_ydata()
            if _xs_raw is None:
                _xs_raw = []
            if _ys_raw is None:
                _ys_raw = []
            try:
                # list/tuple/ndarray 统一转 float32/64
                xs = _np.asarray(_xs_raw, dtype=float)
            except Exception:
                xs = _np.asarray([], dtype=float)
            try:
                ys = _np.asarray(_ys_raw, dtype=float)
            except Exception:
                ys = _np.asarray([], dtype=float)
            if xs.size == 0 or ys.size == 0 or xs.size != ys.size:
                return None
            # 仅取视口内，降低计算量
            try:
                x0, x1 = self.ax.get_xlim()
                mask = (xs >= x0) & (xs <= x1)
                if not _np.any(mask):
                    # 无窗口内数据则放弃
                    return None
                xs_v = xs[mask]
                ys_v = ys[mask]
            except Exception:
                xs_v, ys_v = xs, ys
            # 在像素空间对折线段进行最近投影，得到更精确的最近点
            pts = _np.column_stack([xs_v, ys_v])
            pix = self.ax.transData.transform(pts)
            if pix.shape[0] == 0:
                return None
            if pix.shape[0] == 1:
                dx = pix[0, 0] - event.x
                dy = pix[0, 1] - event.y
                d = float((dx*dx + dy*dy) ** 0.5)
                if d > float(max_pixel_dist):
                    return None
                return (None, 0, float(xs_v[0]), float(ys_v[0]))
            p0 = pix[:-1, :]
            p1 = pix[1:, :]
            seg = p1 - p0  # (n-1,2)
            v = _np.column_stack([_np.full(p0.shape[0], event.x), _np.full(p0.shape[0], event.y)]) - p0
            seg_len2 = _np.sum(seg * seg, axis=1)
            # 避免除零
            seg_len2 = _np.where(seg_len2 <= 1e-9, 1e-9, seg_len2)
            t = _np.sum(v * seg, axis=1) / seg_len2
            t = _np.clip(t, 0.0, 1.0)
            cp = p0 + (seg * t[:, None])  # 最近点（像素）
            dxy = cp - _np.array([event.x, event.y])[None, :]
            dist2 = _np.sum(dxy * dxy, axis=1)
            j = int(_np.argmin(dist2))  # 段索引 j -> 点在 j..j+1 上
            dmin = float(dist2[j] ** 0.5)
            if dmin > float(max_pixel_dist):
                return None
            # 回到数据坐标：在 xs_v[j]..xs_v[j+1] 之间按 t[j] 插值
            tj = float(t[j])
            x_hit = float(xs_v[j] + tj * (xs_v[j+1] - xs_v[j]))
            y_hit = float(ys_v[j] + tj * (ys_v[j+1] - ys_v[j]))
            # 返回 j（段起点索引）作为 idx 以便相邻参考
            return (None, j, x_hit, y_hit)
        except Exception:
            return None

    def _format_pitch_text(self, y_value: float, x_value: float = None) -> str:
        """根据悬停点的 y(连续八度) 反推频率并格式化文本。
        文本格式：<音名><八度> · <频率Hz> · <偏差cents>（可选时间戳）
        """
        try:
            import math as _m
            # y = octave_exact = midi/12 - 1 => midi = (y+1)*12
            midi = float(y_value) * 12.0 + 12.0
            # midi -> 频率
            hz = 440.0 * (2.0 ** ((midi - 69.0) / 12.0))
            # 计算音名/八度与分音偏差
            note_info = None
            try:
                if callable(getattr(self, 'frequency_to_note_info', None)):
                    note_info = self.frequency_to_note_info(hz)
            except Exception:
                note_info = None
            if note_info and isinstance(note_info, dict) and note_info.get('note_name') is not None:
                # 使用 ASCII 升降号，避免在部分中文字体下出现方块字符
                name = self._normalize_note_ascii(f"{note_info.get('note_name','')}")
                octv = note_info.get('octave', '')
                cents = note_info.get('cents', 0.0)
                parts = [f"{name}{octv}", f"{hz:.2f} Hz", f"{cents:+.1f} cents"]
            else:
                # 退化：仅显示Hz
                parts = [f"{hz:.2f} Hz"]
            # 可选附加时间
            try:
                if x_value is not None:
                    parts.append(f"t={float(x_value):.2f}s")
            except Exception:
                pass
            return "  ·  ".join(parts)
        except Exception:
            # 再退化：仅根据 y 值显示
            try:
                return f"y={float(y_value):.3f}"
            except Exception:
                return ""

    def _format_magnifier_text(self, y_value: float, x_value: float = None) -> str:
        """放大镜内的文本：优先显示 音符(如 B3) · 频率Hz · t=xxs，不显示 cents。"""
        try:
            # 由 y 估算频率
            midi = float(y_value) * 12.0 + 12.0
            hz = 440.0 * (2.0 ** ((midi - 69.0) / 12.0))
            name_oct = None
            try:
                if callable(getattr(self, 'frequency_to_note_info', None)):
                    ni = self.frequency_to_note_info(hz)
                    if ni and isinstance(ni, dict) and ni.get('note_name') is not None:
                        # 使用 ASCII 升降号，避免在部分中文字体下出现方块字符
                        nm = self._normalize_note_ascii(f"{ni.get('note_name','')}")
                        oc = ni.get('octave', '')
                        name_oct = f"{nm}{oc}"
            except Exception:
                name_oct = None
            # 兜底：自行从 MIDI 计算音符与八度
            if not name_oct:
                try:
                    import math as _m
                    midi_rounded = int(round(midi))
                    pc = midi_rounded % 12
                    octave = (midi_rounded // 12) - 1
                    names = ['C','C#','D','D#','E','F','F#','G','G#','A','A#','B']
                    # 使用 ASCII 升号，避免 Unicode ♯ 在部分字体下显示方块
                    nm2 = names[pc]
                    name_oct = f"{nm2}{octave}"
                except Exception:
                    name_oct = None
            parts = []
            if name_oct:
                parts.append(name_oct)
            parts.append(f"{hz:.2f} Hz")
            if x_value is not None:
                parts.append(f"t={float(x_value):.2f}s")
            return "  ·  ".join(parts)
        except Exception:
            try:
                return f"t={float(x_value):.2f}s" if x_value is not None else ""
            except Exception:
                return ""

    def _normalize_note_ascii(self, s: str) -> str:
        """将可能出现的 Unicode 升降号替换为 ASCII，避免字体方块。"""
        try:
            return s.replace('♯', '#').replace('♭', 'b')
        except Exception:
            return s

    def _capture_magnifier_crop(self, x: float, y: float):
        """从主轴截图裁剪出放大镜窗口内容（返回 RGBA ndarray 或 None）。"""
        try:
            ax_main = getattr(self, 'ax', None)
            fig = getattr(self, 'figure', None)
            if ax_main is None or fig is None:
                return None
            # 计算窗口范围
            try:
                x0, x1 = ax_main.get_xlim()
                y0, y1 = ax_main.get_ylim()
            except Exception:
                return None
            main_w_px = float(ax_main.bbox.width)
            main_h_px = float(ax_main.bbox.height)
            if main_w_px <= 0 or main_h_px <= 0:
                return None
            try:
                target_sec = float(getattr(self, '_magn_target_window_sec', 2.0))
            except Exception:
                target_sec = 2.0
            half_w = 0.5 * target_sec
            try:
                dy = (y1 - y0) / max(1e-6, (x1 - x0)) * (half_w * 2.0)
                half_h = 0.5 * dy
            except Exception:
                half_h = 0.5
            xL, xR = float(x) - half_w, float(x) + half_w
            yB, yT = float(y) - half_h, float(y) + half_h
            # 转到显示像素
            import numpy as _np
            p0 = ax_main.transData.transform([(xL, yB), (xR, yT)])
            (xL_px, yB_px), (xR_px, yT_px) = p0[0], p0[1]
            ab = ax_main.get_window_extent()
            ax_x0, ax_y0, ax_x1, ax_y1 = float(ab.x0), float(ab.y0), float(ab.x1), float(ab.y1)
            ix0 = int(_np.floor(max(min(xL_px, xR_px), ax_x0)))
            ix1 = int(_np.ceil(min(max(xL_px, xR_px), ax_x1)))
            iy0 = int(_np.floor(max(min(yB_px, yT_px), ax_y0)))
            iy1 = int(_np.ceil(min(max(yB_px, yT_px), ax_y1)))
            if ix1 <= ix0 or iy1 <= iy0:
                return None
            # 强制刷新画布，避免拿到旧帧
            try:
                fig.canvas.draw()
            except Exception:
                pass
            fig_w_px = int(_np.round(fig.bbox.width))
            fig_h_px = int(_np.round(fig.bbox.height))
            buf = None
            try:
                mem = fig.canvas.buffer_rgba()
                buf = _np.frombuffer(mem, dtype=_np.uint8).reshape(fig_h_px, fig_w_px, 4)
            except Exception:
                try:
                    _renderer = getattr(fig.canvas, 'renderer', None) or fig.canvas.get_renderer()
                    buf = _np.asarray(_renderer.buffer_rgba())
                except Exception:
                    buf = None
            if buf is None:
                return None
            row0 = int(max(0, min(fig_h_px, _np.floor(fig_h_px - iy1))))
            row1 = int(max(0, min(fig_h_px, _np.ceil(fig_h_px - iy0))))
            col0 = int(max(0, min(fig_w_px, ix0)))
            col1 = int(max(0, min(fig_w_px, ix1)))
            if row1 <= row0 or col1 <= col0:
                return None
            crop = buf[row0:row1, col0:col1, :]
            return crop
        except Exception:
            return None

    def _handle_hover_tooltip(self, event):
        try:
            dbg_hover = bool(getattr(self, 'debug_flags', {}).get('hover_magnifier_log', False))
            # 清轴或切换后确保注解/高亮图元存在
            try:
                self._ensure_hover_annot()
                self._ensure_hover_highlight_artists()
            except Exception:
                pass
            if self._hover_annot is None:
                return
            # 门控
            if not self._hover_gating_allowed():
                if dbg_hover:
                    try:
                        now = time.time()
                        last = float(getattr(self, '_last_log_times', {}).get('hover_magnifier', 0.0))
                        if now - last > 0.6:
                            try:
                                ap = getattr(self, 'audio_processor', None)
                            except Exception:
                                ap = None
                            print(
                                "[HOVER_DIAG] gate=0 "
                                f"is_paused={int(bool(getattr(self,'is_paused',False)))} "
                                f"is_rec={int(bool(getattr(self,'is_recording',False)))} "
                                f"is_rec_active={int(bool(getattr(self,'is_recording_active',False)))} "
                                f"rec_paused={int(bool(getattr(self,'is_recording_paused',False)))} "
                                f"ext_paused={int(bool(getattr(self,'_external_paused',False)))} "
                                f"back_paused={int(bool(getattr(self,'is_backing_paused',False)))} "
                                f"sel_active={int(bool(getattr(self,'selection_active',False)))} "
                                f"retake_active={int(bool(getattr(self,'retake_selection_active',False)))} "
                                f"listenback={int(bool(getattr(self,'listenback_enabled',False)))} "
                                f"ap_rec={int(bool(getattr(ap,'is_recording',False)) if ap else 0)} "
                                f"ap_paused={int(bool(getattr(ap,'is_paused',False)) if ap else 0)} "
                                f"lb_state={getattr(self,'_lb_state',None)} lb_user_paused={int(bool(getattr(self,'_lb_user_paused',False)))}"
                            )
                            try:
                                self._last_log_times['hover_magnifier'] = now
                            except Exception:
                                pass
                    except Exception:
                        pass
                if self._hover_annot.get_visible():
                    self._hover_annot.set_visible(False)
                try:
                    self._hide_hover_highlight()
                except Exception:
                    pass
                try:
                    self._hide_magnifier()
                except Exception:
                    pass
                return
            # 正在拖拽则不显示
            if getattr(self, 'dragging', False) or getattr(self, '_sel_dragging_side', None) is not None or getattr(self, '_dragging_playhead', False):
                if dbg_hover:
                    try:
                        now = time.time()
                        last = float(getattr(self, '_last_log_times', {}).get('hover_magnifier', 0.0))
                        if now - last > 0.6:
                            print("[HOVER_DIAG] gate=1 drag=1")
                            try:
                                self._last_log_times['hover_magnifier'] = now
                            except Exception:
                                pass
                    except Exception:
                        pass
                if self._hover_annot.get_visible():
                    self._hover_annot.set_visible(False)
                try:
                    self._hide_hover_highlight()
                except Exception:
                    pass
                try:
                    self._hide_magnifier()
                except Exception:
                    pass
                return
            # 节流
            now = time.time()
            if now - float(getattr(self, '_hover_last_t', 0.0)) < float(getattr(self, '_hover_throttle_sec', 0.05)):
                return
            self._hover_last_t = now
            # 先从已存在的 PathCollection 命中；若失败再从 _segments 回退查找
            hit_radius = float(getattr(self, '_hover_hit_radius_px', 18))
            hit = self._find_nearest_point(event, max_pixel_dist=hit_radius)
            if not hit:
                # 普通模式下常见：只有主线无散点
                hit = self._fallback_nearest_from_line(event, max_pixel_dist=hit_radius)
            if not hit:
                # 再退回到分段缓存
                hit = self._fallback_nearest_from_segments(event, max_pixel_dist=hit_radius)
            if not hit:
                if self._hover_annot.get_visible():
                    self._hover_annot.set_visible(False)
                if dbg_hover:
                    try:
                        now = time.time()
                        last = float(getattr(self, '_last_log_times', {}).get('hover_magnifier', 0.0))
                        if now - last > 0.6:
                            cols = self._collect_visible_point_collections()
                            segs = getattr(self, '_segment_points', None)
                            seg_n = len(segs) if isinstance(segs, (list, tuple)) else 0
                            print(f"[HOVER_DIAG] gate=1 hit=0 cols={len(cols)} seg_points={seg_n} inaxes={int(bool(event.inaxes==self.ax))}")
                            try:
                                self._last_log_times['hover_magnifier'] = now
                            except Exception:
                                pass
                    except Exception:
                        pass
                try:
                    self._hide_hover_highlight()
                except Exception:
                    pass
                try:
                    self._hide_magnifier()
                except Exception:
                    pass
                return
            col, idx, x, y = hit
            text = self._format_pitch_text(y, x)
            if not text:
                if self._hover_annot.get_visible():
                    self._hover_annot.set_visible(False)
                try:
                    self._hide_hover_highlight()
                except Exception:
                    pass
                try:
                    self._hide_magnifier()
                except Exception:
                    pass
                return
            # 更新主注解文本，但由于放大镜显示需求，主图注解将保持隐藏（只在镜片内显示）
            self._hover_annot.xy = (x, y)
            self._hover_annot.set_text(text)
            # 自适应偏移，避免遮挡
            try:
                bbox = self.ax.get_window_extent()
                right_bias = (event.x > (bbox.x0 + bbox.width * 0.66))
                up_bias = (event.y > (bbox.y0 + bbox.height * 0.66))
                dx = -12 if right_bias else 10
                dy = -16 if up_bias else 16
                self._hover_annot.set_position((dx, dy))
            except Exception:
                pass
            self._hover_annot.set_zorder(9999)
            # 只在镜片内显示文本：主图注解隐藏（强制隐藏，避免重复显示）
            try:
                self._hover_annot.set_visible(False)
            except Exception:
                pass
            # 高亮悬停点
            try:
                self._update_hover_highlight(x, y)
            except Exception:
                pass
            # 放大镜：靠近细节点时显示局部放大，并在放大区内显示同样的信息
            try:
                # 放大镜内文本：音符 · 频率 · t
                mag_text = self._format_magnifier_text(y, x)
                self._update_magnifier(event, x, y, mag_text)
            except Exception:
                pass
            if dbg_hover:
                try:
                    now = time.time()
                    last = float(getattr(self, '_last_log_times', {}).get('hover_magnifier', 0.0))
                    if now - last > 0.6:
                        print(f"[HOVER_DIAG] gate=1 hit=1 x={x:.3f} y={y:.3f} magn_visible={int(bool(getattr(self,'_magn_visible',False)))}")
                        try:
                            ol = getattr(self, '_magn_overlay_label', None)
                            ow = getattr(self, '_magn_overlay_window', None)
                            ol_vis = int(bool(ol is not None and getattr(ol, 'isVisible', lambda: False)()))
                            ow_vis = int(bool(ow is not None and getattr(ow, 'isVisible', lambda: False)()))
                            print(f"[HOVER_DIAG] overlay_label={ol_vis} overlay_window={ow_vis}")
                        except Exception:
                            pass
                        try:
                            self._last_log_times['hover_magnifier'] = now
                        except Exception:
                            pass
                except Exception:
                    pass
            # 轻量刷新
            self.canvas.draw_idle()
        except Exception:
            pass

    def _on_mouse_leave(self, event):
        try:
            if self._hover_annot is not None and self._hover_annot.get_visible():
                self._hover_annot.set_visible(False)
                self.canvas.draw_idle()
            try:
                self._hide_hover_highlight()
            except Exception:
                pass
            try:
                self._hide_magnifier()
            except Exception:
                pass
            # 恢复默认箭头光标
            try:
                canvas = getattr(self, 'canvas', None)
                if canvas is not None:
                    try:
                        from PyQt6.QtCore import Qt
                        from PyQt6.QtGui import QCursor
                        canvas.setCursor(QCursor(Qt.CursorShape.ArrowCursor))
                    except Exception:
                        from PyQt5.QtCore import Qt  # type: ignore
                        from PyQt5.QtGui import QCursor  # type: ignore
                        canvas.setCursor(QCursor(Qt.ArrowCursor))
                self._cursor_is_feather = False
            except Exception:
                pass
        except Exception:
            pass

    def _start_playhead_timer(self, abs_start: float, abs_end: float):
        try:
            # 回听启动前：清理临时叠加线与头部点，避免跨时间残影/连线
            try:
                self._reset_on_listenback_start()
            except Exception:
                pass
            self._ensure_playhead()
            # 记录区间绝对时间
            self._lb_abs_start = float(abs_start)
            self._lb_abs_end = float(abs_end)
            # 记录实际启动的墙钟，用于相对推进播放头
            self._lb_wall_start = time.time()
            self._lb_play_abs_start = float(abs_start)
            # 启动“覆盖绘制宽限期”：宽限内不按覆盖过滤临时折线，确保曲线立即可见
            try:
                self._lb_cover_grace_until = time.time() + float(getattr(self, '_lb_cover_grace_sec', 1.0))
            except Exception:
                pass
            # 立刻把播放头设置到起点，避免第一帧“静止”错觉
            try:
                if hasattr(self, 'start_time') and self.start_time is not None and hasattr(self, '_lb_playhead') and self._lb_playhead is not None:
                    x0 = float(self._lb_play_abs_start - float(self.start_time))
                    self._lb_playhead.set_xdata([x0, x0])
                    self._lb_playhead.set_visible(True)
                    self._lb_playhead.set_zorder(148)
                    # 回听开始：标记起点覆盖（不干扰去重）
                    try:
                        if getattr(self, 'listenback_enabled', False) and getattr(self, 'selection_active', False) and not getattr(self, '_dragging_playhead', False):
                            self._cov_add_point(x0)
                    except Exception:
                        pass
            except Exception:
                pass
            # 计时器刷新播放头位置
            if not hasattr(self, '_lb_timer') or self._lb_timer is None:
                self._lb_timer = QTimer(self)
                self._lb_timer.setTimerType(Qt.TimerType.PreciseTimer)
                self._lb_timer.timeout.connect(self._on_playhead_tick)
            self._lb_timer.start(16)
            # 订阅处理器完成信号
            try:
                ap = getattr(self, 'audio_processor', None)
                if ap is not None:
                    try:
                        ap.listenback_playback_finished.disconnect(self._on_playback_finished)
                    except Exception:
                        pass
                    ap.listenback_playback_finished.connect(self._on_playback_finished)
            except Exception:
                pass
        except Exception:
            pass

    def _reset_on_listenback_start(self):
        """回听开始/跳转时的可视叠加清理：
        - 隐藏并清空临时叠加线(_provisional_line/_provisional_polyline)
        - 清空头部即时散点缓存与集合（避免跨分钟残留）
        - 轻量隐藏渐变叠加点
        """
        try:
            # 临时叠加线
            try:
                self._provisional_polyline = None
            except Exception:
                pass
            if hasattr(self, '_provisional_line') and self._provisional_line is not None:
                try:
                    self._provisional_line.set_data([], [])
                    self._provisional_line.set_visible(False)
                except Exception:
                    pass
            # 抑制临时折线：设置短时冷却，避免重置后下一帧又生成跨分钟连线
            try:
                import time as _t
                self._suppress_provisional_until = _t.time() + float(getattr(self, '_suppress_provisional_window', 0.35))
            except Exception:
                pass
            # 头部点列表与集合
            try:
                if hasattr(self, '_head_points'):
                    try:
                        self._head_points.clear() if hasattr(self._head_points, 'clear') else None
                    except Exception:
                        self._head_points = []
                if hasattr(self, '_head_points_scatter') and self._head_points_scatter is not None:
                    import numpy as _np
                    self._head_points_scatter.set_offsets(_np.empty((0, 2)))
                    self._head_points_scatter.set_alpha(0.0)
            except Exception:
                        # 优先从坐标轴移除，避免残留
                        if hasattr(self, 'ax') and self._provisional_line in getattr(self.ax, 'lines', []):
                            self._provisional_line.remove()
            if hasattr(self, 'gradient_overlay_points') and self.gradient_overlay_points is not None:
                try:
                    self._provisional_line = None
                    if self.gradient_overlay_points in getattr(self.ax, 'collections', []):
                        self.gradient_overlay_points.remove()
                except Exception:
                    # 同时设置一个恢复禁令，禁止在冷却期被 setup_ecg_grid 等路径误恢复
                    self._ban_restore_provisional_until = _t.time() + float(getattr(self, '_suppress_provisional_window', 0.35))
                    pass
                self.gradient_overlay_points = None
            # 触发一次轻量重绘
            try:
                if hasattr(self, 'canvas'):
                    self.canvas.draw_idle()
            except Exception:
                pass
        except Exception:
            pass

    def _stop_playhead_timer(self):
        try:
            if hasattr(self, '_lb_timer') and self._lb_timer is not None:
                self._lb_timer.stop()
        except Exception:
            pass

    def _on_playhead_tick(self):
        try:
            try:
                ap = getattr(self, 'audio_processor', None)
                if ap is not None and str(getattr(ap, '_lb_state', 'stopped')) != 'playing':
                    self._stop_playhead_timer()
                    return
            except Exception:
                pass
            # 根据墙钟相对增量推进（与回放绝对时间对齐）
            if not hasattr(self, '_lb_abs_start') or not hasattr(self, '_lb_wall_start'):
                return
            if self._lb_abs_start is None or self._lb_wall_start is None or getattr(self, '_lb_abs_end', None) is None:
                self._stop_playhead_timer()
                return
            # 将绝对时间映射到可视坐标（start_time参考）
            if not hasattr(self, 'start_time') or self.start_time is None:
                return
            now = time.time()
            # 以启动时刻为零点推进
            cur_abs = float(self._lb_play_abs_start) + float(now - float(self._lb_wall_start))
            # 限制在区间内
            cur_abs = min(max(cur_abs, self._lb_abs_start), self._lb_abs_end)
            x = float(cur_abs - float(self.start_time))
            try:
                self.follow_playback_time(x)
            except Exception:
                pass
            try:
                self._lb_playhead.set_xdata([x, x])
                self._lb_playhead.set_visible(True)
                self._lb_playhead.set_zorder(148)
            except Exception:
                pass
            # 播放推进：按播放头位置标记覆盖（真实播放，且非拖动）
            try:
                if getattr(self, 'listenback_enabled', False) and getattr(self, 'selection_active', False) and not getattr(self, '_dragging_playhead', False):
                    ap = getattr(self, 'audio_processor', None)
                    if ap is None or getattr(ap, '_lb_state', '') == 'playing':
                        self._cov_add_point(x)
            except Exception:
                pass
            self.canvas.draw_idle()
            # 到达末尾则触发完成
            if cur_abs >= self._lb_abs_end - 1e-3:
                self._on_playback_finished()
        except Exception:
            pass

    def _on_playback_finished(self):
        try:
            # 若是“用户暂停”导致的 finished 回调（关闭流触发），忽略复位逻辑
            if getattr(self, '_lb_user_paused', False):
                try:
                    self._lb_user_paused = False
                except Exception:
                    pass
                # 已在暂停处理里完成UI更新，这里只确保计时器停止
                self._stop_playhead_timer()
                return
            self._stop_playhead_timer()
            # 保留播放头可见，并将其复位到左边线
            try:
                if hasattr(self, '_lb_playhead') and self._lb_playhead is not None:
                    xL = float(getattr(self, 'sel_start', 0.0) or 0.0)
                    self._lb_playhead.set_xdata([xL, xL])
                    self._lb_playhead.set_ydata([0.0, 1.0])
                    self._lb_playhead.set_visible(True)
                    try:
                        self._lb_playhead.set_zorder(148)
                    except Exception:
                        pass
                    # 自然结束后，允许后续自动贴边逻辑生效
                    try:
                        self._lb_resume_abs_start = None
                        self._lb_user_moved_playhead = False
                    except Exception:
                        pass
            except Exception:
                pass
            # 播放完整区间后：将 [sel_start, sel_end] 并入覆盖，确保“全段已绘制”
            try:
                if getattr(self, 'listenback_enabled', False) and getattr(self, 'selection_active', False):
                    s = float(getattr(self, 'sel_start', 0.0) or 0.0)
                    e = float(getattr(self, 'sel_end', s))
                    if e > s:
                        self._cov_add_range(s, e)
            except Exception:
                pass
            self.selection_active = True
            self.update_listenback_artists()
            self.canvas.draw_idle()
        except Exception:
            pass
    
    def on_mouse_scroll(self, event):
        """鼠标滚轮事件（上下移动音高视图）"""
        if event.inaxes != self.ax:
            return
        prof = getattr(self, '_current_zoom_profile', None) or self._get_zoom_profile()
        if prof.get('disable_v_scroll'):
            return  # 不允许滚动
        
        # 滚轮上下移动音高视图中心
        scroll_sensitivity = 0.3  # 滚动敏感度
        if event.step > 0:  # 向上滚动
            delta_y = scroll_sensitivity
        else:  # 向下滚动
            delta_y = -scroll_sensitivity
        
        # 更新音高视图中心
        prev_center = self.y_view_center
        new_y_center = self.y_view_center + delta_y
        self.y_view_center = max(0.5, min(7.5, new_y_center))
        try:
            print(f"[MWHEEL] mode={prof.get('mode')} delta={delta_y:+.2f} center={self.y_view_center:.3f} Δ={self.y_view_center-prev_center:+.3f}")
        except Exception:
            pass
        self._user_overrode_center = True
        
        # 🔥 完全按照vertical_scroll的模式处理，确保一致性
        # 先更新坐标轴范围
        self.update_axis_ranges()
        
        # 🔥 修复音调线消失问题：强制重新绘制音调线数据
        if len(self.pitch_data) > 0:
            # 强制更新显示，确保音调线在滚轮滚动后重新绘制
            self._force_redraw_on_next_update = True
            # 🔥 关键修复：设置一个更持久的重绘标志，防止定时器覆盖
            self._scroll_triggered_redraw = True
            self.update_display()
        else:
            self.canvas.draw_idle()
        
        # 同步更新垂直滚动条位置
        if hasattr(self, 'v_scrollbar'):
            # 将y_view_center (1.5-6.5) 映射到滚动条范围 (0-100)
            scroll_value = int((self.y_view_center - 1.5) / 5.0 * 100)
            self.v_scrollbar.blockSignals(True)  # 阻止信号避免循环
            self.v_scrollbar.setValue(100 - scroll_value)  # 反转，顶部对应高音
            self.v_scrollbar.blockSignals(False)
        
        # 🔥 阻止事件传播，避免与matplotlib默认滚轮行为冲突
        return True
    
    def on_vertical_scroll(self, value):
        """垂直滚动条事件（控制音高视图中心, 遵从 zoom profile 的 disable_v_scroll）"""
        prof = getattr(self, '_current_zoom_profile', None) or self._get_zoom_profile()
        if prof.get('disable_v_scroll'):
            # 强制保持其指定中心
            fc = prof.get('force_center', 4.0)
            if self.y_view_center != fc:
                self.y_view_center = fc
                self.update_axis_ranges()
            self.update_scrollbars()
            return
        half_range = self.compute_half_range()
        min_center = half_range
        max_center = 8.0 - half_range
        normalized_value = (100 - value) / 100.0
        self.y_view_center = min_center + normalized_value * (max_center - min_center)
        self._user_overrode_center = True
        try:
            print(f"[VSCROLL] value={value} center={self.y_view_center:.3f} half={half_range:.2f} bounds=({min_center:.2f},{max_center:.2f}) mode={prof.get('mode')}")
        except Exception:
            pass
        self.update_axis_ranges()
        # 立即同步以避免下一次刷新覆盖视觉效果
        self.update_scrollbars()
        try:
            self._refresh_technique_artists(force=True)
        except Exception:
            pass
        try:
            ylim = self.ax.get_ylim()
            print(f"[VSCROLL AXIS] mode={prof.get('mode')} ylim={ylim}")
        except Exception:
            pass
        if len(self.pitch_data) > 0:
            self._force_redraw_on_next_update = True
            self.update_display()
        elif getattr(self, '_use_pyqtgraph', False):
            self._pg_sync_view()
        else:
            self.canvas.draw_idle()
        # 更新辅助线位置
        try:
            self.update_guides()
        except Exception:
            pass
    
    def on_horizontal_scroll(self, value):
        """水平滚动条事件（控制时间偏移）"""
        # 将滚动条值 (0-100) 映射到时间偏移范围
        # 优先使用伴奏锁定总长度（修复：分析/录音开始后初期只能滚到约120秒的问题）
        try:
            if getattr(self, '_backing_axis_locked', False):
                max_time = float(getattr(self, '_backing_axis_length', self.max_history_time))
            else:
                max_time = float(getattr(self, 'max_history_time', 0.0))
        except Exception:
            max_time = getattr(self, 'max_history_time', 0.0)
        # 标记手动操作时间，供平滑器参考
        try:
            import time as _t
            self._last_manual_scroll_time = _t.time()
        except Exception:
            pass
        # 滚动条左端(0)对应最开始时间(时间偏移0)，右端(100)对应最大偏移
        normalized_value = value / 100.0
        max_offset = max(0.0, max_time - float(getattr(self, 'time_window', 16.0)))
        self.time_offset = normalized_value * max_offset
        # 新增：为保证暂停/手动seek时水平滚动条拖动立即生效并保持“无缓动”体验，
        # 这里设置一个短期(1.6s)的平滑禁用窗口，在 _smooth_set_xlim 内检测。
        try:
            import time as _t
            now_ts = _t.time()
            # 标记手动滚动活跃期（用于平滑函数判断直接跳过）
            self._manual_scroll_active_until = now_ts + 1.6
            # 若处于暂停或非录音激活状态，同时在伴奏模式/或有伴奏锁，延长一点以提升体验
            paused = bool(getattr(self, 'is_recording_paused', False)) or not bool(getattr(self, 'is_recording_active', False))
            backing_locked = bool(getattr(self, '_backing_axis_locked', False))
            if paused and backing_locked:
                self._manual_scroll_active_until = now_ts + 2.2
            # 通用抑制时间戳（比 _suppress_next_smooth_xlim 更长，允许后续系统多次刷新仍保持即时跳转）
            self._suppress_smooth_until = self._manual_scroll_active_until
        except Exception:
            pass
        # 若接近最右端直接对齐，避免多次拖动才能看到最末尾
        try:
            if normalized_value > 0.98:
                self.time_offset = max_offset
                # 临时时间锚定（短期，保留原逻辑）
                try:
                    import time as _t
                    self._manual_end_anchor_until = _t.time() + 3.0
                except Exception:
                    pass
            # 持久“查看末端”模式：伴奏锁定 + 用户处于末端区域时激活
            try:
                if getattr(self, '_backing_axis_locked', False):
                    if normalized_value > 0.975:
                        if not getattr(self, '_viewing_backing_end', False):
                            self._viewing_backing_end = True
                            if getattr(self, '_debug_axis_trace', False):
                                print(f"[END_VIEW] enter backing_end len={getattr(self,'_backing_axis_length','?')} tw={getattr(self,'time_window',0)}")
                    elif normalized_value < 0.90 and getattr(self, '_viewing_backing_end', False):
                        self._viewing_backing_end = False
                        if getattr(self, '_debug_axis_trace', False):
                            print(f"[END_VIEW] leave (user scrolled away)")
            except Exception:
                pass
        except Exception:
            pass
        # 调试：记录一次关键状态
        try:
            # 默认关闭高频打印：print 会阻塞 GUI 线程，导致倒计时/滚动卡顿
            if getattr(self, '_debug_axis_trace', False):
                print(f"[HSCROLL] val={value} norm={normalized_value:.3f} max_time={max_time:.2f} time_window={getattr(self,'time_window',0)} max_offset={max_offset:.2f} time_offset={self.time_offset:.2f} locked={getattr(self,'_backing_axis_locked',False)} locked_len={getattr(self,'_backing_axis_length','-')}")
            # 若已经滚到末端，立即强制刷新 xlim，避免视觉上仍显示前段数据
            if normalized_value > 0.98:
                try:
                    if hasattr(self, 'ax'):
                        self.ax.set_xlim(self.time_offset, self.time_offset + float(getattr(self,'time_window',16.0)))
                        self.canvas.draw_idle()
                        if getattr(self, '_debug_axis_trace', False):
                            print(f"[HSCROLL-END] force_xlim=({self.time_offset:.2f},{self.time_offset + float(getattr(self,'time_window',16.0)):.2f}) end_view={getattr(self,'_viewing_backing_end',False)}")
                        # 抑制下一次平滑
                        self._suppress_next_smooth_xlim = True
                except Exception:
                    pass
            # 硬末端锁激活/退出逻辑：伴奏锁定 + 用户滚动 >98.5% 进入，<90% 退出
            try:
                if getattr(self, '_backing_axis_locked', False):
                    # 进入硬锁
                    if normalized_value > 0.985:
                        if not getattr(self, '_hard_end_view_active', False):
                            self._hard_end_view_active = True
                            # 计算末端窗口并立即设置
                            _total = float(getattr(self, '_backing_axis_length', max_time))
                            _tw = float(getattr(self, 'time_window', 16.0))
                            _start = max(0.0, _total - _tw)
                            self.time_offset = _start
                            try:
                                if hasattr(self, 'ax'):
                                    self.ax.set_xlim(_start, _start + _tw)
                                    if getattr(self, '_debug_axis_trace', False):
                                        print(f"[END_HARD] enter total={_total:.2f} win={_tw:.2f} -> ({_start:.2f},{_start + _tw:.2f})")
                            except Exception:
                                pass
                            self._suppress_next_smooth_xlim = True
                    # 退出硬锁
                    elif normalized_value < 0.90 and getattr(self, '_hard_end_view_active', False):
                        self._hard_end_view_active = False
                        if getattr(self, '_debug_axis_trace', False):
                            print("[END_HARD] leave (user scrolled away)")
                    # 硬起点锁：用户滚动接近最左端并希望看到精确 0s 不被轻微回弹
                    retake_active = False
                    try:
                        retake_active = bool(
                            self._retake_future_preserve_active()
                            or getattr(self, '_retake_dual_mode_active', False)
                            or getattr(self, '_retake_countdown_active', False)
                            or getattr(self, '_retake_overlay_enabled', False)
                        )
                    except Exception:
                        retake_active = False
                    if retake_active and getattr(self, '_hard_start_view_active', False):
                        self._hard_start_view_active = False
                    if normalized_value < 0.015 and not retake_active:
                        if not getattr(self, '_hard_start_view_active', False):
                            self._hard_start_view_active = True
                            try:
                                self.time_offset = 0.0
                                if hasattr(self, 'ax'):
                                    _tw2 = float(getattr(self,'time_window',16.0))
                                    self.ax.set_xlim(0.0, _tw2)
                                    if getattr(self, '_debug_axis_trace', False):
                                        print(f"[START_HARD] enter win={_tw2:.2f} -> (0.00,{_tw2:.2f})")
                                self._suppress_next_smooth_xlim = True
                            except Exception:
                                pass
                    elif normalized_value > 0.10 and getattr(self, '_hard_start_view_active', False):
                        self._hard_start_view_active = False
                        if getattr(self, '_debug_axis_trace', False):
                            print("[START_HARD] leave (user scrolled away)")
            except Exception:
                pass
        except Exception:
            pass
        # 伴奏模式长度纠正：优先使用自身锁属性；若没有再回退父窗口
        try:
            locked_flag = getattr(self, '_backing_axis_locked', None)
            locked_len_local = getattr(self, '_backing_axis_length', None)
            parent = None
            if locked_flag is None or locked_len_local is None:
                try:
                    parent = self.parent() if hasattr(self, 'parent') else None
                except Exception:
                    parent = None
                if parent is not None and getattr(parent, '_backing_axis_locked', False):
                    locked_flag = True
                    locked_len_local = float(getattr(parent, '_backing_axis_length', 0.0))
            if locked_flag and locked_len_local and locked_len_local > 0:
                cur_len = float(getattr(self, 'max_history_time', 0.0))
                # 任何缩短(>0.01)都强制恢复，避免需要多次拖动
                if cur_len + 0.01 < locked_len_local:
                    try:
                        if hasattr(self, 'set_max_history_time'):
                            self.set_max_history_time(locked_len_local)
                        else:
                            self.max_history_time = locked_len_local
                    except Exception:
                        pass
                    max_offset = max(0.0, locked_len_local - float(getattr(self, 'time_window', 16.0)))
                    if normalized_value > 0.90:  # 放宽条件，用户已接近末端即可直接对齐
                        self.time_offset = max_offset
                    try:
                        if hasattr(self, 'update_scrollbars'):
                            self.update_scrollbars()
                    except Exception:
                        pass
                    try:
                        print(f"🔁 强制恢复伴奏锁定长度 {locked_len_local:.2f}s (原={cur_len:.2f}s) horizontal_scroll")
                    except Exception:
                        pass
        except Exception:
            pass
        # 手动覆盖：记录短暂窗口抑制自动滚动
        try:
            import time as _t
            self._manual_time_offset_override_until = _t.time() + 2.5
        except Exception:
            pass
        
        # 手动滚动时暂时禁用自动滚动
        if hasattr(self, 'auto_scroll_enabled'):
            self.auto_scroll_enabled = False
            
            # 设置定时器，3秒后重新启用自动滚动
            if not hasattr(self, 'auto_scroll_timer'):
                self.auto_scroll_timer = QTimer()
                self.auto_scroll_timer.timeout.connect(self.re_enable_auto_scroll)
                self.auto_scroll_timer.setSingleShot(True)
            
            self.auto_scroll_timer.start(3000)  # 3秒后重新启用
        
        # 🔥 修复音调线显示问题：强制重新绘制数据
        self._force_redraw_on_next_update = True
        # 清空旧临时叠加主线但不设抑制禁令，允许按新视窗快速重建，避免“线短暂无”
        try:
            import time as _t
            # 提升细节点可见窗口，确保滚动后第一帧就有“白点”
            try:
                self._force_points_visible_until = _t.time() + float(getattr(self, '_post_seek_points_boost_sec', 0.90))
            except Exception:
                pass
            if hasattr(self, '_provisional_line') and self._provisional_line is not None:
                try:
                    self._provisional_line.set_visible(False)
                except Exception:
                    pass
            if hasattr(self, '_provisional_polyline'):
                self._provisional_polyline = None
        except Exception:
            pass
        # 切换时间窗口时，旧的段缓存可能与新视口不一致，主动刷新
        try:
            if hasattr(self, '_segments_cache'):
                delattr(self, '_segments_cache')
        except Exception:
            pass
        try:
            if hasattr(self, '_segments_cache_window'):
                delattr(self, '_segments_cache_window')
        except Exception:
            pass
        
        # 更新显示（轻量：直接设置 xlim + 刷新批量细节点，避免每次重建网格造成卡顿）
        try:
            x_min = self.time_offset
            x_max = self.time_offset + self.time_window
            # 滚动条为明确的用户导航：直接设置，避免粘滞
            self.ax.set_xlim(x_min, x_max)
            self._suppress_next_smooth_xlim = True
        except Exception:
            pass
        if getattr(self, 'is_recording_active', False):
            # 先确保细节点在上层，避免被线覆盖产生“消失错觉”
            try:
                if hasattr(self, '_batched_points') and self._batched_points is not None:
                    self._batched_points.set_zorder(14)
            except Exception:
                pass
            # 普通模式禁止滚动时刷新批量点，避免出现灰/淡细点和重复
            try:
                mode = (self.display_mode.currentText() if hasattr(self, 'display_mode') else "普通模式")
            except Exception:
                mode = "普通模式"
            if mode != "普通模式":
                self._refresh_batched_points_for_current_xlim()
            # 为避免“只有线没有点/线也缺失”的观感，滚动后立即触发一次重绘
            # 这样会按新视窗重建分段曲线和逐段散点
            try:
                self.update_display()
            except Exception:
                pass
        else:
            try:
                # 快速判断：若当前视口完全在最后数据点之后，则走轻路径避免重帧
                last_t = None
                try:
                    last_t = self.time_data[-1] if self.time_data else None
                except Exception:
                    last_t = None
                x_min = self.time_offset
                x_max = self.time_offset + self.time_window
                in_blank_future = (last_t is not None) and (x_min > last_t + 1e-3)
                if (last_t is None) or in_blank_future:
                    try:
                        self.update_guides()
                    except Exception:
                        pass
                else:
                    self._force_redraw_on_next_update = True
                    self.update_display()
            except Exception:
                pass
        if getattr(self, '_use_pyqtgraph', False):
            # GPU 模式：确保 pyqtgraph 视图始终反映当前 scroll 状态
            self._pg_sync_view()
        if hasattr(self, 'canvas'):
            self.canvas.draw_idle()
        # 更新辅助线位置
        try:
            self.update_guides()
        except Exception:
            pass
        try:
            self._refresh_technique_artists(force=True)
        except Exception:
            pass
        # A+B附加：水平滚动后立即对现存图元执行cap过滤，避免暂停回看时旧点回潮
        try:
            if getattr(self, '_cap_visible_time_enabled', False):
                if hasattr(self, '_enforce_cap_on_existing_artists'):
                    self._enforce_cap_on_existing_artists()
                # 再做一次集合净空，确保任何新生成的PathCollection也被裁剪
                if hasattr(self, '_purge_collections_beyond_cap'):
                    self._purge_collections_beyond_cap()
        except Exception:
            pass
    
    def re_enable_auto_scroll(self):
        """重新启用自动滚动"""
        self.auto_scroll_enabled = True
        try:
            dbg = bool(getattr(self, 'debug_flags', {}).get('auto_scroll_log', False) or getattr(self, '_debug_axis_trace', False))
        except Exception:
            dbg = False
        if dbg and not (callable(getattr(self, '_should_suppress_audio_debug', None)) and self._should_suppress_audio_debug()):
            print("🔄 自动滚动已重新启用")
    
    def update_scrollbars(self):
        """更新滚动条位置以同步当前视图状态"""
        # 垂直滚动条
        if hasattr(self, 'v_scrollbar'):
            try:
                prof = getattr(self, '_current_zoom_profile', None) or self._get_zoom_profile()
                half_range = self.compute_half_range()
                disable_v = bool(prof.get('disable_v_scroll'))
                # 合法中心范围：保持上下边界在 [1.0, 7.0] 内
                min_center = 1.0 + float(half_range)
                max_center = 7.0 - float(half_range)
                if max_center < min_center:
                    min_center = max_center = 4.0
                if disable_v:
                    # 固定中心，禁用滚动条
                    fc = float(prof.get('force_center', 4.0))
                    self.y_view_center = fc
                    last_enabled = getattr(self, '_last_v_scrollbar_enabled', None)
                    if last_enabled is not False:
                        self.v_scrollbar.setEnabled(False)
                        self._last_v_scrollbar_enabled = False
                    last_value = getattr(self, '_last_v_scrollbar_value', None)
                    if last_value != 50:
                        self.v_scrollbar.blockSignals(True)
                        self.v_scrollbar.setValue(50)
                        self.v_scrollbar.blockSignals(False)
                        self._last_v_scrollbar_value = 50
                else:
                    # 允许垂直滚动：启用滚动条并在越界时夹紧中心
                    last_enabled = getattr(self, '_last_v_scrollbar_enabled', None)
                    if last_enabled is not True:
                        self.v_scrollbar.setEnabled(True)
                        self._last_v_scrollbar_enabled = True
                    changed = False
                    if self.y_view_center < min_center:
                        self.y_view_center = min_center; changed = True
                    elif self.y_view_center > max_center:
                        self.y_view_center = max_center; changed = True
                    # 同步滚动条值（顶部对应高音 → 反转）
                    if max_center > min_center:
                        ratio = (self.y_view_center - min_center) / (max_center - min_center)
                    else:
                        ratio = 0.5
                    scroll_value = int((1.0 - ratio) * 100)
                    try:
                        sig = (prof.get('mode'), round(self.y_view_center, 2), half_range, scroll_value, changed)
                        now_ts = time.time()
                        if sig != getattr(self, '_last_scroll_signature', None) or (now_ts - getattr(self, '_last_scroll_log_time', 0.0)) > 1.5:
                            self._log_rate_limit('scroll_sync', f"[SCROLLBAR SYNC] mode={prof.get('mode')} center={self.y_view_center:.2f} half={half_range} val={scroll_value} changed={changed}", interval=0.5, burst=2)
                            self._last_scroll_signature = sig
                            self._last_scroll_log_time = now_ts
                    except Exception:
                        pass
                    last_value = getattr(self, '_last_v_scrollbar_value', None)
                    if last_value != scroll_value:
                        self.v_scrollbar.blockSignals(True)
                        self.v_scrollbar.setValue(scroll_value)
                        self.v_scrollbar.blockSignals(False)
                        self._last_v_scrollbar_value = scroll_value
                # 引导线可见性
                if getattr(self, 'v_guide_glow_line', None) is not None:
                    self.v_guide_glow_line.set_visible(self.guides_enabled)
                if getattr(self, 'h_guide_glow_line', None) is not None:
                    self.h_guide_glow_line.set_visible(self.guides_enabled)
            except Exception as e:
                try:
                    print(f"⚠️ 更新滚动条时出错: {e}")
                except Exception:
                    pass

        if hasattr(self, 'h_scrollbar'):
            # 更新水平滚动条 - 适应新的滚动逻辑
            # 移除对time_data的依赖，直接使用max_history_time
            max_time = self.max_history_time  # 直接使用最大历史时间
            max_offset = max(0, max_time - self.time_window)
            
            if max_offset > 0:
                # 左端(0)对应时间偏移0，右端(100)对应最大偏移
                normalized_offset = self.time_offset / max_offset
                scroll_value = int(normalized_offset * 100)
            else:
                scroll_value = 0  # 默认最左边位置
            
            last_h_value = getattr(self, '_last_h_scrollbar_value', None)
            if last_h_value != scroll_value:
                self.h_scrollbar.blockSignals(True)
                self.h_scrollbar.setValue(scroll_value)
                self.h_scrollbar.blockSignals(False)
                self._last_h_scrollbar_value = scroll_value
    
    # --- 已绘制覆盖：工具 ---
    def _cov_is_covered(self, t: float) -> bool:
        try:
            cov = getattr(self, '_drawn_coverage', None)
            if not cov:
                return False
            tol = float(getattr(self, '_cov_merge_epsilon', 0.05))
            # 线性扫描（区间数很小，且已合并）
            for (s, e) in cov:
                if t >= (s - tol) and t <= (e + tol):
                    return True
            return False
        except Exception:
            return False

    def _cov_add_point(self, t: float):
        try:
            if t is None:
                return
            if not hasattr(self, '_drawn_coverage') or self._drawn_coverage is None:
                self._drawn_coverage = []
            half = float(getattr(self, '_cov_point_half', 0.02))
            s, e = max(0.0, float(t) - half), float(t) + half
            tol = float(getattr(self, '_cov_merge_epsilon', 0.05))
            cov = list(self._drawn_coverage)
            new_s, new_e = s, e
            merged = []
            inserted = False
            for (cs, ce) in cov:
                # 若与新区间相交/相邻（含 tol），则合并
                if not inserted and (new_s <= ce + tol) and (new_e >= cs - tol):
                    new_s = min(new_s, cs)
                    new_e = max(new_e, ce)
                else:
                    merged.append((cs, ce))
            # 将合并后的新区间插入并按起点排序，然后再次线性合并，确保无重叠
            merged.append((new_s, new_e))
            merged.sort(key=lambda x: x[0])
            out = []
            for (cs, ce) in merged:
                if not out:
                    out.append((cs, ce))
                else:
                    ps, pe = out[-1]
                    if cs <= pe + tol:
                        out[-1] = (ps, max(pe, ce))
                    else:
                        out.append((cs, ce))
            self._drawn_coverage = out
        except Exception:
            pass

    def _cov_add_range(self, s: float, e: float):
        """将一个时间区间 [s, e] 合并进已绘制覆盖中。"""
        try:
            if s is None or e is None:
                return
            a, b = float(min(s, e)), float(max(s, e))
            if a == b:
                # 退化为点
                self._cov_add_point(a)
                return
            if not hasattr(self, '_drawn_coverage') or self._drawn_coverage is None:
                self._drawn_coverage = []
            tol = float(getattr(self, '_cov_merge_epsilon', 0.05))
            cov = list(self._drawn_coverage)
            merged = []
            new_s, new_e = max(0.0, a), b
            for (cs, ce) in cov:
                if (new_s <= ce + tol) and (new_e >= cs - tol):
                    new_s = min(new_s, cs)
                    new_e = max(new_e, ce)
                else:
                    merged.append((cs, ce))
            merged.append((new_s, new_e))
            merged.sort(key=lambda x: x[0])
            out = []
            for (cs, ce) in merged:
                if not out:
                    out.append((cs, ce))
                else:
                    ps, pe = out[-1]
                    if cs <= pe + tol:
                        out[-1] = (ps, max(pe, ce))
                    else:
                        out.append((cs, ce))
            self._drawn_coverage = out
        except Exception:
            pass

    def _cov_reset(self):
        try:
            self._drawn_coverage = []
        except Exception:
            pass

    def _maybe_forward_inject_after_cap(self):
        """方案C主动触发：cap 提升后立即检查是否需要前向散点注入。
        条件与 draw_segmented_pitch_line 尾部一致，避免等待下一次重帧导致测试看不到 >cap 新点。"""
        try:
            if not (getattr(self, '_cap_visible_time_enabled', False) and not getattr(self, '_cap_strict_lock', False)):
                if getattr(self,'debug_flags',{}).get('cap_diag'):
                    print('[CAP_INJECT] RET_A disabled_or_strict_lock')
                return
            if not (bool(getattr(self, 'is_analyzing', False)) or str(getattr(self, 'backing_mode', '')).lower() in ('accompaniment','analysis','analyzing')):
                if getattr(self,'debug_flags',{}).get('cap_diag'):
                    print('[CAP_INJECT] RET_B not analyzing/backing mode')
                return
            cap = float(getattr(self, '_max_visible_time', 0.0))
            max_buf_t = None
            try:
                if hasattr(self, 'time_data') and self.time_data:
                    max_buf_t = float(self.time_data[-1])
            except Exception:
                max_buf_t = None
            # 需要至少已经写入当前 cap 对应的新点（或更远）
            if max_buf_t is None or max_buf_t < cap - 1e-6:
                if getattr(self,'debug_flags',{}).get('cap_diag'):
                    print(f'[CAP_INJECT] RET_C insufficient buffer max_buf_t={max_buf_t} cap={cap}')
                return
            # 检查现有 segment_points 是否已有 >cap 点
            has_forward_visible = False
            try:
                import numpy as _np
                if hasattr(self, '_segment_points') and self._segment_points:
                    for coll in self._segment_points:
                        try:
                            off = coll.get_offsets()
                            if off is None: continue
                            arr = _np.asarray(off, dtype=_np.float32)
                            if arr.size and (arr[:,0].max(initial=-1.0) > cap + 1e-6):
                                has_forward_visible = True
                                break
                        except Exception:
                            pass
            except Exception:
                pass
            if has_forward_visible:
                if getattr(self,'debug_flags',{}).get('cap_diag'):
                    print('[CAP_INJECT] RET_D already has forward visible points')
                return
            # 当前已显示的最大时间（用于判断缺口区间）
            cur_vis_max = -1.0
            try:
                import numpy as _np
                if hasattr(self, '_segment_points') and self._segment_points:
                    for coll in self._segment_points:
                        try:
                            off = coll.get_offsets();
                            if off is None: continue
                            arr = _np.asarray(off, dtype=_np.float32)
                            if arr.size:
                                mv = float(arr[:,0].max(initial=-1.0))
                                if mv > cur_vis_max: cur_vis_max = mv
                        except Exception: pass
            except Exception:
                pass
            # 准备采集 >cap 新点
            new_t, new_p = [], []
            try:
                import numpy as _np
                tbuf = list(getattr(self, 'time_data', []))
                pbuf = list(getattr(self, 'pitch_data', []))
                if tbuf and pbuf and len(tbuf) == len(pbuf):
                    for tt, pp in zip(tbuf, pbuf):
                        ftt = float(tt)
                        if ftt > cur_vis_max + 1e-6 and ftt <= cap + 1e-6:  # 填补 (cur_vis_max, cap]
                            new_t.append(ftt); new_p.append(float(pp))
                max_new_pts = int(getattr(self, '_forward_inject_points_cap', 600))
                if len(new_t) > max_new_pts:
                    step = int(_np.ceil(len(new_t)/max_new_pts))
                    new_t = new_t[::step]; new_p = new_p[::step]
            except Exception:
                new_t, new_p = [], []
            if not new_t:
                if getattr(self,'debug_flags',{}).get('cap_diag'):
                    print(f'[CAP_INJECT] RET_E no new points cur_vis_max={cur_vis_max} cap={cap}')
                return
            # 注入逻辑（与 draw_segmented_pitch_line 保持一致）
            try:
                import numpy as _np
                detail_rgb = (1.0, 1.0, 1.0)
                arr = _np.column_stack((new_t, new_p))
                try:
                    # 统一使用 cap 过滤（含分析/伴奏视觉前瞻），避免硬性按 _max_visible_time 截断
                    arr = self._cap_filter_offsets_array(arr)
                except Exception:
                    pass
                # 计算尺寸
                try:
                    if hasattr(self, '_segment_points') and self._segment_points:
                        s_existing = None
                        try:
                            s_existing = self._segment_points[0].get_sizes()
                        except Exception:
                            s_existing = None
                        if s_existing is not None and len(s_existing):
                            s_val = float(s_existing[0])
                        else:
                            base_w = float(getattr(self, 'current_linewidth', 0.6))
                            zoom = float(getattr(self, 'zoom_level', 1.0))
                            diameter = max(2.0, min(base_w * 3.6 / (0.6 if zoom < 1 else min(zoom, 3.0)), 5.0))
                            s_val = diameter ** 2
                    else:
                        base_w = float(getattr(self, 'current_linewidth', 0.6))
                        zoom = float(getattr(self, 'zoom_level', 1.0))
                        diameter = max(2.0, min(base_w * 3.6 / (0.6 if zoom < 1 else min(zoom, 3.0)), 5.0))
                        s_val = diameter ** 2
                except Exception:
                    s_val = 9.0
                pts = self.ax.scatter(arr[:,0], arr[:,1], s=s_val, color=detail_rgb, alpha=0.96, linewidths=0, edgecolors='none', zorder=14)
                try: pts.set_visible(True)
                except Exception: pass
                if not hasattr(self, '_segment_points') or self._segment_points is None:
                    self._segment_points = []
                self._segment_points.append(pts)
                self._forward_segment_last_inject_cap = float(cap)
                if getattr(self,'debug_flags',{}).get('cap_diag'):
                    try:
                        import numpy as _np
                        print(f"[CAP_INJECT] injected pts={arr.shape[0]} range=({arr[:,0].min():.3f},{arr[:,0].max():.3f}) cur_vis_max_prev={cur_vis_max:.3f} cap={cap:.3f}")
                    except Exception:
                        print('[CAP_INJECT] injected')
                # 强制调度一次绘制
                try:
                    if hasattr(self, 'canvas'):
                        self.canvas.draw_idle()
                except Exception:
                    pass
            except Exception:
                pass
        except Exception:
            pass

    def _force_forward_segment_refresh(self):
        """在分析/伴奏模式下：若 seek 后 cap 已向前推进但仍无 > 初始cap 可见点，强制一次前向段刷新/注入。
        触发条件：
          1) _post_seek_initial_cap 存在
          2) 当前 cap > initial_cap + 阈值 (默认0.08s)
          3) _segment_points / 兜底点 中仍不存在 > initial_cap 的点
          4) 避免重复：同一 cap 区间只强制一次 (记录 _last_forward_refresh_cap)
        """
        try:
            if not (getattr(self, '_cap_visible_time_enabled', False) and not getattr(self, '_cap_strict_lock', False)):
                if getattr(self,'debug_flags',{}).get('cap_diag'):
                    print('[CAP_FWD_REFRESH] RET_A disabled_or_strict_lock')
                return
            if not (bool(getattr(self,'is_analyzing',False)) or str(getattr(self,'backing_mode','')).lower() in ('accompaniment','analysis','analyzing')):
                if getattr(self,'debug_flags',{}).get('cap_diag'):
                    print('[CAP_FWD_REFRESH] RET_B not analyzing/backing')
                return
            init_cap = float(getattr(self, '_post_seek_initial_cap', -1.0))
            if init_cap < 0:
                if getattr(self,'debug_flags',{}).get('cap_diag'):
                    print('[CAP_FWD_REFRESH] RET_C no initial cap')
                return
            cur_cap = float(getattr(self, '_max_visible_time', 0.0))
            thr = float(getattr(self, '_forward_refresh_threshold', 0.08))
            if cur_cap <= init_cap + thr:
                if getattr(self,'debug_flags',{}).get('cap_diag'):
                    print(f'[CAP_FWD_REFRESH] RET_D cur_cap({cur_cap:.3f}) <= init_cap+thr({init_cap+thr:.3f})')
                return
            # 若已有 > initial cap 的可见点则无需刷新
            has_forward = False
            try:
                import numpy as _np
                if hasattr(self,'_segment_points') and self._segment_points:
                    for coll in self._segment_points:
                        try:
                            off = coll.get_offsets();
                            if off is None: continue
                            arr = _np.asarray(off, dtype=_np.float32)
                            if arr.size and (arr[:,0].max(initial=-1.0) > init_cap + 1e-6):
                                has_forward = True; break
                        except Exception:
                            pass
                if (not has_forward) and hasattr(self,'_browse_points_fallback') and self._browse_points_fallback is not None:
                    try:
                        off = self._browse_points_fallback.get_offsets()
                        if off is not None:
                            arr2 = _np.asarray(off, dtype=_np.float32)
                            if arr2.size and (arr2[:,0].max(initial=-1.0) > init_cap + 1e-6):
                                has_forward = True
                    except Exception:
                        pass
            except Exception:
                pass
            if has_forward:
                if getattr(self,'debug_flags',{}).get('cap_diag'):
                    print('[CAP_FWD_REFRESH] RET_E already has forward points')
                return
            last_ref = float(getattr(self, '_last_forward_refresh_cap', -1.0))
            if last_ref >= 0 and cur_cap <= last_ref + 1e-9:
                if getattr(self,'debug_flags',{}).get('cap_diag'):
                    print('[CAP_FWD_REFRESH] RET_F already refreshed at this cap')
                return
            # 收集 > initial_cap 的点（受cap过滤后仍应包含部分）
            new_t, new_p = [], []
            try:
                tbuf = list(getattr(self,'time_data', [])); pbuf = list(getattr(self,'pitch_data', []))
                if tbuf and pbuf and len(tbuf)==len(pbuf):
                    for tt, pp in zip(tbuf, pbuf):
                        if float(tt) > init_cap + 1e-6:
                            if float(tt) <= cur_cap + 1e-6:  # 只取当前cap内，保持一致
                                new_t.append(float(tt)); new_p.append(float(pp))
            except Exception:
                new_t, new_p = [], []
            if not new_t:
                if getattr(self,'debug_flags',{}).get('cap_diag'):
                    print('[CAP_FWD_REFRESH] RET_G no candidate points in buffer')
                return
            # 注入逻辑与方案C一致（不重复计算尺寸，如无size则自算）
            try:
                import numpy as _np
                arr = _np.column_stack((new_t, new_p))
                # 统一 cap 过滤（含分析/伴奏视觉前瞻），避免先行硬截断导致>cap新点迟显
                try:
                    arr = self._cap_filter_offsets_array(arr)
                except Exception:
                    pass
                if arr.size == 0:
                    if getattr(self,'debug_flags',{}).get('cap_diag'):
                        print('[CAP_FWD_REFRESH] RET_H filtered empty after cap filter')
                    return
                if getattr(self,'debug_flags',{}).get('cap_diag'):
                    print(f"[CAP_FWD_REFRESH] inject {arr.shape[0]} pts range=({arr[:,0].min():.3f},{arr[:,0].max():.3f}) init_cap={init_cap:.3f} cur_cap={cur_cap:.3f}")
                # 计算尺寸
                try:
                    if hasattr(self,'_segment_points') and self._segment_points:
                        s_existing = None
                        try: s_existing = self._segment_points[0].get_sizes()
                        except Exception: s_existing = None
                        if s_existing is not None and len(s_existing):
                            s_val = float(s_existing[0])
                        else:
                            base_w = float(getattr(self,'current_linewidth',0.6)); zoom = float(getattr(self,'zoom_level',1.0))
                            diameter = max(2.0, min(base_w * 3.6 / (0.6 if zoom < 1 else min(zoom,3.0)), 5.0))
                            s_val = diameter**2
                    else:
                        base_w = float(getattr(self,'current_linewidth',0.6)); zoom = float(getattr(self,'zoom_level',1.0))
                        diameter = max(2.0, min(base_w * 3.6 / (0.6 if zoom < 1 else min(zoom,3.0)), 5.0))
                        s_val = diameter**2
                except Exception:
                    s_val = 9.0
                detail_rgb = (1.0,1.0,1.0)
                pts = self.ax.scatter(arr[:,0], arr[:,1], s=s_val, color=detail_rgb, alpha=0.96, linewidths=0, edgecolors='none', zorder=14)
                try: pts.set_visible(True)
                except Exception: pass
                if not hasattr(self,'_segment_points') or self._segment_points is None:
                    self._segment_points = []
                self._segment_points.append(pts)
                self._last_forward_refresh_cap = float(cur_cap)
                try:
                    if hasattr(self,'canvas'): self.canvas.draw_idle()
                except Exception: pass
            except Exception:
                pass
        except Exception:
            pass

    def set_technique_panel_state(self, state: Optional[TechniquePanelState]) -> None:
        try:
            self._technique_panel_state = _normalize_technique_panel_state(state)
        except Exception:
            self._technique_panel_state = TechniquePanelState()
        try:
            self._update_technique_button_text_visualizer()
        except Exception:
            pass
        try:
            self._refresh_technique_artists(force=True)
        except Exception:
            pass

    def _update_technique_button_text_visualizer(self) -> None:
        try:
            btn = getattr(self, 'technique_recognition_btn', None)
            if btn is None:
                return
            state = getattr(self, '_technique_panel_state', None)
            cfg = getattr(state, 'config', None)
            enabled = bool(cfg is not None and getattr(cfg, 'enabled', False))
            selected = _normalize_technique_selection(getattr(state, 'selected_types', []) or [])
            count = len(selected) if enabled else 0
            if enabled and bool(getattr(state, 'last_source_frame_count', 0) or 0) > 0:
                base_text = '技巧分析'
            elif enabled:
                base_text = '技巧识别设置'
            else:
                base_text = '技巧识别'
            btn.setText(f"{base_text} ({count})" if count > 0 else base_text)
            if enabled and bool(getattr(state, 'last_source_frame_count', 0) or 0) > 0:
                btn.setToolTip('点击后可对当前普通模式数据做技巧分区与标注；录音完成后分析整段，暂停时分析当前已播放片段；按住 Ctrl 再点击可打开设置')
            else:
                btn.setToolTip('配置录音完成后的技巧识别项目与展示方式')
        except Exception:
            pass

    def _get_technique_external_infer_strategy_visualizer(self, strategy_override: Optional[str] = None) -> str:
        if strategy_override is not None:
            return _normalize_technique_external_infer_strategy(strategy_override, 'auto')
        try:
            current = getattr(self, '_technique_external_infer_strategy', None)
        except Exception:
            current = None
        return _normalize_technique_external_infer_strategy(current, _load_technique_external_infer_strategy_setting())

    def _translate_technique_external_reason(self, reason: str) -> str:
        mapping = {
            'manual_cpu': '设置项指定 CPU 优先',
            'manual_gpu': '设置项指定 GPU 优先',
            'env_force_cpu': '检测到强制 CPU 环境变量',
            'cuda_hidden': 'CUDA 设备已被环境变量隐藏',
            'local_torch_failure': '当前 GUI 进程本地 torch 导入失败',
            'recent_gpu_failure': '最近一次 GPU external 推理失败后已降级 CPU',
            'gpu_probe_unavailable': '未检测到可用 GPU',
            'gpu_probe_missing': '当前无法获取 GPU probe，保守降级 CPU',
            'gpu_available': '检测到 GPU 可用，可优先尝试 GPU',
        }
        return mapping.get(str(reason or '').strip(), str(reason or '').strip() or '未记录')

    def _resolve_effective_external_force_cpu_preference(self, preference_attr: str, *, strategy_override: Optional[str] = None) -> Tuple[bool, str]:
        strategy = self._get_technique_external_infer_strategy_visualizer(strategy_override)
        if strategy == 'cpu':
            return True, 'manual_cpu'
        if strategy == 'gpu':
            return False, 'manual_gpu'
        env_force_cpu = str(os.environ.get('MIND_ECHO_FORCE_CPU', '') or '').strip().lower()
        if env_force_cpu in {'1', 'true', 'yes', 'on'}:
            return True, 'env_force_cpu'
        if 'CUDA_VISIBLE_DEVICES' in os.environ and str(os.environ.get('CUDA_VISIBLE_DEVICES', '') or '').strip() == '':
            return True, 'cuda_hidden'
        if _get_local_torch_import_failure_reason():
            return True, 'local_torch_failure'
        backend_key = 'voice' if 'chest' in str(preference_attr or '') else 'mix'
        if bool(getattr(self, f'_external_{backend_key}_gpu_retry_blocked', False)):
            return True, 'recent_gpu_failure'
        try:
            gpu_accelerator = getattr(self, 'gpu_accelerator', None)
        except Exception:
            gpu_accelerator = None
        if gpu_accelerator is not None:
            try:
                if bool(gpu_accelerator.is_gpu_available()):
                    return False, 'gpu_available'
                return True, 'gpu_probe_unavailable'
            except Exception:
                pass
        return True, 'gpu_probe_missing'

    def _build_technique_backend_status_visualizer(self, strategy_override: Optional[str] = None) -> Tuple[str, str, bool]:
        voice_cpu, voice_reason = self._resolve_effective_external_force_cpu_preference('_prefer_chest_falsetto_external_cpu', strategy_override=strategy_override)
        mix_cpu, mix_reason = self._resolve_effective_external_force_cpu_preference('_prefer_mix_binary_external_cpu', strategy_override=strategy_override)
        strategy = self._get_technique_external_infer_strategy_visualizer(strategy_override)
        if voice_cpu == mix_cpu:
            order_text = 'CPU优先' if voice_cpu else 'GPU优先'
        else:
            order_text = f"音色{'CPU' if voice_cpu else 'GPU'}/混声{'CPU' if mix_cpu else 'GPU'}"
        failure_reason = _get_local_torch_import_failure_reason()
        external_only = bool(failure_reason)
        mode_text = 'external-only' if external_only else '自动'
        if strategy == 'auto':
            strategy_text = f'自动→{order_text}'
        elif strategy == 'cpu':
            strategy_text = '手动CPU优先'
        else:
            strategy_text = '手动GPU优先'
        short_text = f'技巧推理: {mode_text}/{strategy_text}'
        tooltip_lines = [
            f'当前技巧推理路径: {mode_text}',
            f'external 调度策略: {"自动" if strategy == "auto" else strategy_text.replace("手动", "")}',
            f'当前生效顺序: {order_text}',
        ]
        if strategy == 'auto':
            if voice_reason == mix_reason:
                tooltip_lines.append(f'自动策略依据: {self._translate_technique_external_reason(voice_reason)}')
            else:
                tooltip_lines.append(f'音色自动依据: {self._translate_technique_external_reason(voice_reason)}')
                tooltip_lines.append(f'混声自动依据: {self._translate_technique_external_reason(mix_reason)}')
        if external_only:
            tooltip_lines.append('本地 torch 当前不可用，已直接切到 external-only。')
            if failure_reason:
                tooltip_lines.append(f'原因: {failure_reason}')
            tooltip_lines.append('若已修复本地环境，可在设置中清除 external-only 缓存。')
        else:
            tooltip_lines.append('本地模型可用时优先使用本地；不可用时回退 external。')
        return short_text, '\n'.join(tooltip_lines), external_only

    def _update_technique_backend_status_visualizer(self) -> None:
        try:
            label = getattr(self, 'technique_backend_label', None)
            if label is None:
                return
            text, tooltip, external_only = self._build_technique_backend_status_visualizer()
            if str(label.text() or '') != text:
                label.setText(text)
            label.setToolTip(tooltip)
            if external_only:
                label.setStyleSheet(
                    'color: #FFF3D6; background: rgba(96, 52, 12, 0.95); border: 1px solid #E0A84F; border-radius: 6px; padding: 4px 8px; font-size: 10px; font-weight: 700;'
                )
            else:
                label.setStyleSheet(
                    'color: #D9F6EA; background: rgba(18, 58, 42, 0.92); border: 1px solid #3BAA7B; border-radius: 6px; padding: 4px 8px; font-size: 10px; font-weight: 700;'
                )
        except Exception:
            pass
        try:
            host = getattr(self, '_host_interface', None)
            refresher = getattr(host, '_refresh_technique_backend_status_panel', None) if host is not None else None
            if callable(refresher):
                refresher()
        except Exception:
            pass

    def open_technique_recognition_dialog(self):
        try:
            host = getattr(self, '_host_interface', None)
        except Exception:
            host = None
        if host is not None and hasattr(host, 'open_technique_recognition_dialog'):
            host.open_technique_recognition_dialog()

    def _reset_technique_tracking(self, *, clear_events: bool = False) -> None:
        try:
            self._technique_recent_frames.clear()
        except Exception:
            self._technique_recent_frames = deque(maxlen=240)
        self._technique_active_states = {}
        self._technique_last_frame_time = 0.0
        self._technique_last_frame_pitch = 0.0
        self._technique_last_frame_rate = 0.0
        if clear_events:
            try:
                self._technique_events.clear()
            except Exception:
                self._technique_events = deque(maxlen=240)
            self._clear_technique_artists()

    def _clear_technique_artists(self) -> None:
        for attr_name in ('_technique_region_artists', '_technique_label_artists', '_technique_edge_hint_artists'):
            artists = list(getattr(self, attr_name, []) or [])
            for artist in artists:
                try:
                    artist.remove()
                except Exception:
                    pass
            setattr(self, attr_name, [])
        summary_artist = getattr(self, '_technique_summary_artist', None)
        if summary_artist is not None:
            try:
                summary_artist.remove()
            except Exception:
                pass
        self._technique_summary_artist = None

    def _technique_enabled_for_current_mode(self) -> bool:
        try:
            state = getattr(self, '_technique_panel_state', None)
            cfg = getattr(state, 'config', None)
            if cfg is None or not bool(getattr(cfg, 'enabled', False)):
                return False
            mode_text = self.display_mode.currentText() if hasattr(self, 'display_mode') else '普通模式'
            if mode_text == '普通模式':
                return bool(getattr(cfg, 'show_in_normal_mode', True))
            if mode_text == '专业模式':
                return bool(getattr(cfg, 'show_in_professional_mode', True))
            return bool(getattr(cfg, 'show_in_normal_mode', True))
        except Exception:
            return False

    def _technique_type_selected(self, event_type: str) -> bool:
        try:
            selected = _normalize_technique_selection(getattr(getattr(self, '_technique_panel_state', None), 'selected_types', []) or [])
            return str(event_type or '') in selected
        except Exception:
            return False

    def _extract_frame_features_from_payload(self, pitch_data: dict, global_time: float) -> Optional[FrameFeatures]:
        features = pitch_data.get('_frame_features') if isinstance(pitch_data, dict) else None
        if isinstance(features, FrameFeatures):
            return features
        try:
            start_wall = float(getattr(self, 'start_time', 0.0) or 0.0)
            if float(global_time) > 1e8 and start_wall > 1e8:
                global_time = max(0.0, float(global_time) - start_wall)
        except Exception:
            pass
        try:
            note_info = pitch_data.get('note_info') or {}
        except Exception:
            note_info = {}
        try:
            mode_name = self.display_mode.currentText() if hasattr(self, 'display_mode') else '普通模式'
        except Exception:
            mode_name = '普通模式'
        try:
            return FrameFeatures(
                timeline_time=float(global_time),
                wall_time=float(time.time()),
                raw_frequency_hz=float(pitch_data.get('raw_frequency', 0.0) or 0.0),
                detected_frequency_hz=float(pitch_data.get('detected_frequency', pitch_data.get('frequency', 0.0)) or 0.0),
                display_frequency_hz=float(pitch_data.get('display_frequency', pitch_data.get('frequency', 0.0)) or 0.0),
                has_pitch=bool(pitch_data.get('has_pitch', False)),
                confidence=float(pitch_data.get('confidence', 0.0) or 0.0),
                audio_rms=float(pitch_data.get('audio_rms', 0.0) or 0.0),
                note_name=note_info.get('note_name'),
                octave=note_info.get('octave'),
                midi_number=note_info.get('midi_number'),
                cents=note_info.get('cents'),
                zcr=pitch_data.get('zcr'),
                fast_change=bool(pitch_data.get('_fast_change', False)),
                harmonic_candidates=list(pitch_data.get('harmonic_candidates', []) or []),
                mid_high_ratio=pitch_data.get('mid_high_ratio'),
                hm_over_hh=pitch_data.get('hm_over_hh'),
                spectral_tilt=pitch_data.get('spectral_tilt'),
                tonal_hum=pitch_data.get('tonal_hum'),
                breath_detect_hint=bool(pitch_data.get('breath_detect_hint', False)),
                vibrato_info=dict(pitch_data.get('vibrato_info', {}) or {}),
                mode_name=str(mode_name),
                preview_only=bool(pitch_data.get('_preview_only', False)),
                source_flags={},
            )
        except Exception:
            return None

    def _technique_context_pitch(self, features: Optional[FrameFeatures], *, min_conf: float = 0.40) -> Optional[float]:
        if features is None:
            return None
        try:
            if (not bool(getattr(features, 'has_pitch', False))) or float(getattr(features, 'confidence', 0.0) or 0.0) < float(min_conf):
                return None
            pitch_val = float(getattr(features, 'detected_frequency_hz', 0.0) or 0.0)
            return pitch_val if pitch_val > 0.0 else None
        except Exception:
            return None

    def _breath_airflow_evidence(self, features: Optional[FrameFeatures]) -> float:
        if features is None:
            return 0.0
        try:
            rms = float(getattr(features, 'audio_rms', 0.0) or 0.0)
        except Exception:
            rms = 0.0
        try:
            zcr = float(getattr(features, 'zcr', 0.0) or 0.0)
        except Exception:
            zcr = 0.0
        try:
            hm_over_hh = float(getattr(features, 'hm_over_hh', 1.0) or 1.0)
        except Exception:
            hm_over_hh = 1.0
        try:
            mid_high_ratio = float(getattr(features, 'mid_high_ratio', 1.0) or 1.0)
        except Exception:
            mid_high_ratio = 1.0
        try:
            tonal_hum = bool(getattr(features, 'tonal_hum', False))
        except Exception:
            tonal_hum = False
        try:
            confidence = float(getattr(features, 'confidence', 0.0) or 0.0)
        except Exception:
            confidence = 0.0
        evidence = 0.0
        if bool(getattr(features, 'breath_detect_hint', False)):
            evidence += 0.42
        if 0.00018 <= rms <= 0.0058:
            evidence += 0.10
        if zcr >= 0.16:
            evidence += min(0.22, ((zcr - 0.16) / 0.18) * 0.22)
        if hm_over_hh >= 1.12:
            evidence += min(0.14, ((hm_over_hh - 1.12) / 0.60) * 0.14)
        if tonal_hum:
            evidence -= 0.28
        if bool(getattr(features, 'has_pitch', False)) and confidence >= 0.40:
            evidence -= 0.24
        if mid_high_ratio >= 2.05 and zcr <= 0.12:
            evidence -= 0.14
        return max(0.0, min(1.0, evidence))

    def _breath_has_voiced_continuity(self, features: Optional[FrameFeatures]) -> bool:
        if features is None:
            return False
        try:
            if bool(getattr(features, 'has_pitch', False)):
                freq_val = float(getattr(features, 'detected_frequency_hz', 0.0) or 0.0)
                conf_val = float(getattr(features, 'confidence', 0.0) or 0.0)
                if freq_val > 0.0 and conf_val >= 0.34:
                    return True
        except Exception:
            pass
        try:
            voiced_score = float(getattr(features, 'voiced_score', 0.0) or 0.0)
        except Exception:
            voiced_score = 0.0
        try:
            zcr = float(getattr(features, 'zcr', 0.0) or 0.0)
        except Exception:
            zcr = 0.0
        try:
            mid_high_ratio = float(getattr(features, 'mid_high_ratio', 1.0) or 1.0)
        except Exception:
            mid_high_ratio = 1.0
        try:
            tonal_hum = bool(getattr(features, 'tonal_hum', False))
        except Exception:
            tonal_hum = False
        return (not tonal_hum) and voiced_score >= 0.52 and zcr <= 0.13 and mid_high_ratio >= 1.45

    def _breath_pitch_intrusion_bridge(self, features: Optional[FrameFeatures], breath_state: Optional[Dict[str, Any]] = None) -> bool:
        if features is None:
            return False
        try:
            if not bool(getattr(features, 'has_pitch', False)):
                return False
        except Exception:
            return False
        try:
            confidence = float(getattr(features, 'confidence', 0.0) or 0.0)
        except Exception:
            confidence = 0.0
        try:
            rms = float(getattr(features, 'audio_rms', 0.0) or 0.0)
        except Exception:
            rms = 0.0
        try:
            zcr = float(getattr(features, 'zcr', 0.0) or 0.0)
        except Exception:
            zcr = 0.0
        try:
            tonal_hum = bool(getattr(features, 'tonal_hum', False))
        except Exception:
            tonal_hum = False
        airflow_evidence = self._breath_airflow_evidence(features)
        if tonal_hum:
            return False
        if confidence >= 0.68 and not (rms <= 0.0038 and airflow_evidence >= 0.34):
            return False
        if rms > 0.0048:
            return False
        if airflow_evidence < 0.24 and zcr < 0.14:
            return False
        if breath_state:
            try:
                last_time = float(breath_state.get('last_time', 0.0) or 0.0)
                now_t = float(getattr(features, 'timeline_time', 0.0) or 0.0)
                if last_time > 0.0 and (now_t - last_time) > 0.12:
                    return False
            except Exception:
                pass
        return True

    def _breath_pitch_like_candidate(self, features: Optional[FrameFeatures]) -> bool:
        if features is None:
            return False
        try:
            if not bool(getattr(features, 'has_pitch', False)):
                return False
        except Exception:
            return False
        try:
            confidence = float(getattr(features, 'confidence', 0.0) or 0.0)
        except Exception:
            confidence = 0.0
        try:
            rms = float(getattr(features, 'audio_rms', 0.0) or 0.0)
        except Exception:
            rms = 0.0
        try:
            semi_delta = float(getattr(features, 'semitone_delta_prev', 0.0) or 0.0)
        except Exception:
            semi_delta = 0.0
        try:
            continuity = float(getattr(features, 'continuity_score', 0.0) or 0.0)
        except Exception:
            continuity = 0.0
        airflow_evidence = self._breath_airflow_evidence(features)
        voiced_continuity = self._breath_has_voiced_continuity(features)
        if voiced_continuity:
            return False
        if not self._breath_pitch_intrusion_bridge(features, None):
            return False
        if confidence > 0.64 and airflow_evidence < 0.46:
            return False
        unstable_pitch = bool(semi_delta >= 2.2 or continuity <= 0.40 or bool(getattr(features, 'fast_change', False)))
        return airflow_evidence >= 0.34 and rms <= 0.0048 and unstable_pitch

    def _breath_can_extend_silence(self, features: Optional[FrameFeatures], breath_state: Optional[Dict[str, Any]]) -> bool:
        if features is None or not breath_state:
            return False
        try:
            if bool(getattr(features, 'has_pitch', False)):
                return False
        except Exception:
            return False
        try:
            tonal_hum = bool(getattr(features, 'tonal_hum', False))
        except Exception:
            tonal_hum = False
        if tonal_hum:
            return False
        try:
            rms = float(getattr(features, 'audio_rms', 0.0) or 0.0)
        except Exception:
            rms = 0.0
        try:
            zcr = float(getattr(features, 'zcr', 0.0) or 0.0)
        except Exception:
            zcr = 0.0
        try:
            now_t = float(getattr(features, 'timeline_time', 0.0) or 0.0)
            last_t = float(breath_state.get('last_time', 0.0) or 0.0)
        except Exception:
            now_t, last_t = 0.0, 0.0
        if last_t > 0.0 and (now_t - last_t) > 0.22:
            return False
        try:
            breath_peak = float(breath_state.get('breath_score_peak', 0.0) or 0.0)
        except Exception:
            breath_peak = 0.0
        try:
            suppressed = int(breath_state.get('suppressed_pitch_frames', 0) or 0)
        except Exception:
            suppressed = 0
        try:
            pre_pitch = float(breath_state.get('pre_pitch_hz', 0.0) or 0.0)
        except Exception:
            pre_pitch = 0.0
        return rms <= 0.00160 and (zcr >= 0.05 or rms <= 0.00042) and (breath_peak >= 0.40 or suppressed >= 1) and pre_pitch > 0.0

    def _breath_gap_bridgeable(self, left_event: Optional[BaseTechniqueEvent], right_event: Optional[BaseTechniqueEvent]) -> bool:
        if left_event is None or right_event is None:
            return False
        try:
            gap_start = float(getattr(left_event, 'end_time', 0.0) or 0.0)
            gap_end = float(getattr(right_event, 'start_time', 0.0) or 0.0)
        except Exception:
            return False
        gap = gap_end - gap_start
        if gap <= 0.0:
            return True
        if gap > 0.62:
            return False
        try:
            frames = list(getattr(self, '_technique_recent_frames', []) or [])
        except Exception:
            frames = []
        if not frames:
            return gap <= 0.28
        sparse_pitch = 0
        silence_like = 0
        solid_voiced = 0
        tonal_count = 0
        considered = 0
        breath_seed = {
            'last_time': gap_start,
            'breath_score_peak': max(
                float(getattr(left_event, 'breath_score_peak', 0.0) or 0.0),
                float(getattr(right_event, 'breath_score_peak', 0.0) or 0.0),
                0.52,
            ),
            'suppressed_pitch_frames': max(
                int(getattr(left_event, 'suppressed_pitch_frames', 0) or 0),
                int(getattr(right_event, 'suppressed_pitch_frames', 0) or 0),
                2,
            ),
            'pre_pitch_hz': float(getattr(left_event, 'pre_pitch_hz', 0.0) or 0.0),
        }
        for item in frames:
            try:
                t_val = float(getattr(item, 'timeline_time', 0.0) or 0.0)
            except Exception:
                continue
            if t_val <= gap_start or t_val >= gap_end:
                continue
            considered += 1
            try:
                tonal_hum = bool(getattr(item, 'tonal_hum', False))
            except Exception:
                tonal_hum = False
            if tonal_hum:
                tonal_count += 1
                continue
            if self._breath_has_voiced_continuity(item):
                try:
                    conf = float(getattr(item, 'confidence', 0.0) or 0.0)
                    rms = float(getattr(item, 'audio_rms', 0.0) or 0.0)
                except Exception:
                    conf, rms = 0.0, 0.0
                if conf >= 0.46 and rms >= 0.0028:
                    solid_voiced += 1
                    continue
            if self._breath_pitch_like_candidate(item) or self._breath_pitch_intrusion_bridge(item, None):
                sparse_pitch += 1
                continue
            if self._breath_can_extend_silence(item, breath_seed):
                silence_like += 1
                continue
            try:
                rms = float(getattr(item, 'audio_rms', 0.0) or 0.0)
            except Exception:
                rms = 0.0
            if rms <= 0.00055 and self._breath_airflow_evidence(item) >= 0.18:
                silence_like += 1
        if considered <= 0:
            return gap <= 0.28
        if solid_voiced >= 2:
            return False
        if tonal_count >= max(2, considered // 2):
            return False
        bridge_units = sparse_pitch + silence_like
        return bridge_units >= max(1, int(round(considered * 0.55)))

    def _estimate_feature_scores(self, features: FrameFeatures) -> None:
        try:
            if features.voiced_score is None:
                voiced = 0.0
                if features.has_pitch:
                    voiced += 0.55
                voiced += min(0.25, max(0.0, float(features.confidence)) * 0.25)
                voiced += min(0.20, max(0.0, float(features.audio_rms)) / 0.010 * 0.20)
                features.voiced_score = max(0.0, min(1.0, voiced))
        except Exception:
            pass
        try:
            if features.breath_score is None:
                breath = self._breath_airflow_evidence(features) * 0.72
                if not features.has_pitch:
                    breath += 0.24
                rms = max(0.0, float(features.audio_rms or 0.0))
                if 0.00030 <= rms <= 0.0062:
                    breath += 0.10
                if self._breath_has_voiced_continuity(features):
                    breath -= 0.20
                features.breath_score = max(0.0, min(1.0, breath))
        except Exception:
            pass
        try:
            if features.noise_score is None:
                noise = 0.0
                if not features.has_pitch and float(features.audio_rms or 0.0) < 0.0004:
                    noise += 0.50
                features.noise_score = max(0.0, min(1.0, noise))
        except Exception:
            pass

    def _update_feature_dynamics(self, features: FrameFeatures) -> None:
        try:
            prev_t = float(getattr(self, '_technique_last_frame_time', 0.0) or 0.0)
            prev_f = float(getattr(self, '_technique_last_frame_pitch', 0.0) or 0.0)
            prev_rate = float(getattr(self, '_technique_last_frame_rate', 0.0) or 0.0)
        except Exception:
            prev_t, prev_f, prev_rate = 0.0, 0.0, 0.0
        try:
            cur_f = float(features.detected_frequency_hz or 0.0)
        except Exception:
            cur_f = 0.0
        try:
            dt = float(features.timeline_time) - prev_t if prev_t > 0.0 else 0.0
        except Exception:
            dt = 0.0
        try:
            if prev_f > 0.0 and cur_f > 0.0:
                semi = abs(12.0 * math.log2(max(cur_f, 1e-9) / max(prev_f, 1e-9)))
                features.semitone_delta_prev = semi
                if dt > 1e-6:
                    rate = semi / dt
                    features.semitone_rate = rate
                    features.semitone_accel = (rate - prev_rate) / dt if prev_t > 0.0 else 0.0
                    features.continuity_score = max(0.0, min(1.0, 1.0 - semi / 6.0))
                    self._technique_last_frame_rate = float(rate)
                else:
                    features.semitone_rate = 0.0
                    features.semitone_accel = 0.0
            else:
                features.semitone_delta_prev = None
                features.semitone_rate = 0.0
                features.semitone_accel = 0.0
        except Exception:
            pass
        self._technique_last_frame_time = float(features.timeline_time or 0.0)
        if cur_f > 0.0:
            self._technique_last_frame_pitch = cur_f

    def _append_technique_event(self, event: BaseTechniqueEvent) -> None:
        try:
            cfg = getattr(getattr(self, '_technique_panel_state', None), 'config', None)
            merge_gap = float(getattr(cfg, 'merge_gap_s', 0.12) or 0.12) if cfg is not None else 0.12
        except Exception:
            merge_gap = 0.12
        try:
            if self._technique_events:
                last_event = self._technique_events[-1]
                if (
                    getattr(last_event, 'event_type', None) == getattr(event, 'event_type', None)
                    and (float(event.start_time) - float(last_event.end_time)) <= merge_gap
                ):
                    last_event.end_time = max(float(last_event.end_time), float(event.end_time))
                    last_event.center_time = 0.5 * (float(last_event.start_time) + float(last_event.end_time))
                    last_event.duration = max(0.0, float(last_event.end_time) - float(last_event.start_time))
                    last_event.confidence = max(float(last_event.confidence), float(event.confidence))
                    last_event.strength = max(float(last_event.strength), float(event.strength))
                    return
        except Exception:
            pass
        try:
            self._technique_events.append(event)
        except Exception:
            pass

    def _finalize_active_event(self, event_type: str, now_t: float, *, final_features: Optional[FrameFeatures] = None) -> None:
        state = dict(getattr(self, '_technique_active_states', {}).get(event_type, {}) or {})
        if not state:
            return
        try:
            cfg = getattr(getattr(self, '_technique_panel_state', None), 'config', None)
        except Exception:
            cfg = None
        start_time = float(state.get('start_time', now_t) or now_t)
        end_time = max(float(state.get('last_time', now_t) or now_t), start_time)
        if event_type == 'breath':
            try:
                end_time = max(end_time, self._extend_breath_region_from_context(end_time, backward=False, limit_s=0.24))
            except Exception:
                pass
        duration = max(0.0, end_time - start_time)
        if event_type == 'breath':
            min_dur = float(getattr(cfg, 'min_breath_duration_s', 0.06) or 0.06) if cfg is not None else 0.06
            if duration < min_dur:
                self._technique_active_states.pop(event_type, None)
                return
            post_pitch = self._technique_context_pitch(final_features, min_conf=0.40)
            event = BreathEvent(
                event_type='breath',
                start_time=start_time,
                end_time=end_time,
                confidence=float(state.get('confidence', 0.62) or 0.62),
                strength=float(state.get('strength', 0.60) or 0.60),
                center_time=0.5 * (start_time + end_time),
                duration=duration,
                source_layer='state_machine',
                display_label='换气',
                display_color='#6EC6FF',
                subtype=str(state.get('subtype', 'normal_breath') or 'normal_breath'),
                mean_rms=float(state.get('mean_rms', 0.0) or 0.0),
                mean_zcr=state.get('mean_zcr'),
                breath_score_peak=state.get('breath_score_peak'),
                pre_pitch_hz=state.get('pre_pitch_hz'),
                post_pitch_hz=post_pitch,
                suppressed_pitch_frames=int(state.get('suppressed_pitch_frames', 0) or 0),
            )
            self._append_technique_event(event)
        elif event_type == 'slide':
            min_dur = float(getattr(cfg, 'min_slide_duration_s', 0.08) or 0.08) if cfg is not None else 0.08
            if duration < min_dur:
                self._technique_active_states.pop(event_type, None)
                return
            start_pitch = float(state.get('start_pitch_hz', 0.0) or 0.0)
            end_pitch = float(state.get('last_pitch_hz', start_pitch) or start_pitch)
            try:
                span = abs(12.0 * math.log2(max(end_pitch, 1e-9) / max(start_pitch, 1e-9))) if start_pitch > 0 and end_pitch > 0 else 0.0
            except Exception:
                span = 0.0
            event = SlideEvent(
                event_type='slide',
                start_time=start_time,
                end_time=end_time,
                confidence=float(state.get('confidence', 0.60) or 0.60),
                strength=float(state.get('strength', 0.58) or 0.58),
                center_time=0.5 * (start_time + end_time),
                duration=duration,
                source_layer='state_machine',
                display_label='滑音',
                display_color='#FFB74D',
                direction=str(state.get('direction', 'mixed') or 'mixed'),
                start_pitch_hz=start_pitch,
                end_pitch_hz=end_pitch,
                pitch_span_semitones=span,
                mean_semitone_rate=state.get('mean_rate'),
                peak_semitone_rate=state.get('peak_rate'),
                smoothness_score=state.get('smoothness_score'),
                continuity_score=state.get('continuity_score'),
            )
            self._append_technique_event(event)
        elif event_type == 'vibrato':
            min_dur = float(getattr(cfg, 'min_vibrato_duration_s', 0.18) or 0.18) if cfg is not None else 0.18
            if duration < min_dur:
                self._technique_active_states.pop(event_type, None)
                return
            event = VibratoEvent(
                event_type='vibrato',
                start_time=start_time,
                end_time=end_time,
                confidence=float(state.get('confidence', 0.68) or 0.68),
                strength=float(state.get('strength', 0.66) or 0.66),
                center_time=0.5 * (start_time + end_time),
                duration=duration,
                source_layer='pattern',
                display_label='颤音',
                display_color='#BA68C8',
                rate_hz=state.get('rate_hz'),
                depth_hz=state.get('depth_hz'),
                depth_cents=state.get('depth_cents'),
                regularity_score=state.get('regularity_score'),
                stability_score=state.get('stability_score'),
                base_pitch_hz=state.get('base_pitch_hz'),
            )
            self._append_technique_event(event)
        elif event_type == 'register_transition':
            min_dur = float(getattr(cfg, 'min_register_transition_s', 0.10) or 0.10) if cfg is not None else 0.10
            if duration < min_dur:
                self._technique_active_states.pop(event_type, None)
                return
            event = RegisterTransitionEvent(
                event_type='register_transition',
                start_time=start_time,
                end_time=end_time,
                confidence=float(state.get('confidence', 0.56) or 0.56),
                strength=float(state.get('strength', 0.54) or 0.54),
                center_time=0.5 * (start_time + end_time),
                duration=duration,
                source_layer='state_machine',
                display_label='换声区',
                display_color='#EF9A9A',
                subtype=str(state.get('subtype', 'uncertain') or 'uncertain'),
                pre_register_state=state.get('pre_register_state'),
                post_register_state=state.get('post_register_state'),
                center_pitch_hz=state.get('center_pitch_hz'),
                span_semitones=state.get('span_semitones'),
                pitch_continuity_score=state.get('continuity_score'),
                harmonic_shift_score=state.get('harmonic_shift_score'),
                timbre_shift_score=state.get('timbre_shift_score'),
            )
            self._append_technique_event(event)
        elif event_type == 'breathy_phonation':
            min_dur = float(getattr(cfg, 'min_breathy_duration_s', 0.10) or 0.10) if cfg is not None else 0.10
            if duration < min_dur:
                self._technique_active_states.pop(event_type, None)
                return
            event = BreathyPhonationEvent(
                event_type='breathy_phonation',
                start_time=start_time,
                end_time=end_time,
                confidence=float(state.get('confidence', 0.57) or 0.57),
                strength=float(state.get('strength', 0.52) or 0.52),
                center_time=0.5 * (start_time + end_time),
                duration=duration,
                source_layer='state_machine',
                display_label='气声',
                display_color='#80CBC4',
                mean_rms=state.get('mean_rms'),
                voiced_soft_score=state.get('voiced_soft_score'),
                breathy_score=state.get('breathy_score'),
            )
            self._append_technique_event(event)
        self._technique_active_states.pop(event_type, None)

    def _ingest_technique_frame(self, features: FrameFeatures) -> None:
        self._estimate_feature_scores(features)
        self._update_feature_dynamics(features)
        try:
            self._technique_recent_frames.append(features)
        except Exception:
            return

        breath_state = self._technique_active_states.get('breath')
        pre_pitch = None
        has_recent_voiced_context = False
        for item in reversed(list(self._technique_recent_frames)[:-1]):
            try:
                delta_t = float(features.timeline_time) - float(getattr(item, 'timeline_time', 0.0) or 0.0)
                if delta_t > 0.52:
                    break
                item_pitch = self._technique_context_pitch(item, min_conf=0.40)
                if item_pitch is not None:
                    pre_pitch = item_pitch
                    has_recent_voiced_context = True
                    break
            except Exception:
                continue
        try:
            breath_score_val = float(features.breath_score or 0.0)
        except Exception:
            breath_score_val = 0.0
        try:
            noise_score_val = float(features.noise_score or 0.0)
        except Exception:
            noise_score_val = 0.0
        try:
            voiced_score_val = float(features.voiced_score or 0.0)
        except Exception:
            voiced_score_val = 0.0
        try:
            rms_val = float(features.audio_rms or 0.0)
        except Exception:
            rms_val = 0.0
        airflow_evidence = self._breath_airflow_evidence(features)
        voiced_continuity = self._breath_has_voiced_continuity(features)
        breath_pitch_like = self._breath_pitch_like_candidate(features)
        silent_gap_candidate = bool(
            (not bool(getattr(features, 'has_pitch', False)))
            and has_recent_voiced_context
            and (not voiced_continuity)
            and (not bool(getattr(features, 'tonal_hum', False)))
            and 0.00008 <= rms_val <= 0.00160
            and (airflow_evidence >= 0.18 or breath_score_val >= 0.18 or getattr(features, 'zcr', 0.0) >= 0.05)
        )
        try:
            breath_core = bool(
                (
                    (
                        (not features.has_pitch)
                        and airflow_evidence >= 0.52
                        and breath_score_val >= 0.44
                        and noise_score_val <= 0.78
                        and voiced_score_val <= 0.42
                        and (not voiced_continuity)
                        and (not bool(getattr(features, 'tonal_hum', False)))
                        and 0.00018 <= rms_val <= 0.00540
                    )
                    or breath_pitch_like
                    or silent_gap_candidate
                )
            )
        except Exception:
            breath_core = False
        breath_candidate = bool(
            self._technique_type_selected('breath')
            and breath_core
            and has_recent_voiced_context
        )
        if breath_candidate:
            if breath_state is None:
                start_time = float(features.timeline_time)
                try:
                    start_time = self._extend_breath_region_from_context(start_time, backward=True, limit_s=0.20)
                except Exception:
                    start_time = float(features.timeline_time)
                self._technique_active_states['breath'] = {
                    'start_time': start_time,
                    'last_time': float(features.timeline_time),
                    'mean_rms': float(features.audio_rms or 0.0),
                    'mean_zcr': float(features.zcr or 0.0) if getattr(features, 'zcr', None) is not None else None,
                    'breath_score_peak': float(features.breath_score or 0.0),
                    'pre_pitch_hz': pre_pitch,
                    'suppressed_pitch_frames': 0 if breath_pitch_like else 1,
                    'confidence': max(0.56 if silent_gap_candidate else 0.60, min(0.90, 0.44 + airflow_evidence * 0.34 + breath_score_val * 0.14)),
                    'strength': max(0.54 if silent_gap_candidate else 0.58, min(0.90, 0.40 + max(airflow_evidence, breath_score_val) * 0.40)),
                }
            else:
                breath_state['last_time'] = float(features.timeline_time)
                breath_state['mean_rms'] = 0.82 * float(breath_state.get('mean_rms', features.audio_rms) or features.audio_rms) + 0.18 * float(features.audio_rms or 0.0)
                if getattr(features, 'zcr', None) is not None:
                    prev_mean_zcr = breath_state.get('mean_zcr')
                    if prev_mean_zcr is None:
                        breath_state['mean_zcr'] = float(features.zcr or 0.0)
                    else:
                        breath_state['mean_zcr'] = 0.82 * float(prev_mean_zcr or 0.0) + 0.18 * float(features.zcr or 0.0)
                breath_state['breath_score_peak'] = max(float(breath_state.get('breath_score_peak', 0.0) or 0.0), float(max(features.breath_score or 0.0, airflow_evidence)))
                if not features.has_pitch:
                    breath_state['suppressed_pitch_frames'] = int(breath_state.get('suppressed_pitch_frames', 0) or 0) + 1
                elif breath_pitch_like:
                    breath_state['suppressed_pitch_frames'] = int(breath_state.get('suppressed_pitch_frames', 0) or 0) + 1
        elif breath_state is not None and self._breath_pitch_intrusion_bridge(features, breath_state):
            breath_state['last_time'] = float(features.timeline_time)
            breath_state['mean_rms'] = 0.86 * float(breath_state.get('mean_rms', features.audio_rms) or features.audio_rms) + 0.14 * float(features.audio_rms or 0.0)
            if getattr(features, 'zcr', None) is not None:
                prev_mean_zcr = breath_state.get('mean_zcr')
                if prev_mean_zcr is None:
                    breath_state['mean_zcr'] = float(features.zcr or 0.0)
                else:
                    breath_state['mean_zcr'] = 0.86 * float(prev_mean_zcr or 0.0) + 0.14 * float(features.zcr or 0.0)
            breath_state['breath_score_peak'] = max(
                float(breath_state.get('breath_score_peak', 0.0) or 0.0),
                float(max(features.breath_score or 0.0, self._breath_airflow_evidence(features)))
            )
            breath_state['suppressed_pitch_frames'] = int(breath_state.get('suppressed_pitch_frames', 0) or 0) + 1
        elif breath_state is not None and (not bool(getattr(features, 'has_pitch', False))) and (not voiced_continuity) and (not bool(getattr(features, 'tonal_hum', False))):
            try:
                last_time = float(breath_state.get('last_time', 0.0) or 0.0)
            except Exception:
                last_time = 0.0
            if float(features.timeline_time) - last_time <= 0.14 and (
                airflow_evidence >= 0.34
                or (0.00010 <= float(features.audio_rms or 0.0) <= 0.00036 and breath_score_val >= 0.30)
                or self._breath_can_extend_silence(features, breath_state)
            ):
                breath_state['last_time'] = float(features.timeline_time)
                breath_state['mean_rms'] = 0.86 * float(breath_state.get('mean_rms', features.audio_rms) or features.audio_rms) + 0.14 * float(features.audio_rms or 0.0)
                if getattr(features, 'zcr', None) is not None:
                    prev_mean_zcr = breath_state.get('mean_zcr')
                    if prev_mean_zcr is None:
                        breath_state['mean_zcr'] = float(features.zcr or 0.0)
                    else:
                        breath_state['mean_zcr'] = 0.86 * float(prev_mean_zcr or 0.0) + 0.14 * float(features.zcr or 0.0)
                breath_state['breath_score_peak'] = max(float(breath_state.get('breath_score_peak', 0.0) or 0.0), float(max(features.breath_score or 0.0, airflow_evidence)))
                breath_state['suppressed_pitch_frames'] = int(breath_state.get('suppressed_pitch_frames', 0) or 0) + 1
        elif breath_state is not None:
            self._finalize_active_event('breath', float(features.timeline_time), final_features=features)

        slide_state = self._technique_active_states.get('slide')
        try:
            voiced_score = float(features.voiced_score or 0.0)
        except Exception:
            voiced_score = 0.0
        try:
            semitone_delta_prev = float(features.semitone_delta_prev or 0.0)
        except Exception:
            semitone_delta_prev = 0.0
        try:
            semitone_rate = float(features.semitone_rate or 0.0)
        except Exception:
            semitone_rate = 0.0
        try:
            semitone_accel = abs(float(features.semitone_accel or 0.0))
        except Exception:
            semitone_accel = 0.0
        slide_candidate = bool(
            self._technique_type_selected('slide')
            and features.has_pitch
            and bool(features.fast_change)
            and (breath_state is None)
            and voiced_score >= 0.66
            and float(features.confidence or 0.0) >= 0.56
            and float(features.audio_rms or 0.0) >= 0.00075
            and 0.55 <= semitone_delta_prev <= 3.20
            and 3.2 <= semitone_rate <= 18.0
            and semitone_accel <= 22.0
            and float(features.continuity_score or 0.0) >= 0.28
            and float(features.breath_score or 0.0) <= 0.30
        )
        if slide_candidate:
            direction = 'up'
            try:
                prev_pitch = float(getattr(self, '_technique_last_frame_pitch', 0.0) or 0.0)
                if prev_pitch > 0.0 and float(features.detected_frequency_hz or 0.0) < prev_pitch:
                    direction = 'down'
            except Exception:
                direction = 'mixed'
            if slide_state is None:
                self._technique_active_states['slide'] = {
                    'start_time': float(features.timeline_time),
                    'last_time': float(features.timeline_time),
                    'start_pitch_hz': float(features.detected_frequency_hz or 0.0),
                    'last_pitch_hz': float(features.detected_frequency_hz or 0.0),
                    'direction': direction,
                    'peak_rate': float(features.semitone_rate or 0.0),
                    'mean_rate': float(features.semitone_rate or 0.0),
                    'smoothness_score': max(0.0, min(1.0, 1.0 - float(features.semitone_accel or 0.0) / 20.0)),
                    'continuity_score': float(features.continuity_score or 0.0),
                    'confidence': max(0.56, min(0.86, 0.50 + float(features.confidence or 0.0) * 0.35)),
                    'strength': max(0.52, min(0.88, float(features.semitone_rate or 0.0) / 8.0)),
                }
            else:
                if str(slide_state.get('direction', direction)) != direction:
                    slide_state['direction'] = 'mixed'
                slide_state['last_time'] = float(features.timeline_time)
                slide_state['last_pitch_hz'] = float(features.detected_frequency_hz or 0.0)
                slide_state['peak_rate'] = max(float(slide_state.get('peak_rate', 0.0) or 0.0), float(features.semitone_rate or 0.0))
                slide_state['mean_rate'] = 0.78 * float(slide_state.get('mean_rate', 0.0) or 0.0) + 0.22 * float(features.semitone_rate or 0.0)
                slide_state['continuity_score'] = max(float(slide_state.get('continuity_score', 0.0) or 0.0), float(features.continuity_score or 0.0))
        elif slide_state is not None:
            self._finalize_active_event('slide', float(features.timeline_time), final_features=features)

        vibrato_state = self._technique_active_states.get('vibrato')
        vibrato_info = dict(features.vibrato_info or {})
        vibrato_candidate = bool(
            self._technique_type_selected('vibrato')
            and (not bool(getattr(self, '_disable_realtime_vibrato_detection', False)))
            and vibrato_info.get('has_vibrato')
        )
        if vibrato_candidate:
            if vibrato_state is None:
                self._technique_active_states['vibrato'] = {
                    'start_time': float(features.timeline_time),
                    'last_time': float(features.timeline_time),
                    'rate_hz': float(vibrato_info.get('rate', 0.0) or 0.0),
                    'depth_hz': float(vibrato_info.get('depth', 0.0) or 0.0),
                    'base_pitch_hz': float(features.detected_frequency_hz or 0.0),
                    'confidence': max(0.62, min(0.90, 0.55 + float(features.confidence or 0.0) * 0.35)),
                    'strength': max(0.60, min(0.92, float(vibrato_info.get('depth', 0.0) or 0.0) / 8.0)),
                    'regularity_score': 0.68,
                    'stability_score': float(features.continuity_score or 0.0),
                    'depth_cents': float(vibrato_info.get('depth', 0.0) or 0.0) * 100.0 / max(float(features.detected_frequency_hz or 1.0), 1.0),
                }
            else:
                vibrato_state['last_time'] = float(features.timeline_time)
                vibrato_state['rate_hz'] = 0.72 * float(vibrato_state.get('rate_hz', 0.0) or 0.0) + 0.28 * float(vibrato_info.get('rate', 0.0) or 0.0)
                vibrato_state['depth_hz'] = max(float(vibrato_state.get('depth_hz', 0.0) or 0.0), float(vibrato_info.get('depth', 0.0) or 0.0))
        elif vibrato_state is not None:
            self._finalize_active_event('vibrato', float(features.timeline_time), final_features=features)

        breathy_state = self._technique_active_states.get('breathy_phonation')
        breathy_candidate = bool(
            self._technique_type_selected('breathy_phonation')
            and features.has_pitch
            and 0.00045 <= float(features.audio_rms or 0.0) <= 0.0026
            and float(features.confidence or 0.0) <= 0.86
            and (float(features.breath_score or 0.0) >= 0.22 or bool(features.breath_detect_hint))
        )
        if breathy_candidate:
            if breathy_state is None:
                self._technique_active_states['breathy_phonation'] = {
                    'start_time': float(features.timeline_time),
                    'last_time': float(features.timeline_time),
                    'mean_rms': float(features.audio_rms or 0.0),
                    'voiced_soft_score': float(features.voiced_score or 0.0),
                    'breathy_score': max(float(features.breath_score or 0.0), 0.32),
                    'confidence': 0.58,
                    'strength': max(0.48, float(features.breath_score or 0.48)),
                }
            else:
                breathy_state['last_time'] = float(features.timeline_time)
                breathy_state['mean_rms'] = 0.82 * float(breathy_state.get('mean_rms', features.audio_rms) or features.audio_rms) + 0.18 * float(features.audio_rms or 0.0)
                breathy_state['breathy_score'] = max(float(breathy_state.get('breathy_score', 0.0) or 0.0), float(features.breath_score or 0.0))
        elif breathy_state is not None:
            self._finalize_active_event('breathy_phonation', float(features.timeline_time), final_features=features)

        register_state = self._technique_active_states.get('register_transition')
        register_candidate = bool(
            self._technique_type_selected('register_transition')
            and features.has_pitch
            and bool(features.fast_change)
            and len(list(features.harmonic_candidates or [])) >= 2
            and 0.75 <= float(features.semitone_delta_prev or 0.0) <= 4.5
            and float(features.audio_rms or 0.0) >= 0.0008
        )
        if register_candidate:
            if register_state is None:
                self._technique_active_states['register_transition'] = {
                    'start_time': float(features.timeline_time),
                    'last_time': float(features.timeline_time),
                    'center_pitch_hz': float(features.detected_frequency_hz or 0.0),
                    'span_semitones': float(features.semitone_delta_prev or 0.0),
                    'continuity_score': float(features.continuity_score or 0.0),
                    'harmonic_shift_score': min(1.0, len(list(features.harmonic_candidates or [])) / 5.0),
                    'timbre_shift_score': max(0.35, float(features.breath_score or 0.0)),
                    'confidence': 0.56,
                    'strength': 0.52,
                    'subtype': 'uncertain',
                }
            else:
                register_state['last_time'] = float(features.timeline_time)
                register_state['span_semitones'] = max(float(register_state.get('span_semitones', 0.0) or 0.0), float(features.semitone_delta_prev or 0.0))
                register_state['continuity_score'] = max(float(register_state.get('continuity_score', 0.0) or 0.0), float(features.continuity_score or 0.0))
        elif register_state is not None:
            self._finalize_active_event('register_transition', float(features.timeline_time), final_features=features)

    def _ingest_technique_features(self, pitch_data: dict, global_time: float) -> None:
        if not self._technique_enabled_for_current_mode():
            return
        features = self._extract_frame_features_from_payload(pitch_data, global_time)
        if features is None:
            return
        self._ingest_technique_frame(features)

    def _build_offline_vibrato_events(self, frames: List[FrameFeatures]) -> List[VibratoEvent]:
        if (not _OFFLINE_TECHNIQUE_SERVICE_AVAILABLE) or (not self._technique_type_selected('vibrato')):
            return []
        try:
            state = getattr(self, '_technique_panel_state', None)
            cfg = getattr(state, 'config', None)
        except Exception:
            cfg = None
        try:
            service_cfg = OfflineVibratoConfig(
                min_duration_s=max(0.26, float(getattr(cfg, 'min_vibrato_duration_s', 0.18) or 0.18)),
                merge_gap_s=float(getattr(cfg, 'merge_gap_s', 0.12) or 0.12) if cfg is not None else 0.12,
            )
            service = OfflineTechniqueAnalysisService(config=service_cfg)
            self._offline_technique_service = service
            regions = service.detect_vibrato(list(frames or []))
        except Exception:
            return []
        events: List[VibratoEvent] = []
        for region in regions:
            try:
                event = VibratoEvent(
                    event_type='vibrato',
                    start_time=float(region.start_time),
                    end_time=float(region.end_time),
                    confidence=float(region.confidence),
                    strength=float(region.strength),
                    center_time=float(region.center_time),
                    duration=float(region.duration),
                    source_layer='offline_service',
                    display_label='颤音',
                    display_color='#BA68C8',
                    feature_snapshot={
                        'base_pitch_hz': float(region.base_pitch_hz),
                        'rate_hz': float(region.rate_hz),
                        'depth_cents': float(region.depth_cents),
                    },
                    display_payload={
                        'detector': 'offline_v1',
                        **dict(getattr(region, 'debug_payload', {}) or {}),
                    },
                    rate_hz=float(region.rate_hz),
                    depth_hz=float(region.depth_hz),
                    depth_cents=float(region.depth_cents),
                    regularity_score=float(region.regularity_score),
                    stability_score=float(region.stability_score),
                    base_pitch_hz=float(region.base_pitch_hz),
                    is_natural_like=bool(
                        3.8 <= float(region.rate_hz) <= 7.5
                        and 12.0 <= float(region.depth_cents) <= 120.0
                        and float(region.regularity_score) >= 0.30
                    ),
                )
            except Exception:
                continue
            events.append(event)
        return events

    def _offline_local_file_source_kind(self, frames: List[FrameFeatures]) -> str:
        for item in list(frames or []):
            if not isinstance(item, FrameFeatures):
                continue
            try:
                flags = dict(getattr(item, 'source_flags', {}) or {})
            except Exception:
                flags = {}
            if bool(flags.get('onepass_full_audio', False)):
                return 'local_file_onepass'
            if bool(flags.get('offline_local_file', False)):
                return 'local_file_partial'
        return ''

    def _build_offline_gap_breath_events(
        self,
        frames: List[FrameFeatures],
        *,
        audio_samples: Optional[np.ndarray] = None,
        sample_rate: Optional[int] = None,
    ) -> List[BreathEvent]:
        if not self._technique_type_selected('breath'):
            return []
        source_kind = self._offline_local_file_source_kind(frames)
        if source_kind != 'local_file_onepass':
            return []
        valid_frames: List[FrameFeatures] = []
        for item in list(frames or []):
            if not isinstance(item, FrameFeatures):
                continue
            if bool(getattr(item, 'preview_only', False)):
                continue
            if not bool(getattr(item, 'has_pitch', False)):
                continue
            valid_frames.append(item)
        if len(valid_frames) < 3:
            return []
        valid_frames.sort(key=lambda item: float(getattr(item, 'timeline_time', 0.0) or 0.0))
        diffs = []
        for idx in range(1, len(valid_frames)):
            try:
                gap = float(valid_frames[idx].timeline_time) - float(valid_frames[idx - 1].timeline_time)
            except Exception:
                gap = 0.0
            if gap > 0.0:
                diffs.append(gap)
        if not diffs:
            return []
        try:
            base_dt = float(np.median(np.asarray(diffs, dtype=np.float32)))
        except Exception:
            base_dt = min(diffs)
        base_dt = max(0.008, min(0.080, base_dt))
        try:
            audio_np = np.asarray(audio_samples, dtype=np.float32).reshape(-1) if audio_samples is not None and sample_rate is not None else None
            sr_value = int(sample_rate or 0)
        except Exception:
            audio_np = None
            sr_value = 0
        events: List[BreathEvent] = []
        for idx in range(1, len(valid_frames)):
            prev_item = valid_frames[idx - 1]
            cur_item = valid_frames[idx]
            try:
                prev_t = float(prev_item.timeline_time)
                cur_t = float(cur_item.timeline_time)
            except Exception:
                continue
            raw_gap = cur_t - prev_t
            if raw_gap < max(0.07, base_dt * 1.8):
                continue
            prev_support_gap = None
            next_support_gap = None
            if idx >= 2:
                try:
                    prev_support_gap = prev_t - float(valid_frames[idx - 2].timeline_time)
                except Exception:
                    prev_support_gap = None
            if idx + 1 < len(valid_frames):
                try:
                    next_support_gap = float(valid_frames[idx + 1].timeline_time) - cur_t
                except Exception:
                    next_support_gap = None
            support_gap_limit = max(0.09, base_dt * 1.7)
            has_prev_support = bool(prev_support_gap is not None and prev_support_gap <= support_gap_limit)
            has_next_support = bool(next_support_gap is not None and next_support_gap <= support_gap_limit)
            both_support = has_prev_support and has_next_support
            single_support = (has_prev_support or has_next_support) and not both_support
            # 双侧支撑：正常检测；单侧支撑：需更明显的间隙特征
            if not (both_support or single_support):
                continue
            if single_support and raw_gap < max(0.12, base_dt * 3.0):
                continue
            start_time = max(0.0, prev_t + base_dt * 0.45)
            end_time = max(start_time, cur_t - base_dt * 0.45)
            duration = max(0.0, end_time - start_time)
            startup_guard_s = 0.0
            try:
                startup_guard_s = float(getattr(self, '_offline_gap_breath_start_guard_s', 0.50) or 0.50)
            except Exception:
                startup_guard_s = 0.50
            if start_time < max(0.0, startup_guard_s):
                continue
            if duration < 0.09 or duration > 0.95:
                continue
            mean_rms = 0.0
            mean_zcr = 0.0
            if audio_np is not None and sr_value > 0:
                try:
                    start_idx = max(0, int(round(start_time * sr_value)))
                    end_idx = min(len(audio_np), int(round(end_time * sr_value)))
                    if end_idx > start_idx:
                        chunk = audio_np[start_idx:end_idx]
                        mean_rms = float(np.sqrt(np.mean(np.square(chunk, dtype=np.float64), dtype=np.float64)))
                        if chunk.size >= 8:
                            sign = np.sign(chunk)
                            mean_zcr = float(np.mean(np.abs(np.diff(sign))) * 0.5)
                except Exception:
                    mean_rms = 0.0
                    mean_zcr = 0.0
            pre_pitch = float(getattr(prev_item, 'display_frequency_hz', 0.0) or getattr(prev_item, 'detected_frequency_hz', 0.0) or 0.0)
            post_pitch = float(getattr(cur_item, 'display_frequency_hz', 0.0) or getattr(cur_item, 'detected_frequency_hz', 0.0) or 0.0)
            breath_peak = max(0.58, min(0.92, 0.54 + duration * 0.75 + mean_zcr * 0.45))
            confidence = max(0.56, min(0.90, 0.50 + duration * 0.68 + mean_zcr * 0.40))
            strength = max(0.54, min(0.88, 0.48 + duration * 0.72 + max(0.0, 0.0022 - mean_rms) * 120.0))
            suppressed_pitch_frames = max(2, int(round(duration / max(base_dt, 1e-3))))
            event = BreathEvent(
                event_type='breath',
                start_time=float(start_time),
                end_time=float(end_time),
                confidence=float(confidence),
                strength=float(strength),
                center_time=0.5 * (float(start_time) + float(end_time)),
                duration=float(duration),
                source_layer='offline_gap_breath',
                display_label='换气',
                display_color='#6EC6FF',
                subtype='offline_gap',
                mean_rms=float(mean_rms),
                mean_zcr=float(mean_zcr),
                breath_score_peak=float(breath_peak),
                pre_pitch_hz=float(pre_pitch),
                post_pitch_hz=float(post_pitch),
                suppressed_pitch_frames=int(suppressed_pitch_frames),
                feature_snapshot={
                    'gap_duration_s': float(duration),
                    'base_dt_s': float(base_dt),
                    'has_prev_support': bool(has_prev_support),
                    'has_next_support': bool(has_next_support),
                },
                display_payload={
                    'detector': 'offline_gap_breath',
                    'source_kind': source_kind,
                },
            )
            events.append(event)
        return events

    def _resolve_chest_falsetto_checkpoint_path(self) -> Optional[Path]:
        for candidate in _CHEST_FALSETTO_CHECKPOINT_CANDIDATES:
            try:
                if Path(candidate).exists():
                    return Path(candidate)
            except Exception:
                continue
        return None

    def _resolve_mix_binary_checkpoint_path(self) -> Optional[Path]:
        for candidate in _MIX_BINARY_CHECKPOINT_CANDIDATES:
            try:
                if Path(candidate).exists():
                    return Path(candidate)
            except Exception:
                continue
        return None

    def _resolve_mix_binary_summary_payload(self, checkpoint_path: Optional[Path] = None) -> Dict[str, Any]:
        resolved_path = Path(checkpoint_path) if checkpoint_path is not None else self._resolve_mix_binary_checkpoint_path()
        if resolved_path is None:
            return {}
        summary_path = Path(resolved_path).with_name('training_summary.json')
        try:
            if summary_path.exists():
                payload = json.loads(summary_path.read_text(encoding='utf-8'))
                if isinstance(payload, dict):
                    return dict(payload)
        except Exception:
            pass
        return {}

    def _resolve_mix_binary_threshold(self) -> float:
        default_threshold = 0.45
        checkpoint_path = self._resolve_mix_binary_checkpoint_path()
        if checkpoint_path is None:
            return default_threshold
        try:
            payload = self._resolve_mix_binary_summary_payload(checkpoint_path)
            threshold = default_threshold
            if payload:
                threshold = float(payload.get('best_threshold', payload.get('threshold', default_threshold)) or default_threshold)
            artifact_name = str(Path(checkpoint_path).parent.name or '')
            threshold_floor = _MIX_BINARY_SOFTWARE_THRESHOLD_FLOORS.get(artifact_name)
            if threshold_floor is not None:
                threshold = max(float(threshold), float(threshold_floor))
            return max(0.05, min(0.95, float(threshold)))
        except Exception:
            pass
        return default_threshold

    def _resolve_chest_falsetto_batch_infer_script_path(self) -> Optional[Path]:
        candidate = project_root / 'ml_dl_models' / 'chest_falsetto' / 'squeezenet_binary' / 'batch_infer_squeezenet_binary.py'
        try:
            return candidate if candidate.exists() else None
        except Exception:
            return None

    def _resolve_mix_binary_batch_infer_script_path(self) -> Optional[Path]:
        candidate = project_root / 'ml_dl_models' / 'gtsinger_multitech' / 'lightweight_training' / 'batch_infer_mix_binary_squeezenet.py'
        try:
            return candidate if candidate.exists() else None
        except Exception:
            return None

    def _should_retry_external_infer_on_cpu(self, error_text: str) -> bool:
        text = str(error_text or '').strip().lower()
        if not text:
            return False
        return any(token in text for token in ('bad allocation', 'out of memory', 'cuda', 'cudnn', 'cublas'))

    def _build_external_infer_env(self, force_cpu: bool) -> Optional[Dict[str, str]]:
        if not force_cpu:
            return None
        env = dict(os.environ)
        env['CUDA_VISIBLE_DEVICES'] = ''
        env['MIND_ECHO_FORCE_CPU'] = '1'
        return env

    def _resolve_external_python_candidates(self) -> List[str]:
        python_candidates: List[str] = []
        preferred_python = str(getattr(self, '_preferred_external_torch_python', '') or '').strip()
        if preferred_python:
            python_candidates.append(preferred_python)
        env_python = str(os.environ.get('MIND_ECHO_TORCH_PYTHON', '') or '').strip()
        if env_python:
            python_candidates.append(env_python)
        try:
            current_python = str(sys.executable or '').strip()
            if current_python:
                python_candidates.append(current_python)
        except Exception:
            pass
        python_candidates.append('python')
        deduped: List[str] = []
        seen: set[str] = set()
        for item in python_candidates:
            key = str(item or '').strip().lower()
            if not key or key in seen:
                continue
            seen.add(key)
            deduped.append(str(item))
        return deduped

    def _resolve_external_force_cpu_order(self, preference_attr: str) -> Tuple[bool, bool]:
        prefer_cpu, reason = self._resolve_effective_external_force_cpu_preference(preference_attr)
        setattr(self, preference_attr, bool(prefer_cpu))
        try:
            if 'chest' in str(preference_attr or ''):
                self._last_external_voice_order_reason = str(reason)
            else:
                self._last_external_mix_order_reason = str(reason)
        except Exception:
            pass
        return (True, False) if prefer_cpu else (False, True)

    def _resample_chest_falsetto_audio(self, audio: np.ndarray, sample_rate: int, target_sample_rate: int) -> np.ndarray:
        y = np.asarray(audio, dtype=np.float32).reshape(-1)
        if y.size <= 0 or int(sample_rate) <= 0 or int(target_sample_rate) <= 0 or int(sample_rate) == int(target_sample_rate):
            return y.astype(np.float32, copy=False)
        try:
            from scipy.signal import resample_poly  # type: ignore
            g = math.gcd(int(sample_rate), int(target_sample_rate))
            up = int(target_sample_rate) // max(1, g)
            down = int(sample_rate) // max(1, g)
            return np.asarray(resample_poly(y, up, down), dtype=np.float32)
        except Exception:
            pass
        old_n = int(y.size)
        new_n = max(1, int(round(old_n * float(target_sample_rate) / float(sample_rate))))
        if old_n <= 1 or new_n <= 1:
            return y.astype(np.float32, copy=False)
        t_old = np.linspace(0.0, 1.0, old_n, endpoint=False, dtype=np.float32)
        t_new = np.linspace(0.0, 1.0, new_n, endpoint=False, dtype=np.float32)
        return np.asarray(np.interp(t_new, t_old, y), dtype=np.float32)

    def _build_chest_falsetto_mel_image(self, audio_window: np.ndarray, torch_module: Any) -> Optional[np.ndarray]:
        y = np.asarray(audio_window, dtype=np.float32).reshape(-1)
        if y.size < 32:
            return None
        try:
            n_fft = 1024
            hop_length = 256
            win_length = 1024
            n_mels = 128
            waveform = torch_module.as_tensor(y)
            if int(waveform.numel()) < win_length:
                waveform = torch_module.nn.functional.pad(waveform, (0, win_length - int(waveform.numel())))
            window = torch_module.hann_window(win_length, dtype=torch_module.float32)
            stft = torch_module.stft(
                waveform,
                n_fft=n_fft,
                hop_length=hop_length,
                win_length=win_length,
                window=window,
                center=True,
                return_complex=True,
            )
            power = stft.abs().pow(2.0)
            hz_to_mel = lambda value_hz: 2595.0 * math.log10(1.0 + float(value_hz) / 700.0)
            mel_to_hz = lambda value_mel: 700.0 * (10.0 ** (float(value_mel) / 2595.0) - 1.0)
            upper_hz = float(_CHEST_FALSETTO_TARGET_SR) * 0.5
            mel_points = np.linspace(hz_to_mel(30.0), hz_to_mel(upper_hz), n_mels + 2, dtype=np.float32)
            hz_points = np.asarray([mel_to_hz(float(item)) for item in mel_points], dtype=np.float32)
            bins = np.floor((n_fft + 1) * hz_points / float(_CHEST_FALSETTO_TARGET_SR)).astype(np.int32)
            bins = np.clip(bins, 0, n_fft // 2)
            filterbank = np.zeros((n_mels, n_fft // 2 + 1), dtype=np.float32)
            for mel_idx in range(1, n_mels + 1):
                left = int(bins[mel_idx - 1])
                center = int(bins[mel_idx])
                right = int(bins[mel_idx + 1])
                if center <= left:
                    center = min(left + 1, n_fft // 2)
                if right <= center:
                    right = min(center + 1, n_fft // 2)
                if center > left:
                    filterbank[mel_idx - 1, left:center] = np.linspace(0.0, 1.0, max(center - left, 1), endpoint=False, dtype=np.float32)
                if right > center:
                    filterbank[mel_idx - 1, center:right] = np.linspace(1.0, 0.0, max(right - center, 1), endpoint=False, dtype=np.float32)
            mel_filter = torch_module.from_numpy(filterbank)
            mel_spec = torch_module.matmul(mel_filter, power)
            mel_spec = torch_module.log10(torch_module.clamp(mel_spec, min=1e-10))
            mel_spec = mel_spec - mel_spec.amin()
            peak = float(mel_spec.amax()) if int(mel_spec.numel()) > 0 else 0.0
            if peak > 0.0:
                mel_spec = mel_spec / peak
            mel_np = np.asarray(mel_spec.cpu().numpy(), dtype=np.float32)
            return np.stack((mel_np, mel_np, mel_np), axis=0).astype(np.float32)
        except Exception:
            return None

    def _run_chest_falsetto_external_inference(self, audio_windows: List[np.ndarray]) -> Optional[List[Dict[str, Any]]]:
        script_path = self._resolve_chest_falsetto_batch_infer_script_path()
        checkpoint_path = self._resolve_chest_falsetto_checkpoint_path()
        if script_path is None or checkpoint_path is None:
            self._last_chest_falsetto_model_error = 'external_infer_missing_assets'
            return None
        if not audio_windows:
            self._last_chest_falsetto_model_error = 'external_infer_no_windows'
            return None
        deduped = self._resolve_external_python_candidates()

        import tempfile
        import subprocess

        windows = []
        for item in audio_windows:
            try:
                windows.append(np.asarray(item, dtype=np.float32).reshape(-1))
            except Exception:
                continue
        if not windows:
            self._last_chest_falsetto_model_error = 'external_infer_no_valid_windows'
            return None

        with tempfile.TemporaryDirectory(prefix='mindecho_cf_') as temp_dir:
            temp_root = Path(temp_dir)
            input_npz = temp_root / 'windows.npz'
            output_json = temp_root / 'result.json'
            try:
                np.savez_compressed(
                    str(input_npz),
                    windows=np.stack(windows, axis=0).astype(np.float32),
                    sample_rate=np.asarray([_CHEST_FALSETTO_TARGET_SR], dtype=np.int32),
                )
            except Exception as exc:
                self._last_chest_falsetto_model_error = f'external_infer_pack_failed:{type(exc).__name__}'
                return None

            last_error = 'external_infer_launch_failed'
            for python_cmd in deduped:
                for force_cpu in self._resolve_external_force_cpu_order('_prefer_chest_falsetto_external_cpu'):
                    try:
                        completed = subprocess.run(
                            [
                                python_cmd,
                                str(script_path),
                                '--input-npz',
                                str(input_npz),
                                '--output-json',
                                str(output_json),
                                '--checkpoint',
                                str(checkpoint_path),
                                '--image-size',
                                str(_CHEST_FALSETTO_IMAGE_SIZE),
                            ],
                            capture_output=True,
                            text=True,
                            timeout=180,
                            check=False,
                            env=self._build_external_infer_env(force_cpu),
                        )
                    except Exception as exc:
                        last_error = f'external_infer_exec_failed:{type(exc).__name__}'
                        break
                    if completed.returncode != 0:
                        stderr_text = str(completed.stderr or '').strip()
                        last_error = f'external_infer_failed:{completed.returncode}'
                        if stderr_text:
                            last_error += f':{stderr_text.splitlines()[-1][:96]}'
                        if (not force_cpu) and self._should_retry_external_infer_on_cpu(stderr_text):
                            setattr(self, '_external_voice_gpu_retry_blocked', True)
                            continue
                        break
                    try:
                        payload = json.loads(output_json.read_text(encoding='utf-8'))
                    except Exception as exc:
                        last_error = f'external_infer_parse_failed:{type(exc).__name__}'
                        break
                    if isinstance(payload, list):
                        self._preferred_external_torch_python = str(python_cmd)
                        setattr(self, '_prefer_chest_falsetto_external_cpu', bool(force_cpu))
                        if not force_cpu:
                            setattr(self, '_external_voice_gpu_retry_blocked', False)
                        self._last_chest_falsetto_model_error = ''
                        return payload
                    last_error = 'external_infer_bad_payload'
                    break
            self._last_chest_falsetto_model_error = last_error
            return None

    def _run_mix_binary_external_inference(self, audio_windows: List[np.ndarray]) -> Optional[List[Dict[str, Any]]]:
        script_path = self._resolve_mix_binary_batch_infer_script_path()
        checkpoint_path = self._resolve_mix_binary_checkpoint_path()
        if script_path is None or checkpoint_path is None:
            self._last_mix_binary_model_error = 'external_infer_missing_assets'
            return None
        if not audio_windows:
            self._last_mix_binary_model_error = 'external_infer_no_windows'
            return None
        deduped = self._resolve_external_python_candidates()

        import tempfile
        import subprocess

        windows = []
        for item in audio_windows:
            try:
                windows.append(np.asarray(item, dtype=np.float32).reshape(-1))
            except Exception:
                continue
        if not windows:
            self._last_mix_binary_model_error = 'external_infer_no_valid_windows'
            return None

        with tempfile.TemporaryDirectory(prefix='mindecho_mix_') as temp_dir:
            temp_root = Path(temp_dir)
            input_npz = temp_root / 'windows.npz'
            output_json = temp_root / 'result.json'
            try:
                np.savez_compressed(
                    str(input_npz),
                    windows=np.stack(windows, axis=0).astype(np.float32),
                    sample_rate=np.asarray([_CHEST_FALSETTO_TARGET_SR], dtype=np.int32),
                )
            except Exception as exc:
                self._last_mix_binary_model_error = f'external_infer_pack_failed:{type(exc).__name__}'
                return None

            last_error = 'external_infer_launch_failed'
            for python_cmd in deduped:
                for force_cpu in self._resolve_external_force_cpu_order('_prefer_mix_binary_external_cpu'):
                    try:
                        completed = subprocess.run(
                            [
                                python_cmd,
                                str(script_path),
                                '--input-npz',
                                str(input_npz),
                                '--output-json',
                                str(output_json),
                                '--checkpoint',
                                str(checkpoint_path),
                                '--artifact-dir',
                                str(Path(checkpoint_path).parent),
                            ],
                            capture_output=True,
                            text=True,
                            timeout=180,
                            check=False,
                            env=self._build_external_infer_env(force_cpu),
                        )
                    except Exception as exc:
                        last_error = f'external_infer_exec_failed:{type(exc).__name__}'
                        break
                    if completed.returncode != 0:
                        stderr_text = str(completed.stderr or '').strip()
                        last_error = f'external_infer_failed:{completed.returncode}'
                        if stderr_text:
                            last_error += f':{stderr_text.splitlines()[-1][:96]}'
                        if (not force_cpu) and self._should_retry_external_infer_on_cpu(stderr_text):
                            setattr(self, '_external_mix_gpu_retry_blocked', True)
                            continue
                        break
                    try:
                        payload = json.loads(output_json.read_text(encoding='utf-8'))
                    except Exception as exc:
                        last_error = f'external_infer_parse_failed:{type(exc).__name__}'
                        break
                    if isinstance(payload, list):
                        self._preferred_external_torch_python = str(python_cmd)
                        setattr(self, '_prefer_mix_binary_external_cpu', bool(force_cpu))
                        if not force_cpu:
                            setattr(self, '_external_mix_gpu_retry_blocked', False)
                        self._last_mix_binary_model_error = ''
                        return payload
                    last_error = 'external_infer_bad_payload'
                    break
            self._last_mix_binary_model_error = last_error
            return None

    def _get_chest_falsetto_model_bundle(self) -> Optional[Dict[str, Any]]:
        checkpoint_path = self._resolve_chest_falsetto_checkpoint_path()
        if checkpoint_path is None:
            self._last_chest_falsetto_model_error = 'checkpoint_missing'
            return None
        try:
            mtime = float(checkpoint_path.stat().st_mtime)
        except Exception:
            mtime = 0.0
        cached = getattr(self, '_chest_falsetto_model_bundle', None)
        if isinstance(cached, dict):
            try:
                if str(cached.get('path', '')) == str(checkpoint_path) and float(cached.get('mtime', -1.0)) == mtime:
                    self._last_chest_falsetto_model_error = ''
                    return cached
            except Exception:
                pass
        torch, torch_error = _import_torch_safely()
        if torch is None:
            self._last_chest_falsetto_model_error = str(torch_error or 'torch_import_failed')
            return None
        device = torch.device('cpu')

        def _build_torchvision_model():
            from torchvision import models  # type: ignore
            model_obj = models.squeezenet1_1(weights=None)
            model_obj.classifier[1] = torch.nn.Conv2d(512, 2, kernel_size=1)
            model_obj.num_classes = 2
            return model_obj, 'torchvision'

        def _build_torch_only_model():
            nn = torch.nn

            class _Fire(nn.Module):
                def __init__(self, inplanes: int, squeeze_planes: int, expand1x1_planes: int, expand3x3_planes: int):
                    super().__init__()
                    self.squeeze = nn.Conv2d(inplanes, squeeze_planes, kernel_size=1)
                    self.squeeze_activation = nn.ReLU(inplace=True)
                    self.expand1x1 = nn.Conv2d(squeeze_planes, expand1x1_planes, kernel_size=1)
                    self.expand1x1_activation = nn.ReLU(inplace=True)
                    self.expand3x3 = nn.Conv2d(squeeze_planes, expand3x3_planes, kernel_size=3, padding=1)
                    self.expand3x3_activation = nn.ReLU(inplace=True)

                def forward(self, x):
                    x = self.squeeze_activation(self.squeeze(x))
                    return torch.cat([
                        self.expand1x1_activation(self.expand1x1(x)),
                        self.expand3x3_activation(self.expand3x3(x)),
                    ], 1)

            class _SqueezeNet(nn.Module):
                def __init__(self, num_classes: int = 2):
                    super().__init__()
                    self.num_classes = num_classes
                    self.features = nn.Sequential(
                        nn.Conv2d(3, 64, kernel_size=3, stride=2),
                        nn.ReLU(inplace=True),
                        nn.MaxPool2d(kernel_size=3, stride=2, ceil_mode=True),
                        _Fire(64, 16, 64, 64),
                        _Fire(128, 16, 64, 64),
                        nn.MaxPool2d(kernel_size=3, stride=2, ceil_mode=True),
                        _Fire(128, 32, 128, 128),
                        _Fire(256, 32, 128, 128),
                        nn.MaxPool2d(kernel_size=3, stride=2, ceil_mode=True),
                        _Fire(256, 48, 192, 192),
                        _Fire(384, 48, 192, 192),
                        _Fire(384, 64, 256, 256),
                        _Fire(512, 64, 256, 256),
                    )
                    self.classifier = nn.Sequential(
                        nn.Dropout(p=0.5),
                        nn.Conv2d(512, num_classes, kernel_size=1),
                        nn.ReLU(inplace=True),
                        nn.AdaptiveAvgPool2d((1, 1)),
                    )

                def forward(self, x):
                    x = self.features(x)
                    x = self.classifier(x)
                    return torch.flatten(x, 1)

            return _SqueezeNet(num_classes=2), 'torch_only_fallback'

        model_backend = 'unknown'
        try:
            model, model_backend = _build_torchvision_model()
        except Exception as exc:
            try:
                model, model_backend = _build_torch_only_model()
            except Exception as fallback_exc:
                self._last_chest_falsetto_model_error = f'model_build_failed:{type(exc).__name__}:{type(fallback_exc).__name__}'
                return None
        try:
            checkpoint = torch.load(str(checkpoint_path), map_location=device)
        except Exception as exc:
            self._last_chest_falsetto_model_error = f'checkpoint_load_failed:{type(exc).__name__}'
            return None
        state_dict = checkpoint.get('model_state_dict', checkpoint) if isinstance(checkpoint, dict) else checkpoint
        try:
            model.load_state_dict(state_dict)
        except Exception as exc:
            self._last_chest_falsetto_model_error = f'state_dict_load_failed:{type(exc).__name__}'
            return None
        model.to(device)
        model.eval()
        bundle = {
            'path': str(checkpoint_path),
            'mtime': mtime,
            'torch': torch,
            'device': device,
            'model': model,
            'backend': model_backend,
            'mean': torch.tensor(_CHEST_FALSETTO_MEAN, dtype=torch.float32).view(3, 1, 1),
            'std': torch.tensor(_CHEST_FALSETTO_STD, dtype=torch.float32).view(3, 1, 1),
        }
        self._last_chest_falsetto_model_error = ''
        self._chest_falsetto_model_bundle = bundle
        return bundle

    def _get_mix_binary_model_bundle(self) -> Optional[Dict[str, Any]]:
        checkpoint_path = self._resolve_mix_binary_checkpoint_path()
        if checkpoint_path is None:
            self._last_mix_binary_model_error = 'checkpoint_missing'
            return None
        try:
            mtime = float(checkpoint_path.stat().st_mtime)
        except Exception:
            mtime = 0.0
        cached = getattr(self, '_mix_binary_model_bundle', None)
        if isinstance(cached, dict):
            try:
                if str(cached.get('path', '')) == str(checkpoint_path) and float(cached.get('mtime', -1.0)) == mtime:
                    self._last_mix_binary_model_error = ''
                    return cached
            except Exception:
                pass
        summary_payload = self._resolve_mix_binary_summary_payload(checkpoint_path)
        backbone_name = str(summary_payload.get('backbone_name', 'squeezenet11') or 'squeezenet11').strip().lower()
        threshold = self._resolve_mix_binary_threshold()
        image_size = max(64, int(summary_payload.get('image_size', 224) or 224))
        sample_rate = max(8000, int(summary_payload.get('sample_rate', _CHEST_FALSETTO_TARGET_SR) or _CHEST_FALSETTO_TARGET_SR))
        n_fft = max(128, int(summary_payload.get('n_fft', 1024) or 1024))
        hop_length = max(32, int(summary_payload.get('hop_length', 256) or 256))
        n_mels = max(32, int(summary_payload.get('n_mels', 128) or 128))
        bundle = {
            'path': str(checkpoint_path),
            'mtime': mtime,
            'threshold': max(0.05, min(0.95, threshold)),
            'backbone_name': backbone_name,
            'image_size': image_size,
            'sample_rate': sample_rate,
            'n_fft': n_fft,
            'hop_length': hop_length,
            'n_mels': n_mels,
            'force_external': False,
        }
        torch, torch_error = _import_torch_safely()
        if torch is None:
            bundle['force_external'] = True
            self._last_mix_binary_model_error = str(torch_error or 'torch_import_failed')
            self._mix_binary_model_bundle = bundle
            return bundle
        device = torch.device('cpu')
        try:
            model = self._build_mix_binary_model_architecture(torch, backbone_name)
        except Exception as exc:
            bundle['force_external'] = True
            self._last_mix_binary_model_error = f'model_build_failed:{type(exc).__name__}'
            self._mix_binary_model_bundle = bundle
            return bundle
        try:
            checkpoint = torch.load(str(checkpoint_path), map_location=device)
        except TypeError:
            try:
                checkpoint = torch.load(str(checkpoint_path), map_location=device, weights_only=False)
            except Exception as exc:
                bundle['force_external'] = True
                self._last_mix_binary_model_error = f'checkpoint_load_failed:{type(exc).__name__}'
                self._mix_binary_model_bundle = bundle
                return bundle
        except Exception as exc:
            exc_text = str(exc or '')
            if 'weights_only' in exc_text:
                try:
                    checkpoint = torch.load(str(checkpoint_path), map_location=device, weights_only=False)
                except Exception as retry_exc:
                    bundle['force_external'] = True
                    self._last_mix_binary_model_error = f'checkpoint_load_failed:{type(retry_exc).__name__}'
                    self._mix_binary_model_bundle = bundle
                    return bundle
            else:
                bundle['force_external'] = True
                self._last_mix_binary_model_error = f'checkpoint_load_failed:{type(exc).__name__}'
                self._mix_binary_model_bundle = bundle
                return bundle
        state_dict = checkpoint.get('model_state_dict', checkpoint) if isinstance(checkpoint, dict) else checkpoint
        try:
            model.load_state_dict(state_dict)
        except Exception as exc:
            bundle['force_external'] = True
            self._last_mix_binary_model_error = f'state_dict_load_failed:{type(exc).__name__}'
            self._mix_binary_model_bundle = bundle
            return bundle
        model.to(device)
        model.eval()
        try:
            if isinstance(checkpoint, dict):
                threshold = float(checkpoint.get('threshold', checkpoint.get('best_threshold', threshold)) or threshold)
        except Exception:
            threshold = self._resolve_mix_binary_threshold()
        mel_filter = self._build_mix_binary_mel_filterbank(sample_rate=sample_rate, n_fft=n_fft, n_mels=n_mels)
        bundle.update({
            'torch': torch,
            'device': device,
            'model': model,
            'threshold': max(0.05, min(0.95, threshold)),
            'mean': torch.tensor(_CHEST_FALSETTO_MEAN, dtype=torch.float32).view(3, 1, 1),
            'std': torch.tensor(_CHEST_FALSETTO_STD, dtype=torch.float32).view(3, 1, 1),
            'stft_window': torch.hann_window(int(n_fft), dtype=torch.float32),
            'mel_filter': torch.from_numpy(np.asarray(mel_filter, dtype=np.float32)),
        })
        self._last_mix_binary_model_error = ''
        self._mix_binary_model_bundle = bundle
        return bundle

    def _build_mix_binary_model_architecture(self, torch_module: Any, backbone_name: str) -> Any:
        name = str(backbone_name or 'squeezenet11').strip().lower()
        from torchvision import models  # type: ignore
        if name == 'squeezenet11':
            model = models.squeezenet1_1(weights=None)
            model.classifier[1] = torch_module.nn.Conv2d(512, 2, kernel_size=1)
            model.num_classes = 2
            return model
        if name == 'mobilenet_v3_small':
            model = models.mobilenet_v3_small(weights=None)
            in_features = int(model.classifier[-1].in_features)
            model.classifier[-1] = torch_module.nn.Linear(in_features, 2)
            return model
        if name == 'efficientnet_b0':
            model = models.efficientnet_b0(weights=None)
            in_features = int(model.classifier[-1].in_features)
            model.classifier[-1] = torch_module.nn.Linear(in_features, 2)
            return model
        raise ValueError(f'unsupported_backbone:{name}')

    def _build_mix_binary_mel_filterbank(self, *, sample_rate: int, n_fft: int, n_mels: int) -> np.ndarray:
        upper_hz = float(sample_rate) * 0.5
        mel_points = np.linspace(
            2595.0 * math.log10(1.0 + 30.0 / 700.0),
            2595.0 * math.log10(1.0 + upper_hz / 700.0),
            n_mels + 2,
            dtype=np.float32,
        )
        hz_points = np.asarray([700.0 * (10.0 ** (float(item) / 2595.0) - 1.0) for item in mel_points], dtype=np.float32)
        bins = np.floor((n_fft + 1) * hz_points / float(sample_rate)).astype(np.int32)
        bins = np.clip(bins, 0, n_fft // 2)
        filterbank = np.zeros((n_mels, n_fft // 2 + 1), dtype=np.float32)
        for mel_idx in range(1, n_mels + 1):
            left = int(bins[mel_idx - 1])
            center = int(bins[mel_idx])
            right = int(bins[mel_idx + 1])
            if center <= left:
                center = min(left + 1, n_fft // 2)
            if right <= center:
                right = min(center + 1, n_fft // 2)
            if center > left:
                filterbank[mel_idx - 1, left:center] = np.linspace(0.0, 1.0, max(center - left, 1), endpoint=False, dtype=np.float32)
            if right > center:
                filterbank[mel_idx - 1, center:right] = np.linspace(1.0, 0.0, max(right - center, 1), endpoint=False, dtype=np.float32)
        return filterbank

    def _build_mix_binary_window_tensor(self, audio_window: np.ndarray, bundle: Dict[str, Any]) -> Optional[Any]:
        try:
            import torch.nn.functional as torch_F  # type: ignore
        except Exception:
            return None
        torch = bundle.get('torch')
        if torch is None:
            return None
        y = np.asarray(audio_window, dtype=np.float32).reshape(-1)
        if y.size < 32:
            return None
        target_sample_rate = int(bundle.get('sample_rate', _CHEST_FALSETTO_TARGET_SR) or _CHEST_FALSETTO_TARGET_SR)
        if target_sample_rate != int(_CHEST_FALSETTO_TARGET_SR):
            try:
                y = self._resample_chest_falsetto_audio(y, int(_CHEST_FALSETTO_TARGET_SR), target_sample_rate)
            except Exception:
                return None
        n_fft = int(bundle.get('n_fft', 1024) or 1024)
        hop_length = int(bundle.get('hop_length', 256) or 256)
        image_size = int(bundle.get('image_size', 224) or 224)
        waveform = torch.as_tensor(y)
        if int(waveform.numel()) < n_fft:
            waveform = torch.nn.functional.pad(waveform, (0, n_fft - int(waveform.numel())))
        try:
            window = bundle.get('stft_window')
            if window is None or int(window.numel()) != n_fft:
                window = torch.hann_window(n_fft, dtype=torch.float32)
            stft = torch.stft(
                waveform,
                n_fft=n_fft,
                hop_length=hop_length,
                win_length=n_fft,
                window=window,
                center=True,
                return_complex=True,
            )
            power = stft.abs().pow(2.0)
            mel_filter = bundle.get('mel_filter')
            if mel_filter is None:
                mel_filter = self._build_mix_binary_mel_filterbank(
                    sample_rate=target_sample_rate,
                    n_fft=n_fft,
                    n_mels=int(bundle.get('n_mels', 128) or 128),
                )
                mel_filter = torch.from_numpy(np.asarray(mel_filter, dtype=np.float32))
            elif not hasattr(mel_filter, 'device'):
                mel_filter = torch.from_numpy(np.asarray(mel_filter, dtype=np.float32))
            mel_spec = torch.matmul(mel_filter, power)
            mel_spec = torch.log10(torch.clamp(mel_spec, min=1e-10))
            mel_spec = mel_spec - mel_spec.amin()
            peak = float(mel_spec.amax()) if int(mel_spec.numel()) > 0 else 0.0
            if peak > 0.0:
                mel_spec = mel_spec / peak
            rgb = torch.stack((mel_spec, mel_spec, mel_spec), dim=0).to(dtype=torch.float32)
            tensor = torch_F.interpolate(
                rgb.unsqueeze(0),
                size=(image_size, image_size),
                mode='bilinear',
                align_corners=False,
            ).squeeze(0)
            mean = bundle.get('mean')
            std = bundle.get('std')
            if mean is not None and std is not None:
                tensor = (tensor - mean) / std
            return tensor
        except Exception:
            return None

    def _predict_mix_binary_local(self, audio_windows: List[np.ndarray], bundle: Dict[str, Any]) -> Optional[List[Dict[str, Any]]]:
        torch = bundle.get('torch') if isinstance(bundle, dict) else None
        model = bundle.get('model') if isinstance(bundle, dict) else None
        device = bundle.get('device') if isinstance(bundle, dict) else None
        if torch is None or model is None or device is None:
            return None
        tensors = []
        for item in list(audio_windows or []):
            tensor = self._build_mix_binary_window_tensor(item, bundle)
            if tensor is None:
                self._last_mix_binary_model_error = 'local_preprocess_failed'
                return None
            tensors.append(tensor)
        if not tensors:
            self._last_mix_binary_model_error = 'local_no_valid_windows'
            return None
        results: List[Dict[str, Any]] = []
        batch_size = int(_CHEST_FALSETTO_BATCH_SIZE)
        try:
            with torch.no_grad():
                for start_idx in range(0, len(tensors), batch_size):
                    batch = torch.stack(tensors[start_idx:start_idx + batch_size]).to(device)
                    logits = model(batch)
                    probs = torch.softmax(logits, dim=1).cpu().numpy()
                    for prob in probs:
                        results.append({
                            'non_mix_prob': float(prob[0]),
                            'mix_prob': float(prob[1]),
                        })
        except Exception as exc:
            self._last_mix_binary_model_error = f'local_predict_failed:{type(exc).__name__}'
            return None
        self._last_mix_binary_model_error = ''
        return results

    def _build_chest_falsetto_window_tensor(self, audio_window: np.ndarray, bundle: Dict[str, Any]) -> Optional[Any]:
        try:
            import torch.nn.functional as torch_F  # type: ignore
        except Exception:
            return None
        torch = bundle.get('torch')
        if torch is None:
            return None
        rgb = self._build_chest_falsetto_mel_image(audio_window, torch)
        if rgb is None:
            return None
        tensor = torch.from_numpy(rgb).unsqueeze(0)
        tensor = torch_F.interpolate(
            tensor,
            size=(_CHEST_FALSETTO_IMAGE_SIZE, _CHEST_FALSETTO_IMAGE_SIZE),
            mode='bilinear',
            align_corners=False,
        ).squeeze(0)
        mean = bundle.get('mean')
        std = bundle.get('std')
        if mean is None or std is None:
            return tensor
        return (tensor - mean) / std

    def _smooth_chest_falsetto_predictions(self, predictions: List[Dict[str, Any]], hop_s: float) -> List[Dict[str, Any]]:
        if len(predictions) < 3:
            return predictions
        smoothed = [dict(item) for item in predictions]
        for idx in range(1, len(smoothed) - 1):
            prev_item = smoothed[idx - 1]
            cur_item = smoothed[idx]
            next_item = smoothed[idx + 1]
            prev_type = str(prev_item.get('event_type', '') or '')
            cur_type = str(cur_item.get('event_type', '') or '')
            next_type = str(next_item.get('event_type', '') or '')
            if prev_type != next_type or prev_type == cur_type:
                continue
            try:
                gap_left = float(cur_item.get('center_time', 0.0) or 0.0) - float(prev_item.get('center_time', 0.0) or 0.0)
                gap_right = float(next_item.get('center_time', 0.0) or 0.0) - float(cur_item.get('center_time', 0.0) or 0.0)
            except Exception:
                continue
            if gap_left > hop_s * 1.8 or gap_right > hop_s * 1.8:
                continue
            prev_margin = float(prev_item.get('probability_margin', 0.0) or 0.0)
            next_margin = float(next_item.get('probability_margin', 0.0) or 0.0)
            cur_margin = float(cur_item.get('probability_margin', 0.0) or 0.0)
            if cur_margin > max(prev_margin, next_margin) * 1.12:
                continue
            cur_item['event_type'] = prev_type
            cur_item['voice_type'] = prev_item.get('voice_type', prev_type)
            cur_item['chest_prob'] = 0.5 * (float(prev_item.get('chest_prob', 0.0) or 0.0) + float(next_item.get('chest_prob', 0.0) or 0.0))
            cur_item['falsetto_prob'] = 0.5 * (float(prev_item.get('falsetto_prob', 0.0) or 0.0) + float(next_item.get('falsetto_prob', 0.0) or 0.0))
            if 'mix_prob' in prev_item or 'mix_prob' in next_item:
                cur_item['mix_prob'] = 0.5 * (float(prev_item.get('mix_prob', 0.0) or 0.0) + float(next_item.get('mix_prob', 0.0) or 0.0))
                cur_item['mix_threshold'] = 0.5 * (float(prev_item.get('mix_threshold', 0.45) or 0.45) + float(next_item.get('mix_threshold', 0.45) or 0.45))
            cur_item['confidence'] = max(float(cur_item.get('confidence', 0.0) or 0.0), 0.5 * (float(prev_item.get('confidence', 0.0) or 0.0) + float(next_item.get('confidence', 0.0) or 0.0)))
            cur_item['probability_margin'] = abs(float(cur_item.get('chest_prob', 0.0) or 0.0) - float(cur_item.get('falsetto_prob', 0.0) or 0.0))
        return smoothed

    def _voice_prediction_accepted(self, confidence: float, probability_margin: float, *, relaxed: bool = False) -> bool:
        if relaxed:
            return confidence >= 0.48 and probability_margin >= 0.018
        return confidence >= 0.52 and probability_margin >= 0.05

    def _voice_prediction_record_accepted(self, record: Dict[str, Any], *, relaxed: bool = False) -> bool:
        event_type = str(record.get('event_type', '') or '')
        mean_pitch_hz = float(record.get('mean_pitch_hz', 0.0) or 0.0)
        voiced_ratio = float(record.get('voiced_ratio', 0.0) or 0.0)
        stable_ratio = float(record.get('stable_ratio', 0.0) or 0.0)
        confidence = float(record.get('confidence', 0.0) or 0.0)
        probability_margin = float(record.get('probability_margin', 0.0) or 0.0)
        if event_type == 'chest_voice':
            if mean_pitch_hz > 0.0 and mean_pitch_hz < 240.0:
                if relaxed:
                    return confidence >= 0.49 and probability_margin >= 0.010 and voiced_ratio >= 0.16
                return confidence >= 0.50 and probability_margin >= 0.015 and voiced_ratio >= 0.18
            if mean_pitch_hz > 0.0 and mean_pitch_hz < 320.0:
                if relaxed:
                    return confidence >= 0.50 and probability_margin >= 0.018 and voiced_ratio >= 0.17
                return confidence >= 0.53 and probability_margin >= 0.030 and voiced_ratio >= 0.20 and stable_ratio >= 0.04
            if mean_pitch_hz > 0.0 and mean_pitch_hz >= 320.0:
                if relaxed:
                    return confidence >= 0.44 and probability_margin >= 0.006 and voiced_ratio >= 0.12
                return confidence >= 0.46 and probability_margin >= 0.010 and voiced_ratio >= 0.14 and stable_ratio >= 0.02
        return self._voice_prediction_accepted(confidence, probability_margin, relaxed=relaxed)

    def _apply_voice_type_context_priors(
        self,
        chest_prob: float,
        falsetto_prob: float,
        *,
        mean_pitch_hz: float,
        voiced_ratio: float,
        stable_ratio: float,
        mean_rms: float,
        mean_zcr: float = 0.0,
        mean_breath_score: float = 0.0,
        breath_hint_ratio: float = 0.0,
    ) -> Dict[str, Any]:
        chest_prob = max(0.0, float(chest_prob or 0.0))
        falsetto_prob = max(0.0, float(falsetto_prob or 0.0))
        mean_pitch_hz = max(0.0, float(mean_pitch_hz or 0.0))
        voiced_ratio = max(0.0, float(voiced_ratio or 0.0))
        stable_ratio = max(0.0, float(stable_ratio or 0.0))
        mean_rms = max(0.0, float(mean_rms or 0.0))
        mean_zcr = max(0.0, float(mean_zcr or 0.0))
        mean_breath_score = max(0.0, float(mean_breath_score or 0.0))
        breath_hint_ratio = max(0.0, float(breath_hint_ratio or 0.0))

        chest_bias = 0.0
        falsetto_bias = 0.0
        force_chest = False
        breath_like = bool(
            0.00008 <= mean_rms <= 0.0026
            and (mean_zcr >= 0.09 or mean_breath_score >= 0.22 or breath_hint_ratio >= 0.14)
            and voiced_ratio <= 0.46
            and stable_ratio <= 0.20
        )

        # 低音区默认更应保守地判为真声，避免把轻薄真声误判为假声。
        if mean_pitch_hz > 0.0:
            if mean_pitch_hz < 240.0:
                chest_bias += 0.42
                if falsetto_prob < 0.88:
                    force_chest = True
            elif mean_pitch_hz < 290.0:
                chest_bias += 0.22
            elif mean_pitch_hz < 340.0:
                chest_bias += 0.20
            elif mean_pitch_hz < 420.0:
                chest_bias += 0.08
            elif mean_pitch_hz >= 520.0:
                falsetto_bias += 0.04
            elif mean_pitch_hz >= 420.0:
                falsetto_bias += 0.02

        if mean_pitch_hz < 300.0:
            if voiced_ratio >= 0.56 and stable_ratio >= 0.14:
                chest_bias += 0.09
            if mean_rms >= 0.00055 and mean_zcr <= 0.13:
                chest_bias += 0.05
        if mean_pitch_hz < 320.0 and voiced_ratio >= 0.62 and stable_ratio >= 0.24:
            chest_bias += 0.08
        if mean_pitch_hz >= 360.0 and mean_rms <= 0.00045 and stable_ratio < 0.18:
            falsetto_bias += 0.03
        if breath_like:
            chest_bias += 0.14
            falsetto_bias -= 0.18
        if mean_pitch_hz < 340.0 and mean_zcr >= 0.12 and stable_ratio < 0.12:
            falsetto_bias -= 0.05

        adjusted_chest = chest_prob + chest_bias
        adjusted_falsetto = max(0.0, falsetto_prob + falsetto_bias)
        total = max(1e-9, adjusted_chest + adjusted_falsetto)
        adjusted_chest /= total
        adjusted_falsetto /= total

        if force_chest:
            adjusted_chest = max(adjusted_chest, adjusted_falsetto + 0.06)
            total = max(1e-9, adjusted_chest + adjusted_falsetto)
            adjusted_chest /= total
            adjusted_falsetto /= total

        event_type = 'chest_voice' if adjusted_chest >= adjusted_falsetto else 'falsetto'
        return {
            'event_type': event_type,
            'voice_type': 'chest' if event_type == 'chest_voice' else 'falsetto',
            'chest_prob': float(adjusted_chest),
            'falsetto_prob': float(adjusted_falsetto),
            'confidence': float(max(adjusted_chest, adjusted_falsetto)),
            'probability_margin': float(abs(adjusted_chest - adjusted_falsetto)),
            'context_forced_chest': bool(force_chest),
            'context_pitch_hz': float(mean_pitch_hz),
        }

    def _build_offline_chest_falsetto_events(
        self,
        frames: List[FrameFeatures],
        audio_samples: Optional[np.ndarray] = None,
        sample_rate: Optional[int] = None,
    ) -> List[VoiceTypeEvent]:
        self._last_voice_type_debug = {
            'model_ready': False,
            'candidate_windows': 0,
            'predicted_windows': 0,
            'accepted_windows': 0,
            'context_adjusted_windows': 0,
            'relaxed_used': False,
            'reason': '',
        }
        if not (self._technique_type_selected('chest_voice') or self._technique_type_selected('falsetto')):
            self._last_voice_type_debug['reason'] = 'not_selected'
            return []
        if audio_samples is None or sample_rate is None:
            self._last_voice_type_debug['reason'] = 'missing_audio'
            return []
        bundle = self._get_chest_falsetto_model_bundle()
        if bundle:
            self._last_voice_type_debug['model_ready'] = True
            try:
                self._last_voice_type_debug['backend'] = str(bundle.get('backend', '') or '')
            except Exception:
                pass
        torch = bundle.get('torch') if isinstance(bundle, dict) else None
        model = bundle.get('model') if isinstance(bundle, dict) else None
        device = bundle.get('device') if isinstance(bundle, dict) else None
        if bundle is not None and (torch is None or model is None or device is None):
            self._last_voice_type_debug['reason'] = 'model_bundle_incomplete'
            return []

        audio = np.asarray(audio_samples, dtype=np.float32).reshape(-1)
        if audio.size < 64:
            self._last_voice_type_debug['reason'] = 'audio_too_short'
            return []
        audio = np.nan_to_num(audio, nan=0.0, posinf=0.0, neginf=0.0)
        try:
            if int(sample_rate) != _CHEST_FALSETTO_TARGET_SR:
                audio = self._resample_chest_falsetto_audio(audio, int(sample_rate), _CHEST_FALSETTO_TARGET_SR)
        except Exception:
            self._last_voice_type_debug['reason'] = 'resample_failed'
            return []
        if audio.size < 64:
            self._last_voice_type_debug['reason'] = 'audio_too_short_after_resample'
            return []

        valid_frames: List[FrameFeatures] = []
        for item in list(frames or []):
            if not isinstance(item, FrameFeatures):
                continue
            if bool(getattr(item, 'preview_only', False)):
                continue
            valid_frames.append(item)
        if not valid_frames:
            self._last_voice_type_debug['reason'] = 'no_valid_frames'
            return []
        valid_frames = sorted(valid_frames, key=lambda item: float(getattr(item, 'timeline_time', 0.0) or 0.0))

        times = np.asarray([float(getattr(item, 'timeline_time', 0.0) or 0.0) for item in valid_frames], dtype=np.float32)
        confidences = np.asarray([float(getattr(item, 'confidence', 0.0) or 0.0) for item in valid_frames], dtype=np.float32)
        has_pitch = np.asarray([bool(getattr(item, 'has_pitch', False)) for item in valid_frames], dtype=bool)
        rms_values = np.asarray([float(getattr(item, 'audio_rms', 0.0) or 0.0) for item in valid_frames], dtype=np.float32)
        zcr_values = np.asarray([float(getattr(item, 'zcr', 0.0) or 0.0) for item in valid_frames], dtype=np.float32)
        breath_scores = np.asarray([float(getattr(item, 'breath_score', 0.0) or 0.0) for item in valid_frames], dtype=np.float32)
        breath_hints = np.asarray([1.0 if bool(getattr(item, 'breath_detect_hint', False)) else 0.0 for item in valid_frames], dtype=np.float32)
        pitches = np.asarray([float(getattr(item, 'display_frequency_hz', 0.0) or getattr(item, 'detected_frequency_hz', 0.0) or 0.0) for item in valid_frames], dtype=np.float32)
        voiced_mask = np.logical_and(has_pitch, confidences >= 0.34)
        stable_mask = np.logical_and(has_pitch, confidences >= 0.50)

        total_duration = max(float(audio.size) / float(_CHEST_FALSETTO_TARGET_SR), float(times[-1] if times.size else 0.0))
        window_s = float(_CHEST_FALSETTO_WINDOW_S)
        hop_s = float(_CHEST_FALSETTO_HOP_S)
        window_samples = max(1, int(round(window_s * _CHEST_FALSETTO_TARGET_SR)))
        hop_samples = max(1, int(round(hop_s * _CHEST_FALSETTO_TARGET_SR)))

        candidate_windows: List[Dict[str, Any]] = []
        tensors = []
        audio_windows: List[np.ndarray] = []
        max_start = max(0, int(audio.size) - window_samples)
        if max_start <= 0:
            candidate_starts = [0]
        else:
            candidate_starts = list(range(0, max_start + 1, hop_samples))
            if candidate_starts[-1] != max_start:
                candidate_starts.append(max_start)

        for sample_start in candidate_starts:
            sample_end = min(int(audio.size), int(sample_start + window_samples))
            window = np.asarray(audio[sample_start:sample_end], dtype=np.float32)
            if window.size < window_samples:
                padded = np.zeros(window_samples, dtype=np.float32)
                padded[:window.size] = window
                window = padded
            start_time = float(sample_start) / float(_CHEST_FALSETTO_TARGET_SR)
            end_time = start_time + window_s
            frame_mask = np.logical_and(times >= start_time, times < end_time)
            frame_count = int(np.count_nonzero(frame_mask))
            if frame_count < 2:
                continue
            voiced_ratio = float(np.mean(voiced_mask[frame_mask])) if frame_count > 0 else 0.0
            stable_ratio = float(np.mean(stable_mask[frame_mask])) if frame_count > 0 else 0.0
            mean_rms = float(np.mean(rms_values[frame_mask])) if frame_count > 0 else 0.0
            mean_zcr = float(np.mean(zcr_values[frame_mask])) if frame_count > 0 else 0.0
            mean_breath_score = float(np.mean(breath_scores[frame_mask])) if frame_count > 0 else 0.0
            breath_hint_ratio = float(np.mean(breath_hints[frame_mask])) if frame_count > 0 else 0.0
            # 呼吸段跳过真假声分类：明显呼吸特征 → 不是声区，避免假声误判
            # 三个触发条件覆盖不同呼吸表现形态
            low_energy_breath = (
                voiced_ratio <= 0.48
                and mean_rms <= 0.0050
                and (mean_zcr >= 0.05 or mean_breath_score >= 0.13 or breath_hint_ratio >= 0.06)
            )
            high_hint_breath = (
                breath_hint_ratio >= 0.14
                and voiced_ratio <= 0.55
                and mean_rms <= 0.0060
            )
            # 中间态：有一定呼吸提示 + 低稳定度 + 低能量 → 很可能是换气
            moderate_breath = (
                breath_hint_ratio >= 0.06
                and voiced_ratio <= 0.45
                and mean_rms <= 0.0035
                and stable_ratio <= 0.14
                and mean_zcr >= 0.04
            )
            window_breath_like = bool(low_energy_breath or high_hint_breath or moderate_breath)
            if window_breath_like:
                continue
            if voiced_ratio < 0.17 or stable_ratio < 0.03 or mean_rms < 0.00008:
                continue
            pitch_slice = pitches[frame_mask]
            positive_pitch = pitch_slice[pitch_slice > 0.0]
            mean_pitch_hz = float(np.mean(positive_pitch)) if positive_pitch.size else 0.0
            candidate_meta = {
                'start_time': start_time,
                'end_time': min(total_duration, end_time),
                'center_time': start_time + 0.5 * window_s,
                'voiced_ratio': voiced_ratio,
                'stable_ratio': stable_ratio,
                'mean_rms': mean_rms,
                'mean_zcr': mean_zcr,
                'mean_breath_score': mean_breath_score,
                'breath_hint_ratio': breath_hint_ratio,
                'mean_pitch_hz': mean_pitch_hz,
            }
            window_audio = np.asarray(window, dtype=np.float32)
            if bundle is not None:
                tensor = self._build_chest_falsetto_window_tensor(window, bundle)
                if tensor is None:
                    continue
                candidate_windows.append(candidate_meta)
                tensors.append(tensor)
                audio_windows.append(window_audio)
            else:
                candidate_windows.append(candidate_meta)
                audio_windows.append(window_audio)

        self._last_voice_type_debug['candidate_windows'] = len(candidate_windows)

        if not candidate_windows or ((bundle is not None and not tensors) or (bundle is None and not audio_windows)):
            self._last_voice_type_debug['reason'] = 'no_candidate_windows'
            return []

        all_predictions: List[Dict[str, Any]] = []
        predictions: List[Dict[str, Any]] = []
        if bundle is not None:
            mix_bundle = self._get_mix_binary_model_bundle()
            mix_threshold = float(mix_bundle.get('threshold', self._resolve_mix_binary_threshold()) or self._resolve_mix_binary_threshold()) if isinstance(mix_bundle, dict) else self._resolve_mix_binary_threshold()
            mix_results = None
            if isinstance(mix_bundle, dict) and not bool(mix_bundle.get('force_external', False)):
                mix_results = self._predict_mix_binary_local(audio_windows, mix_bundle)
            if mix_results is None:
                mix_results = self._run_mix_binary_external_inference(audio_windows)
            batch_size = int(_CHEST_FALSETTO_BATCH_SIZE)
            with torch.no_grad():
                for start_idx in range(0, len(tensors), batch_size):
                    batch_tensors = tensors[start_idx:start_idx + batch_size]
                    try:
                        batch = torch.stack(batch_tensors).to(device)
                        logits = model(batch)
                        probs = torch.softmax(logits, dim=1).cpu().numpy()
                    except Exception:
                        continue
                    for offset, prob in enumerate(probs):
                        record_idx = start_idx + offset
                        record = dict(candidate_windows[record_idx])
                        if mix_results is not None and record_idx < len(mix_results):
                            try:
                                record['mix_prob'] = float(mix_results[record_idx].get('mix_prob', 0.0) or 0.0)
                                record['mix_threshold'] = float(mix_threshold)
                            except Exception:
                                pass
                        adjusted = self._apply_voice_type_context_priors(
                            float(prob[0]),
                            float(prob[1]),
                            mean_pitch_hz=float(record.get('mean_pitch_hz', 0.0) or 0.0),
                            voiced_ratio=float(record.get('voiced_ratio', 0.0) or 0.0),
                            stable_ratio=float(record.get('stable_ratio', 0.0) or 0.0),
                            mean_rms=float(record.get('mean_rms', 0.0) or 0.0),
                            mean_zcr=float(record.get('mean_zcr', 0.0) or 0.0),
                            mean_breath_score=float(record.get('mean_breath_score', 0.0) or 0.0),
                            breath_hint_ratio=float(record.get('breath_hint_ratio', 0.0) or 0.0),
                        )
                        record.update({
                            'event_type': adjusted['event_type'],
                            'voice_type': adjusted['voice_type'],
                            'chest_prob': adjusted['chest_prob'],
                            'falsetto_prob': adjusted['falsetto_prob'],
                            'confidence': adjusted['confidence'],
                            'probability_margin': adjusted['probability_margin'],
                            'context_forced_chest': adjusted['context_forced_chest'],
                        })
                        if bool(adjusted.get('context_forced_chest', False)):
                            self._last_voice_type_debug['context_adjusted_windows'] = int(self._last_voice_type_debug.get('context_adjusted_windows', 0) or 0) + 1
                        all_predictions.append(record)
                        event_type = str(record.get('event_type', '') or '')
                        if not self._technique_type_selected(event_type):
                            continue
                        if not self._voice_prediction_record_accepted(record, relaxed=False):
                            continue
                        predictions.append(record)
        else:
            external_results = self._run_chest_falsetto_external_inference(audio_windows)
            if external_results is None:
                self._last_voice_type_debug['reason'] = str(getattr(self, '_last_chest_falsetto_model_error', '') or 'model_unavailable')
                return []
            mix_bundle = self._get_mix_binary_model_bundle()
            mix_threshold = float(mix_bundle.get('threshold', self._resolve_mix_binary_threshold()) or self._resolve_mix_binary_threshold()) if isinstance(mix_bundle, dict) else self._resolve_mix_binary_threshold()
            mix_results = None
            if isinstance(mix_bundle, dict) and not bool(mix_bundle.get('force_external', False)):
                mix_results = self._predict_mix_binary_local(audio_windows, mix_bundle)
            if mix_results is None:
                mix_results = self._run_mix_binary_external_inference(audio_windows)
            self._last_voice_type_debug['model_ready'] = True
            self._last_voice_type_debug['backend'] = 'external_python'
            for idx, prob in enumerate(list(external_results or [])):
                if idx >= len(candidate_windows):
                    break
                try:
                    chest_prob = float(prob.get('chest_prob', 0.0) or 0.0)
                    falsetto_prob = float(prob.get('falsetto_prob', 0.0) or 0.0)
                except Exception:
                    continue
                record = dict(candidate_windows[idx])
                if mix_results is not None and idx < len(mix_results):
                    try:
                        record['mix_prob'] = float(mix_results[idx].get('mix_prob', 0.0) or 0.0)
                        record['mix_threshold'] = float(mix_threshold)
                    except Exception:
                        pass
                adjusted = self._apply_voice_type_context_priors(
                    chest_prob,
                    falsetto_prob,
                    mean_pitch_hz=float(record.get('mean_pitch_hz', 0.0) or 0.0),
                    voiced_ratio=float(record.get('voiced_ratio', 0.0) or 0.0),
                    stable_ratio=float(record.get('stable_ratio', 0.0) or 0.0),
                    mean_rms=float(record.get('mean_rms', 0.0) or 0.0),
                    mean_zcr=float(record.get('mean_zcr', 0.0) or 0.0),
                    mean_breath_score=float(record.get('mean_breath_score', 0.0) or 0.0),
                    breath_hint_ratio=float(record.get('breath_hint_ratio', 0.0) or 0.0),
                )
                record.update({
                    'event_type': adjusted['event_type'],
                    'voice_type': adjusted['voice_type'],
                    'chest_prob': adjusted['chest_prob'],
                    'falsetto_prob': adjusted['falsetto_prob'],
                    'confidence': adjusted['confidence'],
                    'probability_margin': adjusted['probability_margin'],
                    'context_forced_chest': adjusted['context_forced_chest'],
                })
                if bool(adjusted.get('context_forced_chest', False)):
                    self._last_voice_type_debug['context_adjusted_windows'] = int(self._last_voice_type_debug.get('context_adjusted_windows', 0) or 0) + 1
                all_predictions.append(record)
                event_type = str(record.get('event_type', '') or '')
                if not self._technique_type_selected(event_type):
                    continue
                if not self._voice_prediction_record_accepted(record, relaxed=False):
                    continue
                predictions.append(record)

        self._last_voice_type_debug['predicted_windows'] = len(all_predictions)

        if (not predictions) and all_predictions:
            relaxed_predictions = []
            for record in all_predictions:
                event_type = str(record.get('event_type', '') or '')
                if not self._technique_type_selected(event_type):
                    continue
                if not self._voice_prediction_record_accepted(record, relaxed=True):
                    continue
                relaxed_predictions.append(record)
            if relaxed_predictions:
                predictions = relaxed_predictions
                self._last_voice_type_debug['relaxed_used'] = True

        if not predictions:
            self._last_voice_type_debug['reason'] = 'no_prediction_passed'
            return []

        self._last_voice_type_debug['accepted_windows'] = len(predictions)

        predictions = sorted(predictions, key=lambda item: float(item.get('center_time', 0.0) or 0.0))
        predictions = self._smooth_chest_falsetto_predictions(predictions, hop_s)
        checkpoint_label = ''
        source_kind = self._offline_local_file_source_kind(valid_frames)
        try:
            if isinstance(bundle, dict):
                checkpoint_label = str(bundle.get('path', '') or '')
            else:
                checkpoint_label = str(self._resolve_chest_falsetto_checkpoint_path() or '')
        except Exception:
            checkpoint_label = ''

        runs: List[List[Dict[str, Any]]] = []
        current_run: List[Dict[str, Any]] = []
        for item in predictions:
            if not current_run:
                current_run = [item]
                continue
            prev_item = current_run[-1]
            same_type = str(prev_item.get('event_type', '') or '') == str(item.get('event_type', '') or '')
            gap = float(item.get('center_time', 0.0) or 0.0) - float(prev_item.get('center_time', 0.0) or 0.0)
            if same_type and gap <= hop_s * 1.8:
                current_run.append(item)
                continue
            runs.append(current_run)
            current_run = [item]
        if current_run:
            runs.append(current_run)

        events: List[VoiceTypeEvent] = []
        for idx, run in enumerate(runs):
            if not run:
                continue
            event_type = str(run[0].get('event_type', '') or '')
            first_center = float(run[0].get('center_time', 0.0) or 0.0)
            last_center = float(run[-1].get('center_time', 0.0) or 0.0)
            start_time = max(0.0, first_center - window_s * 0.5)
            end_time = min(total_duration, last_center + window_s * 0.5)
            if idx > 0 and runs[idx - 1]:
                prev_center = float(runs[idx - 1][-1].get('center_time', 0.0) or 0.0)
                start_time = max(start_time, 0.5 * (prev_center + first_center))
            if idx + 1 < len(runs) and runs[idx + 1]:
                next_center = float(runs[idx + 1][0].get('center_time', 0.0) or 0.0)
                end_time = min(end_time, 0.5 * (last_center + next_center))
            if end_time <= start_time:
                continue
            frame_mask = np.logical_and(times >= start_time, times <= end_time)
            frame_count = int(np.count_nonzero(frame_mask))
            if frame_count <= 0:
                continue
            voiced_ratio = float(np.mean(voiced_mask[frame_mask])) if frame_count > 0 else 0.0
            stable_ratio = float(np.mean(stable_mask[frame_mask])) if frame_count > 0 else 0.0
            mean_rms = float(np.mean(rms_values[frame_mask])) if frame_count > 0 else 0.0
            mean_zcr = float(np.mean(zcr_values[frame_mask])) if frame_count > 0 else 0.0
            mean_breath_score = float(np.mean(breath_scores[frame_mask])) if frame_count > 0 else 0.0
            breath_hint_ratio = float(np.mean(breath_hints[frame_mask])) if frame_count > 0 else 0.0
            pitch_slice = pitches[frame_mask]
            positive_pitch = pitch_slice[pitch_slice > 0.0]
            mean_pitch_hz = float(np.mean(positive_pitch)) if positive_pitch.size else float(np.mean([float(item.get('mean_pitch_hz', 0.0) or 0.0) for item in run]))
            chest_prob = float(np.mean([float(item.get('chest_prob', 0.0) or 0.0) for item in run]))
            falsetto_prob = float(np.mean([float(item.get('falsetto_prob', 0.0) or 0.0) for item in run]))
            mix_prob = float(np.mean([float(item.get('mix_prob', 0.0) or 0.0) for item in run])) if any('mix_prob' in item for item in run) else 0.0
            mix_threshold = float(np.mean([float(item.get('mix_threshold', 0.45) or 0.45) for item in run])) if any('mix_threshold' in item for item in run) else 0.45
            confidence = float(np.mean([float(item.get('confidence', 0.0) or 0.0) for item in run]))
            probability_margin = float(np.mean([float(item.get('probability_margin', 0.0) or 0.0) for item in run]))
            margin_strength = max(0.0, min(1.0, probability_margin / 0.35))
            strength = max(0.0, min(1.0, confidence * 0.62 + margin_strength * 0.38))
            label_text, color = self._get_technique_event_style(event_type)
            event = VoiceTypeEvent(
                event_type=event_type,
                start_time=float(start_time),
                end_time=float(end_time),
                confidence=confidence,
                strength=strength,
                center_time=0.5 * (float(start_time) + float(end_time)),
                duration=max(0.0, float(end_time) - float(start_time)),
                source_layer='offline_squeezenet',
                display_label=label_text,
                display_color=color,
                feature_snapshot={
                    'mean_pitch_hz': mean_pitch_hz,
                    'voiced_ratio': voiced_ratio,
                    'stable_ratio': stable_ratio,
                    'mean_rms': mean_rms,
                    'mean_zcr': mean_zcr,
                    'mean_breath_score': mean_breath_score,
                    'breath_hint_ratio': breath_hint_ratio,
                    'chest_prob': chest_prob,
                    'falsetto_prob': falsetto_prob,
                    'mix_prob': mix_prob,
                    'mix_threshold': mix_threshold,
                },
                display_payload={
                    'model': 'squeezenet_binary_mel_safe_v2',
                    'window_s': window_s,
                    'hop_s': hop_s,
                    'checkpoint': checkpoint_label,
                    'source_kind': source_kind,
                    'stable_ratio': stable_ratio,
                    'mean_rms': mean_rms,
                    'mean_zcr': mean_zcr,
                    'mean_breath_score': mean_breath_score,
                    'breath_hint_ratio': breath_hint_ratio,
                    'mix_prob': mix_prob,
                    'mix_threshold': mix_threshold,
                },
                voice_type='chest' if event_type == 'chest_voice' else 'falsetto',
                mean_pitch_hz=mean_pitch_hz,
                voiced_ratio=voiced_ratio,
                chest_prob=chest_prob,
                falsetto_prob=falsetto_prob,
                mix_prob=mix_prob,
                probability_margin=probability_margin,
                window_count=len(run),
            )
            events.append(event)
        return events

    def _build_rule_based_mix_events(
        self,
        frames: List[FrameFeatures],
        voice_events: List[VoiceTypeEvent],
    ) -> List[MixVoiceEvent]:
        if not any(self._technique_type_selected(name) for name in ('strong_mix', 'weak_mix', 'balanced_mix')):
            return []

        capture_mix_rule_debug = bool(getattr(self, '_capture_mix_rule_debug', False))
        debug_rows: List[Dict[str, Any]] = []
        try:
            self._last_mix_rule_debug_rows = debug_rows
        except Exception:
            pass

        def _clamp01(value: float) -> float:
            return max(0.0, min(1.0, float(value or 0.0)))

        mix_events: List[MixVoiceEvent] = []
        for event in list(voice_events or []):
            if not isinstance(event, VoiceTypeEvent):
                continue
            try:
                duration = float(getattr(event, 'duration', 0.0) or 0.0)
                confidence = float(getattr(event, 'confidence', 0.0) or 0.0)
                strength = float(getattr(event, 'strength', 0.0) or 0.0)
                probability_margin = float(getattr(event, 'probability_margin', 0.0) or 0.0)
                chest_prob = float(getattr(event, 'chest_prob', 0.0) or 0.0)
                falsetto_prob = float(getattr(event, 'falsetto_prob', 0.0) or 0.0)
                voiced_ratio = float(getattr(event, 'voiced_ratio', 0.0) or 0.0)
                mean_pitch_hz = float(getattr(event, 'mean_pitch_hz', 0.0) or 0.0)
            except Exception:
                continue
            debug_row: Optional[Dict[str, Any]] = None
            if capture_mix_rule_debug:
                debug_row = {
                    'event_type': str(getattr(event, 'event_type', '') or ''),
                    'voice_type': str(getattr(event, 'voice_type', '') or ''),
                    'start_time': float(getattr(event, 'start_time', 0.0) or 0.0),
                    'end_time': float(getattr(event, 'end_time', 0.0) or 0.0),
                    'duration': duration,
                    'confidence': confidence,
                    'strength': strength,
                    'probability_margin': probability_margin,
                    'chest_prob': chest_prob,
                    'falsetto_prob': falsetto_prob,
                    'voiced_ratio': voiced_ratio,
                    'mean_pitch_hz': mean_pitch_hz,
                }
            if duration < 0.18 or mean_pitch_hz <= 0.0:
                if debug_row is not None:
                    debug_row['skip_reason'] = 'invalid_duration_or_pitch'
                    debug_rows.append(debug_row)
                continue

            try:
                snapshot = dict(getattr(event, 'feature_snapshot', {}) or {})
            except Exception:
                snapshot = {}
            mean_rms = float(snapshot.get('mean_rms', 0.0) or 0.0)
            mean_zcr = float(snapshot.get('mean_zcr', 0.0) or 0.0)
            stable_ratio = float(snapshot.get('stable_ratio', 0.0) or 0.0)
            mean_breath_score = float(snapshot.get('mean_breath_score', 0.0) or 0.0)
            breath_hint_ratio = float(snapshot.get('breath_hint_ratio', 0.0) or 0.0)
            learned_mix_prob = float(snapshot.get('mix_prob', getattr(event, 'mix_prob', 0.0) or 0.0) or 0.0)
            learned_mix_threshold = float(snapshot.get('mix_threshold', 0.45) or 0.45)
            learned_mix_margin = (learned_mix_prob - learned_mix_threshold) if learned_mix_prob > 0.0 else 0.0

            heuristic_mix_support = _clamp01(1.0 - (probability_margin / 0.40))
            learned_mix_support = _clamp01((learned_mix_prob - (learned_mix_threshold - 0.12)) / 0.42) if learned_mix_prob > 0.0 else 0.0
            mix_support = heuristic_mix_support
            if learned_mix_prob > 0.0:
                mix_support = _clamp01(0.32 * heuristic_mix_support + 0.68 * learned_mix_support)
            pitch_support = _clamp01((mean_pitch_hz - 210.0) / 230.0)
            stable_support = _clamp01((stable_ratio - 0.08) / 0.24)
            voiced_support = _clamp01((voiced_ratio - 0.34) / 0.34)
            low_energy_air = _clamp01((0.0014 - mean_rms) / 0.0011) if mean_rms > 0.0 else 0.0
            zcr_air = _clamp01((mean_zcr - 0.08) / 0.16)
            breathiness = max(
                _clamp01(mean_breath_score / 0.34),
                _clamp01(breath_hint_ratio / 0.22),
                zcr_air * 0.82,
                low_energy_air * 0.68,
            )
            head_bias = _clamp01((falsetto_prob - chest_prob + 0.18) / 0.50)
            chest_bias = _clamp01((chest_prob - falsetto_prob + 0.18) / 0.50)
            if debug_row is not None:
                debug_row.update({
                    'mean_rms': mean_rms,
                    'mean_zcr': mean_zcr,
                    'stable_ratio': stable_ratio,
                    'mean_breath_score': mean_breath_score,
                    'breath_hint_ratio': breath_hint_ratio,
                    'learned_mix_prob': learned_mix_prob,
                    'learned_mix_threshold': learned_mix_threshold,
                    'learned_mix_margin': learned_mix_margin,
                    'heuristic_mix_support': heuristic_mix_support,
                    'learned_mix_support': learned_mix_support,
                    'mix_support': mix_support,
                    'head_bias': head_bias,
                    'chest_bias': chest_bias,
                })
            pure_learned_head_mix = (
                learned_mix_prob >= learned_mix_threshold
                and head_bias >= 0.70
                and heuristic_mix_support <= 0.08
            )
            marginal_head_mix = (
                learned_mix_prob >= learned_mix_threshold
                and head_bias >= 0.90
                and learned_mix_margin < 0.05
                and heuristic_mix_support < 0.30
                and learned_mix_support < 0.45
            )
            released_high_pitch_head_mix = (
                marginal_head_mix
                and mean_pitch_hz >= 470.0
                and falsetto_prob >= 0.95
                and mean_rms >= 0.075
                and learned_mix_margin >= 0.005
                and learned_mix_support >= 0.30
            )
            released_near_threshold_high_pitch_head_mix = (
                not released_high_pitch_head_mix
                and learned_mix_margin >= -0.0015
                and learned_mix_prob >= max(0.50, learned_mix_threshold - 0.002)
                and head_bias >= 0.92
                and mean_pitch_hz >= 500.0
                and falsetto_prob >= 0.93
                and falsetto_prob <= 0.96
                and mean_rms >= 0.08
                and learned_mix_support >= 0.28
            )
